// ============================================================
//  Lease Amendment UI — JavaScript
//  Reads leaseId from URL params (passed by openLeaseAmendmentUI)
//  Loads: Lease Terms, Units, Recurring Charges, Deposits, Clauses
//  Actions: Edit terms, Edit/Add/Delete charges, deposits, units, clauses
// ============================================================
// ── Hide Dynamics 365 dialog chrome title ─────────────────────
(function hideDialogTitle() {
  try {
    const parentDoc = window.parent.document;

    // Inject CSS immediately — hides before any paint
    const style = parentDoc.createElement("style");
    style.id = "hideDialogChromeTitle";
    style.textContent = `
      [id^="defaultDialogChromeTitle"],
      [id^="defaultDialogChromeTitle"] * {
        visibility: hidden !important;
        height: 0 !important;
        overflow: hidden !important;
        padding: 0 !important;
        margin: 0 !important;
      }
    `;
    parentDoc.head.appendChild(style);

    // MutationObserver as backup for late-rendered elements
    const observer = new MutationObserver(() => {
      const titleEl = parentDoc.querySelector(
        '[id^="defaultDialogChromeTitle"]',
      );
      if (titleEl) {
        titleEl.style.cssText =
          "visibility:hidden!important;height:0!important;overflow:hidden!important;padding:0!important;margin:0!important;";
      }
    });

    observer.observe(parentDoc.body, { childList: true, subtree: true });

    // Stop observing after 5s to avoid memory leak
    setTimeout(() => observer.disconnect(), 5000);
  } catch (e) {
    console.warn("Could not hide dialog title:", e);
  }
})();

// ── Show loader BEFORE first paint, hide wizard until ready ───
// In the Dynamics web-resource load order the HTML body (with
// #amendContainer visible) can paint before this script's stylesheet is
// applied, causing a one-frame flash. We mitigate by (1) injecting the
// override into <html> as early as possible, and (2) force-hiding the
// container the instant it exists via a short-lived observer.
(function ppShowLoaderEarly() {
  try {
    const s = document.createElement("style");
    s.id = "amendEarlyLoaderCss";
    s.textContent =
      "#amendContainer{visibility:hidden !important;}" +
      "#amendLoadingScreen{display:flex !important;}";
    (document.head || document.documentElement).appendChild(s);

    // Force-hide the container as soon as it appears (beats the cascade race)
    const _forceHide = () => {
      const c = document.getElementById("amendContainer");
      if (c) {
        c.style.visibility = "hidden";
        return true;
      }
      return false;
    };
    if (!_forceHide()) {
      const _obs = new MutationObserver(() => {
        if (_forceHide()) _obs.disconnect();
      });
      _obs.observe(document.documentElement, {
        childList: true,
        subtree: true,
      });
      // Safety: stop observing after 4s regardless
      setTimeout(() => {
        try {
          _obs.disconnect();
        } catch (_) {}
      }, 4000);
    }
  } catch (e) {
    /* non-fatal */
  }
})();

