//       native statuscode field on array_leaseamendments only.
const AMENDMENT_STATUS = {
  DRAFT: 126330006, // statuscode value for Draft
  PENDING: 126330001, // statuscode value for Pending
  ACTIVE: 126330002, // statuscode value for Active
  FAILED: 126330003, // statuscode value for Failed
};

// ══════════════════════════════════════════════════════════════
//  "Effective Lease End" helper
//  Returns the amendment's expiry date (amend_endDate input) if set,
//  otherwise falls back to the lease record's array_leaseenddate.
//  All downstream validations / autofills for unit, charge, deposit,
//  clause, option, discount end-dates should use this value as the
//  authoritative "lease end" boundary so that when the user is
//  extending or shortening the lease via this amendment, child
//  records stay consistent with the new boundary.
//  Returns a YYYY-MM-DD string, or "" if neither is available.
// ══════════════════════════════════════════════════════════════
function getEffectiveLeaseEnd() {
  const amendmentExpiry = document.getElementById("amend_endDate")?.value || "";
  if (amendmentExpiry) return amendmentExpiry;
  const leaseEnd =
    amendLeaseData && amendLeaseData.array_leaseenddate
      ? amendLeaseData.array_leaseenddate.substring(0, 10)
      : "";
  return leaseEnd;
}

// ══════════════════════════════════════════════════════════════
//  DEFERRED WRITE — Draft amendment reuse helper
//  Queries for an existing Draft amendment on this lease.
//  If found → reuses it (updates terms). If not → creates new.
//  This prevents duplicate Draft amendments when a user saves
//  halfway through, closes the browser, and reopens the wizard.
// ══════════════════════════════════════════════════════════════
async function resolveOrCreateAmendment(amendmentRecord) {
  // ── Edit mode: amendment already exists — update header fields only ───
  if (isEditMode && editingAmendmentId) {
    const updatePayload = { ...amendmentRecord };
    delete updatePayload["array_LeaseAgreement@odata.bind"]; // already linked
    delete updatePayload["array_versionnumber"]; // preserve original version
    try {
      await XrmCtx.WebApi.updateRecord(
        "array_leaseamendments",
        editingAmendmentId,
        updatePayload,
      );
      console.log(
        `ℹ️ Edit mode: updated amendment header ${editingAmendmentId}`,
      );
    } catch (e) {
      console.warn("resolveOrCreateAmendment (edit mode): update failed:", e);
      throw e;
    }
    return editingAmendmentId;
  }

  // ── Normal mode: existing Draft-reuse / create-new logic ─────────────
  const clientUrl = XrmCtx.Utility.getGlobalContext().getClientUrl();
  const url =
    `${clientUrl}/api/data/v9.2/array_leaseamendmentses` +
    `?$select=array_leaseamendmentsid,array_amendmentname,array_versionnumber` +
    `&$filter=_array_leaseagreement_value eq ${amendLeaseId}` +
    ` and statuscode eq ${AMENDMENT_STATUS.DRAFT}` +
    `&$orderby=createdon desc&$top=1`;

  try {
    const resp = await fetch(url, {
      headers: {
        "OData-MaxVersion": "4.0",
        "OData-Version": "4.0",
        Accept: "application/json",
        Prefer: 'odata.include-annotations="*"',
      },
      credentials: "same-origin",
    });
    if (resp.ok) {
      const data = await resp.json();
      const existing = data.value && data.value[0];
      if (existing) {
        const existingId = existing.array_leaseamendmentsid.replace(
          /[{}]/g,
          "",
        );
        console.log(
          `ℹ️ Reusing existing Draft amendment: ${existingId} ` +
            `(${existing.array_amendmentname || "untitled"})`,
        );
        const updatePayload = { ...amendmentRecord };
        delete updatePayload["array_LeaseAgreement@odata.bind"];
        await XrmCtx.WebApi.updateRecord(
          "array_leaseamendments",
          existingId,
          updatePayload,
        );
        return existingId;
      }
    }
  } catch (e) {
    console.warn("resolveOrCreateAmendment: query failed, will create new:", e);
  }

  // No Draft found — create new
  const created = await XrmCtx.WebApi.createRecord(
    "array_leaseamendments",
    amendmentRecord,
  );
  const newId = created.id.replace(/[{}]/g, "");
  if (!newId) throw new Error("Amendment record created but no ID returned.");
  console.log(`✅ New amendment record created: ${newId}`);
  return newId;
}

