function selectSignMethod(method) {
  selectedSignMethod = method;

  // Update button visual states
  document
    .querySelectorAll(".sign-method-btn:not(:disabled)")
    .forEach((btn) => {
      btn.classList.remove("selected");
      const badge = btn.querySelector(".sign-method-badge-selected");
      if (badge) badge.remove();
    });

  const btn = document.getElementById(
    method === "manual" ? "btnManualSign" : "btnDocuSign",
  );
  if (btn) {
    btn.classList.add("selected");
    if (!btn.querySelector(".sign-method-badge-selected")) {
      const badge = document.createElement("div");
      badge.className = "sign-method-badge-selected";
      badge.textContent = "✓ Selected";
      btn.appendChild(badge);
    }
  }

  // Enable Next button when on sign-in step
  const nextBtn = document.getElementById("btnWizardNext");
  if (nextBtn && WIZARD_STAGES[currentWizardStage] === "signin") {
    nextBtn.disabled = false;
  }
}

