// ── Bootstrap ────────────────────────────────────────────────
// ── Pending Selection Screen helpers ─────────────────────────
function showPendingSelectionScreen() {
  document.getElementById("pendingSelectionScreen").style.display = "flex";
}

function hidePendingSelectionScreen() {
  document.getElementById("pendingSelectionScreen").style.display = "none";
}

async function pss_loadAndShow() {
  if (!amendLeaseId) return false;

  try {
    const clientUrl = XrmCtx.Utility.getGlobalContext().getClientUrl();
    const url =
      `${clientUrl}/api/data/v9.2/array_leaseamendmentses` +
      `?$select=array_leaseamendmentsid,array_amendmentname,array_amendmenttype,` +
      `array_effectivedate,createdon,statuscode` +
      `&$filter=_array_leaseagreement_value eq ${amendLeaseId}` +
      ` and statuscode eq ${AMENDMENT_STATUS.PENDING}` +
      `&$orderby=array_effectivedate asc`;

    const resp = await fetch(url, {
      headers: {
        "OData-MaxVersion": "4.0",
        "OData-Version": "4.0",
        Accept: "application/json",
        Prefer: 'odata.include-annotations="*"',
      },
      credentials: "same-origin",
    });

    if (!resp.ok) throw new Error(`HTTP ${resp.status}`);
    const data = await resp.json();
    const pending = data.value || [];

    if (!pending.length) return false;

    await _pss_preloadAmendmentTypeLabels();
    pss_renderTable(pending);
    document.getElementById("pssLoading").style.display = "none";
    document.getElementById("pssTableWrapper").style.display = "block";
    showPendingSelectionScreen();
    return true;
  } catch (e) {
    console.warn("pss_loadAndShow: failed:", e);
    return false;
  }
}

async function _pss_preloadAmendmentTypeLabels() {
  if (Object.keys(_pssAmendmentTypeLabels).length > 0) return;
  if (amendmentTypeOptions && amendmentTypeOptions.length > 0) {
    amendmentTypeOptions.forEach((o) => {
      _pssAmendmentTypeLabels[o.Value] =
        o.Label?.UserLocalizedLabel?.Label || String(o.Value);
    });
    return;
  }
  const clientUrl = XrmCtx.Utility.getGlobalContext().getClientUrl();
  const namesToTry = ["array_amendmenttype", "array_AmendmentType"];
  for (const name of namesToTry) {
    try {
      const resp = await fetch(
        `${clientUrl}/api/data/v9.2/GlobalOptionSetDefinitions(Name='${name}')/Microsoft.Dynamics.CRM.OptionSetMetadata`,
        {
          headers: {
            "OData-MaxVersion": "4.0",
            "OData-Version": "4.0",
            Accept: "application/json",
          },
          credentials: "same-origin",
        },
      );
      if (!resp.ok) continue;
      const d = await resp.json();
      if (d?.Options?.length) {
        d.Options.forEach((o) => {
          _pssAmendmentTypeLabels[o.Value] =
            o.Label?.UserLocalizedLabel?.Label || String(o.Value);
        });
        break;
      }
    } catch (_) {
      /* silent */
    }
  }
}

function pss_renderTable(pending) {
  const tbody = document.getElementById("pssTableBody");
  if (!tbody) return;

  tbody.innerHTML = pending
    .map((a) => {
      const id = a.array_leaseamendmentsid.replace(/[{}]/g, "");
      const name = a.array_amendmentname || "Untitled";
      const typeRaw = a.array_amendmenttype || "";
      const typeLabel = typeRaw
        ? typeRaw
            .split(",")
            .map((v) => _pssAmendmentTypeLabels[parseInt(v.trim())] || v.trim())
            .join(", ")
        : "—";
      const effDate = a.array_effectivedate
        ? formatDateAmend(a.array_effectivedate)
        : "—";
      const createdOn = a.createdon ? formatDateAmend(a.createdon) : "—";

      return `<tr class="pss-row" data-id="${id}" data-name="${_pssEsc(name)}"
                    onclick="pss_selectRow(this, '${id}', '${_pssEsc(name)}')">
            <td style="width:32px;text-align:center;">
                <div style="width:16px;height:16px;border-radius:50%;border:2px solid #CBD5E1;
                            display:inline-flex;align-items:center;justify-content:center;"
                     id="pss-radio-${id}"></div>
            </td>
            <td style="font-weight:600;">${_pssEsc(name)}</td>
            <td style="color:#5A6070;">${_pssEsc(typeLabel)}</td>
            <td>${effDate}</td>
            <td style="color:#5A6070;">${createdOn}</td>
            <td><span class="pss-status-pill">Pending</span></td>
        </tr>`;
    })
    .join("");
}

function _pssEsc(s) {
  return String(s || "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

function pss_selectRow(row, id, name) {
  document.querySelectorAll(".pss-row").forEach((r) => {
    r.classList.remove("pss-row-selected");
    const radio = document.getElementById("pss-radio-" + r.dataset.id);
    if (radio) {
      radio.style.borderColor = "";
      radio.style.background = "";
      radio.innerHTML = "";
    }
  });

  row.classList.add("pss-row-selected");
  const radio = document.getElementById("pss-radio-" + id);
  if (radio) {
    radio.style.borderColor = "#1C6BD4";
    radio.style.background = "#1C6BD4";
    radio.innerHTML = `<svg width="8" height="8" viewBox="0 0 10 10" fill="white"><circle cx="5" cy="5" r="4"/></svg>`;
  }

  _pssSelectedAmendmentId = id;
  _pssSelectedAmendmentName = name;

  const editBtn = document.getElementById("btnPssEdit");
  if (editBtn) editBtn.disabled = false;

  const hint = document.getElementById("pssSelectionHint");
  if (hint) hint.textContent = `"${name}" selected — click Edit to continue.`;
}

function pss_cancel() {
  hidePendingSelectionScreen();
  try {
    window.close();
  } catch (_) {}
}

function pss_createNew() {
  hidePendingSelectionScreen();
  isEditMode = false;
  editingAmendmentId = null;
  document.getElementById("amendLoadingScreen").style.display = "flex";
  _bootstrapWizardData();
}

async function pss_editSelected() {
  if (!_pssSelectedAmendmentId) return;

  const editBtn = document.getElementById("btnPssEdit");
  if (editBtn) {
    editBtn.disabled = true;
    editBtn.textContent = "Opening…";
  }

  try {
    editingAmendmentId = _pssSelectedAmendmentId;
    isEditMode = true;

    // Re-evaluate the AI autofill banner — it was created earlier when
    // isEditMode was still false, so it may currently be visible. Hide
    // it now that edit mode is active.
    try {
      if (typeof _aiBanner_updateMode === "function") _aiBanner_updateMode();
    } catch (_) {}

    hidePendingSelectionScreen();
    document.getElementById("amendLoadingScreen").style.display = "flex";
    await _bootstrapWizardData();
  } catch (e) {
    console.error("pss_editSelected: failed:", e);
    showAmendNotification(
      "❌ Could not open amendment for editing: " + (e.message || e),
      "error",
    );
    if (editBtn) {
      editBtn.disabled = false;
      editBtn.textContent = "Edit Selected";
    }
  }
}

async function bootstrapAmendmentUI() {
  try {
    const raw = new URLSearchParams(window.location.search).get("data");
    if (raw) {
      const parsed = JSON.parse(decodeURIComponent(raw));
      amendLeaseId = parsed.recordId || parsed.leaseId || null;

      if (parsed.sourceOptionId) {
        amendSourceOptionId = parsed.sourceOptionId
          .toLowerCase()
          .replace(/[{}]/g, "")
          .trim();
      }
    }

    if (!amendLeaseId) {
      showAmendNotification(
        "No lease ID received. Please close and reopen this form.",
        "error",
      );
      hideLoadingScreen();
      return;
    }

    // Load lookups + lease data first (needed before pending check)
    await Promise.all([loadAmendLookups(), loadLeaseDetails()]);

    selectedSignMethod = "manual";

    // Check for pending amendments — show selection screen if found
    const selectionShown = await pss_loadAndShow();
    if (selectionShown) {
      // Hide the loader — PSS is now visible; user selects via pss_editSelected()
      // Must also remove the early-paint CSS override, otherwise its
      // `#amendLoadingScreen{display:flex !important}` keeps the loader on top.
      const _earlyCss = document.getElementById("amendEarlyLoaderCss");
      if (_earlyCss) _earlyCss.remove();
      document.getElementById("amendLoadingScreen").style.display = "none";
      return;
    }

    // No pending amendments — go straight to new wizard (loader stays on)
    isEditMode = false;
    editingAmendmentId = null;
    await _bootstrapWizardData();
  } catch (err) {
    console.error("❌ Amendment UI init error:", err);
    showAmendNotification(
      "Error initialising amendment UI: " + (err.message || err),
      "error",
    );
    hideLoadingScreen();
  }
}

// ── Edit mode: restore Terms fields from the amendment being edited ──
async function loadEditModeTermsFields() {
  if (!isEditMode || !editingAmendmentId) return;
  try {
    const clientUrl = XrmCtx.Utility.getGlobalContext().getClientUrl();
    const resp = await fetch(
      `${clientUrl}/api/data/v9.2/array_leaseamendmentses(${editingAmendmentId})` +
        `?$select=array_leaseamendmentsid,array_amendmentname,array_effectivedate,` +
        `array_expirydate,array_amendmentdate,array_amendmenttype,array_description,` +
        `array_versionnumber`,
      {
        headers: {
          "OData-MaxVersion": "4.0",
          "OData-Version": "4.0",
          Accept: "application/json",
          Prefer: 'odata.include-annotations="*"',
        },
        credentials: "same-origin",
      },
    );
    if (!resp.ok) {
      console.error("loadEditModeTermsFields: fetch failed HTTP", resp.status);
      return;
    }
    const rec = await resp.json();
    if (!rec.array_leaseamendmentsid) {
      console.error(
        "loadEditModeTermsFields: record not found for",
        editingAmendmentId,
      );
      return;
    }

    console.log(
      "✅ Edit mode terms loaded:",
      rec.array_leaseamendmentsid,
      "| effectiveDate:",
      rec.array_effectivedate,
      "| amendmentType:",
      rec.array_amendmenttype,
    );

    if (rec.array_effectivedate) {
      const el = document.getElementById("amend_startDate");
      if (el) el.value = rec.array_effectivedate.substring(0, 10);
    }
    if (rec.array_expirydate) {
      const el = document.getElementById("amend_endDate");
      if (el) el.value = rec.array_expirydate.substring(0, 10);
    }
    if (rec.array_amendmentdate) {
      const el = document.getElementById("amend_moveInDate");
      if (el) el.value = rec.array_amendmentdate.substring(0, 10);
    }
    if (rec.array_description) {
      const el = document.getElementById("amend_description");
      if (el) el.value = rec.array_description;
    }

    // Restore amendment type selections — always call to re-render chips
    // even if null (clears any stale selections from bootstrap)
    await loadAmendmentTypeOptions(rec.array_amendmenttype || null);

    applyRenewalDateConstraint();
    applyDateMaxToAll();

    // Load existing SharePoint documents (non-fatal — runs in background)
    fu_loadExistingSharePointFiles(editingAmendmentId).catch((e) =>
      console.warn("SharePoint doc load failed (non-fatal):", e),
    );
  } catch (e) {
    console.error("loadEditModeTermsFields: failed:", e);
  }
}

// ── Render Lease Health Summary + Smart Suggestions ───────────
// Uses data already in memory (no API calls). Lease Terms step only.
function renderLeaseInsights() {
  const card = document.getElementById("smartSuggestionsCard");
  const statsRow = document.getElementById("ssStatsRow");
  const body = document.getElementById("smartSuggestionsBody");
  const countPill = document.getElementById("ssCountPill");
  if (!card || !body || !statsRow) return;

  // ── Compact stats row (replaces the Lease Health Summary card) ──
  const totalArea = (amendExistingUnits || []).reduce(
    (sum, u) => sum + (parseFloat(u.array_Unit?.array_unitareasqm) || 0),
    0,
  );
  const activeUnits = (amendExistingUnits || []).length;
  const activeCharges = (amendExistingCharges || []).length;
  const activeClauses = (amendClauses || []).length;
  const activeDeposits = (amendDeposits || []).length;
  const activeOptions = (amendExistingOptions || []).length;

  const leaseEnd = amendLeaseData?.array_leaseenddate
    ? amendLeaseData.array_leaseenddate.substring(0, 10)
    : "";
  let daysToExpiry = null;
  let expiryColor = "#1C6BD4";
  if (leaseEnd) {
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    daysToExpiry = Math.ceil((new Date(leaseEnd) - today) / 86400000);
    if (daysToExpiry < 0) expiryColor = "#7F1515";
    else if (daysToExpiry <= 90) expiryColor = "#7A4F0A";
    else if (daysToExpiry <= 180) expiryColor = "#0369A1";
    else expiryColor = "#2E7D32";
  }
  const expiryValue =
    daysToExpiry === null
      ? "—"
      : daysToExpiry < 0
        ? `Exp ${Math.abs(daysToExpiry)}d ago`
        : daysToExpiry === 0
          ? "Expires today"
          : `${daysToExpiry}d`;

  // ── Stats strip ("Lease Insights") removed — keep only Smart Suggestions ──
  statsRow.innerHTML = "";
  statsRow.style.display = "none";

  // Rename card header from "Smart Suggestions & Lease Insights" to "Smart Suggestions"
  const _ssHeading = card.querySelector("h3");
  if (_ssHeading) _ssHeading.textContent = "Smart Suggestions";

  // ── Build suggestions ──
  const suggestions = [];

  if (leaseEnd && daysToExpiry !== null) {
    if (daysToExpiry < 0) {
      suggestions.push({
        icon: "warning",
        text: `Lease expired ${Math.abs(daysToExpiry)} days ago. Consider extending or terminating.`,
        color: "#7F1515",
        bg: "#FEF2F2",
        border: "#FCA5A5",
      });
    } else if (daysToExpiry <= 90) {
      const hasRenewal = (amendExistingOptions || []).some(
        (o) => parseInt(o.array_optiontype) === OPTION_TYPE_RENEWAL,
      );
      if (!hasRenewal) {
        suggestions.push({
          icon: "warning",
          text: `Lease expires in ${daysToExpiry} days. No renewal option set — consider adding one.`,
          color: "#7A4F0A",
          bg: "#FFF8EC",
          border: "#FFCF7F",
        });
      } else {
        suggestions.push({
          icon: "info",
          text: `Lease expires in ${daysToExpiry} days. Renewal option is set.`,
          color: "#0369A1",
          bg: "#EBF3FF",
          border: "#BBDBFF",
        });
      }
    }
  }

  const openEndedCharges = (amendExistingCharges || []).filter(
    (c) => !c.array_enddate,
  ).length;
  if (openEndedCharges > 0) {
    suggestions.push({
      icon: "info",
      text: `${openEndedCharges} recurring charge${openEndedCharges > 1 ? "s have" : " has"} no end date set.`,
      color: "#5A6070",
      bg: "#F1F2F4",
      border: "#EAECF0",
    });
  }

  if (!activeUnits) {
    suggestions.push({
      icon: "warning",
      text: "This lease has no active units. Add at least one unit before submitting amendments.",
      color: "#7F1515",
      bg: "#FEF2F2",
      border: "#FCA5A5",
    });
  }

  if (!activeDeposits) {
    suggestions.push({
      icon: "info",
      text: "No security or insurance records exist. Consider adding deposit requirements.",
      color: "#5A6070",
      bg: "#F1F2F4",
      border: "#EAECF0",
    });
  }

  const effVal = document.getElementById("amend_startDate")?.value || "";
  if (effVal) {
    const todayStr = new Date().toISOString().substring(0, 10);
    if (effVal < todayStr) {
      suggestions.push({
        icon: "warning",
        text: `Effective Date is in the past (${formatDateAmend(effVal)}). Same-day amendment — changes apply immediately on save.`,
        color: "#7A4F0A",
        bg: "#FFF8EC",
        border: "#FFCF7F",
      });
    }
  }

  if (countPill) countPill.textContent = suggestions.length || "✓";

  if (!suggestions.length) {
    suggestions.push({
      icon: "ok",
      text: "Everything looks good. No issues detected with the current lease setup.",
      color: "#2E7D32",
      bg: "#EDF7EE",
      border: "#A8D5AB",
    });
  }

  const iconSvg = {
    warning: `<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M10.29 3.86L1.82 18a2 2 0 001.71 3h16.94a2 2 0 001.71-3L13.71 3.86a2 2 0 00-3.42 0z"></path><line x1="12" y1="9" x2="12" y2="13"></line><line x1="12" y1="17" x2="12.01" y2="17"></line></svg>`,
    info: `<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="10"></circle><line x1="12" y1="16" x2="12" y2="12"></line><line x1="12" y1="8" x2="12.01" y2="8"></line></svg>`,
    ok: `<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><polyline points="20 6 9 17 4 12"></polyline></svg>`,
  };

  body.innerHTML = suggestions
    .map(
      (s) => `
        <div style="display:flex;align-items:flex-start;gap:10px;padding:10px 12px;
                    background:${s.bg};border:1px solid ${s.border};border-radius:8px;
                    border-left:3px solid ${s.color};min-height:48px;">
            <span style="color:${s.color};flex-shrink:0;margin-top:1px;">${iconSvg[s.icon] || iconSvg.info}</span>
            <span style="font-size:12.5px;color:${s.color};line-height:1.5;">${esc(s.text)}</span>
        </div>
    `,
    )
    .join("");

  card.style.display = "block";
}

// ── Shared wizard data loader ─────────────────────────────────
async function _bootstrapWizardData() {
  try {
    await Promise.all([
      loadUnits(),
      loadCharges(),
      loadDeposits(),
      loadClauses(),
      loadOptions(),
      loadDiscounts(),
    ]);

    if (isEditMode && editingAmendmentId) {
      await loadEditModeTermsFields();
      await loadAmendmentChildRecords(editingAmendmentId);
    }

    cl_loadClauseLookups().catch((e) =>
      console.warn("Clause lookups background load failed:", e),
    );

    if (!isEditMode) {
      checkPendingAmendmentBanner().catch((e) =>
        console.warn("Pending amendment check failed (non-fatal):", e),
      );
    }

    // Render Lease Health + Smart Suggestions cards (non-fatal — synchronous, uses data already loaded)
    try {
      renderLeaseInsights();
    } catch (e) {
      console.warn("Lease insights render failed (non-fatal):", e);
    }

    hideLoadingScreen();

    if (isEditMode) {
      showAmendNotification(
        `✏️ Editing amendment "${_pssSelectedAmendmentName || editingAmendmentId}" — all staged changes have been loaded.`,
        "info",
      );
    }
  } catch (err) {
    console.error("❌ Wizard data load error:", err);
    showAmendNotification(
      "Error loading amendment data: " + (err.message || err),
      "error",
    );
    hideLoadingScreen();
  }
}

