// ── Load Charges ─────────────────────────────────────────────
async function loadCharges() {
  try {
    const clientUrl = XrmCtx.Utility.getGlobalContext().getClientUrl();
    // Only load ACTIVE charges (statecode eq 0) on initial load — inactive ones are hidden
    // Only load ACTIVE charges (statecode eq 0) on initial load — inactive ones are hidden.
    // Also exclude BILLED charges (statuscode = 126330001) — once invoicing has started
    // on a charge, amending it here would create re-billing / credit note problems.
    const url = `${clientUrl}/api/data/v9.2/array_recurringcharges?$select=array_recurringchargeid,array_chargename,array_amount,array_startdate,array_enddate,array_frequency,array_billablearea,array_prorationenabled,array_prefrequencyoffset,array_dueindays,array_invoicegenerationdate,array_duedaterule,_transactioncurrencyid_value&$filter=_array_leaseagreement_value eq ${amendLeaseId} and statecode eq 0 and statuscode ne 126330001&$expand=array_Unit($select=array_unitid,array_unitname),array_ChargeType($select=array_chargetypeid,array_name)`;
    const resp = await fetch(url, {
      headers: {
        "OData-MaxVersion": "4.0",
        "OData-Version": "4.0",
        Accept: "application/json",
        Prefer: 'odata.include-annotations="*"',
      },
      credentials: "same-origin",
    });
    if (!resp.ok) throw new Error(`Charges fetch: HTTP ${resp.status}`);
    const data = await resp.json();
    // On initial load, all fetched records are "existing". New charges are tracked separately.
    // Preserve any newly added charges already in amendNewCharges.
    amendExistingCharges = data.value || [];
    // Rebuild the combined list for preview (active existing + new)
    amendCharges = [...amendExistingCharges, ...amendNewCharges];
    renderExistingChargesTable();
    renderNewChargesTable();
    updateBadge("charges", amendCharges.length);
  } catch (e) {
    console.error("Error loading charges:", e);
    const errRow = `<tr><td colspan="8" style="text-align:center;padding:30px;color:#B91C1C;">Could not load recurring charges.</td></tr>`;
    const tb1 = document.getElementById("existingChargesTbody");
    if (tb1) tb1.innerHTML = errRow;
  }
}

// ══════════════════════════════════════════════════════════════════════════════
//  FUNCTION 2 — renderExistingChargesTable
//  Changes:
//    • EDITED badge on End Date cell for charges with _pendingEndDateEdit = true
//    • Shows the pending new end date alongside the badge
//    • All other logic identical to original
// ══════════════════════════════════════════════════════════════════════════════
function renderExistingChargesTable() {
  renderChargesAISummary();
  const tbody = document.getElementById("existingChargesTbody");
  if (!tbody) return;

  const allExisting = [
    ...amendExistingCharges.map((c) => ({ ...c, _deactivated: false })),
    ...amendDeactivatedCharges.map((c) => ({ ...c, _deactivated: true })),
  ];

  const pill = document.getElementById("existingChargesCountPill");
  if (pill)
    pill.textContent = `${allExisting.length} record${allExisting.length !== 1 ? "s" : ""}`;

  if (!allExisting.length) {
    tbody.innerHTML = `<tr><td colspan="8"><div class="amend-empty">
      <svg width="48" height="48" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5">
        <path d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2"/>
        <rect x="9" y="3" width="6" height="4" rx="1"/>
      </svg>
      <p>No existing recurring charges</p>
    </div></td></tr>`;
    return;
  }

  tbody.innerHTML = allExisting
    .map((c, i) => {
      const unit = c.array_Unit || {};
      const chargeType = c.array_ChargeType || {};
      const ccyId = c._transactioncurrencyid_value;
      const ccyMatch = ccyId
        ? amendCurrencies.find((cu) => cu.transactioncurrencyid === ccyId)
        : null;
      const sym =
        (ccyMatch && ccyMatch.currencysymbol) ||
        c[
          "_transactioncurrencyid_value@OData.Community.Display.V1.FormattedValue"
        ] ||
        "";
      const freqLabel = getFreqLabel(c.array_frequency);
      const isDeactivated = c._deactivated === true;
      const rowClass = isDeactivated ? "charge-deactivated" : "";
      const rowBg =
        !isDeactivated && i % 2 === 0 ? 'style="background:#F8F9FC"' : "";

      // ── EDITED badge: shown if end date was changed in this session ──
      const hasEndDateEdit = !isDeactivated && c._pendingEndDateEdit === true;
      const endDateDisplay = hasEndDateEdit
        ? `${formatDateAmend(c._pendingEndDate)}
           <span style="background:#FFF8EC;color:#854d0e;font-size:10px;font-weight:700;
                        padding:1px 5px;border-radius:5px;vertical-align:middle;
                        margin-left:4px;display:inline-block;">EDITED</span>`
        : formatDateAmend(c.array_enddate);

      const actionButtons = isDeactivated
        ? `<button class="btn-amend-activate"
              onclick="activateCharge('${c.array_recurringchargeid}')"
              title="Re-activate this charge">
              <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5">
                <polyline points="20 6 9 17 4 12"/>
              </svg>
              Activate
           </button>`
        : `<span style="display:inline-flex;gap:6px;align-items:center;">
             <!-- EDIT: blue pencil icon -->
             <button
               onclick="openSupersedeChargeModal('${c.array_recurringchargeid}')"
               title="Edit Charge"
               style="display:inline-flex;align-items:center;justify-content:center;width:30px;height:30px;
                      border-radius:7px;border:1.5px solid #BBDBFF;background:#EBF3FF;color:#0D4A9E;
                      cursor:pointer;transition:all 0.15s;padding:0;"
               onmouseover="this.style.background='#EBF3FF';this.style.borderColor='#1C6BD4';"
               onmouseout="this.style.background='#EBF3FF';this.style.borderColor='#BBDBFF';">
               <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                 <path d="M11 4H4a2 2 0 00-2 2v14a2 2 0 002 2h14a2 2 0 002-2v-7"/>
                 <path d="M18.5 2.5a2.121 2.121 0 013 3L12 15l-4 1 1-4 9.5-9.5z"/>
               </svg>
             </button>
             <!-- DEACTIVATE: amber slash icon -->
             <button
               onclick="openSimpleDeactivateChargeModal_existing('${c.array_recurringchargeid}', ${amendExistingCharges.indexOf(c)})"
               title="Deactivate Charge"
               style="display:inline-flex;align-items:center;justify-content:center;width:30px;height:30px;
                      border-radius:7px;border:1.5px solid #FFCF7F;background:#FFF8EC;color:#7A4F0A;
                      cursor:pointer;transition:all 0.15s;padding:0;"
               onmouseover="this.style.background='#FFCF7F';this.style.borderColor='#7A4F0A';"
               onmouseout="this.style.background='#FFF8EC';this.style.borderColor='#FFCF7F';">
               <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5">
                 <circle cx="12" cy="12" r="10"/>
                 <line x1="4.93" y1="4.93" x2="19.07" y2="19.07"/>
               </svg>
             </button>
           </span>`;

      return `<tr class="${rowClass}" ${rowBg}>
        <td>
          <strong style="text-decoration:none;">${esc(c.array_chargename || "—")}</strong>
          ${isDeactivated ? '<span class="charge-deactivated-badge">INACTIVE</span>' : ""}
          ${
            hasEndDateEdit
              ? `<span style="background:#e0f2fe;color:#0369A1;font-size:10px;font-weight:700;
                                           padding:1px 6px;border-radius:5px;vertical-align:middle;
                                           margin-left:5px;">END DATE EDITED</span>`
              : ""
          }
        </td>
        <td>${esc(unit.array_unitname || "All Units")}</td>
        <td>${esc(chargeType.array_name || "—")}</td>
        <td style="text-align:center;">
          <span style="background:#F1F2F4;color:#475569;padding:3px 10px;border-radius:6px;
                       font-size:11px;font-weight:600;">${freqLabel}</span>
        </td>
        <td>${formatDateAmend(c.array_startdate)}</td>
        <td>${endDateDisplay}</td>
        <td style="text-align:right;font-weight:700;color:${isDeactivated ? "#9CA3AF" : "#1C6BD4"};">
          ${sym}${c.array_amount != null ? parseFloat(c.array_amount).toFixed(2) : "—"}
        </td>
        <td style="text-align:center;white-space:nowrap;">${actionButtons}</td>
      </tr>`;
    })
    .join("");

  renderChargesTotals();
}

