async function loadDiscounts() {
  try {
    const clientUrl = XrmCtx.Utility.getGlobalContext().getClientUrl();
    const url =
      `${clientUrl}/api/data/v9.2/array_discounts` +
      `?$select=array_discountid,array_chargetype,array_discounttype,` +
      `array_discountpercentage,array_discountamount,array_startdate,array_enddate` +
      `&$filter=_array_leaseagreement_value eq ${amendLeaseId} and statecode eq 0`;

    const resp = await fetch(url, {
      headers: {
        "OData-MaxVersion": "4.0",
        "OData-Version": "4.0",
        Accept: "application/json",
        Prefer: 'odata.include-annotations="*"',
      },
      credentials: "same-origin",
    });
    if (!resp.ok) throw new Error(`Discounts fetch: HTTP ${resp.status}`);
    const data = await resp.json();
    amendExistingDiscounts = data.value || [];
    disc_renderDiscountsTable();
    updateBadge(
      "discounts",
      amendExistingDiscounts.length + amendNewDiscounts.length,
    );
  } catch (e) {
    console.error("Error loading discounts:", e);
    const tbody = document.getElementById("existingDiscountsTbody");
    if (tbody)
      tbody.innerHTML = `<tr><td colspan="6" style="text-align:center;padding:30px;color:#B91C1C;">
        Could not load discounts.</td></tr>`;
  }
}

// ════════════════════════════════════════════════════════════════════════════
//  EDIT MODE — Child record loaders
//  Called after all standard load functions in edit mode.
//  Hydrates in-memory arrays with previously staged changes linked to
//  the amendment being re-drafted.
// ════════════════════════════════════════════════════════════════════════════

async function loadAmendmentChildRecords(amendmentId) {
  if (!amendmentId) return;
  console.log(`🔄 Loading child records for amendment: ${amendmentId}`);

  await Promise.all([
    _editLoad_charges(amendmentId),
    _editLoad_units(amendmentId),
    _editLoad_discounts(amendmentId),
    _editLoad_deposits(amendmentId),
    _editLoad_clauses(amendmentId),
    _editLoad_options(amendmentId),
  ]);

  renderExistingChargesTable();
  renderNewChargesTable();
  renderExistingUnitsTable();
  renderNewUnitsTable();
  disc_renderDiscountsTable();
  renderDepositsTable();
  cl_renderClausesTable();
  ao_renderExistingOptionsTable();
  ao_renderNewOptionsTable();

  updateBadge("charges", amendExistingCharges.length + amendNewCharges.length);
  updateBadge("units", amendExistingUnits.length + amendNewUnits.length);
  updateBadge(
    "discounts",
    amendExistingDiscounts.length + amendNewDiscounts.length,
  );
  updateBadge("deposits", amendDeposits.length + amendNewDeposits.length);
  updateBadge("options", amendExistingOptions.length + amendNewOptions.length);

  console.log("✅ Child records hydrated for edit mode.");
}

async function _editLoad_charges(amendmentId) {
  try {
    const clientUrl = XrmCtx.Utility.getGlobalContext().getClientUrl();
    const newResp = await fetch(
      `${clientUrl}/api/data/v9.2/array_recurringcharges` +
        `?$select=array_recurringchargeid,array_chargename,array_amount,array_startdate,` +
        `array_enddate,array_frequency,array_billablearea,array_prorationenabled,` +
        `array_prefrequencyoffset,array_dueindays,array_invoicegenerationdate,array_duedaterule,` +
        `_transactioncurrencyid_value,statecode,statuscode` +
        `&$filter=_array_leaseamendments_value eq ${amendmentId} and statecode ne 0` +
        `&$expand=array_Unit($select=array_unitid,array_unitname),` +
        `array_ChargeType($select=array_chargetypeid,array_name)`,
      {
        headers: {
          "OData-MaxVersion": "4.0",
          "OData-Version": "4.0",
          Accept: "application/json",
          Prefer: 'odata.include-annotations="*"',
        },
        credentials: "same-origin",
      },
    );
    if (newResp.ok) {
      const d = await newResp.json();
      (d.value || []).forEach((c) => {
        if (
          !amendNewCharges.some(
            (x) => x.array_recurringchargeid === c.array_recurringchargeid,
          )
        )
          amendNewCharges.push(c);
      });
    }

    const actionResp = await fetch(
      `${clientUrl}/api/data/v9.2/array_recurringcharges` +
        `?$select=array_recurringchargeid,array_enddate,array_amendmentactions,statecode` +
        `&$filter=_array_leaseagreement_value eq ${amendLeaseId}` +
        ` and _array_leaseamendments_value eq ${amendmentId}` +
        ` and array_amendmentactions ne null and statecode eq 0` +
        `&$expand=array_Unit($select=array_unitid,array_unitname),` +
        `array_ChargeType($select=array_chargetypeid,array_name)`,
      {
        headers: {
          "OData-MaxVersion": "4.0",
          "OData-Version": "4.0",
          Accept: "application/json",
          Prefer: 'odata.include-annotations="*"',
        },
        credentials: "same-origin",
      },
    );
    if (actionResp.ok) {
      const d = await actionResp.json();
      (d.value || []).forEach((c) => {
        const action = c.array_amendmentactions;
        const idx = amendExistingCharges.findIndex(
          (x) => x.array_recurringchargeid === c.array_recurringchargeid,
        );
        if (action === 126330001 && idx !== -1) {
          amendDeactivatedCharges.push({
            ...amendExistingCharges[idx],
            ...c,
            _pendingDeactivate: true,
            _deactivateProration: false,
            _deactivateEndDate: c.array_enddate || "",
          });
          amendExistingCharges.splice(idx, 1);
        } else if (action === 126330002 && idx !== -1) {
          amendExistingCharges[idx]._pendingEndDateEdit = true;
          amendExistingCharges[idx]._pendingEndDate = c.array_enddate || "";
        }
      });
    }
    amendCharges = [...amendExistingCharges, ...amendNewCharges];
  } catch (e) {
    console.warn("_editLoad_charges: failed (non-fatal):", e);
  }
}

async function _editLoad_units(amendmentId) {
  try {
    const clientUrl = XrmCtx.Utility.getGlobalContext().getClientUrl();
    const newResp = await fetch(
      `${clientUrl}/api/data/v9.2/array_leaseunitassociations` +
        `?$select=array_leaseunitassociationid,array_startdate,array_enddate,statecode` +
        `&$filter=_array_leaseamendments_value eq ${amendmentId} and statecode ne 0` +
        `&$expand=array_Unit($select=array_unitid,array_unitname,array_unitareasqm)`,
      {
        headers: {
          "OData-MaxVersion": "4.0",
          "OData-Version": "4.0",
          Accept: "application/json",
          Prefer: 'odata.include-annotations="*"',
        },
        credentials: "same-origin",
      },
    );
    if (newResp.ok) {
      const d = await newResp.json();
      (d.value || []).forEach((u) => {
        if (
          !amendNewUnits.some(
            (x) =>
              (x._assoc?.array_leaseunitassociationid ||
                x.array_leaseunitassociationid) ===
              u.array_leaseunitassociationid,
          )
        )
          amendNewUnits.push({ ...u, _assoc: u, array_Unit: u.array_Unit });
      });
    }

    const actionResp = await fetch(
      `${clientUrl}/api/data/v9.2/array_leaseunitassociations` +
        `?$select=array_leaseunitassociationid,array_enddate,array_amendmentactions,array_amendmentenddate,statecode` +
        `&$filter=_array_leaseagreement_value eq ${amendLeaseId}` +
        ` and _array_leaseamendments_value eq ${amendmentId}` +
        ` and array_amendmentactions ne null and statecode eq 0` +
        `&$expand=array_Unit($select=array_unitid,array_unitname,array_unitareasqm)`,
      {
        headers: {
          "OData-MaxVersion": "4.0",
          "OData-Version": "4.0",
          Accept: "application/json",
          Prefer: 'odata.include-annotations="*"',
        },
        credentials: "same-origin",
      },
    );
    if (actionResp.ok) {
      const d = await actionResp.json();
      (d.value || []).forEach((u) => {
        const action = u.array_amendmentactions;
        const idx = amendExistingUnits.findIndex(
          (x) =>
            x.array_leaseunitassociationid === u.array_leaseunitassociationid,
        );
        if (action === 126330001 && idx !== -1) {
          amendDeactivatedUnits.push({
            ...amendExistingUnits[idx],
            ...u,
            _pendingDeactivate: true,
          });
          amendExistingUnits.splice(idx, 1);
        } else if (action === 126330002) {
          if (
            !amendEditedUnits.some(
              (x) => x.assocId === u.array_leaseunitassociationid,
            )
          )
            amendEditedUnits.push({
              assocId: u.array_leaseunitassociationid,
              endDate: u.array_amendmentenddate || u.array_enddate || "",
            });
        }
      });
    }
    amendUnits = [
      ...amendExistingUnits,
      ...amendNewUnits.map((u) => u._assoc),
    ].filter(Boolean);
  } catch (e) {
    console.warn("_editLoad_units: failed (non-fatal):", e);
  }
}

async function _editLoad_discounts(amendmentId) {
  try {
    const clientUrl = XrmCtx.Utility.getGlobalContext().getClientUrl();
    const resp = await fetch(
      `${clientUrl}/api/data/v9.2/array_discounts` +
        `?$select=array_discountid,array_chargetype,array_discounttype,array_discountpercentage,array_discountamount,array_startdate,array_enddate,statecode,array_amendmentactions` +
        `&$filter=_array_leaseamendments_value eq ${amendmentId}`,
      {
        headers: {
          "OData-MaxVersion": "4.0",
          "OData-Version": "4.0",
          Accept: "application/json",
          Prefer: 'odata.include-annotations="*"',
        },
        credentials: "same-origin",
      },
    );
    if (!resp.ok) return;
    const d = await resp.json();
    (d.value || []).forEach((rec) => {
      if (rec.statecode !== 0) {
        if (
          !amendNewDiscounts.some(
            (x) => x.array_discountid === rec.array_discountid,
          )
        )
          amendNewDiscounts.push(rec);
      } else if (rec.array_amendmentactions === 126330001) {
        const idx = amendExistingDiscounts.findIndex(
          (x) => x.array_discountid === rec.array_discountid,
        );
        if (idx !== -1) {
          amendDeactivatedDiscounts.push({
            ...amendExistingDiscounts[idx],
            _pendingDeactivate: true,
          });
          amendExistingDiscounts.splice(idx, 1);
        }
      }
    });
  } catch (e) {
    console.warn("_editLoad_discounts: failed (non-fatal):", e);
  }
}

