async function _editLoad_clauses(amendmentId) {
  try {
    const clientUrl = XrmCtx.Utility.getGlobalContext().getClientUrl();
    const resp = await fetch(
      `${clientUrl}/api/data/v9.2/array_leaseclauses` +
        `?$select=array_leaseclauseid,array_clausetype,array_description,array_startdate,array_enddate,array_expirydate,statecode,array_amendmentactions` +
        `&$filter=_array_leaseamendments_value eq ${amendmentId}`,
      {
        headers: {
          "OData-MaxVersion": "4.0",
          "OData-Version": "4.0",
          Accept: "application/json",
          Prefer: 'odata.include-annotations="*"',
        },
        credentials: "same-origin",
      },
    );
    if (!resp.ok) return;
    const d = await resp.json();
    (d.value || []).forEach((rec) => {
      if (rec.statecode !== 0) {
        if (
          typeof amendNewClauses !== "undefined" &&
          !amendNewClauses.some(
            (x) => x.array_leaseclauseid === rec.array_leaseclauseid,
          )
        )
          amendNewClauses.push(rec);
      } else if (rec.array_amendmentactions === 126330001) {
        if (
          !pendingClauseExpiryUpdates.some(
            (x) => x.id === rec.array_leaseclauseid,
          )
        )
          pendingClauseExpiryUpdates.push({
            id: rec.array_leaseclauseid,
            newExpiryDate: rec.array_expirydate || rec.array_enddate || "",
          });
      }
    });
  } catch (e) {
    console.warn("_editLoad_clauses: failed (non-fatal):", e);
  }
}

