// ── Load Deposits ────────────────────────────────────────────
async function loadDeposits() {
  try {
    const clientUrl = XrmCtx.Utility.getGlobalContext().getClientUrl();
    const url = `${clientUrl}/api/data/v9.2/array_deposits?$select=array_depositid,array_type,array_deposittype,array_requiredamount,array_duedate,array_numberofpayments,array_collateralapproved,array_deliverydate,array_expirydate,array_guaranteeno,array_comment&$filter=_array_leaseagreement_value eq ${amendLeaseId} and statecode eq 0&$expand=array_Unit($select=array_unitid,array_unitname),array_RequiredAmountCurrency($select=transactioncurrencyid,currencyname,isocurrencycode,currencysymbol)`;
    const resp = await fetch(url, {
      headers: {
        "OData-MaxVersion": "4.0",
        "OData-Version": "4.0",
        Accept: "application/json",
        Prefer: 'odata.include-annotations="*"',
      },
      credentials: "same-origin",
    });
    if (!resp.ok) throw new Error(`Deposits fetch: HTTP ${resp.status}`);
    const data = await resp.json();
    amendDeposits = data.value || [];
    // Do NOT reset amendNewDeposits or pendingDepositUpdates — those are session-staged
    renderDepositsTable();
    updateBadge("deposits", amendDeposits.length + amendNewDeposits.length);
  } catch (e) {
    console.error("Error loading deposits:", e);
    setTableError("depositsTbody", 7, "Could not load security & insurance.");
  }
}

// ── Render Deposits Table  ──────────────────────────
function renderDepositsTable() {
  const tbody = document.getElementById("depositsTbody");
  const newTbody = document.getElementById("newDepositsTbody");

  // Existing deposits = active (amendDeposits) + deactivated-this-session
  // (amendDeactivatedDeposits, e.g. records superseded by a full-field edit).
  const allExistingDeposits = [
    ...amendDeposits.map((d) => ({ ...d, _deactivated: false })),
    ...amendDeactivatedDeposits.map((d) => ({ ...d, _deactivated: true })),
  ];

  const existingPill = document.getElementById("existingDepositsCountPill");
  if (existingPill)
    existingPill.textContent = `${allExistingDeposits.length} record${allExistingDeposits.length !== 1 ? "s" : ""}`;

  if (!allExistingDeposits.length) {
    tbody.innerHTML = `<tr><td colspan="7"><div class="amend-empty"><svg width="48" height="48" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><rect x="1" y="4" width="22" height="16" rx="2"/><line x1="1" y1="10" x2="23" y2="10"/></svg><p>No existing security &amp; insurance records</p><span>Records loaded from the lease will appear here</span></div></td></tr>`;
  } else {
    tbody.innerHTML = allExistingDeposits
      .map((d, i) => {
        const unit = d.array_Unit || {};
        const ccy = d.array_RequiredAmountCurrency || {};
        const sym = ccy.currencysymbol || "";
        const typeLabel =
          d["array_type@OData.Community.Display.V1.FormattedValue"] ||
          getOptionLabel(amendCollateralTypes, d.array_type) ||
          "—";
        const subTypeLabel =
          d["array_deposittype@OData.Community.Display.V1.FormattedValue"] ||
          getOptionLabel(amendDepositSubTypes, d.array_deposittype) ||
          "—";
        const pendingEdit = pendingDepositUpdates.find(
          (p) => p.id === d.array_depositid,
        );
        const displayDueDate = pendingEdit
          ? pendingEdit.dueDate
          : d.array_duedate;
        return `<tr style="${i % 2 === 0 ? "background:#F8F9FC" : ""}">
                <td>${esc(unit.array_unitname || "All Units")}</td>
                <td><span class="status-pill" style="background:#e0f2fe;color:#0369A1;">${esc(typeLabel)}</span>${d._deactivated ? '<span class="charge-deactivated-badge">INACTIVE</span>' : ""}</td>
                <td>${esc(subTypeLabel)}</td>
                <td>${formatDateAmend(displayDueDate)}${pendingEdit ? ' <span style="background:#FFF8EC;color:#854d0e;font-size:10px;font-weight:700;padding:1px 6px;border-radius:6px;vertical-align:middle;">EDITED</span>' : ""}</td>
                <td style="text-align:right;font-weight:700;color:#7A4F0A;">${sym}${d.array_requiredamount != null ? parseFloat(d.array_requiredamount).toFixed(2) : "—"}</td>
                <td style="text-align:center;">${esc(ccy.isocurrencycode || "—")}</td>
                <td style="text-align:center;white-space:nowrap;">
                    ${
                      d._deactivated
                        ? ""
                        : `<button
                      onclick="openEditDepositModal(${i}, true)"
                      title="Edit"
                      style="display:inline-flex;align-items:center;justify-content:center;width:30px;height:30px;border-radius:7px;border:1.5px solid #BBDBFF;background:#EBF3FF;color:#0D4A9E;cursor:pointer;transition:all 0.15s;padding:0;"
                      onmouseover="this.style.background='#EBF3FF';this.style.borderColor='#1C6BD4';"
                      onmouseout="this.style.background='#EBF3FF';this.style.borderColor='#BBDBFF';">
                      <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                        <path d="M11 4H4a2 2 0 00-2 2v14a2 2 0 002 2h14a2 2 0 002-2v-7"/>
                        <path d="M18.5 2.5a2.121 2.121 0 013 3L12 15l-4 1 1-4 9.5-9.5z"/>
                      </svg>
                    </button>`
                    }
                </td>
            </tr>`;
      })
      .join("");
  }

  const newPill = document.getElementById("newDepositsCountPill");
  if (newPill)
    newPill.textContent = `${amendNewDeposits.length} record${amendNewDeposits.length !== 1 ? "s" : ""}`;

  if (!amendNewDeposits.length) {
    newTbody.innerHTML = `<tr><td colspan="7" style="text-align:center;padding:28px;color:#9CA3AF;font-size:13px;">
            <svg width="36" height="36" viewBox="0 0 24 24" fill="none" stroke="#CBD5E1" stroke-width="1.5" style="display:block;margin:0 auto 8px;"><rect x="1" y="4" width="22" height="16" rx="2"/><line x1="1" y1="10" x2="23" y2="10"/></svg>
            No new security &amp; insurance added yet. Click <strong style="color:#2E7D32;">"Add Security"</strong> to create one.
        </td></tr>`;
  } else {
    newTbody.innerHTML = amendNewDeposits
      .map((d, i) => {
        const unit = d._unitName || "All Units";
        const ccy = d._currencyCode || "—";
        const sym = d._currencySymbol || "";
        const typeLabel = d._typeLabel || "—";
        // ── FIX: only show _subTypeLabel, never issuer name ──
        const subTypeLabel = d._subTypeLabel || "—";

        const isDeposit =
          String(d.array_type) === String(getDepositTypeValue());
        // Bank name shown as a subtle secondary line under sub type (deposit only)
        const bankLine =
          isDeposit && d._bankName
            ? `<div style="font-size:10px;color:#9CA3AF;margin-top:2px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;max-width:140px;" title="${esc(d._bankName)}">
               <svg width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="#9CA3AF" stroke-width="2" style="vertical-align:middle;margin-right:2px;">
                 <rect x="1" y="4" width="22" height="16" rx="2"/><line x1="1" y1="10" x2="23" y2="10"/>
               </svg>${esc(d._bankName)}
             </div>`
            : "";
        // Issuer shown as a subtle secondary line (non-deposit only)
        const issuerLine =
          !isDeposit && d._issuerName
            ? `<div style="font-size:10px;color:#9CA3AF;margin-top:2px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;max-width:140px;" title="${esc(d._issuerName)}">
               <svg width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="#9CA3AF" stroke-width="2" style="vertical-align:middle;margin-right:2px;">
                 <path d="M17 21v-2a4 4 0 00-4-4H5a4 4 0 00-4 4v2"/><circle cx="9" cy="7" r="4"/>
               </svg>${esc(d._issuerName)}
             </div>`
            : "";

        return `<tr style="${i % 2 === 0 ? "background:#F8F9FC" : ""}">
                <td>${esc(unit)}</td>
                <td><span class="status-pill" style="background:#e0f2fe;color:#0369A1;">${esc(typeLabel)}</span></td>
                <td>
                  <div>${esc(subTypeLabel)}</div>
                  ${bankLine}${issuerLine}
                </td>
                <td>${formatDateAmend(d.array_duedate)}</td>
                <td style="text-align:right;font-weight:700;color:#2E7D32;">${sym}${d.array_requiredamount != null ? parseFloat(d.array_requiredamount).toFixed(2) : "—"}</td>
                <td style="text-align:center;">${esc(ccy)}</td>
                <td style="text-align:center;white-space:nowrap;">
                    <button
                      onclick="openEditDepositModal(${i}, false)"
                      title="Edit"
                      style="display:inline-flex;align-items:center;justify-content:center;width:30px;height:30px;border-radius:7px;border:1.5px solid #BBDBFF;background:#EBF3FF;color:#0D4A9E;cursor:pointer;transition:all 0.15s;padding:0;margin-right:4px;"
                      onmouseover="this.style.background='#EBF3FF';this.style.borderColor='#1C6BD4';"
                      onmouseout="this.style.background='#EBF3FF';this.style.borderColor='#BBDBFF';">
                      <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                        <path d="M11 4H4a2 2 0 00-2 2v14a2 2 0 002 2h14a2 2 0 002-2v-7"/>
                        <path d="M18.5 2.5a2.121 2.121 0 013 3L12 15l-4 1 1-4 9.5-9.5z"/>
                      </svg>
                    </button>
                    <button
                      onclick="removeNewDeposit(${i})"
                      title="Remove"
                      style="display:inline-flex;align-items:center;justify-content:center;width:30px;height:30px;border-radius:7px;border:1.5px solid #FCA5A5;background:#FEF2F2;color:#B91C1C;cursor:pointer;transition:all 0.15s;padding:0;"
                      onmouseover="this.style.background='#FEF2F2';this.style.borderColor='#B91C1C';"
                      onmouseout="this.style.background='#FEF2F2';this.style.borderColor='#FCA5A5';">
                      <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                        <polyline points="3 6 5 6 21 6"/>
                        <path d="M19 6l-1 14H6L5 6"/>
                        <path d="M10 11v6M14 11v6"/>
                        <path d="M9 6V4h6v2"/>
                      </svg>
                    </button>
                </td>
            </tr>`;
      })
      .join("");
  }

  updateBadge("deposits", amendDeposits.length + amendNewDeposits.length);
  renderDepositsSummaryPanel();
}

