// ══════════════════════════════════════════════════════════════
//  VALIDATION ENGINE
//  Runs against all in-memory state; returns a list of issues
//  Each issue: { id, severity, step, stepIndex, message, action? }
//  - id: stable identifier so we can dedupe / re-render in place
//  - severity: 'warning' | 'info'
//  - step: human-readable step name
//  - stepIndex: WIZARD_STAGES index for "Go to step" button
//  - message: end-user text
//  - action: optional { label, handler } for inline fix buttons (e.g. auto-cap)
// ══════════════════════════════════════════════════════════════
const VALIDATION_STEP_INDEX = {
  terms: 2,
  fileupload: 1,
  units: 3,
  charges: 4,
  discounts: 5,
  deposits: 6,
  clauses: 7,
  options: 8,
  notes: 9,
  preview: 10,
};

// Run all 15 validation rules and return aggregated issues
function runValidations() {
  const issues = [];
  const effEnd = getEffectiveLeaseEnd();
  const effStart = document.getElementById("amend_startDate")?.value || "";
  const leaseStart = amendLeaseData?.array_leasestartdate
    ? amendLeaseData.array_leasestartdate.substring(0, 10)
    : "";
  const leaseEndRaw = amendLeaseData?.array_leaseenddate
    ? amendLeaseData.array_leaseenddate.substring(0, 10)
    : "";

  // Helper to push an issue
  const push = (issue) => issues.push(issue);

  // Helper: find unit assoc for a given unit id
  const findAssocByUnitId = (unitId) =>
    (amendExistingUnits || []).find(
      (u) => (u.array_Unit?.array_unitid || "") === unitId,
    );

  // ── #1: Unit end-date cascade — for each edited unit (shortened), find related records past new end ──
  (amendEditedUnits || []).forEach((edit) => {
    const newEnd = edit.endDate ? edit.endDate.substring(0, 10) : null;
    if (!newEnd) return;
    const assoc = (amendExistingUnits || []).find(
      (u) => u.array_leaseunitassociationid === edit.assocId,
    );
    if (!assoc) return;
    const unitId = assoc.array_Unit?.array_unitid || "";
    const unitName = assoc.array_Unit?.array_unitname || "this unit";
    const affectedCharges = (amendExistingCharges || []).filter((c) => {
      const cu = c.array_Unit?.array_unitid || "";
      const ce = c.array_enddate ? c.array_enddate.substring(0, 10) : null;
      return cu === unitId && ce && ce > newEnd;
    });
    const affectedDeposits = (amendDeposits || []).filter((d) => {
      const du = d._array_unit_value || d.array_Unit?.array_unitid || "";
      const de = d.array_duedate ? d.array_duedate.substring(0, 10) : null;
      return du === unitId && de && de > newEnd;
    });
    const affectedClauses = (amendClauses || []).filter((cl) => {
      const clu = cl._array_unit_value || cl.array_Unit?.array_unitid || "";
      const cle = cl.array_expirydate
        ? cl.array_expirydate.substring(0, 10)
        : null;
      return clu === unitId && cle && cle > newEnd;
    });
    const total =
      affectedCharges.length + affectedDeposits.length + affectedClauses.length;
    if (total > 0) {
      const parts = [];
      if (affectedCharges.length)
        parts.push(
          `${affectedCharges.length} charge${affectedCharges.length > 1 ? "s" : ""}`,
        );
      if (affectedDeposits.length)
        parts.push(
          `${affectedDeposits.length} deposit${affectedDeposits.length > 1 ? "s" : ""}`,
        );
      if (affectedClauses.length)
        parts.push(
          `${affectedClauses.length} clause${affectedClauses.length > 1 ? "s" : ""}`,
        );
      push({
        id: `gap1-${edit.assocId}`,
        severity: "warning",
        step: "Units",
        stepIndex: VALIDATION_STEP_INDEX.units,
        message: `${unitName} end date shortened to ${formatDateAmend(newEnd)}. ${parts.join(", ")} extend past this date and will become inconsistent.`,
        action: {
          label: `Auto-cap ${total} record${total > 1 ? "s" : ""} to ${formatDateAmend(newEnd)}`,
          handler: () => {
            affectedCharges.forEach((c) => {
              c.array_enddate = newEnd + "T00:00:00Z";
              c._pendingEndDateEdit = true;
            });
            affectedDeposits.forEach((d) => {
              d.array_duedate = newEnd + "T00:00:00Z";
              d._pendingDueDateEdit = true;
            });
            affectedClauses.forEach((cl) => {
              cl.array_expirydate = newEnd + "T00:00:00Z";
              cl._pendingExpiryDateEdit = true;
            });
          },
        },
      });
    }
  });

  // ── #2, #3, #4: Charge dates vs unit/effective lease end ──
  const allCharges = [
    ...(amendExistingCharges || []),
    ...(amendNewCharges || []),
  ];
  allCharges.forEach((c, idx) => {
    const cs = c.array_startdate ? c.array_startdate.substring(0, 10) : null;
    const ce = c.array_enddate ? c.array_enddate.substring(0, 10) : null;
    const cName =
      c.array_recurringchargename || c.array_name || `Charge ${idx + 1}`;
    const cUnitId = c.array_Unit?.array_unitid || "";
    if (cUnitId) {
      const assoc = findAssocByUnitId(cUnitId);
      if (assoc) {
        const us = assoc.array_startdate
          ? assoc.array_startdate.substring(0, 10)
          : null;
        const ue = assoc.array_enddate
          ? assoc.array_enddate.substring(0, 10)
          : null;
        const uName = assoc.array_Unit?.array_unitname || "the linked unit";
        if (us && cs && cs < us) {
          push({
            id: `gap3-${c.array_recurringchargeid || idx}`,
            severity: "warning",
            step: "Recurring Charges",
            stepIndex: VALIDATION_STEP_INDEX.charges,
            message: `Charge "${cName}" starts ${formatDateAmend(cs)}, before ${uName}'s start (${formatDateAmend(us)}).`,
          });
        }
        if (ue && ce && ce > ue) {
          push({
            id: `gap2-${c.array_recurringchargeid || idx}`,
            severity: "warning",
            step: "Recurring Charges",
            stepIndex: VALIDATION_STEP_INDEX.charges,
            message: `Charge "${cName}" ends ${formatDateAmend(ce)}, after ${uName}'s end (${formatDateAmend(ue)}).`,
          });
        }
      }
    }
    if (effEnd && ce && ce > effEnd) {
      push({
        id: `gap4-${c.array_recurringchargeid || idx}`,
        severity: "warning",
        step: "Recurring Charges",
        stepIndex: VALIDATION_STEP_INDEX.charges,
        message: `Charge "${cName}" ends ${formatDateAmend(ce)}, after lease/amendment end (${formatDateAmend(effEnd)}).`,
      });
    }
  });

  // ── #5: Deposit due date outside lease term ──
  (amendDeposits || []).forEach((d, idx) => {
    const due = d.array_duedate ? d.array_duedate.substring(0, 10) : null;
    const dName = d.array_name || `Deposit ${idx + 1}`;
    if (!due) return;
    if (leaseStart && due < leaseStart) {
      push({
        id: `gap5-before-${d.array_depositid || idx}`,
        severity: "warning",
        step: "Security & Insurance",
        stepIndex: VALIDATION_STEP_INDEX.deposits,
        message: `Deposit "${dName}" due ${formatDateAmend(due)}, before lease start (${formatDateAmend(leaseStart)}).`,
      });
    }
    if (effEnd && due > effEnd) {
      push({
        id: `gap5-after-${d.array_depositid || idx}`,
        severity: "warning",
        step: "Security & Insurance",
        stepIndex: VALIDATION_STEP_INDEX.deposits,
        message: `Deposit "${dName}" due ${formatDateAmend(due)}, after lease/amendment end (${formatDateAmend(effEnd)}).`,
      });
    }
  });

  // ── #6, #7: Discount checks ──
  const allDiscounts = [
    ...(amendExistingDiscounts || []),
    ...(amendNewDiscounts || []),
  ];
  allDiscounts.forEach((d, idx) => {
    const ds = d.array_startdate ? d.array_startdate.substring(0, 10) : null;
    const de = d.array_enddate ? d.array_enddate.substring(0, 10) : null;
    const dName = d.array_name || `Discount ${idx + 1}`;
    // #6: Linked to a specific charge → must fit inside charge dates
    const linkedRcId =
      d._array_recurringcharge_value ||
      d.array_RecurringCharge?.array_recurringchargeid ||
      "";
    if (linkedRcId) {
      const linkedC = allCharges.find(
        (c) =>
          (c.array_recurringchargeid || "").toLowerCase() ===
          String(linkedRcId).toLowerCase(),
      );
      if (linkedC) {
        const cs = linkedC.array_startdate
          ? linkedC.array_startdate.substring(0, 10)
          : null;
        const ce = linkedC.array_enddate
          ? linkedC.array_enddate.substring(0, 10)
          : null;
        const cName = linkedC.array_recurringchargename || "the linked charge";
        if (cs && ds && ds < cs) {
          push({
            id: `gap6-start-${d.array_discountid || idx}`,
            severity: "warning",
            step: "Discounts",
            stepIndex: VALIDATION_STEP_INDEX.discounts,
            message: `Discount "${dName}" starts ${formatDateAmend(ds)}, before "${cName}" starts (${formatDateAmend(cs)}) — will silently not apply.`,
          });
        }
        if (ce && de && de > ce) {
          push({
            id: `gap6-end-${d.array_discountid || idx}`,
            severity: "warning",
            step: "Discounts",
            stepIndex: VALIDATION_STEP_INDEX.discounts,
            message: `Discount "${dName}" ends ${formatDateAmend(de)}, after "${cName}" ends (${formatDateAmend(ce)}) — will silently not apply.`,
          });
        }
      }
    }
    // #7: Lease/amendment bounds
    if (effStart && ds && ds < effStart) {
      push({
        id: `gap7-start-${d.array_discountid || idx}`,
        severity: "warning",
        step: "Discounts",
        stepIndex: VALIDATION_STEP_INDEX.discounts,
        message: `Discount "${dName}" starts ${formatDateAmend(ds)}, before amendment effective date (${formatDateAmend(effStart)}).`,
      });
    }
    if (effEnd && de && de > effEnd) {
      push({
        id: `gap7-end-${d.array_discountid || idx}`,
        severity: "warning",
        step: "Discounts",
        stepIndex: VALIDATION_STEP_INDEX.discounts,
        message: `Discount "${dName}" ends ${formatDateAmend(de)}, after lease/amendment end (${formatDateAmend(effEnd)}).`,
      });
    }
  });

  // ── #8: Lease expiry extension — backend gap, informational ──
  if (effEnd && leaseEndRaw && effEnd > leaseEndRaw) {
    push({
      id: "gap8-backend",
      severity: "info",
      step: "Lease Terms",
      stepIndex: VALIDATION_STEP_INDEX.terms,
      message: `Lease expiry is being extended from ${formatDateAmend(leaseEndRaw)} to ${formatDateAmend(effEnd)}. Note: individual unit associations are not auto-extended yet (handled by backend in a future release).`,
    });
  }

  // ── #9: Clause dates outside lease term ──
  const allClauses = [...(amendClauses || []), ...(amendNewClauses || [])];
  allClauses.forEach((cl, idx) => {
    const eff = cl.array_effectivedate
      ? cl.array_effectivedate.substring(0, 10)
      : null;
    const exp = cl.array_expirydate
      ? cl.array_expirydate.substring(0, 10)
      : null;
    const cName = cl.array_clausename || cl.array_name || `Clause ${idx + 1}`;
    if (leaseStart && eff && eff < leaseStart) {
      push({
        id: `gap9-eff-${cl.array_leaseclauseid || idx}`,
        severity: "warning",
        step: "Financial Clauses",
        stepIndex: VALIDATION_STEP_INDEX.clauses,
        message: `Clause "${cName}" effective ${formatDateAmend(eff)}, before lease start (${formatDateAmend(leaseStart)}).`,
      });
    }
    if (effEnd && exp && exp > effEnd) {
      push({
        id: `gap9-exp-${cl.array_leaseclauseid || idx}`,
        severity: "warning",
        step: "Financial Clauses",
        stepIndex: VALIDATION_STEP_INDEX.clauses,
        message: `Clause "${cName}" expires ${formatDateAmend(exp)}, after lease/amendment end (${formatDateAmend(effEnd)}).`,
      });
    }
  });

  // ── #10, #11: Lease option checks ──
  const allOptions = [
    ...(amendExistingOptions || []),
    ...(amendNewOptions || []),
  ];
  allOptions.forEach((o, idx) => {
    const oExp = o.array_expirydate
      ? o.array_expirydate.substring(0, 10)
      : null;
    const oAvail = o.array_executiondate
      ? o.array_executiondate.substring(0, 10)
      : null;
    const oNotice = o.array_noticedeadline
      ? o.array_noticedeadline.substring(0, 10)
      : null;
    const oName = o.array_optionname || o.array_name || `Option ${idx + 1}`;
    // #10: Notice deadline >= expiry
    if (oNotice && oExp && oNotice >= oExp) {
      push({
        id: `gap10-${o.array_leaseoptionid || idx}`,
        severity: "warning",
        step: "Lease Options",
        stepIndex: VALIDATION_STEP_INDEX.options,
        message: `Option "${oName}" notice deadline (${formatDateAmend(oNotice)}) is on or after the expiry date (${formatDateAmend(oExp)}).`,
      });
    }
    // #11: Available From / Expiry outside lease term
    if (leaseStart && oAvail && oAvail < leaseStart) {
      push({
        id: `gap11-avail-${o.array_leaseoptionid || idx}`,
        severity: "warning",
        step: "Lease Options",
        stepIndex: VALIDATION_STEP_INDEX.options,
        message: `Option "${oName}" available from ${formatDateAmend(oAvail)}, before lease start (${formatDateAmend(leaseStart)}).`,
      });
    }
    if (effEnd && oExp && oExp > effEnd) {
      push({
        id: `gap11-exp-${o.array_leaseoptionid || idx}`,
        severity: "warning",
        step: "Lease Options",
        stepIndex: VALIDATION_STEP_INDEX.options,
        message: `Option "${oName}" expires ${formatDateAmend(oExp)}, after lease/amendment end (${formatDateAmend(effEnd)}).`,
      });
    }
  });

  // ── #12: Occupied unit selected ──
  // Check newly added units for occupied conflict (stamped during selection in modal)
  (amendNewUnits || []).forEach((u, idx) => {
    if (u._wasOccupied) {
      const uName =
        u._assoc?.array_Unit?.array_unitname || u.unitName || `Unit ${idx + 1}`;
      push({
        id: `gap12-${u._assoc?.array_leaseunitassociationid || idx}`,
        severity: "warning",
        step: "Units",
        stepIndex: VALIDATION_STEP_INDEX.units,
        message: `${uName} was occupied on another lease at selection time. Saving will create a future-dated association that may overlap.`,
      });
    }
  });

  // ── #13: Effective date >90 days in the past ──
  if (effStart) {
    const today = new Date().toISOString().substring(0, 10);
    if (effStart < today) {
      const daysAgo = Math.round(
        (new Date(today) - new Date(effStart)) / 86400000,
      );
      if (daysAgo > 90) {
        push({
          id: "gap13",
          severity: "info",
          step: "Lease Terms",
          stepIndex: VALIDATION_STEP_INDEX.terms,
          message: `Effective date is ${daysAgo} days in the past (${formatDateAmend(effStart)}). Backdating by more than 90 days is unusual — please confirm this is intentional.`,
        });
      }
    }
  }

  // ── #14: Amendment Type "Renewal" without renewal option ──
  if (
    typeof selectedAmendmentTypes !== "undefined" &&
    Array.isArray(selectedAmendmentTypes)
  ) {
    const renewalTypeIds = (amendmentTypeOptions || [])
      .filter((opt) => {
        const lbl = (opt.Label?.UserLocalizedLabel?.Label || "").toLowerCase();
        return lbl.includes("renewal") || lbl.includes("renew");
      })
      .map((opt) => opt.Value);
    const hasRenewalType = selectedAmendmentTypes.some(
      (v) =>
        renewalTypeIds.includes(parseInt(v, 10)) || renewalTypeIds.includes(v),
    );
    if (hasRenewalType) {
      // Look for a Renewal lease option (by type label)
      const hasRenewalOption = allOptions.some((o) => {
        const t = (
          o["array_optiontype@OData.Community.Display.V1.FormattedValue"] ||
          o.array_optiontype_label ||
          ""
        ).toLowerCase();
        return t.includes("renewal") || t.includes("renew");
      });
      if (!hasRenewalOption) {
        push({
          id: "gap14",
          severity: "warning",
          step: "Lease Options",
          stepIndex: VALIDATION_STEP_INDEX.options,
          message: `Amendment type "Renewal" is selected but no Renewal lease option exists. Consider adding one to record the renewal terms.`,
        });
      }
    }
  }

  // ── #15: Unit deactivation leaving active deposits/clauses ──
  (amendDeactivatedUnits || []).forEach((du, idx) => {
    const unitId = du.array_Unit?.array_unitid || "";
    const uName = du.array_Unit?.array_unitname || `Unit ${idx + 1}`;
    if (!unitId) return;
    const linkedDeposits = (amendDeposits || []).filter((d) => {
      const x = d._array_unit_value || d.array_Unit?.array_unitid || "";
      return x === unitId;
    });
    const linkedClauses = (amendClauses || []).filter((cl) => {
      const x = cl._array_unit_value || cl.array_Unit?.array_unitid || "";
      return x === unitId;
    });
    if (linkedDeposits.length || linkedClauses.length) {
      const parts = [];
      if (linkedDeposits.length)
        parts.push(
          `${linkedDeposits.length} deposit${linkedDeposits.length > 1 ? "s" : ""}`,
        );
      if (linkedClauses.length)
        parts.push(
          `${linkedClauses.length} clause${linkedClauses.length > 1 ? "s" : ""}`,
        );
      push({
        id: `gap15-${du.array_leaseunitassociationid || idx}`,
        severity: "warning",
        step: "Units",
        stepIndex: VALIDATION_STEP_INDEX.units,
        message: `${uName} is being deactivated but has ${parts.join(" and ")} still linked. These will remain active — review and deactivate manually if needed.`,
      });
    }
  });

  // ── REQUIRED-FIELD VALIDATIONS (blocking) ─────────────────────────
  // These map to Dataverse-required attributes. Catching them here means
  // the user sees one consolidated error list on the Preview page BEFORE
  // they click Save — instead of getting a server 400 mid-save with the
  // amendment left in an inconsistent half-saved state.

  // --- Discounts: amount/percentage is required ---
  (amendNewDiscounts || []).forEach((d, idx) => {
    const pct = d.array_discountpercentage;
    const amt = d.array_discountamount;
    const hasValue =
      (pct !== undefined &&
        pct !== null &&
        pct !== "" &&
        !isNaN(parseFloat(pct))) ||
      (amt !== undefined &&
        amt !== null &&
        amt !== "" &&
        !isNaN(parseFloat(amt)));
    if (!hasValue) {
      push({
        id: `req-disc-amount-${idx}`,
        severity: "error",
        step: "Discounts",
        stepIndex: VALIDATION_STEP_INDEX.discounts,
        message: `Discount #${idx + 1} is missing an amount/percentage. Open the discount and enter a value.`,
      });
    }
  });

  // --- Recurring charges (new): currency, charge type, amount required ---
  (pendingNewCharges || []).forEach((c, idx) => {
    const cName = c.name || c.array_chargename || `Charge #${idx + 1}`;
    const ccy = c.currency || c._transactioncurrencyid_value;
    if (!ccy) {
      push({
        id: `req-charge-ccy-${idx}`,
        severity: "error",
        step: "Recurring Charges",
        stepIndex: VALIDATION_STEP_INDEX.charges,
        message: `Charge "${cName}" is missing a currency. Open the charge and select one.`,
      });
    }
    const amt = c.amount != null ? c.amount : c.array_amount;
    if (
      amt == null ||
      amt === "" ||
      isNaN(parseFloat(amt)) ||
      parseFloat(amt) <= 0
    ) {
      push({
        id: `req-charge-amt-${idx}`,
        severity: "error",
        step: "Recurring Charges",
        stepIndex: VALIDATION_STEP_INDEX.charges,
        message: `Charge "${cName}" is missing a valid amount.`,
      });
    }
    const ct = c.chargeType || c._array_chargetype_value;
    if (!ct) {
      push({
        id: `req-charge-type-${idx}`,
        severity: "error",
        step: "Recurring Charges",
        stepIndex: VALIDATION_STEP_INDEX.charges,
        message: `Charge "${cName}" is missing a Charge Type.`,
      });
    }
    // AI-prefilled charges carry only part of the charge setup (no invoice
    // type, due date rule, frequency start…). The user must open and save
    // them once in the charge form; saving clears this flag.
    if (c._aiIncomplete === true) {
      push({
        id: `req-charge-ai-${idx}`,
        severity: "error",
        step: "Recurring Charges",
        stepIndex: VALIDATION_STEP_INDEX.charges,
        message: `Charge "${cName}" was prefilled from the document. Open it, review and save it.`,
      });
    }
  });

  // --- Deposits / Security & Insurance: type, amount, currency ---
  (amendNewDeposits || []).forEach((d, idx) => {
    const label = d._typeLabel || d.array_name || `Record #${idx + 1}`;
    if (d.array_type == null || d.array_type === "") {
      push({
        id: `req-dep-type-${idx}`,
        severity: "error",
        step: "Security & Insurance",
        stepIndex: VALIDATION_STEP_INDEX.deposits,
        message: `Security/Insurance "${label}" is missing a Type.`,
      });
    }
    // Amount + Currency required only for non-exempt collateral types.
    // Notary 777 p.4/p.5 KPC carry no monetary value.
    const depAmountRequired =
      typeof ed_typeRequiresAmount === "function"
        ? ed_typeRequiresAmount(d.array_type)
        : !(COLLATERAL_TYPES_NO_AMOUNT || []).includes(parseInt(d.array_type));

    if (depAmountRequired) {
      const amt = d.array_requiredamount;
      if (
        amt == null ||
        amt === "" ||
        isNaN(parseFloat(amt)) ||
        parseFloat(amt) <= 0
      ) {
        push({
          id: `req-dep-amt-${idx}`,
          severity: "error",
          step: "Security & Insurance",
          stepIndex: VALIDATION_STEP_INDEX.deposits,
          message: `Security/Insurance "${label}" is missing a valid Required Amount.`,
        });
      }
      const ccy =
        d._currencyId ||
        d._RequiredAmountCurrency_value ||
        d._transactioncurrencyid_value;
      if (!ccy) {
        push({
          id: `req-dep-ccy-${idx}`,
          severity: "error",
          step: "Security & Insurance",
          stepIndex: VALIDATION_STEP_INDEX.deposits,
          message: `Security/Insurance "${label}" is missing a Required Amount Currency.`,
        });
      }
    }
  });

  // --- Lease options (new): expiry date, type, holder ---
  (typeof amendNewOptions !== "undefined" ? amendNewOptions || [] : []).forEach(
    (o, idx) => {
      const label = `Option #${idx + 1}`;
      if (o.array_optiontype == null || o.array_optiontype === "") {
        push({
          id: `req-opt-type-${idx}`,
          severity: "error",
          step: "Lease Options",
          stepIndex: VALIDATION_STEP_INDEX.options,
          message: `${label} is missing an Option Type.`,
        });
      }
      if (o.array_optionholder == null || o.array_optionholder === "") {
        push({
          id: `req-opt-holder-${idx}`,
          severity: "error",
          step: "Lease Options",
          stepIndex: VALIDATION_STEP_INDEX.options,
          message: `${label} is missing an Option Holder.`,
        });
      }
      if (!o.array_optionexpirydate) {
        push({
          id: `req-opt-expiry-${idx}`,
          severity: "error",
          step: "Lease Options",
          stepIndex: VALIDATION_STEP_INDEX.options,
          message: `${label} is missing an Expiry Date.`,
        });
      }
    },
  );

  // Compute whether any blocker (severity:"error") was added
  const hasBlockers = issues.some((i) => i.severity === "error");
  return { issues, hasBlockers };
}

// Helper: toggle the Save Amendments button based on blocking validation errors
function _toggleSaveButtonForValidation(hasBlockers, blockerCount) {
  const finishBtn = document.getElementById("btnWizardFinish");
  if (!finishBtn) return;
  if (hasBlockers) {
    finishBtn.disabled = true;
    finishBtn.setAttribute("aria-disabled", "true");
    finishBtn.title = `${blockerCount} required field${blockerCount > 1 ? "s are" : " is"} missing. Fix them before saving.`;
    finishBtn.style.opacity = "0.55";
    finishBtn.style.cursor = "not-allowed";
    finishBtn.style.filter = "grayscale(40%)";
  } else {
    finishBtn.disabled = false;
    finishBtn.removeAttribute("aria-disabled");
    finishBtn.removeAttribute("title");
    finishBtn.style.opacity = "";
    finishBtn.style.cursor = "";
    finishBtn.style.filter = "";
  }
}

// Render the validation summary panel inside the Preview step
function renderValidationSummary() {
  const container = document.getElementById("validationSummary");
  if (!container) return;

  const { issues, hasBlockers } = runValidations();
  const errorCount = issues.filter((i) => i.severity === "error").length;

  // Toggle Save button based on blocking errors
  _toggleSaveButtonForValidation(hasBlockers, errorCount);

  if (!issues.length) {
    container.innerHTML = `
            <div style="background:#ecfdf5;border:1px solid #A8D5AB;border-radius:10px;
                        padding:14px 16px;display:flex;align-items:center;gap:10px;
                        font-size:13px;color:#1F5C23;font-weight:600;">
                <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5">
                    <polyline points="20 6 9 17 4 12"></polyline>
                </svg>
                All checks passed. The amendment is ready to save.
            </div>`;
    return;
  }

  const warningCount = issues.filter((i) => i.severity === "warning").length;
  const infoCount = issues.filter((i) => i.severity === "info").length;

  const summaryParts = [];
  if (errorCount)
    summaryParts.push(`${errorCount} error${errorCount > 1 ? "s" : ""}`);
  if (warningCount)
    summaryParts.push(`${warningCount} warning${warningCount > 1 ? "s" : ""}`);
  if (infoCount) summaryParts.push(`${infoCount} info`);

  // Sort issues so errors appear first, then warnings, then info
  const severityOrder = { error: 0, warning: 1, info: 2 };
  issues.sort(
    (a, b) =>
      (severityOrder[a.severity] ?? 9) - (severityOrder[b.severity] ?? 9),
  );

  const renderIssue = (issue, idx) => {
    let colors, iconSvg;
    if (issue.severity === "error") {
      colors = {
        bg: "#FEF2F2",
        border: "#FCA5A5",
        text: "#7F1D1D",
        icon: "#DC2626",
      };
      iconSvg = `<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="${colors.icon}" stroke-width="2.4"><circle cx="12" cy="12" r="10"/><line x1="15" y1="9" x2="9" y2="15"/><line x1="9" y1="9" x2="15" y2="15"/></svg>`;
    } else if (issue.severity === "info") {
      colors = {
        bg: "#EBF3FF",
        border: "#BBDBFF",
        text: "#0D4A9E",
        icon: "#1C6BD4",
      };
      iconSvg = `<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="${colors.icon}" stroke-width="2.2"><circle cx="12" cy="12" r="10"/><line x1="12" y1="16" x2="12" y2="12"/><line x1="12" y1="8" x2="12.01" y2="8"/></svg>`;
    } else {
      colors = {
        bg: "#FFF8EC",
        border: "#FFCF7F",
        text: "#7A4F0A",
        icon: "#7A4F0A",
      };
      iconSvg = `<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="${colors.icon}" stroke-width="2.2"><path d="M10.29 3.86L1.82 18a2 2 0 001.71 3h16.94a2 2 0 001.71-3L13.71 3.86a2 2 0 00-3.42 0z"/><line x1="12" y1="9" x2="12" y2="13"/><line x1="12" y1="17" x2="12.01" y2="17"/></svg>`;
    }

    const actionBtn = issue.action
      ? `<button class="btn-validation-action" data-issue-idx="${idx}"
                       style="background:${colors.icon};color:#fff;border:none;
                              padding:5px 10px;border-radius:6px;font-size:11px;
                              font-weight:600;cursor:pointer;margin-top:8px;
                              display:inline-flex;align-items:center;gap:5px;">
                  ${esc(issue.action.label)}
              </button>`
      : "";

    return `
            <div style="background:${colors.bg};border:1px solid ${colors.border};border-radius:8px;
                        padding:10px 12px;margin-bottom:8px;">
                <div style="display:flex;align-items:flex-start;gap:10px;">
                    <span style="flex-shrink:0;margin-top:1px;">${iconSvg}</span>
                    <div style="flex:1;min-width:0;">
                        <div style="font-size:12.5px;color:${colors.text};line-height:1.55;">
                            ${esc(issue.message)}
                        </div>
                        <div style="margin-top:6px;display:flex;align-items:center;gap:10px;flex-wrap:wrap;">
                            <button class="btn-validation-goto" data-step-idx="${issue.stepIndex}"
                                    style="background:transparent;border:1px solid ${colors.border};
                                           color:${colors.text};padding:3px 9px;border-radius:6px;
                                           font-size:10.5px;font-weight:600;cursor:pointer;
                                           display:inline-flex;align-items:center;gap:4px;">
                                Go to ${esc(issue.step)}
                                <svg width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3">
                                    <polyline points="9 18 15 12 9 6"></polyline>
                                </svg>
                            </button>
                            ${actionBtn}
                        </div>
                    </div>
                </div>
            </div>`;
  };

  // Header style varies by severity: red if blockers, amber otherwise
  const headerBg = hasBlockers
    ? "linear-gradient(135deg,#FEF2F2 0%,#FECACA 100%)"
    : "linear-gradient(135deg,#FFF8EC 0%,#FFCF7F 100%)";
  const headerText = hasBlockers ? "#7F1D1D" : "#7A4F0A";
  const headerIcon = hasBlockers ? "#DC2626" : "#7A4F0A";
  const pillBg = hasBlockers ? "rgba(220,38,38,0.16)" : "rgba(146,64,14,0.18)";
  const headerTitle = hasBlockers
    ? "Action Required Before Save"
    : "Validation Summary";
  const introText = hasBlockers
    ? `<strong style="color:#7F1D1D;">${errorCount} required field${errorCount > 1 ? "s are" : " is"} missing.</strong> The Save Amendments button is disabled until you fix them. Click "Go to ..." on any item below to jump to the right step.`
    : "Review the items below before saving. You can override and save anyway, or go back to a step to fix.";

  container.innerHTML = `
        <div style="background:#fff;border:1px solid ${hasBlockers ? "#FCA5A5" : "#EAECF0"};border-radius:10px;
                    overflow:hidden;margin-bottom:18px;${hasBlockers ? "box-shadow:0 4px 14px rgba(220,38,38,0.10);" : ""}">
            <div style="background:${headerBg};
                        padding:11px 16px;display:flex;align-items:center;justify-content:space-between;gap:10px;">
                <div style="display:flex;align-items:center;gap:8px;">
                    <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="${headerIcon}" stroke-width="2.5">
                        <path d="M10.29 3.86L1.82 18a2 2 0 001.71 3h16.94a2 2 0 001.71-3L13.71 3.86a2 2 0 00-3.42 0z"/>
                        <line x1="12" y1="9" x2="12" y2="13"/>
                        <line x1="12" y1="17" x2="12.01" y2="17"/>
                    </svg>
                    <h3 style="margin:0;font-size:12px;font-weight:700;color:${headerText};letter-spacing:0.2px;">
                        ${headerTitle}
                    </h3>
                </div>
                <span style="background:${pillBg};color:${headerText};font-size:10.5px;
                             font-weight:700;padding:2px 10px;border-radius:10px;">
                    ${summaryParts.join(" · ")}
                </span>
            </div>
            <div style="padding:12px 16px;">
                <p style="margin:0 0 12px;font-size:12px;color:#5A6070;line-height:1.5;">
                    ${introText}
                </p>
                ${issues.map(renderIssue).join("")}
            </div>
        </div>`;

  // Cache issues so action buttons can resolve their handler
  container._cachedIssues = issues;

  // Wire up "Go to step" buttons
  container.querySelectorAll(".btn-validation-goto").forEach((btn) => {
    btn.addEventListener("click", () => {
      const idx = parseInt(btn.dataset.stepIdx, 10);
      if (!isNaN(idx)) wizardGoTo(idx);
    });
  });

  // Wire up action buttons (e.g. auto-cap) with two-step confirm
  container.querySelectorAll(".btn-validation-action").forEach((btn) => {
    btn.addEventListener("click", () => {
      const issueIdx = parseInt(btn.dataset.issueIdx, 10);
      const issue = container._cachedIssues?.[issueIdx];
      if (!issue || !issue.action) return;

      // Two-step inline confirm: button changes to "Confirm?" / "Cancel"
      if (btn.dataset.confirming === "1") return;
      btn.dataset.confirming = "1";
      const origHtml = btn.innerHTML;
      btn.innerHTML = `Confirm action?`;
      btn.style.background = "#B91C1C";

      const cancel = document.createElement("button");
      cancel.textContent = "Cancel";
      cancel.style.cssText =
        "background:transparent;border:1px solid #CBD5E1;color:#5A6070;padding:5px 10px;border-radius:6px;font-size:11px;font-weight:600;cursor:pointer;margin-left:6px;";
      btn.parentNode.insertBefore(cancel, btn.nextSibling);

      const cleanup = () => {
        btn.dataset.confirming = "";
        btn.innerHTML = origHtml;
        btn.style.background = "";
        cancel.remove();
      };

      cancel.addEventListener("click", (e) => {
        e.stopPropagation();
        cleanup();
      });

      btn.addEventListener(
        "click",
        function once(e) {
          e.stopPropagation();
          btn.removeEventListener("click", once);
          try {
            issue.action.handler();
          } catch (err) {
            console.error("Action handler failed:", err);
          }
          // Re-render tables & validation
          try {
            renderExistingChargesTable && renderExistingChargesTable();
          } catch (e) {}
          try {
            renderExistingDepositsTable && renderExistingDepositsTable();
          } catch (e) {}
          try {
            cl_renderExistingClausesTable && cl_renderExistingClausesTable();
          } catch (e) {}
          showAmendNotification(
            "✅ Records updated. Re-running validation…",
            "success",
          );
          cleanup();
          setTimeout(renderValidationSummary, 100);
        },
        { once: true },
      );
    });
  });
}

// ── Render Preview Panel ──────────────────────────────────────
function renderPreviewPanel() {
  const summaryLines = [];

  // Sign method is fixed to Manual — omit from summary

  const effectiveDate = document.getElementById("amend_startDate")?.value;
  const expiryDate = document.getElementById("amend_endDate")?.value;
  const amendmentDate = document.getElementById("amend_moveInDate")?.value;
  const termParts = [];
  if (effectiveDate)
    termParts.push(`effective from ${formatDateAmend(effectiveDate)}`);
  if (expiryDate) termParts.push(`expiring ${formatDateAmend(expiryDate)}`);
  if (amendmentDate)
    termParts.push(`amendment dated ${formatDateAmend(amendmentDate)}`);
  if (selectedAmendmentTypes?.length) {
    const typeLabels = selectedAmendmentTypes.map((v) => {
      const o = amendmentTypeOptions.find((x) => x.Value === v);
      return o ? o.Label?.UserLocalizedLabel?.Label || String(v) : String(v);
    });
    termParts.push(`type: ${typeLabels.join(", ")}`);
  }
  if (termParts.length)
    summaryLines.push({
      stage: "Lease Terms",
      text: `Amendment configured — ${termParts.join("; ")}.`,
    });

  if (uploadedFiles.length > 0)
    summaryLines.push({
      stage: "Documents",
      text: `${uploadedFiles.length} document${uploadedFiles.length !== 1 ? "s" : ""} attached for upload.`,
    });
  else
    summaryLines.push({ stage: "Documents", text: "No documents attached." });

  const unitParts = [];
  if (amendExistingUnits.length)
    unitParts.push(
      `${amendExistingUnits.length} existing unit${amendExistingUnits.length !== 1 ? "s" : ""} retained`,
    );
  if (amendNewUnits.length)
    unitParts.push(
      `${amendNewUnits.length} new unit${amendNewUnits.length !== 1 ? "s" : ""} added`,
    );
  if (amendDeactivatedUnits.length)
    unitParts.push(
      // CHANGED: was "units marked for deactivation"
      `${amendDeactivatedUnits.length} unit${amendDeactivatedUnits.length !== 1 ? "s" : ""} deactivated`,
    );
  if (amendEditedUnits.length)
    unitParts.push(
      `${amendEditedUnits.length} unit${amendEditedUnits.length !== 1 ? "s" : ""} date-edited`,
    );
  summaryLines.push({
    stage: "Units",
    text: unitParts.length
      ? unitParts.join(", ") + "."
      : "No unit changes made.",
  });

  const chargeParts = [];
  if (amendExistingCharges.length)
    chargeParts.push(
      `${amendExistingCharges.length} existing charge${amendExistingCharges.length !== 1 ? "s" : ""} active`,
    );
  if (amendNewCharges.length)
    chargeParts.push(
      `${amendNewCharges.length} new charge${amendNewCharges.length !== 1 ? "s" : ""} added`,
    );
  if (amendDeactivatedCharges.length) {
    const prorated = amendDeactivatedCharges.filter(
      (c) => c._deactivateProration,
    ).length;
    let deactTxt = `${amendDeactivatedCharges.length} charge${amendDeactivatedCharges.length !== 1 ? "s" : ""} deactivated`;
    if (prorated) deactTxt += ` (${prorated} with last-cycle proration)`;
    chargeParts.push(deactTxt);
  }
  summaryLines.push({
    stage: "Recurring Charges",
    text: chargeParts.length
      ? chargeParts.join(", ") + "."
      : "No charge changes made.",
  });

  const depParts = [];
  if (amendDeposits.length) {
    depParts.push(
      `${amendDeposits.length} existing record${amendDeposits.length !== 1 ? "s" : ""}`,
    );
    if (pendingDepositUpdates.length)
      depParts.push(
        `${pendingDepositUpdates.length} due date${pendingDepositUpdates.length !== 1 ? "s" : ""} updated`,
      );
  }
  if (amendNewDeposits.length)
    depParts.push(
      `${amendNewDeposits.length} new record${amendNewDeposits.length !== 1 ? "s" : ""} added`,
    );
  summaryLines.push({
    stage: "Security & Insurance",
    text: depParts.length
      ? depParts.join(", ") + "."
      : "No security or insurance changes made.",
  });

  const clauseParts = [];
  if (amendClauses.length)
    clauseParts.push(
      `${amendClauses.length} existing clause${amendClauses.length !== 1 ? "s" : ""} active`,
    );
  if (amendNewClauses.length)
    clauseParts.push(
      `${amendNewClauses.length} new clause${amendNewClauses.length !== 1 ? "s" : ""} added`,
    );
  if (amendDeactivatedClauses.length)
    clauseParts.push(
      `${amendDeactivatedClauses.length} clause${amendDeactivatedClauses.length !== 1 ? "s" : ""} deactivated`,
    );
  if (pendingClauseExpiryUpdates.length)
    clauseParts.push(
      `${pendingClauseExpiryUpdates.length} clause expiry date${pendingClauseExpiryUpdates.length !== 1 ? "s" : ""} edited`,
    );
  summaryLines.push({
    stage: "Financial Clauses",
    text: clauseParts.length
      ? clauseParts.join(", ") + "."
      : "No clause changes made.",
  });

  const optionParts = [];
  if (amendExistingOptions.length)
    optionParts.push(
      `${amendExistingOptions.length} existing option${amendExistingOptions.length !== 1 ? "s" : ""} active`,
    );
  if (amendNewOptions.length)
    optionParts.push(
      `${amendNewOptions.length} new option${amendNewOptions.length !== 1 ? "s" : ""} added`,
    );
  if (amendDeactivatedOptions.length) {
    const withDates = amendDeactivatedOptions.filter((o) => o._newExpiryDate);
    let optDeactTxt = `${amendDeactivatedOptions.length} option${amendDeactivatedOptions.length !== 1 ? "s" : ""} deactivated`;
    if (withDates.length)
      optDeactTxt += ` (new expiry: ${withDates.map((o) => formatDateAmend(o._newExpiryDate)).join(", ")})`;
    optionParts.push(optDeactTxt);
  }
  summaryLines.push({
    stage: "Lease Options",
    text: optionParts.length
      ? optionParts.join(", ") + "."
      : "No option changes made.",
  });

  const discParts = [];
  if (amendExistingDiscounts.length)
    discParts.push(
      `${amendExistingDiscounts.length} existing discount${amendExistingDiscounts.length !== 1 ? "s" : ""} active`,
    );
  if (amendNewDiscounts.length)
    discParts.push(
      `${amendNewDiscounts.length} new discount${amendNewDiscounts.length !== 1 ? "s" : ""} staged`,
    );
  if (amendDeactivatedDiscounts.length)
    discParts.push(
      `${amendDeactivatedDiscounts.length} discount${amendDeactivatedDiscounts.length !== 1 ? "s" : ""} deactivated`,
    );
  if (pendingDiscountEndDateEdits.length)
    discParts.push(
      `${pendingDiscountEndDateEdits.length} end date${pendingDiscountEndDateEdits.length !== 1 ? "s" : ""} updated`,
    );
  summaryLines.push({
    stage: "Discounts",
    text: discParts.length
      ? discParts.join(", ") + "."
      : "No discount changes made.",
  });

  const notesValue = (
    document.getElementById("amend_description")?.value || ""
  ).trim();
  if (notesValue) {
    const preview =
      notesValue.length > 120
        ? notesValue.substring(0, 120).trimEnd() + "…"
        : notesValue;
    summaryLines.push({
      stage: "Amendment Notes",
      text: `Note added: "${preview}"`,
    });
  } else {
    summaryLines.push({
      stage: "Amendment Notes",
      text: "No amendment notes provided.",
    });
  }

  // ── Currency helpers ───────────────────────────────────────────────────────
  function _ccyForCharge(c) {
    const ccyId = c._transactioncurrencyid_value;
    const ccyObj = ccyId
      ? amendCurrencies.find((cu) => cu.transactioncurrencyid === ccyId)
      : null;
    return {
      iso: ccyObj?.isocurrencycode || "—",
      symbol: ccyObj?.currencysymbol || "",
    };
  }
  function _ccyForDeposit(d, isNew) {
    if (isNew)
      return { iso: d._currencyCode || "—", symbol: d._currencySymbol || "" };
    const ccyObj = d.array_RequiredAmountCurrency || {};
    return {
      iso: ccyObj.isocurrencycode || "—",
      symbol: ccyObj.currencysymbol || "",
    };
  }
  function _accum(map, iso, symbol, amount) {
    const amt = parseFloat(amount) || 0;
    if (!amt) return;
    if (!map[iso]) map[iso] = { symbol, total: 0 };
    map[iso].total += amt;
  }
  function _diffCcyMaps(oldMap, newMap) {
    const allIsos = new Set([...Object.keys(oldMap), ...Object.keys(newMap)]);
    const parts = [];
    allIsos.forEach((iso) => {
      const oldVal = oldMap[iso]?.total || 0;
      const newVal = newMap[iso]?.total || 0;
      const diff = newVal - oldVal;
      const sym = newMap[iso]?.symbol || oldMap[iso]?.symbol || "";
      if (diff === 0) {
        parts.push(
          `<strong>${sym}${newVal.toFixed(2)} ${iso}</strong> (unchanged)`,
        );
      } else {
        const color = diff > 0 ? "#2E7D32" : "#B91C1C";
        const sign = diff > 0 ? "+" : "−";
        parts.push(
          `<strong>${sym}${newVal.toFixed(2)} ${iso}</strong> <strong style="color:${color};">(${sign}${sym}${Math.abs(diff).toFixed(2)} ${iso})</strong>`,
        );
      }
    });
    return parts;
  }

  const oldArea = [...amendExistingUnits, ...amendDeactivatedUnits].reduce(
    (s, u) => s + (parseFloat(u.array_Unit?.array_unitareasqm) || 0),
    0,
  );
  const newArea = [...amendExistingUnits, ...amendNewUnits].reduce(
    (s, u) => s + (parseFloat(u.array_Unit?.array_unitareasqm) || 0),
    0,
  );

  const oldRentByCcy = {};
  [...amendExistingCharges, ...amendDeactivatedCharges].forEach((c) => {
    const { iso, symbol } = _ccyForCharge(c);
    _accum(oldRentByCcy, iso, symbol, c.array_amount);
  });
  const newRentByCcy = {};
  [...amendExistingCharges, ...amendNewCharges].forEach((c) => {
    const { iso, symbol } = _ccyForCharge(c);
    _accum(newRentByCcy, iso, symbol, c.array_amount);
  });

  const oldDepByCcy = {};
  amendDeposits.forEach((d) => {
    const { iso, symbol } = _ccyForDeposit(d, false);
    _accum(oldDepByCcy, iso, symbol, d.array_requiredamount);
  });
  const newDepByCcy = {};
  amendDeposits.forEach((d) => {
    const { iso, symbol } = _ccyForDeposit(d, false);
    _accum(newDepByCcy, iso, symbol, d.array_requiredamount);
  });
  amendNewDeposits.forEach((d) => {
    const { iso, symbol } = _ccyForDeposit(d, true);
    _accum(newDepByCcy, iso, symbol, d.array_requiredamount);
  });

  const areaDiff = newArea - oldArea;
  const areaColor = areaDiff > 0 ? "#2E7D32" : "#B91C1C";
  const areaSign = areaDiff > 0 ? "+" : "−";
  const areaTxtHtml =
    areaDiff === 0
      ? `Area remains unchanged at <strong>${newArea.toFixed(2)} sq m</strong>`
      : `Area changed from <strong>${oldArea.toFixed(2)} sq m</strong> to <strong>${newArea.toFixed(2)} sq m</strong> (<strong style="color:${areaColor};">${areaSign}${Math.abs(areaDiff).toFixed(2)} sq m</strong>)`;

  const rentParts = _diffCcyMaps(oldRentByCcy, newRentByCcy);
  const depParts2 = _diffCcyMaps(oldDepByCcy, newDepByCcy);
  const changeSentenceHtml =
    areaTxtHtml.charAt(0).toUpperCase() +
    areaTxtHtml.slice(1) +
    "; " +
    (rentParts.length
      ? `recurring charges: ${rentParts.join(", ")}`
      : "no recurring charges configured") +
    "; " +
    (depParts2.length
      ? `security &amp; insurance: ${depParts2.join(", ")}`
      : "no security &amp; insurance configured") +
    ".";

  summaryLines.push({
    stage: "Changes Overview",
    text: changeSentenceHtml.replace(/<[^>]+>/g, ""),
    html: changeSentenceHtml,
    isOverview: true,
  });

  // ── Rebuild AI summary section ─────────────────────────────────────────────
  const existingSummary = document.getElementById("prev-amendment-summary");
  if (existingSummary) existingSummary.remove();

  const summarySection = document.createElement("div");
  summarySection.id = "prev-amendment-summary";
  summarySection.style.cssText = "display:none;"; // AI summary removed; style carrier only
  const panelKey = `sum-${Date.now()}`;

  summarySection.innerHTML = `
    <style>
      @keyframes aiShimmer{0%{background-position:300% 0}100%{background-position:-300% 0}}
      @keyframes sparklePulse{0%,100%{opacity:1;transform:scale(1) rotate(0deg)}25%{opacity:0.8;transform:scale(1.15) rotate(10deg)}75%{opacity:0.9;transform:scale(1.05) rotate(-5deg)}}
      @keyframes blink{0%,100%{opacity:1}50%{opacity:0}}

      /* ── UNIFIED PREVIEW TABLE SYSTEM ── */
      .upv-table {
        width: 100%;
        border-collapse: collapse;
        table-layout: fixed;
        font-size: 12px;
      }
      .upv-table thead tr { background: #F1F2F4; }
      .upv-table th {
        padding: 9px 10px;
        font-size: 10px;
        font-weight: 700;
        color: #475569;
        text-transform: uppercase;
        letter-spacing: 0.5px;
        border-bottom: 2px solid #EAECF0;
        text-align: left;
        white-space: nowrap;
        overflow: hidden;
        text-overflow: ellipsis;
      }
      .upv-table td {
        padding: 10px 10px;
        border-bottom: 1px solid #F1F2F4;
        color: #374151;
        vertical-align: middle;
        overflow: hidden;
        text-overflow: ellipsis;
        white-space: nowrap;
        font-size: 12px;
      }
      .upv-table tbody tr:last-child td { border-bottom: none; }
      .upv-table tbody tr:nth-child(even) td { background: #F8F9FC; }
      .upv-table tbody tr:hover td { background: #f0f4ff; transition: background 0.1s; }

      /* ── 6-COLUMN TABLE: equal-ish widths that sum to 100% ── */
      .upv-6col .upv-c1 { width: 24%; }
      .upv-6col .upv-c2 { width: 18%; }
      .upv-6col .upv-c3 { width: 16%; }
      .upv-6col .upv-c4 { width: 13%; }
      .upv-6col .upv-c5 { width: 14%; }
      .upv-6col .upv-c6 { width: 15%; }

      /* ── 7-COLUMN TABLE (Charges): independent column sizing ── */
      .upv-7col .upv-c1 { width: 22%; }
      .upv-7col .upv-c2 { width: 13%; }
      .upv-7col .upv-c3 { width: 15%; }
      .upv-7col .upv-c4 { width: 10%; }
      .upv-7col .upv-c5 { width: 11%; }
      .upv-7col .upv-c6 { width: 11%; }
      .upv-7col .upv-c7 { width: 18%; }

      .upv-right { text-align: right !important; }
      .upv-center { text-align: center !important; }

      .upv-new-badge {
        background: #EDF7EE; color: #065f46;
        font-size: 9px; font-weight: 700;
        padding: 1px 5px; border-radius: 4px;
        vertical-align: middle; margin-left: 4px;
      }
      .upv-type-pill {
        background: #e0f2fe; color: #0369A1;
        padding: 2px 8px; border-radius: 6px;
        font-size: 11px; font-weight: 600;
        white-space: nowrap; display: inline-block;
      }
      .upv-freq-badge {
        background: #F1F2F4; color: #475569;
        padding: 2px 8px; border-radius: 5px;
        font-size: 10px; font-weight: 600;
        white-space: nowrap; display: inline-block;
      }
      .upv-ccy { font-size: 10px; font-weight: 500; color: #9CA3AF; margin-left: 3px; }

      .upv-empty td {
        text-align: center !important;
        padding: 24px !important;
        color: #9CA3AF !important;
        font-style: italic;
      }
    </style>`;

  const previewPanel = document.getElementById("panel-preview");
  const firstSection = previewPanel?.querySelector(".preview-section");
  if (firstSection) previewPanel.insertBefore(summarySection, firstSection);

  // Insert validation summary placeholder at the very top of preview panel
  let validationDiv = document.getElementById("validationSummary");
  if (!validationDiv) {
    validationDiv = document.createElement("div");
    validationDiv.id = "validationSummary";
    if (previewPanel)
      previewPanel.insertBefore(validationDiv, previewPanel.firstChild);
  }
  renderValidationSummary();

  // ── AI typewriter ──────────────────────────────────────────────────────────
  setTimeout(() => {
    const container = document.getElementById(`sum-lines-${panelKey}`);
    const cursor = document.getElementById(`sum-cursor-${panelKey}`);
    if (!container) return;
    let lineIndex = 0;
    function typeNextLine() {
      if (lineIndex >= summaryLines.length) {
        if (cursor)
          setTimeout(() => {
            cursor.style.display = "none";
          }, 600);
        return;
      }
      const line = summaryLines[lineIndex++];
      const isOverview = line.isOverview === true;
      const lineEl = document.createElement("div");
      lineEl.style.cssText =
        "width:100%;display:flex;align-items:baseline;gap:6px;margin-bottom:5px;" +
        (isOverview
          ? "margin-top:4px;padding-top:6px;border-top:1px solid #EAECF0;"
          : "");
      lineEl.innerHTML = `
        <span style="display:inline-flex;align-items:center;justify-content:center;
                     width:18px;height:18px;border-radius:50%;flex-shrink:0;margin-top:2px;
                     background:${isOverview ? "#FFF8EC" : "#EBF3FF"};
                     color:${isOverview ? "#7A4F0A" : "#0D4A9E"};
                     font-size:10px;font-weight:800;">${lineIndex}</span>
        <span style="font-size:11px;font-weight:700;white-space:nowrap;flex-shrink:0;
                     min-width:130px;margin-left:6px;
                     color:${isOverview ? "#7A4F0A" : "#0D4A9E"};">${esc(line.stage)}</span>
        <span class="sl-text" style="font-size:13px;line-height:1.5;
                     color:${isOverview ? "#0369A1" : "#374151"};
                     font-weight:${isOverview ? "500" : "400"};"></span>`;
      container.appendChild(lineEl);
      const textEl = lineEl.querySelector(".sl-text");
      if (isOverview && line.html) {
        textEl.innerHTML = line.html;
        setTimeout(typeNextLine, 120);
        return;
      }
      let i = 0;
      const text = line.text;
      function typeChar() {
        if (i >= text.length) {
          typeNextLine();
          return;
        }
        textEl.textContent += text[i];
        const ch = text[i];
        let delay = 9;
        if (ch === "," || ch === ";") delay = 35;
        else if (ch === "." || ch === "!") delay = 55;
        else if (ch === " ") delay = 5;
        i++;
        setTimeout(typeChar, delay);
      }
      typeChar();
    }
    typeNextLine();
  }, 80);

  // ── Terms + chips ──────────────────────────────────────────────────────────
  // Sign method fixed to Manual — preview element hidden in HTML
  const fmtDate = (v) => (v ? formatDateAmend(v) : "—");
  const setEl = (id, val) => {
    const el = document.getElementById(id);
    if (el) el.textContent = val || "—";
  };
  setEl(
    "prev-startDate",
    fmtDate(document.getElementById("amend_startDate").value),
  );
  setEl(
    "prev-endDate",
    fmtDate(document.getElementById("amend_endDate").value),
  );
  setEl(
    "prev-moveIn",
    fmtDate(document.getElementById("amend_moveInDate").value),
  );
  const amendTypeEl = document.getElementById("prev-leaseTerm");
  if (amendTypeEl) {
    amendTypeEl.textContent = selectedAmendmentTypes.length
      ? selectedAmendmentTypes
          .map((val) => {
            const opt = amendmentTypeOptions.find((o) => o.Value === val);
            return opt
              ? opt.Label?.UserLocalizedLabel?.Label || String(val)
              : String(val);
          })
          .join(", ")
      : "—";
  }
  setEl(
    "prev-notes",
    document.getElementById("amend_description").value || "—",
  );

  const totalUnitsCount = amendExistingUnits.length + amendNewUnits.length;
  const totalOptionsCount =
    amendExistingOptions.length + amendNewOptions.length;
  const totalClausesCount = amendClauses.length + amendNewClauses.length;

  const setChip = (id, n) => {
    const el = document.getElementById(id);
    if (el) el.textContent = n;
  };
  setChip("prev-count-units", totalUnitsCount);
  setChip("prev-count-charges", amendCharges.length);
  setChip(
    "prev-count-deposits",
    amendDeposits.length + amendNewDeposits.length,
  );
  setChip("prev-count-clauses", totalClausesCount);
  setChip("prev-count-options", totalOptionsCount);
  setChip(
    "prev-count-discounts",
    amendExistingDiscounts.length + amendNewDiscounts.length,
  );

  const setPill = (id, n) => {
    const el = document.getElementById(id);
    if (el) el.textContent = `${n} record${n !== 1 ? "s" : ""}`;
  };
  setPill("prev-pill-units", totalUnitsCount);
  setPill("prev-pill-charges", amendCharges.length);
  setPill("prev-pill-deposits", amendDeposits.length + amendNewDeposits.length);
  setPill("prev-pill-clauses", totalClausesCount);
  setPill("prev-pill-options", totalOptionsCount);
  setPill(
    "prev-pill-discounts",
    amendExistingDiscounts.length + amendNewDiscounts.length,
  );

  // ══════════════════════════════════════════════════════════════════════════
  //  UNIFIED TABLE BUILDER — 6-COLUMN VERSION
  //  Columns: 24% | 18% | 16% | 13% | 14% | 15% = 100%
  // ══════════════════════════════════════════════════════════════════════════
  function _build6ColTable(tableEl, thAlignOverrides) {
    if (!tableEl) return;
    tableEl.className = "upv-table upv-6col";

    const old = tableEl.querySelector("colgroup");
    if (old) old.remove();

    // 6 columns: 24 + 18 + 16 + 13 + 14 + 15 = 100%
    const zones = ["24%", "18%", "16%", "13%", "14%", "15%"];
    const cg = document.createElement("colgroup");
    zones.forEach((w) => {
      const col = document.createElement("col");
      col.style.width = w;
      cg.appendChild(col);
    });
    tableEl.insertBefore(cg, tableEl.firstChild);

    tableEl.querySelectorAll("thead th").forEach((th, i) => {
      th.style.cssText =
        "padding:9px 10px;font-size:10px;font-weight:700;color:#475569;" +
        "text-transform:uppercase;letter-spacing:0.5px;border-bottom:2px solid #EAECF0;" +
        "text-align:left;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;";
      if (thAlignOverrides && thAlignOverrides[i]) {
        th.style.textAlign = thAlignOverrides[i];
      }
    });
  }

  // ══════════════════════════════════════════════════════════════════════════
  //  UNIFIED TABLE BUILDER — 7-COLUMN VERSION (Charges only)
  //  Columns: 22% | 13% | 15% | 10% | 11% | 11% | 18% = 100%
  // ══════════════════════════════════════════════════════════════════════════
  function _build7ColTable(tableEl, thAlignOverrides) {
    if (!tableEl) return;
    tableEl.className = "upv-table upv-7col";

    const old = tableEl.querySelector("colgroup");
    if (old) old.remove();

    // 7 columns: 22 + 13 + 15 + 10 + 11 + 11 + 18 = 100%
    const zones = ["22%", "13%", "15%", "10%", "11%", "11%", "18%"];
    const cg = document.createElement("colgroup");
    zones.forEach((w) => {
      const col = document.createElement("col");
      col.style.width = w;
      cg.appendChild(col);
    });
    tableEl.insertBefore(cg, tableEl.firstChild);

    tableEl.querySelectorAll("thead th").forEach((th, i) => {
      th.style.cssText =
        "padding:9px 10px;font-size:10px;font-weight:700;color:#475569;" +
        "text-transform:uppercase;letter-spacing:0.5px;border-bottom:2px solid #EAECF0;" +
        "text-align:left;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;";
      if (thAlignOverrides && thAlignOverrides[i]) {
        th.style.textAlign = thAlignOverrides[i];
      }
    });
  }

  // Shared td style string
  const TD =
    "padding:10px 10px;border-bottom:1px solid #F1F2F4;vertical-align:middle;" +
    "overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:12px;color:#374151;";

  // Row background alternator
  const rowBg = (i) => (i % 2 === 0 ? "background:#F8F9FC;" : "");

  // Empty row — spans appropriate number of cols
  const emptyRow6 = (msg) =>
    `<tr class="upv-empty"><td colspan="6" style="text-align:center;padding:24px;color:#9CA3AF;font-style:italic;">${msg}</td></tr>`;
  const emptyRow7 = (msg) =>
    `<tr class="upv-empty"><td colspan="7" style="text-align:center;padding:24px;color:#9CA3AF;font-style:italic;">${msg}</td></tr>`;

  // NEW badge
  const newBadge = `<span class="upv-new-badge">NEW</span>`;

  // ════════════════════════════════════════════════════════════
  //  TABLE 1 — UNITS (6 columns)
  //  C1:24% Unit Name  C2:18% Building  C3:16% Type
  //  C4:13% Area       C5:14% Start     C6:15% End
  // ════════════════════════════════════════════════════════════
  const prevUnitsTbody = document.getElementById("prevUnitsTbody");
  if (prevUnitsTbody) {
    _build6ColTable(prevUnitsTbody.closest("table"), { 3: "right" });

    const rows = [
      ...amendExistingUnits.map((u) => ({ ...u, _isNew: false })),
      ...amendNewUnits.map((u) => ({ ...u, _isNew: true })),
    ];

    prevUnitsTbody.innerHTML = !rows.length
      ? emptyRow6("No units associated")
      : rows
          .map((assoc, i) => {
            const unit = assoc.array_Unit || {};
            const unitType =
              assoc[
                "array_Unit._array_unittype_value@OData.Community.Display.V1.FormattedValue"
              ] ||
              unit[
                "_array_unittype_value@OData.Community.Display.V1.FormattedValue"
              ] ||
              "—";
            const building =
              assoc[
                "array_Unit._array_building_value@OData.Community.Display.V1.FormattedValue"
              ] ||
              unit[
                "_array_building_value@OData.Community.Display.V1.FormattedValue"
              ] ||
              assoc._buildingName ||
              "—";
            const isNew = assoc._isNew;
            return `<tr style="${rowBg(i)}">
              <td style="${TD}"><strong>${esc(unit.array_unitname || "—")}</strong>${isNew ? newBadge : ""}</td>
              <td style="${TD}">${esc(building)}</td>
              <td style="${TD}">${esc(unitType)}</td>
              <td style="${TD}text-align:right;">${unit.array_unitareasqm || "—"}</td>
              <td style="${TD}">${formatDateAmend(assoc.array_startdate)}</td>
              <td style="${TD}">${formatDateAmend(assoc.array_enddate)}</td>
            </tr>`;
          })
          .join("");
  }

  // ════════════════════════════════════════════════════════════
  //  TABLE 2 — RECURRING CHARGES (7 columns — independent layout)
  //  C1:22% Name  C2:13% Unit   C3:15% Charge Type
  //  C4:10% Freq  C5:11% Start  C6:11% End   C7:18% Amount
  // ════════════════════════════════════════════════════════════
  const prevChargesTbody = document.getElementById("prevChargesTbody");
  if (prevChargesTbody) {
    _build7ColTable(prevChargesTbody.closest("table"), {
      3: "center",
      6: "right",
    });

    const chargeRows = [
      ...amendExistingCharges.map((c) => ({ ...c, _isNew: false })),
      ...amendNewCharges.map((c) => ({ ...c, _isNew: true })),
    ];
    prevChargesTbody.innerHTML = !chargeRows.length
      ? emptyRow7("No recurring charges")
      : chargeRows
          .map((c, i) => {
            const unit = c.array_Unit || {};
            const chargeType = c.array_ChargeType || {};
            const { iso, symbol: sym } = _ccyForCharge(c);
            const isNew = c._isNew;
            const amtColor = isNew ? "#2E7D32" : "#1C6BD4";
            return `<tr style="${rowBg(i)}">
              <td style="${TD}"><strong>${esc(c.array_chargename || "—")}</strong>${isNew ? newBadge : ""}</td>
              <td style="${TD}">${esc(unit.array_unitname || "All Units")}</td>
              <td style="${TD}">${esc(chargeType.array_name || "—")}</td>
              <td style="${TD}text-align:center;">
                <span class="upv-freq-badge">${getFreqLabel(c.array_frequency)}</span>
              </td>
              <td style="${TD}">${formatDateAmend(c.array_startdate)}</td>
              <td style="${TD}">${formatDateAmend(c.array_enddate)}</td>
              <td style="${TD}text-align:right;font-weight:700;color:${amtColor};">
                ${sym}${c.array_amount != null ? parseFloat(c.array_amount).toFixed(2) : "—"}
                ${iso && iso !== "—" ? `<span class="upv-ccy">${esc(iso)}</span>` : ""}
              </td>
            </tr>`;
          })
          .join("");
  }

  // ════════════════════════════════════════════════════════════
  //  TABLE 3 — SECURITY & INSURANCE (6 columns)
  //  C1:24% Unit  C2:18% Type     C3:16% Sub Type
  //  C4:13% Due   C5:14% Amount   C6:15% Currency
  // ════════════════════════════════════════════════════════════
  const prevDepositsTbody = document.getElementById("prevDepositsTbody");
  if (prevDepositsTbody) {
    _build6ColTable(prevDepositsTbody.closest("table"), {
      4: "right",
      5: "center",
    });

    const depRows = [
      ...amendDeposits.map((d) => ({ ...d, _isNew: false })),
      ...amendNewDeposits.map((d) => ({ ...d, _isNew: true })),
    ];
    prevDepositsTbody.innerHTML = !depRows.length
      ? emptyRow6("No security &amp; insurance records")
      : depRows
          .map((d, i) => {
            const isNew = d._isNew;
            const { iso: ccyCode, symbol: sym } = _ccyForDeposit(d, isNew);
            let unit, typeLabel, subTypeLabel, dueDate, amount;
            if (isNew) {
              unit = d._unitName || "All Units";
              typeLabel = d._typeLabel || "—";
              subTypeLabel = d._subTypeLabel || "—";
              dueDate = d.array_duedate;
              amount = d.array_requiredamount;
            } else {
              const unitObj = d.array_Unit || {};
              unit = unitObj.array_unitname || "All Units";
              typeLabel =
                d["array_type@OData.Community.Display.V1.FormattedValue"] ||
                getOptionLabel(amendCollateralTypes, d.array_type) ||
                "—";
              subTypeLabel =
                d[
                  "array_deposittype@OData.Community.Display.V1.FormattedValue"
                ] ||
                getOptionLabel(amendDepositSubTypes, d.array_deposittype) ||
                "—";
              const pending = pendingDepositUpdates.find(
                (p) => p.id === d.array_depositid,
              );
              dueDate = pending ? pending.dueDate : d.array_duedate;
              amount = d.array_requiredamount;
            }
            const amtColor = isNew ? "#2E7D32" : "#7A4F0A";
            return `<tr style="${rowBg(i)}">
              <td style="${TD}">${esc(unit)}${isNew ? newBadge : ""}</td>
              <td style="${TD}"><span class="upv-type-pill">${esc(typeLabel)}</span></td>
              <td style="${TD}">${esc(subTypeLabel)}</td>
              <td style="${TD}">${formatDateAmend(dueDate)}</td>
              <td style="${TD}text-align:right;font-weight:700;color:${amtColor};">
                ${sym}${amount != null ? parseFloat(amount).toFixed(2) : "—"}
                ${ccyCode && ccyCode !== "—" ? `<span class="upv-ccy">${esc(ccyCode)}</span>` : ""}
              </td>
              <td style="${TD}text-align:center;">${esc(ccyCode)}</td>
            </tr>`;
          })
          .join("");
  }

  // ════════════════════════════════════════════════════════════
  //  TABLE 4 — LEASE CLAUSES (6 columns)
  //  C1:24% Name     C2:18% Clause Type  C3:16% Unit
  //  C4:13% Eff Date C5:14% Exp Date     C6:15% Summary
  // ════════════════════════════════════════════════════════════
  const prevClausesTbody = document.getElementById("prevClausesTbody");
  if (prevClausesTbody) {
    _build6ColTable(prevClausesTbody.closest("table"), {});

    const clauseRows = [
      ...amendClauses.map((cl) => ({ ...cl, _isNew: false })),
      ...amendNewClauses.map((cl) => ({ ...cl, _isNew: true })),
    ];
    prevClausesTbody.innerHTML = !clauseRows.length
      ? emptyRow6("No financial clauses")
      : clauseRows
          .map((cl, i) => {
            const isNew = cl._isNew;
            const clauseTypeName = isNew
              ? cl.clauseType || "—"
              : cl.array_ClauseType?.array_clausetypename || "—";
            const unitName = isNew
              ? cl.unitName || "All Units"
              : cl.array_Unit?.array_unitname || "All Units";
            const instances =
              cl.stepRentInstances ||
              cl.cpiInstances ||
              cl.turnoverInstances ||
              [];
            const firstInst = instances[0] || {};
            const effDate = isNew
              ? firstInst.effectiveDate || cl.effectiveDate || ""
              : cl.array_effectivedate || "";
            const expDate = isNew
              ? firstInst.expiryDate || cl.expiryDate || ""
              : cl.array_expirydate || "";
            const summary = isNew
              ? firstInst.clauseSummary ||
                firstInst.description ||
                cl.clauseSummary ||
                "—"
              : cl.array_clausesummary || cl.array_description || "—";
            const displayName = isNew
              ? cl.clauseType || "New Clause"
              : cl.array_leaseclausename || "—";
            return `<tr style="${rowBg(i)}">
              <td style="${TD}"><strong>${esc(displayName)}</strong>${isNew ? newBadge : ""}</td>
              <td style="${TD}">${esc(clauseTypeName)}</td>
              <td style="${TD}">${esc(unitName)}</td>
              <td style="${TD}">${formatDateAmend(effDate)}</td>
              <td style="${TD}">${formatDateAmend(expDate)}</td>
              <td style="${TD}color:#5A6070;" title="${esc(summary)}">${esc(summary)}</td>
            </tr>`;
          })
          .join("");
  }

  // ════════════════════════════════════════════════════════════
  //  TABLE 5 — LEASE OPTIONS (6 columns)
  //  C1:24% Type    C2:18% Holder      C3:16% Available From
  //  C4:13% Notice  C5:14% Expiry      C6:15% Notice Period
  // ════════════════════════════════════════════════════════════
  const prevOptionsTbody = document.getElementById("prevOptionsTbody");
  if (prevOptionsTbody) {
    _build6ColTable(prevOptionsTbody.closest("table"), { 5: "center" });

    const optionRows = [
      ...amendExistingOptions.map((o) => ({ ...o, _isNew: false })),
      ...amendNewOptions.map((o) => ({ ...o, _isNew: true })),
    ];
    prevOptionsTbody.innerHTML = !optionRows.length
      ? emptyRow6("No lease options")
      : optionRows
          .map((opt, i) => {
            const isNew = opt._isNew;
            const typeLbl = isNew
              ? opt._optionTypeName || "—"
              : opt[
                  "array_optiontype@OData.Community.Display.V1.FormattedValue"
                ] || ao_choiceLabel(ao_optionTypeChoices, opt.array_optiontype);
            const holderLbl = isNew
              ? opt._optionHolderName || "—"
              : opt[
                  "array_optionholder@OData.Community.Display.V1.FormattedValue"
                ] ||
                ao_choiceLabel(ao_optionHolderChoices, opt.array_optionholder);
            return `<tr style="${rowBg(i)}">
              <td style="${TD}"><strong>${esc(typeLbl)}</strong>${isNew ? newBadge : ""}</td>
              <td style="${TD}">${esc(holderLbl)}</td>
              <td style="${TD}">${formatDateAmend(opt.array_optionavailablefrom)}</td>
              <td style="${TD}">${formatDateAmend(opt.array_noticesubmissiondeadline)}</td>
              <td style="${TD}">${formatDateAmend(opt.array_optionexpirydate)}</td>
              <td style="${TD}text-align:center;">
                ${opt.array_noticeperiod != null ? opt.array_noticeperiod : "—"}
              </td>
            </tr>`;
          })
          .join("");
  }

  // ── TABLE 6 — DISCOUNTS preview ──────────────────────────────
  const prevDiscountsTbody = document.getElementById("prevDiscountsTbody");
  if (prevDiscountsTbody) {
    const CHARGE_TYPE_LABELS_PV = {
      126330000: "All Charges",
      126330001: "Specific Type",
      126330002: "Specific Charge",
    };
    const allDiscountsPreview = [
      ...amendExistingDiscounts.map((d) => ({ ...d, _isNew: false })),
      ...amendNewDiscounts.map((d) => ({ ...d, _isNew: true })),
    ];
    setPill("prev-pill-discounts", allDiscountsPreview.length);
    if (!allDiscountsPreview.length) {
      prevDiscountsTbody.innerHTML = `<tr><td colspan="5" style="text-align:center;
              padding:20px;color:#9CA3AF;font-size:12px;font-style:italic;">
              No discounts configured.</td></tr>`;
    } else {
      prevDiscountsTbody.innerHTML = allDiscountsPreview
        .map((d, i) => {
          const dtLabel =
            d.array_discounttype === 126330000 ? "Flat" : "Percentage";
          const amtDisplay =
            d.array_discounttype === 126330001
              ? (d.array_discountpercentage || 0) + "%"
              : d.array_discountpercentage || d.array_discountamount || 0;
          const nb = d._isNew ? `<span class="upv-new-badge">NEW</span>` : "";
          return `<tr style="${i % 2 === 0 ? "background:#F8F9FC;" : ""}">
                  <td style="${TD}">${esc(CHARGE_TYPE_LABELS_PV[d.array_chargetype] || String(d.array_chargetype))}${nb}</td>
                  <td style="${TD}">${dtLabel}</td>
                  <td style="${TD}">${amtDisplay}</td>
                  <td style="${TD}">${formatDateAmend(d.array_startdate)}</td>
                  <td style="${TD}">${formatDateAmend(d.array_enddate)}</td>
                </tr>`;
        })
        .join("");
    }
  }
}

// ══════════════════════════════════════════════════════════════
//  SAME-DAY AMENDMENT CONFIRMATION POPUP
//  Shown when effectiveDate = today. Returns a Promise<boolean>:
//  true = user confirmed proceed, false = user cancelled.
// ══════════════════════════════════════════════════════════════
function _confirmSameDayAmendment(effectiveDate) {
  return new Promise((resolve) => {
    // Remove any stale instance
    const existing = document.getElementById("sameDayConfirmOverlay");
    if (existing) existing.remove();

    const overlay = document.createElement("div");
    overlay.id = "sameDayConfirmOverlay";
    overlay.style.cssText = [
      "position:fixed",
      "inset:0",
      "background:rgba(0,0,0,0.60)",
      "z-index:999995",
      "display:flex",
      "align-items:center",
      "justify-content:center",
    ].join(";");

    overlay.innerHTML = `
      <div style="background:#fff;border-radius:16px;width:min(480px,94vw);
                  overflow:hidden;box-shadow:0 24px 64px rgba(0,0,0,0.30);">

        <!-- Header — amber warning -->
        <div style="background:linear-gradient(135deg,#7A4F0A 0%,#7A4F0A 100%);
                    padding:16px 20px;display:flex;align-items:center;gap:10px;">
          <div style="width:34px;height:34px;border-radius:50%;
                      background:rgba(255,255,255,0.18);
                      display:flex;align-items:center;justify-content:center;flex-shrink:0;">
            <svg width="18" height="18" viewBox="0 0 24 24" fill="none"
                 stroke="#fff" stroke-width="2.5">
              <path d="M10.29 3.86L1.82 18a2 2 0 001.71 3h16.94a2 2 0 001.71-3L13.71 3.86a2 2 0 00-3.42 0z"/>
              <line x1="12" y1="9" x2="12" y2="13"/>
              <line x1="12" y1="17" x2="12.01" y2="17"/>
            </svg>
          </div>
          <h3 style="color:#fff;margin:0;font-size:15px;font-weight:700;">
            Same-Day Amendment — Live Writes
          </h3>
        </div>

        <!-- Body -->
        <div style="padding:22px 24px;">

          <!-- Info banner -->
          <div style="background:#FFF8EC;border:1.5px solid #FFCF7F;border-radius:10px;
                      padding:13px 16px;margin-bottom:18px;display:flex;gap:12px;align-items:flex-start;">
            <svg width="18" height="18" viewBox="0 0 24 24" fill="none"
                 stroke="#7A4F0A" stroke-width="2" style="flex-shrink:0;margin-top:1px;">
              <circle cx="12" cy="12" r="10"/>
              <line x1="12" y1="8" x2="12" y2="12"/>
              <line x1="12" y1="16" x2="12.01" y2="16"/>
            </svg>
            <div>
              <div style="font-size:13px;font-weight:700;color:#7A4F0A;margin-bottom:4px;">
                Effective date is today (${formatDateAmend(effectiveDate)})
              </div>
              <div style="font-size:12px;color:#7A4F0A;line-height:1.6;">
                All changes — new charges, unit associations, deposits, clauses, and options —
                will be <strong>written live to the lease records immediately</strong>.
                The activation flow will <strong>not</strong> be used for this amendment.
              </div>
            </div>
          </div>

          <!-- What will happen list -->
          <div style="font-size:12px;color:#374151;line-height:1.8;margin-bottom:8px;">
            <div style="font-weight:700;color:#111827;margin-bottom:8px;font-size:13px;">
              What will happen when you confirm:
            </div>
            <div style="display:flex;flex-direction:column;gap:5px;">
              <div style="display:flex;align-items:center;gap:8px;">
                <svg width="13" height="13" viewBox="0 0 24 24" fill="none"
                     stroke="#2E7D32" stroke-width="2.5"><polyline points="20 6 9 17 4 12"/></svg>
                New records (charges, units, deposits, clauses, options) created as <strong>Active</strong>
              </div>
              <div style="display:flex;align-items:center;gap:8px;">
                <svg width="13" height="13" viewBox="0 0 24 24" fill="none"
                     stroke="#2E7D32" stroke-width="2.5"><polyline points="20 6 9 17 4 12"/></svg>
                Deactivations applied <strong>immediately</strong> (records set to Inactive)
              </div>
              <div style="display:flex;align-items:center;gap:8px;">
                <svg width="13" height="13" viewBox="0 0 24 24" fill="none"
                     stroke="#2E7D32" stroke-width="2.5"><polyline points="20 6 9 17 4 12"/></svg>
                Lease end-date extension written directly to the lease record
              </div>
              <div style="display:flex;align-items:center;gap:8px;">
                <svg width="13" height="13" viewBox="0 0 24 24" fill="none"
                     stroke="#2E7D32" stroke-width="2.5"><polyline points="20 6 9 17 4 12"/></svg>
                Amendment record created and set to <strong>Pending</strong>
              </div>
            </div>
          </div>
        </div>

        <!-- Footer -->
        <div style="padding:14px 24px;border-top:1px solid #EAECF0;
                    display:flex;justify-content:flex-end;gap:10px;background:#fafafa;">
          <button
            id="sameDayCancelBtn"
            style="background:#F1F2F4;color:#374151;border:1.5px solid #CBD5E1;
                   border-radius:9px;padding:10px 20px;font-size:13px;font-weight:600;
                   cursor:pointer;display:inline-flex;align-items:center;gap:6px;
                   transition:background 0.15s;"
            onmouseover="this.style.background='#EAECF0'"
            onmouseout="this.style.background='#F1F2F4'">
            <svg width="13" height="13" viewBox="0 0 24 24" fill="none"
                 stroke="currentColor" stroke-width="2">
              <line x1="18" y1="6" x2="6" y2="18"/>
              <line x1="6" y1="6" x2="18" y2="18"/>
            </svg>
            Cancel
          </button>
          <button
            id="sameDayConfirmBtn"
            style="background:linear-gradient(135deg,#7A4F0A 0%,#7A4F0A 100%);color:#fff;
                   border:none;border-radius:9px;padding:10px 22px;font-size:13px;font-weight:700;
                   cursor:pointer;display:inline-flex;align-items:center;gap:7px;
                   transition:opacity 0.15s;"
            onmouseover="this.style.opacity='0.88'"
            onmouseout="this.style.opacity='1'">
            <svg width="13" height="13" viewBox="0 0 24 24" fill="none"
                 stroke="currentColor" stroke-width="2.5">
              <polyline points="20 6 9 17 4 12"/>
            </svg>
            Yes, Apply Now
          </button>
        </div>
      </div>`;

    document.body.appendChild(overlay);

    document
      .getElementById("sameDayCancelBtn")
      .addEventListener("click", () => {
        overlay.remove();
        resolve(false);
      });
    document
      .getElementById("sameDayConfirmBtn")
      .addEventListener("click", () => {
        overlay.remove();
        resolve(true);
      });
  });
}

// ── Save Amendments ───────────────────────────────────────────
async function saveAmendments() {
  const btn = document.getElementById("btnWizardFinish");

  // ── Pre-save blocking validation ──────────────────────────────
  // If runValidations reports any severity:"error" issues (e.g. a discount
  // with no amount, a charge with no currency), block the save here and
  // surface the summary panel. This stops a half-saved amendment from
  // being created when Dataverse would 400 on the first required-field
  // violation mid-loop.
  try {
    const _pre =
      typeof runValidations === "function"
        ? runValidations()
        : { hasBlockers: false };
    if (_pre.hasBlockers) {
      // Make sure the user can see the panel + the disabled state
      if (typeof renderValidationSummary === "function")
        renderValidationSummary();
      const errorCount = (_pre.issues || []).filter(
        (i) => i.severity === "error",
      ).length;
      showAmendNotification(
        `❌ Cannot save — ${errorCount} required field${errorCount > 1 ? "s are" : " is"} missing. See the Validation Summary at the top of this step.`,
        "error",
      );
      // Scroll the validation panel into view
      const sumEl = document.getElementById("validationSummary");
      if (sumEl) {
        try {
          sumEl.scrollIntoView({ behavior: "smooth", block: "start" });
        } catch (_) {}
      }
      return;
    }
  } catch (vErr) {
    console.warn("Pre-save validation skipped due to error:", vErr);
  }

  // Collects any critical write failures across all save steps. If non-empty
  // at the end, the amendment is NOT flipped to PENDING and the success
  // screen is NOT shown — preventing a false "success" on a partial save.
  const saveFailures = [];

  // ── Same-day confirmation ─────────────────────────────────────
  // If effective date = today, changes will be written live to the
  // lease records (not deferred). Show a confirmation popup so the
  // user explicitly acknowledges this before proceeding.
  const effectiveDateCheck = document.getElementById("amend_startDate")?.value;
  if (effectiveDateCheck && effectiveDateCheck === getTodayStr()) {
    const confirmed = await _confirmSameDayAmendment(effectiveDateCheck);
    if (!confirmed) return; // user cancelled
  }

  let overlay = document.getElementById("amendSaveOverlay");
  if (!overlay) {
    overlay = document.createElement("div");
    overlay.id = "amendSaveOverlay";
    overlay.style.cssText = [
      "position:fixed",
      "inset:0",
      "background:rgba(11,21,89,0.72)",
      "z-index:999990",
      "display:flex",
      "flex-direction:column",
      "align-items:center",
      "justify-content:center",
      "gap:0",
    ].join(";");
    document.body.appendChild(overlay);
  }

  overlay.innerHTML = `
    <div style="background:#fff;border-radius:20px;padding:40px 48px;text-align:center;
                box-shadow:0 32px 80px rgba(0,0,0,0.35);min-width:320px;max-width:420px;">
      <div id="amendSaveOverlaySpinner">
        <div style="width:56px;height:56px;border:5px solid rgba(11,21,89,0.12);
                    border-top:5px solid #1C6BD4;border-radius:50%;
                    animation:spin 0.7s linear infinite;margin:0 auto 20px;"></div>
        <p style="color:#1C6BD4;font-size:17px;font-weight:700;margin:0 0 6px;">Saving Amendment…</p>
        <p style="color:#5A6070;font-size:13px;margin:0;" id="amendSaveOverlayStatus">
          Please wait, do not close this window.
        </p>
      </div>
      <div id="amendSaveOverlaySuccess" style="display:none;">
        <div id="amendSaveSuccessIcon"
             style="width:64px;height:64px;background:linear-gradient(135deg,#2E7D32,#1F5C23);
                    border-radius:50%;display:flex;align-items:center;justify-content:center;
                    margin:0 auto 20px;">
          <svg width="32" height="32" viewBox="0 0 24 24" fill="none" stroke="#fff" stroke-width="3">
            <polyline points="20 6 9 17 4 12"/>
          </svg>
        </div>
        <p id="amendSaveSuccessHeading"
           style="color:#2E7D32;font-size:18px;font-weight:800;margin:0 0 6px;">
          Amendment Saved!
        </p>
        <p id="amendSaveSuccessBody"
           style="color:#5A6070;font-size:13px;margin:0 0 16px;line-height:1.6;">
          All changes have been saved successfully.
        </p>
        <div id="amendSaveSuccessBadge" style="display:none;margin-bottom:22px;"></div>
        <button onclick="_closeAmendmentUIConfirmed()"
                style="background:linear-gradient(135deg,#1C6BD4,#0D4A9E);color:#fff;border:none;
                       border-radius:10px;padding:12px 36px;font-size:14px;font-weight:700;
                       cursor:pointer;display:inline-flex;align-items:center;gap:8px;">
          <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5">
            <line x1="18" y1="6" x2="6" y2="18"/>
            <line x1="6" y1="6" x2="18" y2="18"/>
          </svg>
          Close
        </button>
      </div>
    </div>`;
  overlay.style.display = "flex";

  const setStatus = (msg) => {
    const el = document.getElementById("amendSaveOverlayStatus");
    if (el) el.textContent = msg;
  };

  if (btn) {
    btn.disabled = true;
    btn.innerHTML = `
      <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"
           style="animation:spin 0.7s linear infinite">
        <path d="M21 12a9 9 0 11-9-9"/>
      </svg> Saving…`;
  }

  try {
    // ── STEP 1: Validate terms fields ─────────────────────────────
    const effectiveDate = document.getElementById("amend_startDate").value;
    const expiryDate = document.getElementById("amend_endDate").value;
    const description = document.getElementById("amend_description").value;

    if (!effectiveDate) throw new Error("Please enter an Effective Date.");
    // Expiry-vs-effective date validation removed by request — any expiry date allowed.

    // ── STEP 1a: Resolve Amendment Date ───────────────────────────
    // Use the value from the Amendment Date field (amend_moveInDate).
    // This is auto-populated with today on load but the user can change it.
    // If somehow empty (field was cleared), fall back to today's UTC ISO string.
    const amendmentDateFieldValue =
      document.getElementById("amend_moveInDate")?.value || "";

    let resolvedAmendmentDate;
    if (amendmentDateFieldValue) {
      // Field has a value (YYYY-MM-DD from the date input).
      // Convert to full ISO UTC datetime for Dataverse DateTime field.
      // We use T00:00:00Z so it stores as midnight UTC on that date.
      resolvedAmendmentDate = amendmentDateFieldValue + "T00:00:00Z";
    } else {
      // Fallback: use current UTC datetime if field was somehow empty
      resolvedAmendmentDate = new Date().toISOString();
    }

    console.log(`✅ Amendment Date to save: ${resolvedAmendmentDate}`);

    // ── Resolve key dates ──────────────────────────────────────────
    const leaseEndDate = amendLeaseData.array_leaseenddate
      ? amendLeaseData.array_leaseenddate.substring(0, 10)
      : "";

    const newExpiryIsGreater =
      expiryDate && leaseEndDate && expiryDate > leaseEndDate;

    const historyNewEndDate = newExpiryIsGreater ? expiryDate : leaseEndDate;
    const historyPreviousEndDate = leaseEndDate || null;

    // ── STEP 1b: Compute version number ───────────────────────────
    setStatus("Computing version number…");
    let newVersionNumber = 1;

    if (isEditMode && editingAmendmentId) {
      // Edit mode: fetch the existing version number — do not bump it
      try {
        const clientUrl = XrmCtx.Utility.getGlobalContext().getClientUrl();
        const vResp = await fetch(
          `${clientUrl}/api/data/v9.2/array_leaseamendmentses(${editingAmendmentId})` +
            `?$select=array_versionnumber`,
          {
            headers: {
              "OData-MaxVersion": "4.0",
              "OData-Version": "4.0",
              Accept: "application/json",
            },
            credentials: "same-origin",
          },
        );
        if (vResp.ok) {
          const vData = await vResp.json();
          newVersionNumber = parseInt(vData.array_versionnumber) || 1;
        }
      } catch (vErr) {
        console.warn("Could not fetch existing version number:", vErr);
      }
    } else {
      // Normal mode: compute next version number
      try {
        const clientUrl = XrmCtx.Utility.getGlobalContext().getClientUrl();
        const versionResp = await fetch(
          `${clientUrl}/api/data/v9.2/array_leaseamendmentses` +
            `?$select=array_versionnumber` +
            `&$filter=_array_leaseagreement_value eq ${amendLeaseId} and statecode eq 0` +
            `&$orderby=array_versionnumber desc&$top=50`,
          {
            headers: {
              "OData-MaxVersion": "4.0",
              "OData-Version": "4.0",
              Accept: "application/json",
              Prefer: 'odata.include-annotations="*"',
            },
            credentials: "same-origin",
          },
        );
        if (versionResp.ok) {
          const versionData = await versionResp.json();
          const records = versionData.value || [];
          if (records.length > 0) {
            const maxVersion = records.reduce((max, rec) => {
              const v = parseInt(rec.array_versionnumber) || 0;
              return v > max ? v : max;
            }, 0);
            newVersionNumber = maxVersion + 1;
          }
        }
      } catch (vErr) {
        console.warn(
          "⚠️ Could not compute version number, defaulting to 1:",
          vErr,
        );
        newVersionNumber = 1;
      }
    }
    console.log(
      `✅ Amendment version number: ${newVersionNumber}` +
        (isEditMode ? " [edit mode — preserved]" : ""),
    );

    // ── STEP 1c: Compute old/new area ─────────────────────────────
    setStatus("Computing old and new values…");

    const oldArea = [...amendExistingUnits, ...amendDeactivatedUnits].reduce(
      (sum, u) => {
        const area = parseFloat(u.array_Unit?.array_unitareasqm || 0);
        return sum + (isNaN(area) ? 0 : area);
      },
      0,
    );

    const newArea = [...amendExistingUnits, ...amendNewUnits].reduce(
      (sum, u) => {
        const area = parseFloat(u.array_Unit?.array_unitareasqm || 0);
        return sum + (isNaN(area) ? 0 : area);
      },
      0,
    );

    console.log(`✅ Area — Old: ${oldArea}, New: ${newArea}`);

    // ── STEP 1d: Compute PLN / EUR rent & deposit splits ──────────
    function _getChargeIso(c) {
      const ccyId = c._transactioncurrencyid_value;
      const ccyObj = ccyId
        ? amendCurrencies.find((cu) => cu.transactioncurrencyid === ccyId)
        : null;
      return (ccyObj?.isocurrencycode || "").toUpperCase();
    }

    function _getDepositIsoExisting(d) {
      const ccyObj = d.array_RequiredAmountCurrency || {};
      return (ccyObj.isocurrencycode || "").toUpperCase();
    }

    function _getDepositIsoNew(d) {
      return (d._currencyCode || "").toUpperCase();
    }

    let oldRentPLN = 0,
      oldRentEUR = 0;
    [...amendExistingCharges, ...amendDeactivatedCharges].forEach((c) => {
      const amt = parseFloat(c.array_amount || 0);
      if (isNaN(amt)) return;
      const iso = _getChargeIso(c);
      if (iso === "PLN") oldRentPLN += amt;
      else if (iso === "EUR") oldRentEUR += amt;
    });

    let newRentPLN = 0,
      newRentEUR = 0;
    [...amendExistingCharges, ...amendNewCharges].forEach((c) => {
      const amt = parseFloat(c.array_amount || 0);
      if (isNaN(amt)) return;
      const iso = _getChargeIso(c);
      if (iso === "PLN") newRentPLN += amt;
      else if (iso === "EUR") newRentEUR += amt;
    });

    console.log(`✅ Rent PLN — Old: ${oldRentPLN}, New: ${newRentPLN}`);
    console.log(`✅ Rent EUR — Old: ${oldRentEUR}, New: ${newRentEUR}`);

    let oldDepositPLN = 0,
      oldDepositEUR = 0;
    amendDeposits.forEach((d) => {
      const amt = parseFloat(d.array_requiredamount || 0);
      if (isNaN(amt)) return;
      const iso = _getDepositIsoExisting(d);
      if (iso === "PLN") oldDepositPLN += amt;
      else if (iso === "EUR") oldDepositEUR += amt;
    });

    let newDepositPLN = 0,
      newDepositEUR = 0;
    amendDeposits.forEach((d) => {
      const amt = parseFloat(d.array_requiredamount || 0);
      if (isNaN(amt)) return;
      const iso = _getDepositIsoExisting(d);
      if (iso === "PLN") newDepositPLN += amt;
      else if (iso === "EUR") newDepositEUR += amt;
    });
    amendNewDeposits.forEach((d) => {
      const amt = parseFloat(d.array_requiredamount || 0);
      if (isNaN(amt)) return;
      const iso = _getDepositIsoNew(d);
      if (iso === "PLN") newDepositPLN += amt;
      else if (iso === "EUR") newDepositEUR += amt;
    });

    console.log(
      `✅ Deposit PLN — Old: ${oldDepositPLN}, New: ${newDepositPLN}`,
    );
    console.log(
      `✅ Deposit EUR — Old: ${oldDepositEUR}, New: ${newDepositEUR}`,
    );

    // ── STEP 2: RESOLVE or CREATE array_leaseamendments ──────────
    // DEFERRED WRITE: reuse existing Draft if found, create new if not.
    // isSameDay drives live-vs-deferred branching for all child records.
    setStatus("Resolving amendment record…");

    const isSameDay = effectiveDate === getTodayStr();
    console.log(
      `ℹ️ Effective date: ${effectiveDate} | Today: ${getTodayStr()} | Same-day: ${isSameDay}`,
    );

    const amendmentRecord = {
      "array_LeaseAgreement@odata.bind": `/array_leaseagreements(${amendLeaseId})`,
      array_effectivedate: effectiveDate,
      array_versionnumber: newVersionNumber,
      array_amendmentname: `Annex No. ${newVersionNumber}`,
      array_amendmentdate: resolvedAmendmentDate,
      array_oldarea: oldArea > 0 ? oldArea : 0,
      array_newarea: newArea > 0 ? newArea : 0,
      array_oldrent: oldRentPLN > 0 ? oldRentPLN : 0,
      array_newrent: newRentPLN > 0 ? newRentPLN : 0,
      array_oldrentineur: oldRentEUR > 0 ? oldRentEUR : 0,
      array_newrentineur: newRentEUR > 0 ? newRentEUR : 0,
      array_olddeposit: oldDepositPLN > 0 ? oldDepositPLN : 0,
      array_newdeposit: newDepositPLN > 0 ? newDepositPLN : 0,
      array_olddepositineur: oldDepositEUR > 0 ? oldDepositEUR : 0,
      array_newdepositineur: newDepositEUR > 0 ? newDepositEUR : 0,
      // Start as Draft (statuscode) — flipped to Pending at end of save
      statuscode: AMENDMENT_STATUS.DRAFT,
    };

    if (expiryDate) amendmentRecord.array_expirydate = expiryDate;
    if (description) amendmentRecord.array_description = description;
    if (selectedAmendmentTypes.length)
      amendmentRecord.array_amendmenttype = selectedAmendmentTypes.join(",");

    // Stage lease end-date on amendment for any future-dated change
    // (extension or shortening). Same-day amendments write directly to
    // the lease in Step 2c below. Flow C promotes on the effective date.
    const _expiryChangedForStaging =
      expiryDate && leaseEndDate && expiryDate !== leaseEndDate;
    if (!isSameDay && _expiryChangedForStaging) {
      amendmentRecord.array_pendingleaseenddate = expiryDate;
    }

    const newAmendmentId = await resolveOrCreateAmendment(amendmentRecord);
    console.log(
      `✅ Amendment resolved: ${newAmendmentId} (v${newVersionNumber})`,
    );

    // ── STEP 2b: CREATE array_leasehistory ────────────────────────
    setStatus("Creating lease history record…");
    try {
      // ── Build detailed history description ────────────────────
      const historyLines = [];

      // 1. Amendment type
      if (selectedAmendmentTypes && selectedAmendmentTypes.length) {
        const typeLabels = selectedAmendmentTypes.map((v) => {
          const o = amendmentTypeOptions.find((x) => x.Value === v);
          return o
            ? o.Label?.UserLocalizedLabel?.Label || String(v)
            : String(v);
        });
        historyLines.push(`Type: ${typeLabels.join(", ")}`);
      }

      // 2. Effective date and expiry date
      const dateParts = [];
      if (effectiveDate)
        dateParts.push(`Effective: ${formatDateAmend(effectiveDate)}`);
      if (expiryDate) dateParts.push(`Expiry: ${formatDateAmend(expiryDate)}`);
      if (dateParts.length) historyLines.push(dateParts.join(" | "));

      // 3. Lease end date change (extension or shortening)
      if (expiryDate && leaseEndDate && expiryDate !== leaseEndDate) {
        const direction = newExpiryIsGreater ? "extended" : "shortened";
        historyLines.push(
          `Lease end date ${direction}: ${formatDateAmend(historyPreviousEndDate)} → ${formatDateAmend(expiryDate)}`,
        );
      }

      // 4. Units
      const unitParts = [];
      if (amendNewUnits.length) unitParts.push(`${amendNewUnits.length} added`);
      if (amendDeactivatedUnits.length)
        unitParts.push(`${amendDeactivatedUnits.length} deactivated`);
      if (amendEditedUnits.length)
        unitParts.push(`${amendEditedUnits.length} date-edited`);
      if (unitParts.length) historyLines.push(`Units: ${unitParts.join(", ")}`);

      // 5. Recurring charges
      const chargeParts = [];
      const chargesDeactivated = amendDeactivatedCharges.filter(
        (c) => c._pendingDeactivate,
      );
      const chargesEndDateEdited = amendExistingCharges.filter(
        (c) => c._pendingEndDateEdit,
      );
      if (pendingNewCharges.length)
        chargeParts.push(`${pendingNewCharges.length} added`);
      if (chargesDeactivated.length)
        chargeParts.push(`${chargesDeactivated.length} deactivated`);
      if (chargesEndDateEdited.length)
        chargeParts.push(`${chargesEndDateEdited.length} end-date edited`);
      if (chargeParts.length)
        historyLines.push(`Charges: ${chargeParts.join(", ")}`);

      // 6. Deposits
      const depositParts = [];
      if (amendNewDeposits.length)
        depositParts.push(`${amendNewDeposits.length} added`);
      if (pendingDepositUpdates.length)
        depositParts.push(`${pendingDepositUpdates.length} due-date edited`);
      if (depositParts.length)
        historyLines.push(`Deposits: ${depositParts.join(", ")}`);

      // 7. Clauses
      const clauseParts = [];
      const clausesDeactivated = amendDeactivatedClauses.filter(
        (c) => c._pendingDeactivate,
      );
      if (amendNewClauses.length)
        clauseParts.push(`${amendNewClauses.length} added`);
      if (clausesDeactivated.length)
        clauseParts.push(`${clausesDeactivated.length} deactivated`);
      if (pendingClauseExpiryUpdates.length)
        clauseParts.push(`${pendingClauseExpiryUpdates.length} expiry edited`);
      if (clauseParts.length)
        historyLines.push(`Clauses: ${clauseParts.join(", ")}`);

      // 8. Options
      const optionParts = [];
      const optionsDeactivated = amendDeactivatedOptions.filter(
        (o) => o._pendingDeactivate,
      );
      if (amendNewOptions.length)
        optionParts.push(`${amendNewOptions.length} added`);
      if (optionsDeactivated.length)
        optionParts.push(`${optionsDeactivated.length} deactivated`);
      if (optionParts.length)
        historyLines.push(`Options: ${optionParts.join(", ")}`);

      // 9. Discounts
      const discountParts = [];
      const discountsDeactivated = amendDeactivatedDiscounts.filter(
        (d) => d._pendingDeactivate,
      );
      if (amendNewDiscounts.length)
        discountParts.push(`${amendNewDiscounts.length} added`);
      if (discountsDeactivated.length)
        discountParts.push(`${discountsDeactivated.length} deactivated`);
      if (pendingDiscountEndDateEdits.length)
        discountParts.push(
          `${pendingDiscountEndDateEdits.length} end-date edited`,
        );
      if (discountParts.length)
        historyLines.push(`Discounts: ${discountParts.join(", ")}`);

      // 10. User notes
      if (description) historyLines.push(`Notes: ${description}`);

      // Join and truncate to ~500 chars to stay within Dataverse field limits
      let historyDescription = historyLines.join("\n");
      if (historyDescription.length > 500) {
        historyDescription = historyDescription.substring(0, 497) + "…";
      }

      const historyRecord = {
        "array_LeaseAgreement@odata.bind": `/array_leaseagreements(${amendLeaseId})`,
        "array_LeaseAmendment@odata.bind": `/array_leaseamendmentses(${newAmendmentId})`,
        array_historytype: 126330000,
        array_statuschangedate: new Date().toISOString(),
        array_description: historyDescription,
        ...(historyPreviousEndDate
          ? { array_previousenddate: historyPreviousEndDate }
          : {}),
        ...(historyNewEndDate ? { array_newenddate: historyNewEndDate } : {}),
      };
      await XrmCtx.WebApi.createRecord("array_leasehistory", historyRecord);
      console.log("✅ Lease history record created.");
    } catch (histErr) {
      console.warn(
        "⚠️ Could not create lease history record:",
        histErr.message || histErr,
      );
    }

    // ── STEP 2c: Lease end-date ───────────────────────────────────
    // Same-day: write directly to lease (live). Future: already staged
    // on amendment.array_pendingleaseenddate above; activation flow
    // will promote it on the effective date.
    //
    // ── GAP #8 (TODO): Propagate lease end-date extension to unit associations ──
    // The Lease Terms step shows a notice claiming "all active unit associations
    // will have their end dates updated to match the new lease expiry date."
    // This is NOT currently implemented in this client. Two options to address:
    //   (a) Add a loop here (same-day) and to the activation flow (future) that
    //       updates each array_leaseunitassociation where array_enddate is null
    //       or equals the old lease end date, setting it to the new expiry.
    //   (b) Move this logic server-side into the activation flow exclusively
    //       and remove the same-day handling here.
    // Until either is done, the UI promise does not match actual behavior.
    // Same-day: apply live to lease + unit associations regardless of
    // whether expiry was extended or shortened. Future-dated changes are
    // staged on the amendment (array_pendingleaseenddate above) and
    // handled by Flow C.
    const expiryChanged =
      expiryDate && leaseEndDate && expiryDate !== leaseEndDate;

    if (expiryChanged) {
      if (isSameDay) {
        setStatus("Updating lease agreement end date…");
        const oldLeaseEnd =
          amendLeaseData && amendLeaseData.array_leaseenddate
            ? amendLeaseData.array_leaseenddate.substring(0, 10)
            : "";
        try {
          await XrmCtx.WebApi.updateRecord(
            "array_leaseagreement",
            amendLeaseId,
            { array_leaseenddate: expiryDate },
          );
          console.log(
            `✅ Lease end date updated live to ${expiryDate} ` +
              `(${newExpiryIsGreater ? "extended" : "shortened"})`,
          );
          amendLeaseData.array_leaseenddate = expiryDate;

          // Re-date active unit associations to the new expiry. Only
          // units whose end date is empty or equals the OLD lease
          // end date are moved; units with a deliberately different
          // end date are left untouched. Applies to both extension
          // and shortening.
          try {
            await propagateExpiryToUnitAssociations(
              amendLeaseId,
              expiryDate,
              oldLeaseEnd,
              setStatus,
            );
          } catch (unitErr) {
            console.warn(
              "⚠️ Could not update unit association end dates:",
              unitErr.message || unitErr,
            );
            saveFailures.push("Update unit association end dates");
          }
        } catch (leaseUpdateErr) {
          console.warn(
            "⚠️ Could not update lease end date:",
            leaseUpdateErr.message || leaseUpdateErr,
          );
          saveFailures.push("Update lease end date");
        }
      } else {
        // Future-dated: staged on amendment.array_pendingleaseenddate.
        // Flow C promotes the lease end date AND re-dates unit
        // associations on the effective date. Do not apply here.
        console.log(
          `ℹ️ Lease end-date change to ${expiryDate} staged on amendment ` +
            `(array_pendingleaseenddate). Flow C will apply on effective date.`,
        );
      }
    }

    // ── STEP 3a: Save newly added Recurring Charges ───────────────
    setStatus("Saving recurring charges…");
    for (const charge of pendingNewCharges) {
      // Guard: skip charge with missing currency to prevent the whole save
      // from aborting on "/transactioncurrencies(undefined)" 400. Falls
      // back to the alternate property AI extraction sets.
      const _chargeCurrency =
        charge.currency || charge._transactioncurrencyid_value;
      if (!_chargeCurrency) {
        console.warn("Skipping charge without currency:", charge);
        saveFailures.push(
          `Recurring charge "${charge.name || charge.array_chargename || "(unnamed)"}" — currency missing`,
        );
        showAmendNotification(
          `❌ A recurring charge was skipped: required currency is missing. Open the charge and set a currency, then save again.`,
          "error",
        );
        continue;
      }

      const chargePayload = {
        array_chargename: charge.name,
        array_amount: charge.amount,
        array_startdate: charge.startDate,
        array_frequency: charge.frequency,
        array_dueindays: charge.dueInDays,
        array_invoicegenerationdate: charge.invoiceGenerationDate,
        array_prorationenabled: charge.prorationEnabled,
        array_prefrequencyoffset: charge.preFrequencyOffset,
        array_prorationenabledforlastcycle: charge.prorationEnabledLastCycle,
        array_invoiceseparately: charge.invoiceSeparately,
        array_taxincluded: charge.taxIncluded,
        "transactioncurrencyid@odata.bind": `/transactioncurrencies(${_chargeCurrency})`,
        "array_LeaseAgreement@odata.bind": `/array_leaseagreements(${amendLeaseId})`,
        "array_LeaseAmendments@odata.bind": `/array_leaseamendmentses(${newAmendmentId})`,
      };
      if (charge.endDate) chargePayload.array_enddate = charge.endDate;
      if (charge.billableArea)
        chargePayload.array_billablearea = charge.billableArea;
      if (charge.chargeType)
        chargePayload["array_ChargeType@odata.bind"] =
          `/array_chargetypes(${charge.chargeType})`;
      // Property lookup (mirrors leasecreation.js). Falls back to the lease's
      // property so supersede / end-date-sync / AI charges also get it.
      const _savePropertyId = String(
        charge.propertyId || amendLeaseData?._array_property_value || "",
      )
        .replace(/[{}]/g, "")
        .trim();
      if (_savePropertyId)
        chargePayload["array_Property@odata.bind"] =
          `/array_properties(${_savePropertyId})`;
      if (charge.unitId)
        chargePayload["array_Unit@odata.bind"] =
          `/array_units(${charge.unitId})`;
      if (charge.vat)
        chargePayload["array_VAT@odata.bind"] = `/array_vats(${charge.vat})`;
      if (charge.bankAccount)
        chargePayload["array_BankAccountNumber@odata.bind"] =
          `/array_bankaccounts(${charge.bankAccount})`;
      if (charge.rateRule)
        chargePayload["array_RateRule@odata.bind"] =
          `/array_exchangerateselectionruleses(${charge.rateRule})`;
      if (charge.invoiceType)
        chargePayload["array_InvoiceType@odata.bind"] =
          `/array_invoicetypes(${charge.invoiceType})`;
      if (charge.invoicePrefix)
        chargePayload["array_InvoicePrefix@odata.bind"] =
          `/array_invoiceprefixes(${charge.invoicePrefix})`;
      if (charge.dueDateRule !== undefined && charge.dueDateRule !== "")
        chargePayload.array_duedaterule = parseInt(charge.dueDateRule);
      if (charge.exchangeRateDay != null)
        chargePayload.array_exchangerateday = charge.exchangeRateDay;
      if (charge.useAsInvoiceCurrency !== undefined)
        chargePayload.array_useasinvoicecurrency = charge.useAsInvoiceCurrency;
      if (charge.prorationEnabledFirstCycle != null)
        chargePayload.array_prorationenabledforfirstcycle =
          charge.prorationEnabledFirstCycle;
      if (charge.frequencyStartDate)
        chargePayload.array_frequencystartdate = charge.frequencyStartDate;
      if (charge.frequencyEndDate)
        chargePayload.array_frequencyenddate = charge.frequencyEndDate;
      if (charge.frequencyStartDay)
        chargePayload.array_frequencystartday = charge.frequencyStartDay;
      if (charge.invoiceGenerationDay)
        chargePayload.array_invoicegenerationday = charge.invoiceGenerationDay;
      if (charge.tenantId) {
        // Recurring charge uses two separate tenant lookups (same as
        // deposits), NOT a single polymorphic array_Tenant. Bind to
        // the right one based on tenantType; otherwise skip to avoid
        // an "undeclared property" 400.
        if (charge.tenantType === "account") {
          chargePayload["array_Tenant_account@odata.bind"] =
            `/accounts(${charge.tenantId})`;
        } else if (charge.tenantType === "contact") {
          chargePayload["array_Tenant_contact@odata.bind"] =
            `/contacts(${charge.tenantId})`;
        }
      }
      // Supersede link: point the new charge back to the original charge
      // it replaced (set when this charge was created via a supersede edit).
      if (charge._amendedFromChargeId)
        chargePayload["array_AmendedFromCharge@odata.bind"] =
          `/array_recurringcharges(${charge._amendedFromChargeId})`;

      // Supersede replacements always take the future-dated path regardless of
      // isSameDay, so the original can co-exist active until Flow C promotes.
      const isSupersedeReplacement = !!charge._amendedFromChargeId;
      const willStageAsPending = !isSameDay || isSupersedeReplacement;

      // Upcoming Invoice Generation Day — the invoice flows filter on this
      // field (mirrors leasecreation.js). For charges that will be staged as
      // Pending Action it is NOT sent on create: the "Invoice Generation for
      // Today is created" flow fires on Create with no status filter, and the
      // record is still active at that moment, so a today-dated value would
      // invoice a pending/supersede charge immediately (double billing).
      // Pending charges get it on the status update instead; the daily list
      // flow only picks up active charges, i.e. after Flow C promotes them.
      const _upcomingInvGenDay = charge.invoiceGenerationDate
        ? String(charge.invoiceGenerationDate).substring(0, 10)
        : "";
      if (_upcomingInvGenDay && !willStageAsPending)
        chargePayload.array_upcominginvoicegenerationday = _upcomingInvGenDay;

      try {
        const created = await XrmCtx.WebApi.createRecord(
          "array_recurringcharge",
          chargePayload,
        );
        if (willStageAsPending) {
          const createdId = created.id.replace(/[{}]/g, "");
          const stagePayload = {
            statecode: 1,
            statuscode: STATUS.recurringcharge.ACTION,
          };
          if (_upcomingInvGenDay)
            stagePayload.array_upcominginvoicegenerationday =
              _upcomingInvGenDay;
          await XrmCtx.WebApi.updateRecord(
            "array_recurringcharge",
            createdId,
            stagePayload,
          );
          console.log(
            `✅ Charge staged as Pending Action: ${charge.name}${isSupersedeReplacement ? " (supersede)" : ""}`,
          );
        } else {
          console.log(`✅ Charge saved live (same-day): ${charge.name}`);
        }
      } catch (chargeErr) {
        console.error(`❌ Failed to save charge "${charge.name}":`, chargeErr);
        saveFailures.push(`Save charge "${charge.name}"`);
        showAmendNotification(
          `❌ Failed to save charge "${charge.name}": ${chargeErr.message || chargeErr}`,
          "error",
        );
      }
    }
    pendingNewCharges = [];

    // ── STEP 3b: Apply charge deactivations ──────────────────────
    // Same-day: deactivate immediately (statecode=1, statuscode=2).
    // Future-dated: write array_amendmentactions=126330001 (Deactivation)
    // on the charge record. The charge stays statecode=0 (active) so
    // CPI/Invoice/KSeF can still pick it up. Flow C reads this field
    // and deactivates the record on the effective date.
    setStatus("Applying charge deactivations…");
    for (const charge of amendDeactivatedCharges.filter(
      (c) => c._pendingDeactivate,
    )) {
      try {
        // Supersede-originated deactivations always take the future-dated path
        // so the record stays statecode=0 until Flow C promotes on the effective date.
        const forceFuture = charge._supersededBySave === true;
        const deactPayload =
          isSameDay && !forceFuture
            ? {
                statecode: 1,
                statuscode: 2,
                array_enddate: charge._deactivateEndDate,
                ...(charge._deactivateProration && {
                  array_prorationenabled: true,
                }),
                "array_LeaseAmendments@odata.bind": `/array_leaseamendmentses(${newAmendmentId})`,
              }
            : {
                // DEFERRED: mark action on the existing active record.
                // statecode stays 0 — charge remains invoiceable until Flow C fires.
                array_amendmentactions: 126330001,
                array_enddate: charge._deactivateEndDate,
                ...(charge._deactivateProration && {
                  array_prorationenabled: true,
                }),
                "array_LeaseAmendments@odata.bind": `/array_leaseamendmentses(${newAmendmentId})`,
              };
        await XrmCtx.WebApi.updateRecord(
          "array_recurringcharge",
          charge.array_recurringchargeid,
          deactPayload,
        );
        charge._pendingDeactivate = false;
        console.log(
          isSameDay
            ? `✅ Charge deactivated live: ${charge.array_recurringchargeid}`
            : `✅ Charge marked Pending Deactivation: ${charge.array_recurringchargeid}`,
        );
      } catch (err) {
        console.error("❌ Failed to deactivate charge:", err);
        saveFailures.push("Deactivate a charge");
        showAmendNotification(
          `❌ Failed to deactivate charge: ${err.message || err}`,
          "error",
        );
      }
    }

    // ── STEP 3c: Apply pending end-date edits on existing charges ──
    // array_amendmentactions=126330002 (Edit) marks this as an amendment edit.
    // Flow C reads this field and processes accordingly on the effective date.
    setStatus("Applying charge end date edits…");
    for (const charge of amendExistingCharges.filter(
      (c) => c._pendingEndDateEdit,
    )) {
      try {
        const payload = {
          array_amendmentactions: 126330002,
          array_enddate: charge._pendingEndDate,
          "array_LeaseAmendments@odata.bind": `/array_leaseamendmentses(${newAmendmentId})`,
        };
        if (charge._pendingLastCycleProration !== undefined)
          payload.array_prorationenabledforlastcycle =
            charge._pendingLastCycleProration === true;
        if (charge._pendingProrationEnabled !== undefined)
          payload.array_prorationenabled =
            charge._pendingProrationEnabled === true;
        await XrmCtx.WebApi.updateRecord(
          "array_recurringcharge",
          charge.array_recurringchargeid,
          payload,
        );
        delete charge._pendingEndDateEdit;
        delete charge._pendingEndDate;
        delete charge._pendingLastCycleProration;
        delete charge._pendingProrationEnabled;
        console.log(
          `✅ Charge end date + proration updated: ${charge.array_recurringchargeid}`,
        );
      } catch (err) {
        console.error("❌ Failed to update charge end date:", err);
        saveFailures.push("Update a charge end date");
        showAmendNotification(
          `❌ Failed to update charge end date: ${err.message || err}`,
          "error",
        );
      }
    }

    // ── STEP 4a: Save newly added Unit Associations ───────────────
    // Same-day: create active + run _au_updateUnitLeaseAndTenant.
    // Future: create as Pending Action; defer the CurrentLease/Tenant
    // side-effect to the activation flow.
    setStatus("Saving unit associations…");
    for (const u of amendNewUnits) {
      if (!u._isPending) continue;
      const unitPayload = {
        "array_LeaseAgreement@odata.bind": `/array_leaseagreements(${amendLeaseId})`,
        "array_Unit@odata.bind": `/array_units(${u._unitId})`,
        array_startdate: u._startDate,
        "array_LeaseAmendments@odata.bind": `/array_leaseamendmentses(${newAmendmentId})`,
      };
      if (u._endDate) unitPayload.array_enddate = u._endDate;
      if (u._buildingId)
        unitPayload["array_Building@odata.bind"] =
          `/array_buildings(${u._buildingId})`;
      try {
        const created = await XrmCtx.WebApi.createRecord(
          "array_leaseunitassociation",
          unitPayload,
        );
        u._isPending = false;
        const createdId = created.id.replace(/[{}]/g, "");
        await XrmCtx.WebApi.updateRecord(
          "array_leaseunitassociation",
          createdId,
          { statecode: 1, statuscode: STATUS.leaseunitassociation.ACTION },
        );
        console.log(
          `✅ Unit association staged as Pending Action: ${u.array_Unit?.array_unitname}`,
        );
      } catch (unitErr) {
        console.error(`❌ Failed to save unit association:`, unitErr);
        saveFailures.push(
          `Save unit "${u.array_Unit?.array_unitname || u._unitId || ""}"`,
        );
        showAmendNotification(
          `❌ Failed to save unit "${u.array_Unit?.array_unitname}": ${unitErr.message || unitErr}`,
          "error",
        );
      }
    }
    amendNewUnits = amendNewUnits.filter((u) => u._isPending);

    // ── STEP 4b: Apply unit deactivations ────────────────────────
    setStatus("Applying unit deactivations…");
    for (const u of amendDeactivatedUnits.filter((u) => u._pendingDeactivate)) {
      try {
        const unitDeactPayload = {
          array_amendmentactions: 126330001,
          array_amendmentenddate: u._deactivateEndDate,
          "array_LeaseAmendments@odata.bind": `/array_leaseamendmentses(${newAmendmentId})`,
        };
        await XrmCtx.WebApi.updateRecord(
          "array_leaseunitassociation",
          u.array_leaseunitassociationid,
          unitDeactPayload,
        );
        u._pendingDeactivate = false;
        console.log(
          isSameDay
            ? `✅ Unit deactivated live: ${u.array_Unit?.array_unitname}`
            : `✅ Unit marked Pending Deactivation: ${u.array_Unit?.array_unitname}`,
        );
      } catch (unitErr) {
        console.error(`❌ Failed to deactivate unit:`, unitErr);
        saveFailures.push(
          `Deactivate unit "${u.array_Unit?.array_unitname || ""}"`,
        );
        showAmendNotification(
          `❌ Failed to deactivate unit "${u.array_Unit?.array_unitname}": ${unitErr.message || unitErr}`,
          "error",
        );
      }
    }

    // ── STEP 4c: Apply pending unit date edits ────────────────────
    // array_amendmentactions=126330002 (Edit) marks this as an amendment edit.
    for (const edit of amendEditedUnits) {
      try {
        await XrmCtx.WebApi.updateRecord(
          "array_leaseunitassociation",
          edit.assocId,
          {
            array_amendmentactions: 126330002,
            array_amendmentenddate: edit.endDate || null,
            "array_LeaseAmendments@odata.bind": `/array_leaseamendmentses(${newAmendmentId})`,
          },
        );
        console.log(`✅ Unit dates updated: ${edit.assocId}`);
      } catch (editErr) {
        console.error(`❌ Failed to update unit dates:`, editErr);
        saveFailures.push("Update unit dates");
        showAmendNotification(
          `❌ Failed to update unit dates: ${editErr.message || editErr}`,
          "error",
        );
      }
    }
    amendEditedUnits = [];

    // ── STEP 5a: Save newly added Security & Insurance ────────────
    setStatus("Saving security & insurance records…");
    for (const dep of amendNewDeposits) {
      const isDeposit =
        String(dep.array_type) === String(getDepositTypeValue());

      // Guard: if currency was somehow not resolved (e.g. AI extraction
      // could not match the document currency), skip this record with a
      // clear error rather than letting Dataverse 400 on
      // "/transactioncurrencies(undefined)" and abort the whole save.
      // Fallback: use the lease's primary currency if available.
      let _currencyId =
        dep._currencyId ||
        dep._RequiredAmountCurrency_value ||
        dep._transactioncurrencyid_value;

      // Amount-exempt types (Notary 777 p.4/p.5) may legitimately have no amount/currency
      const _depAmountRequired =
        typeof ed_typeRequiresAmount === "function"
          ? ed_typeRequiresAmount(dep.array_type)
          : !(COLLATERAL_TYPES_NO_AMOUNT || []).includes(
              parseInt(dep.array_type),
            );

      if (_depAmountRequired && !_currencyId) {
        console.warn("Skipping deposit without currency:", dep);
        saveFailures.push(
          `Security/Insurance "${dep._typeLabel || dep.array_type}" — currency missing`,
        );
        showAmendNotification(
          `❌ A security/insurance record was skipped: required currency is missing. Open the deposit and set a currency, then save again.`,
          "error",
        );
        continue;
      }

      const depPayload = {
        array_type: dep.array_type,
        "array_LeaseAgreement@odata.bind": `/array_leaseagreements(${amendLeaseId})`,
        "array_LeaseAmmendment@odata.bind": `/array_leaseamendmentses(${newAmendmentId})`,
      };
      // Amount + Currency only when present (amount-exempt types skip both)
      if (dep.array_requiredamount != null && dep.array_requiredamount !== "")
        depPayload.array_requiredamount = dep.array_requiredamount;
      if (_currencyId)
        depPayload["array_RequiredAmountCurrency@odata.bind"] =
          `/transactioncurrencies(${_currencyId})`;
      if (dep.array_deposittype)
        depPayload.array_deposittype = dep.array_deposittype;
      if (dep.array_duedate) depPayload.array_duedate = dep.array_duedate;
      if (dep.array_numberofpayments)
        depPayload.array_numberofpayments = dep.array_numberofpayments;
      if (dep._unitId)
        depPayload["array_Unit@odata.bind"] = `/array_units(${dep._unitId})`;
      // Bank Name: Deposit AND Bank Guarantee (BG added per client request)
      const _isBGType =
        parseInt(dep.array_type) === COLLATERAL_TYPE_BANK_GUARANTEE;
      if ((isDeposit || _isBGType) && dep._bankId)
        depPayload["array_BankName@odata.bind"] = `/accounts(${dep._bankId})`;
      if (!isDeposit) {
        if (dep._amountDelivered && dep._amountDelivered > 0)
          depPayload.array_amountdelivered = dep._amountDelivered;
        if (dep._amountDeliveredCurrencyId)
          depPayload["array_AmountDeliveredCurrency@odata.bind"] =
            `/transactioncurrencies(${dep._amountDeliveredCurrencyId})`;
        if (dep._issuerId)
          depPayload["array_Issuer@odata.bind"] = `/accounts(${dep._issuerId})`;
        if (dep._collateralApproved !== "" && dep._collateralApproved != null)
          depPayload.array_collateralapproved =
            dep._collateralApproved === "true";
        // Approved-only fields: persist only when explicitly approved
        if (dep._collateralApproved === "true") {
          if (dep._deliveryDate)
            depPayload.array_deliverydate = dep._deliveryDate;
          if (dep._expiryDate) depPayload.array_expirydate = dep._expiryDate;
          if (dep._guaranteeNo) depPayload.array_guaranteeno = dep._guaranteeNo;
          if (dep._comment) depPayload.array_comment = dep._comment;
        }
      }
      if (dep._tenantId) {
        const entity = dep._tenantType === "account" ? "accounts" : "contacts";
        const field =
          dep._tenantType === "account"
            ? "array_Tenant_account@odata.bind"
            : "array_Tenant_contact@odata.bind";
        depPayload[field] = `/${entity}(${dep._tenantId})`;
      }
      try {
        const created = await XrmCtx.WebApi.createRecord(
          "array_deposit",
          depPayload,
        );
        const createdId = created.id.replace(/[{}]/g, "");
        await XrmCtx.WebApi.updateRecord("array_deposit", createdId, {
          statecode: 1,
          statuscode: STATUS.deposit.ACTION,
        });
        console.log(
          `✅ Security record staged as Pending Action: type ${dep.array_type}`,
        );
      } catch (depErr) {
        console.error("❌ Failed to save security record:", depErr);
        saveFailures.push(
          `Save security/deposit record (type ${dep.array_type})`,
        );
        showAmendNotification(
          `❌ Failed to save security record: ${depErr.message || depErr}`,
          "error",
        );
      }
    }
    amendNewDeposits = [];

    // ── STEP 5b: Apply pending due-date edits on existing deposits ─
    // array_amendmentactions=126330002 (Edit) marks this as an amendment edit.
    // array_amendmentduedate stores the new due date for Flow C to promote.
    setStatus("Applying deposit due date edits…");
    for (const edit of pendingDepositUpdates) {
      try {
        await XrmCtx.WebApi.updateRecord("array_deposit", edit.id, {
          array_amendmentactions: 126330002,
          array_amendmentduedate: edit.dueDate || null,
          "array_LeaseAmmendment@odata.bind": `/array_leaseamendmentses(${newAmendmentId})`,
        });
        console.log(
          `✅ Deposit due date staged via array_amendmentduedate: ${edit.id}`,
        );
      } catch (editErr) {
        console.error("❌ Failed to update deposit due date:", editErr);
        saveFailures.push("Update a deposit due date");
        showAmendNotification(
          `❌ Failed to update deposit due date: ${editErr.message || editErr}`,
          "error",
        );
      }
    }
    pendingDepositUpdates = [];

    // ── STEP 5c: Apply deactivations on existing deposits (e.g. superseded) ─
    // Same-day: deactivate immediately. Future: mark Pending Deactivation
    // (array_amendmentactions=126330001) for Flow C to promote on the
    // effective date. Mirrors the discount/unit deactivation pattern.
    // NOTE: the deposit amendment lookup is named array_LeaseAmmendment.
    for (const dep of amendDeactivatedDeposits.filter(
      (d) => d._pendingDeactivate,
    )) {
      try {
        const payload = isSameDay
          ? {
              statecode: 1,
              statuscode: 2,
              "array_LeaseAmmendment@odata.bind": `/array_leaseamendmentses(${newAmendmentId})`,
            }
          : {
              array_amendmentactions: 126330001,
              array_amendmentduedate: dep._deactivateDueDate || null,
              "array_LeaseAmmendment@odata.bind": `/array_leaseamendmentses(${newAmendmentId})`,
            };
        await XrmCtx.WebApi.updateRecord(
          "array_deposit",
          dep.array_depositid,
          payload,
        );
        dep._pendingDeactivate = false;
        console.log(
          `✅ Deposit ${isSameDay ? "deactivated live" : "marked Pending Deactivation"}: ${dep.array_depositid}`,
        );
      } catch (err) {
        console.error("❌ Failed to deactivate deposit:", err);
        saveFailures.push("Deactivate a deposit");
        showAmendNotification(
          `❌ Failed to deactivate deposit: ${err.message || err}`,
          "error",
        );
      }
    }
    amendDeactivatedDeposits = [];

    // ── STEP 6: Save Lease Clauses ────────────────────────────────
    setStatus("Saving financial clauses…");
    await cl_saveAllPendingClauses(newAmendmentId, isSameDay);

    // ── STEP 7: Save Lease Options ────────────────────────────────────────────
    setStatus("Saving lease options…");
    await ao_saveAllPendingOptions(newAmendmentId, isSameDay);

    // ── STEP 7b: Save Discounts ───────────────────────────────────
    setStatus("Saving discounts…");

    // 1. Apply deactivations on existing discounts
    for (const disc of amendDeactivatedDiscounts.filter(
      (d) => d._pendingDeactivate,
    )) {
      try {
        const payload = isSameDay
          ? {
              statecode: 1,
              statuscode: 2,
              "array_LeaseAmendments@odata.bind": `/array_leaseamendmentses(${newAmendmentId})`,
            }
          : {
              array_amendmentactions: 126330001,
              array_amendmentenddate: disc.array_enddate || null,
              "array_LeaseAmendments@odata.bind": `/array_leaseamendmentses(${newAmendmentId})`,
            };
        await XrmCtx.WebApi.updateRecord(
          "array_discount",
          disc.array_discountid,
          payload,
        );
        disc._pendingDeactivate = false;
        console.log(
          `✅ Discount ${isSameDay ? "deactivated live" : "marked Pending Deactivation"}: ${disc.array_discountid}`,
        );
      } catch (err) {
        console.error("❌ Failed to deactivate discount:", err);
        saveFailures.push("Deactivate a discount");
        showAmendNotification(
          `❌ Failed to deactivate discount: ${err.message || err}`,
          "error",
        );
      }
    }

    // 2. Apply end date edits on existing discounts
    for (const edit of pendingDiscountEndDateEdits) {
      try {
        await XrmCtx.WebApi.updateRecord("array_discount", edit.id, {
          array_amendmentactions: 126330002,
          array_amendmentenddate: edit.endDate || null,
          "array_LeaseAmendments@odata.bind": `/array_leaseamendmentses(${newAmendmentId})`,
        });
        console.log(
          `✅ Discount end date staged: ${edit.id} → ${edit.endDate}`,
        );
      } catch (err) {
        console.error("❌ Failed to update discount end date:", err);
        saveFailures.push("Update a discount end date");
        showAmendNotification(
          `❌ Failed to update discount end date: ${err.message || err}`,
          "error",
        );
      }
    }
    pendingDiscountEndDateEdits = [];

    // 3. Save new discounts with Pending Activation status (future-dated)
    for (const disc of amendNewDiscounts) {
      // Normalize dates to YYYY-MM-DD before appending the time suffix.
      // Guards against double "T00:00:00Z" when the source already had a
      // full ISO string (e.g. AI-extracted dates arrive as ISO), and
      // against empty strings producing an invalid "T00:00:00Z" payload.
      const discStartDate = String(disc.array_startdate || "").substring(0, 10);
      const discEndDate = String(disc.array_enddate || "").substring(0, 10);
      if (!discStartDate || !discEndDate) {
        console.error(
          "❌ Skipping discount with missing start/end date:",
          disc,
        );
        saveFailures.push("Save a discount record (missing start or end date)");
        continue;
      }
      const discPayload = {
        "array_LeaseAgreement@odata.bind": `/array_leaseagreements(${amendLeaseId})`,
        "array_LeaseAmendments@odata.bind": `/array_leaseamendmentses(${newAmendmentId})`,
        array_chargetype: disc.array_chargetype,
        array_discounttype: disc.array_discounttype,
        array_discountpercentage: disc.array_discountpercentage,
        array_startdate: discStartDate + "T00:00:00Z",
        array_enddate: discEndDate + "T00:00:00Z",
      };
      // Specific Type → bind charge type category
      if (
        disc.array_chargetype === DISC_CHARGE_SPECIFIC_TYPE &&
        disc._chargeTypeCategoryId
      ) {
        discPayload["array_ChargeTypeCategory@odata.bind"] =
          `/array_chargetypes(${disc._chargeTypeCategoryId})`;
      }
      // Specific Charge → bind recurring charge
      if (
        disc.array_chargetype === DISC_CHARGE_SPECIFIC_CHARGE &&
        disc._recurringChargeId
      ) {
        discPayload["array_RecurringCharge@odata.bind"] =
          `/array_recurringcharges(${disc._recurringChargeId})`;
      }
      // Supersede link: point the new discount back to the original discount
      // it replaced (set when this discount was created via a supersede edit).
      if (disc._supersedesId) {
        discPayload["array_AmendedFromDiscount@odata.bind"] =
          `/array_discounts(${disc._supersedesId})`;
      }
      try {
        const created = await XrmCtx.WebApi.createRecord(
          "array_discount",
          discPayload,
        );
        if (!isSameDay) {
          const createdId = created.id.replace(/[{}]/g, "");
          await XrmCtx.WebApi.updateRecord("array_discount", createdId, {
            statecode: 1,
            statuscode: STATUS.discount.ACTION,
          });
          console.log(`✅ Discount staged as Pending Activation.`);
        } else {
          console.log(`✅ Discount saved live.`);
        }
      } catch (discErr) {
        console.error("❌ Failed to save discount:", discErr);
        saveFailures.push("Save a discount record");
        showAmendNotification(
          `❌ Failed to save a discount record: ${discErr.message || discErr}`,
          "error",
        );
      }
    }
    amendNewDiscounts = [];

    // ── STEP 8: Trigger Power Automate flow with uploaded files ───
    // fu_triggerFlow lazy-loads AMENDMENT_FLOW_URL from the 'array_UploadPdf'
    // env var and skips internally when unset — do NOT pre-check it here.
    if (uploadedFiles.length > 0) {
      setStatus(
        `Uploading ${uploadedFiles.length} file${uploadedFiles.length !== 1 ? "s" : ""} to flow…`,
      );
      try {
        await fu_triggerFlow(newAmendmentId);
        console.log("✅ Flow triggered with files.");
      } catch (flowErr) {
        console.error("❌ Flow trigger error:", flowErr);
        showAmendNotification(
          `⚠️ Amendment saved, but file upload flow failed: ${flowErr.message || flowErr}`,
          "warning",
        );
      }
    }

    // ── PARTIAL-SAVE GATE ─────────────────────────────────────────
    // If any critical write failed above, do NOT flip the amendment to
    // PENDING (which would trigger the activation flow on an incomplete
    // amendment) and do NOT show the success screen. Leave the amendment
    // as-is (Draft) so it won't auto-activate, and tell the user exactly
    // what failed so they can fix and re-save or delete it.
    if (saveFailures.length > 0) {
      console.error(
        "❌ Amendment partially saved. Failed steps:",
        saveFailures,
      );
      const overlayEl = document.getElementById("amendSaveOverlay");
      if (overlayEl) overlayEl.style.display = "none";
      if (btn) {
        btn.disabled = false;
        // Restore the button label — was set to "Saving…" before the
        // save started. Without this, the user sees a stuck "Saving…"
        // state even though the save has actually finished (with errors).
        btn.innerHTML = `
        <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
          <path d="M19 21H5a2 2 0 01-2-2V5a2 2 0 012-2h11l5 5v11a2 2 0 01-2 2z"/>
          <polyline points="17 21 17 13 7 13 7 21"/>
          <polyline points="7 3 7 8 15 8"/>
        </svg> Save Amendments`;
      }
      const unique = [...new Set(saveFailures)];
      showAmendNotification(
        "⚠️ Amendment NOT completed — some changes failed to save: " +
          unique.join("; ") +
          ". The amendment was left as Draft and has NOT been activated. " +
          "Please review and re-save, or delete it and start again.",
        "error",
      );
      return; // stop before status flip + success screen
    }

    // ── STEP 9: Flip amendment to PENDING ────────────────────────
    // This is the LAST write before success. All child records are
    // already saved/staged at this point. Flipping to PENDING here
    // means the event-driven activation flow (Flow A) fires only
    // after the amendment is fully built — no race mid-save.
    // Same-day amendments also flip to PENDING for audit trail
    // consistency; the activation flow handles the same-day case.
    setStatus("Finalising amendment status…");
    try {
      await XrmCtx.WebApi.updateRecord(
        "array_leaseamendments",
        newAmendmentId,
        { statuscode: AMENDMENT_STATUS.PENDING },
      );
      console.log(
        `✅ Amendment ${newAmendmentId} → PENDING (statuscode). ` +
          `Effective date: ${effectiveDate} | Same-day: ${isSameDay}`,
      );
    } catch (statusErr) {
      // Non-fatal — children are saved, but flow won't auto-trigger.
      // Ops can manually flip statuscode to Pending (126330001).
      console.error(
        "⚠️ Failed to flip amendment to PENDING — children saved but " +
          "activation flow won't auto-trigger. Fix manually:",
        statusErr,
      );
      showAmendNotification(
        "⚠️ Amendment saved but status flip to Pending failed. " +
          "Activation flow may not trigger. Contact admin.",
        "warning",
      );
    }

    // ── SUCCESS ───────────────────────────────────────────────────
    const spinnerEl = document.getElementById("amendSaveOverlaySpinner");
    const successEl = document.getElementById("amendSaveOverlaySuccess");
    if (spinnerEl) spinnerEl.style.display = "none";
    if (successEl) successEl.style.display = "block";

    // Customise success message based on whether effective date is today
    const headingEl = document.getElementById("amendSaveSuccessHeading");
    const bodyEl = document.getElementById("amendSaveSuccessBody");
    const badgeEl = document.getElementById("amendSaveSuccessBadge");

    if (isSameDay) {
      if (headingEl) headingEl.textContent = "Amendment Applied!";
      if (bodyEl)
        bodyEl.textContent =
          "Effective date is today — all changes have been written directly to the lease records.";
      if (badgeEl) {
        badgeEl.style.display = "block";
        badgeEl.innerHTML = `
          <div style="display:inline-flex;align-items:center;gap:8px;
                      background:#EDF7EE;border:1.5px solid #A8D5AB;
                      border-radius:10px;padding:9px 16px;">
            <svg width="15" height="15" viewBox="0 0 24 24" fill="none"
                 stroke="#2E7D32" stroke-width="2.5">
              <polyline points="20 6 9 17 4 12"/>
            </svg>
            <span style="font-size:12px;font-weight:700;color:#15803d;">
              Applied immediately — no activation flow needed
            </span>
          </div>`;
      }
    } else {
      if (headingEl) headingEl.textContent = "Amendment Saved!";
      if (bodyEl)
        bodyEl.textContent =
          "All changes have been staged. The activation flow will apply them on the effective date.";
      if (badgeEl) {
        badgeEl.style.display = "block";
        badgeEl.innerHTML = `
          <div style="display:inline-flex;align-items:center;gap:8px;
                      background:#EBF3FF;border:1.5px solid #BBDBFF;
                      border-radius:10px;padding:9px 16px;">
            <svg width="15" height="15" viewBox="0 0 24 24" fill="none"
                 stroke="#0D4A9E" stroke-width="2.5">
              <circle cx="12" cy="12" r="10"/>
              <line x1="12" y1="8" x2="12" y2="12"/>
              <line x1="12" y1="16" x2="12.01" y2="16"/>
            </svg>
            <span style="font-size:12px;font-weight:700;color:#0D4A9E;">
              Pending activation on ${formatDateAmend(effectiveDate)}
            </span>
          </div>`;
      }
    }

    if (btn) {
      btn.disabled = false;
      btn.innerHTML = `
        <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
          <path d="M19 21H5a2 2 0 01-2-2V5a2 2 0 012-2h11l5 5v11a2 2 0 01-2 2z"/>
          <polyline points="17 21 17 13 7 13 7 21"/>
          <polyline points="7 3 7 8 15 8"/>
        </svg> Save Amendments`;
    }
  } catch (err) {
    console.error("Save amendments error:", err);
    if (overlay) overlay.remove();
    if (btn) {
      btn.disabled = false;
      btn.innerHTML = `
        <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
          <path d="M19 21H5a2 2 0 01-2-2V5a2 2 0 012-2h11l5 5v11a2 2 0 01-2 2z"/>
          <polyline points="17 21 17 13 7 13 7 21"/>
          <polyline points="7 3 7 8 15 8"/>
        </svg> Save Amendments`;
    }
    showAmendNotification(
      `❌ Error saving amendment: ${err.message || err}`,
      "error",
    );
  }
}

// ── Edit Charge Modal ─────────────────────────────────────────
let _editingChargeIdx = null;
let _supersedeChargeId = null; // id of existing charge being superseded (full-field edit)

function openEditChargeModal(idx) {
  _supersedeChargeId = null;
  const c = amendNewCharges[idx];
  if (!c) return;
  _editingChargeIdx = idx;

  // ── Open modal UI shell (resets fields + rebuilds dropdowns) ──
  openAddChargeModal();

  // ── Restore _editingChargeIdx (openAddChargeModal resets it to null) ──
  _editingChargeIdx = idx;

  // ── Update modal title and save button to "Edit" style ────
  const titleEl = document.getElementById("addChargeModalTitle");
  if (titleEl) {
    titleEl.textContent = "Edit Recurring Charge";
    titleEl.style.color = "#0D4A9E";
  }
  const saveBtn = document.getElementById("addChargeSaveBtn");
  if (saveBtn)
    saveBtn.innerHTML = `<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M19 21H5a2 2 0 01-2-2V5a2 2 0 012-2h11l5 5v11a2 2 0 01-2 2z"/><polyline points="17 21 17 13 7 13 7 21"/></svg> Save Changes`;

  // Re-fetch charge after openAddChargeModal (state unchanged)
  const charge = amendNewCharges[idx];
  if (!charge) return;

  // ── Pending charge has the full original payload ──────────
  const pendingCharge = pendingNewCharges.find(
    (p) => p.id === charge.array_recurringchargeid,
  );

  // ── Use setTimeout to run AFTER openAddChargeModal's own
  //    setTimeout (which sets monthly default + runs setup).
  //    Delay of 150ms ensures our restore runs last. ─────────
  setTimeout(() => {
    // ── SECTION 1: Hidden state ─────────────────────────────
    document.getElementById("ac_editId").value =
      charge.array_recurringchargeid || "";

    // ── SECTION 2: Linking Information ─────────────────────
    document.getElementById("ac_name").value =
      pendingCharge?.name || charge.array_chargename || "";

    // Charge Type
    const chargeTypeId =
      pendingCharge?.chargeType ||
      charge.array_ChargeType?.array_chargetypeid ||
      "";
    if (chargeTypeId) {
      const ctEl = document.getElementById("ac_chargeType");
      if (ctEl) ctEl.value = chargeTypeId;
    }

    // Unit
    const unitId =
      pendingCharge?.unitId || charge.array_Unit?.array_unitid || "";
    if (unitId) {
      const uEl = document.getElementById("ac_unit");
      if (uEl) uEl.value = unitId;
    }

    // Trigger invoice type auto-population after charge type + unit are set
    ac_autoPopulateInvoiceType();

    // ── SECTION 3: Timeline Information ────────────────────

    // Start Date
    const startDate =
      pendingCharge?.startDate ||
      (charge.array_startdate ? charge.array_startdate.substring(0, 10) : "");
    const startEl = document.getElementById("ac_startDate");
    if (startEl) startEl.value = startDate;

    // End Date
    const endDate =
      pendingCharge?.endDate ||
      (charge.array_enddate ? charge.array_enddate.substring(0, 10) : "");
    const endEl = document.getElementById("ac_endDate");
    if (endEl) endEl.value = endDate;

    // ── FREQUENCY — restore AFTER openAddChargeModal's
    //    monthly default so it does not get overwritten ──────
    const freqVal =
      pendingCharge?.frequency != null
        ? pendingCharge.frequency
        : charge.array_frequency != null
          ? charge.array_frequency
          : "";

    const freqEl = document.getElementById("ac_frequency");
    if (freqEl && freqVal !== "") {
      freqEl.value = String(freqVal);
      // Trigger visibility and max-date recalculation
      ac_handleFrequencyVisibility();
      ac_updateInvoiceGenDateMax();
    }

    // Pre Frequency Offset
    const preFreqOffset =
      pendingCharge?.preFrequencyOffset != null
        ? pendingCharge.preFrequencyOffset
        : charge.array_prefrequencyoffset != null
          ? charge.array_prefrequencyoffset
          : false;
    const pfEl = document.getElementById("ac_preFrequencyOffset");
    if (pfEl) pfEl.value = preFreqOffset ? "true" : "false";

    // Proration Enabled
    const prorationEnabled =
      pendingCharge?.prorationEnabled != null
        ? pendingCharge.prorationEnabled
        : charge.array_prorationenabled != null
          ? charge.array_prorationenabled
          : false;
    const proEl = document.getElementById("ac_prorationEnabled");
    if (proEl) {
      proEl.value = prorationEnabled ? "true" : "false";
      ac_handleProrationChange();
    }

    // Proration First Cycle
    if (pendingCharge?.prorationEnabledFirstCycle != null) {
      const firstCycleEl = document.getElementById(
        "ac_prorationEnabledFirstCycle",
      );
      if (firstCycleEl) {
        firstCycleEl.value =
          pendingCharge.prorationEnabledFirstCycle === true
            ? "true"
            : pendingCharge.prorationEnabledFirstCycle === false
              ? "false"
              : "";
        ac_handleFirstCycleProrationChange();
      }
    }

    // Proration Last Cycle
    if (pendingCharge?.prorationEnabledLastCycle != null) {
      const lastCycleEl = document.getElementById(
        "ac_prorationEnabledLastCycle",
      );
      if (lastCycleEl)
        lastCycleEl.value = pendingCharge.prorationEnabledLastCycle
          ? "true"
          : "false";
    }

    // First Cycle Frequency End Date (input id is "ac_frequencyStartDate").
    // Only meaningful when first-cycle proration is on; otherwise leave the
    // auto-populated value alone.
    const _firstCycleOn =
      pendingCharge?.prorationEnabledFirstCycle === true ||
      (pendingCharge?.prorationEnabledFirstCycle == null &&
        charge.array_prorationenabledforfirstcycle === true);
    const firstCycleEnd = _firstCycleOn
      ? pendingCharge?.firstCycleEndDate ||
        pendingCharge?.frequencyEndDate ||
        (charge.array_frequencyenddate
          ? String(charge.array_frequencyenddate).substring(0, 10)
          : "")
      : "";
    if (firstCycleEnd) {
      const fsdEl = document.getElementById("ac_frequencyStartDate");
      if (fsdEl) fsdEl.value = firstCycleEnd;
    }

    // Invoice Generation Date
    const invGenDate =
      pendingCharge?.invoiceGenerationDate ||
      (charge.array_invoicegenerationdate
        ? charge.array_invoicegenerationdate.substring(0, 10)
        : "");
    const igEl = document.getElementById("ac_invoiceGenerationDate");
    if (igEl && invGenDate) igEl.value = invGenDate;

    // Due Date Rule
    const dueDateRule =
      pendingCharge?.dueDateRule != null
        ? String(pendingCharge.dueDateRule)
        : "";
    const ddrEl = document.getElementById("ac_dueDateRule");
    if (ddrEl && dueDateRule !== "") {
      ddrEl.value = dueDateRule;
      ac_handleDueDateRuleChange();
    }

    // Due In Days
    const dueInDays =
      pendingCharge?.dueInDays != null
        ? pendingCharge.dueInDays
        : charge.array_dueindays != null
          ? charge.array_dueindays
          : "";
    const didEl = document.getElementById("ac_dueInDays");
    if (didEl) didEl.value = dueInDays;

    // ── SECTION 4: Billing Information ─────────────────────

    // Currency
    const currencyId =
      pendingCharge?.currency || charge._transactioncurrencyid_value || "";
    const ccyEl = document.getElementById("ac_currency");
    if (ccyEl && currencyId) {
      ccyEl.value = currencyId;
      ac_handleCurrencyChange();
    }

    // Amount
    const amtEl = document.getElementById("ac_amount");
    if (amtEl)
      amtEl.value =
        pendingCharge?.amount != null
          ? pendingCharge.amount
          : charge.array_amount != null
            ? charge.array_amount
            : "";

    // Billable Area
    const baEl = document.getElementById("ac_billableArea");
    if (baEl)
      baEl.value =
        pendingCharge?.billableArea != null
          ? pendingCharge.billableArea
          : charge.array_billablearea != null
            ? charge.array_billablearea
            : "";

    // Invoice Separately
    const invSepEl = document.getElementById("ac_invoiceSeparately");
    if (invSepEl)
      invSepEl.value = pendingCharge?.invoiceSeparately ? "true" : "false";

    // Tax Included
    const taxEl = document.getElementById("ac_taxIncluded");
    if (taxEl) taxEl.value = pendingCharge?.taxIncluded ? "true" : "false";

    // VAT — must restore AFTER currency change re-renders billing section
    const vatId = pendingCharge?.vat || "";
    const vatEl = document.getElementById("ac_vat");
    if (vatEl && vatId) vatEl.value = vatId;

    // Invoice Type
    const invoiceTypeId = pendingCharge?.invoiceType || "";
    const invTypeEl = document.getElementById("ac_invoiceType");
    if (invTypeEl && invoiceTypeId) {
      invTypeEl.value = invoiceTypeId;
      invTypeEl.style.background = "";
      ac_handleInvoiceTypeChange();
    }

    // Invoice Prefix (restore if handleInvoiceTypeChange didn't set it)
    const invoicePrefixId = pendingCharge?.invoicePrefix || "";
    const invoicePrefixName = pendingCharge?.invoicePrefixName || "";
    if (invoicePrefixId) {
      const ipEl = document.getElementById("ac_invoicePrefix");
      const ipDEl = document.getElementById("ac_invoicePrefixDisplay");
      if (ipEl) ipEl.value = invoicePrefixId;
      if (ipDEl) ipDEl.value = invoicePrefixName;
    }

    // Use as Invoice Currency
    const invCurrGroup = document.getElementById(
      "ac_useAsInvoiceCurrencyGroup",
    );
    if (
      invCurrGroup &&
      invCurrGroup.style.display !== "none" &&
      pendingCharge?.useAsInvoiceCurrency != null
    ) {
      const uicEl = document.getElementById("ac_useAsInvoiceCurrency");
      if (uicEl)
        uicEl.value = pendingCharge.useAsInvoiceCurrency ? "true" : "false";
    }

    // Bank Account
    const bankAccount = pendingCharge?.bankAccount || "";
    const bankAccountName = pendingCharge?.bankAccountName || "";
    if (bankAccount) {
      const baAccEl = document.getElementById("ac_bankAccount");
      const baAccDEl = document.getElementById("ac_bankAccountDisplay");
      if (baAccEl) baAccEl.value = bankAccount;
      if (baAccDEl) baAccDEl.value = bankAccountName;
      const clearBankBtn = document.getElementById("ac_clearBankAccountBtn");
      if (clearBankBtn) clearBankBtn.style.display = "block";
    }

    // Exchange Rate Rule
    const rateRule = pendingCharge?.rateRule || "";
    const rateRuleName = pendingCharge?.rateRuleName || "";
    if (rateRule) {
      const rrEl = document.getElementById("ac_rateRule");
      const rrDEl = document.getElementById("ac_rateRuleDisplay");
      if (rrEl) rrEl.value = rateRule;
      if (rrDEl) rrDEl.value = rateRuleName;
      const clearRateBtn = document.getElementById("ac_clearRateRuleBtn");
      if (clearRateBtn) clearRateBtn.style.display = "block";
      ac_toggleExchangeRateDayField(rateRuleName);
    }

    // Exchange Rate Day
    const exchangeRateDay = pendingCharge?.exchangeRateDay;
    if (exchangeRateDay != null) {
      const erdEl = document.getElementById("ac_exchangeRateDay");
      if (erdEl) erdEl.value = exchangeRateDay;
    }
  }, 150); // ← 150ms delay ensures this runs after openAddChargeModal's
  //   own setTimeout(80ms) which sets the monthly default
}

// Supersede an EXISTING (saved) recurring charge. Opens the full Add Charge
// modal pre-filled from the existing record, Start Date defaulted to the
// amendment effective date (editable), every field editable. On save the old
// charge is deactivated (end = effective date) and a new charge created (see
// saveAddCharge). NOTE: only fields loaded for existing charges are pre-filled
// (name, type, unit, amount, currency, frequency, dates, due-in-days,
// invoice-gen, proration, billable area). VAT / bank account / rate rule /
// invoice prefix are not loaded for existing charges and start blank.
function openSupersedeChargeModal(chargeId) {
  const charge = amendExistingCharges.find(
    (c) => c.array_recurringchargeid === chargeId,
  );
  if (!charge) return;

  openAddChargeModal(); // resets the form + rebuilds dropdowns
  _editingChargeIdx = null;
  _supersedeChargeId = chargeId; // mark supersede mode (after openAddChargeModal reset)

  const titleEl = document.getElementById("addChargeModalTitle");
  if (titleEl) {
    titleEl.textContent = "Edit Recurring Charge";
    titleEl.style.color = "#0D4A9E";
  }
  const saveBtn = document.getElementById("addChargeSaveBtn");
  if (saveBtn)
    saveBtn.innerHTML = `<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M19 21H5a2 2 0 01-2-2V5a2 2 0 012-2h11l5 5v11a2 2 0 01-2 2z"/><polyline points="17 21 17 13 7 13 7 21"/></svg> Save Changes`;

  const eff = getAmendmentEffectiveDate();

  // Run AFTER openAddChargeModal's own setTimeout(80ms) which sets defaults.
  setTimeout(() => {
    const setVal = (id, v) => {
      const el = document.getElementById(id);
      if (el && v != null && v !== "") el.value = v;
    };

    setVal("ac_name", charge.array_chargename || "");
    const ctId = charge.array_ChargeType?.array_chargetypeid || "";
    if (ctId) setVal("ac_chargeType", ctId);
    const unitId = charge.array_Unit?.array_unitid || "";
    if (unitId) setVal("ac_unit", unitId);
    ac_autoPopulateInvoiceType();

    // Start Date defaults to the amendment effective date (editable).
    setVal(
      "ac_startDate",
      eff ||
        (charge.array_startdate ? charge.array_startdate.substring(0, 10) : ""),
    );
    setVal(
      "ac_endDate",
      charge.array_enddate ? charge.array_enddate.substring(0, 10) : "",
    );

    const freqEl = document.getElementById("ac_frequency");
    if (freqEl && charge.array_frequency != null) {
      freqEl.value = String(charge.array_frequency);
      ac_handleFrequencyVisibility();
      ac_updateInvoiceGenDateMax();
    }

    const pfEl = document.getElementById("ac_preFrequencyOffset");
    if (pfEl) pfEl.value = charge.array_prefrequencyoffset ? "true" : "false";

    const proEl = document.getElementById("ac_prorationEnabled");
    if (proEl) {
      proEl.value = charge.array_prorationenabled ? "true" : "false";
      ac_handleProrationChange();
    }

    // First Cycle Frequency End Date is auto-populated by ac_handleProrationChange()
    // from the NEW start date — don't overwrite it with the old charge's
    // frequency start date (that field is not a frequency start date).
    // Invoice Generation Date is intentionally NOT copied — it is
    // period-specific and must be re-entered/recomputed for the new charge.
    setVal(
      "ac_dueInDays",
      charge.array_dueindays != null ? charge.array_dueindays : "",
    );

    const ccyEl = document.getElementById("ac_currency");
    if (ccyEl && charge._transactioncurrencyid_value) {
      ccyEl.value = charge._transactioncurrencyid_value;
      ac_handleCurrencyChange();
    }
    setVal("ac_amount", charge.array_amount != null ? charge.array_amount : "");
    setVal(
      "ac_billableArea",
      charge.array_billablearea != null ? charge.array_billablearea : "",
    );

    // Due Date Rule: prefill directly from the in-memory value if present
    // (option-set options are already built by openAddChargeModal above).
    // Falls back to a Dataverse retrieve if the value wasn't in the initial
    // fetch, and retries once if the dropdown options aren't ready yet.
    const _applyDdr = (val) => {
      if (val == null || val === "") return false;
      const ddrEl = document.getElementById("ac_dueDateRule");
      if (!ddrEl) return false;
      ddrEl.value = String(val);
      if (ddrEl.value === String(val)) {
        if (typeof ac_handleDueDateRuleChange === "function")
          ac_handleDueDateRuleChange();
        return true;
      }
      return false;
    };
    if (charge.array_duedaterule != null) {
      if (!_applyDdr(charge.array_duedaterule)) {
        // Dropdown not populated yet — retry after a short tick.
        setTimeout(() => _applyDdr(charge.array_duedaterule), 200);
      }
    } else {
      ac_applyDueDateRuleFromCharge(chargeId);
    }
  }, 150);

  openModal("modalAddCharge");
}

// ── Add Charge Modal ──────────────────────────────────────────
function openAddChargeModal() {
  _editingChargeIdx = null;
  _supersedeChargeId = null;

  const titleEl = document.getElementById("addChargeModalTitle");
  if (titleEl) titleEl.textContent = "Add Recurring Charge";
  const saveBtn = document.getElementById("addChargeSaveBtn");
  if (saveBtn)
    saveBtn.innerHTML = `<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><line x1="12" y1="5" x2="12" y2="19"/><line x1="5" y1="12" x2="19" y2="12"/></svg> Add Charge`;

  document.getElementById("ac_editId").value = "";
  document.getElementById("ac_name").value = "";
  document.getElementById("ac_amount").value = "";
  document.getElementById("ac_startDate").value = "";
  document.getElementById("ac_endDate").value = "";
  document.getElementById("ac_invoiceGenerationDate").value = "";
  document.getElementById("ac_dueInDays").value = "";
  document.getElementById("ac_billableArea").value = "";
  document.getElementById("ac_frequencyStartDate").value = "";
  document.getElementById("ac_prorationEnabled").value = "false";
  document.getElementById("ac_preFrequencyOffset").value = "false";
  document.getElementById("ac_prorationEnabledFirstCycle").value = "";
  document.getElementById("ac_prorationEnabledLastCycle").value = "false";
  document.getElementById("ac_invoiceSeparately").value = "false";
  document.getElementById("ac_taxIncluded").value = "false";
  document.getElementById("ac_bankAccount").value = "";
  document.getElementById("ac_bankAccountDisplay").value = "";
  document.getElementById("ac_rateRule").value = "";
  document.getElementById("ac_rateRuleDisplay").value = "";
  document.getElementById("ac_invoicePrefix").value = "";
  document.getElementById("ac_invoicePrefixDisplay").value = "";

  document.getElementById("ac_prorationConditionalFields").style.display =
    "none";
  document.getElementById("ac_firstCycleFrequencyEndDateGroup").style.display =
    "none";
  document.getElementById("ac_exchangeRateDayGroup").style.display = "none";
  document.getElementById("ac_useAsInvoiceCurrencyGroup").style.display =
    "none";

  const clearBankBtn = document.getElementById("ac_clearBankAccountBtn");
  if (clearBankBtn) clearBankBtn.style.display = "none";
  const clearRateBtn = document.getElementById("ac_clearRateRuleBtn");
  if (clearRateBtn) clearRateBtn.style.display = "none";

  const modalBody = document.querySelector("#modalAddCharge .amend-modal-body");
  if (modalBody) {
    modalBody.style.padding = "0";
    modalBody.style.overflowY = "auto";
    const existingWrapper = modalBody.querySelector(".ac-modal-inner-wrapper");
    if (!existingWrapper) {
      const children = Array.from(modalBody.children);
      const wrapper = document.createElement("div");
      wrapper.className = "ac-modal-inner-wrapper";
      wrapper.style.cssText =
        "padding:24px 28px;display:flex;flex-direction:column;gap:0;";
      children.forEach((child) => wrapper.appendChild(child));
      modalBody.appendChild(wrapper);
    } else {
      existingWrapper.style.cssText =
        "padding:24px 28px;display:flex;flex-direction:column;gap:0;";
    }
  }

  const sectionTitles = document.querySelectorAll(
    "#modalAddCharge .amend-modal-body h4",
  );
  sectionTitles.forEach((h4, idx) => {
    h4.style.cssText = `font-size:11px;font-weight:700;color:#1C6BD4;text-transform:uppercase;
      letter-spacing:0.6px;margin:${idx === 0 ? "0" : "8px"} 0 14px;padding-bottom:10px;
      border-bottom:1.5px solid #EBF3FF;display:flex;align-items:center;gap:8px;`;
  });

  document
    .querySelectorAll("#modalAddCharge .amend-form-group label")
    .forEach((lbl) => {
      if (!lbl.style.fontSize) lbl.style.fontSize = "12px";
      lbl.style.fontWeight = "600";
      lbl.style.color = "#374151";
      lbl.style.marginBottom = "5px";
    });

  document
    .querySelectorAll(
      "#modalAddCharge .amend-form-group input, #modalAddCharge .amend-form-group select, #modalAddCharge .amend-form-group textarea",
    )
    .forEach((el) => {
      el.style.borderRadius = "8px";
      el.style.border = "1.5px solid #CBD5E1";
      el.style.padding = "9px 12px";
      el.style.fontSize = "13px";
      el.style.width = "100%";
      el.style.boxSizing = "border-box";
      el.style.transition = "border-color 0.15s";
    });

  const chargeTypeSelect = document.getElementById("ac_chargeType");
  chargeTypeSelect.innerHTML = '<option value="">Select charge type</option>';
  amendChargeTypes.forEach((ct) => {
    const o = document.createElement("option");
    o.value = ct.array_chargetypeid;
    o.textContent = ct.array_name;
    chargeTypeSelect.appendChild(o);
  });
  chargeTypeSelect.removeEventListener("change", ac_autoPopulateInvoiceType);
  chargeTypeSelect.addEventListener("change", ac_autoPopulateInvoiceType);

  const unitSelect = document.getElementById("ac_unit");
  unitSelect.innerHTML = '<option value="">Select Unit</option>';
  amendExistingUnits.forEach((a) => {
    if (a.array_Unit) {
      const o = document.createElement("option");
      o.value = a.array_Unit.array_unitid;
      o.textContent = a.array_Unit.array_unitname;
      unitSelect.appendChild(o);
    }
  });
  amendNewUnits.forEach((a) => {
    if (a.array_Unit) {
      const o = document.createElement("option");
      o.value = a.array_Unit.array_unitid;
      o.textContent = `${a.array_Unit.array_unitname} (New)`;
      unitSelect.appendChild(o);
    }
  });
  unitSelect.removeEventListener("change", ac_autoPopulateInvoiceType);
  unitSelect.addEventListener("change", ac_autoPopulateInvoiceType);

  const currencySelect = document.getElementById("ac_currency");
  currencySelect.innerHTML = '<option value="">Select currency</option>';
  amendCurrencies.forEach((c) => {
    const o = document.createElement("option");
    o.value = c.transactioncurrencyid;
    o.textContent = `${c.currencyname} (${c.isocurrencycode})`;
    currencySelect.appendChild(o);
  });
  const defaultCurrencyId = getDefaultCurrencyId();

  const frequencySelect = document.getElementById("ac_frequency");
  frequencySelect.innerHTML = '<option value="">Select frequency</option>';
  let monthlyValue = null;
  const sortedFreqs = [...amendFrequencies].sort((a, b) => a.Value - b.Value);
  sortedFreqs.forEach((f) => {
    const o = document.createElement("option");
    o.value = f.Value;
    const label = f.Label?.UserLocalizedLabel?.Label || String(f.Value);
    o.textContent = label;
    frequencySelect.appendChild(o);
    if (label.toLowerCase() === "monthly") monthlyValue = f.Value;
  });

  const vatSelect = document.getElementById("ac_vat");
  vatSelect.innerHTML = '<option value="">Select VAT</option>';
  amendVATs.forEach((v) => {
    const o = document.createElement("option");
    o.value = v.array_vatid;
    o.textContent = v.array_name + (v.array_vat ? ` (${v.array_vat}%)` : "");
    vatSelect.appendChild(o);
  });
  if (amendVATs.length >= 1) {
    vatSelect.value = amendVATs[0].array_vatid;
  }
  const vatGroup = vatSelect.closest(".amend-form-group");
  if (vatGroup) {
    const vatLabel = vatGroup.querySelector("label");
    if (vatLabel && !vatLabel.classList.contains("required")) {
      vatLabel.classList.add("required");
    }
  }

  const invTypeSelect = document.getElementById("ac_invoiceType");
  invTypeSelect.innerHTML = '<option value="">Select invoice type</option>';
  amendInvoiceTypes.forEach((t) => {
    const o = document.createElement("option");
    o.value = t.array_invoicetypeid;
    o.textContent = t.array_name;
    invTypeSelect.appendChild(o);
  });
  invTypeSelect.removeEventListener("change", ac_handleInvoiceTypeChange);
  invTypeSelect.addEventListener("change", ac_handleInvoiceTypeChange);

  const dueDateSelect = document.getElementById("ac_dueDateRule");
  dueDateSelect.innerHTML = '<option value="">Select due date rule</option>';
  const sortedDDR = [...amendDueDateRules].sort((a, b) => a.Value - b.Value);
  sortedDDR.forEach((r) => {
    const o = document.createElement("option");
    o.value = r.Value;
    o.textContent = r.Label?.UserLocalizedLabel?.Label || String(r.Value);
    dueDateSelect.appendChild(o);
  });
  dueDateSelect.removeEventListener("change", ac_handleDueDateRuleChange);
  dueDateSelect.addEventListener("change", ac_handleDueDateRuleChange);

  const amendmentStart =
    document.getElementById("amend_startDate")?.value || "";

  // Start date defaults to the amendment effective date only (do NOT fall back
  // to the lease start date).
  const resolvedStart = amendmentStart;
  const resolvedEnd = getEffectiveLeaseEnd();

  const maxDate = getMaxAllowedDate();

  const startInput = document.getElementById("ac_startDate");
  if (resolvedStart) {
    startInput.value = resolvedStart;
  }
  startInput.removeAttribute("min");
  if (maxDate) startInput.max = maxDate;

  const endInput = document.getElementById("ac_endDate");
  if (resolvedEnd) {
    endInput.value = resolvedEnd;
  }
  if (maxDate) endInput.max = maxDate;
  endInput.style.display = "";
  const endGroup = endInput.closest(".amend-form-group");
  if (endGroup) endGroup.style.display = "";

  const invGenInput = document.getElementById("ac_invoiceGenerationDate");
  invGenInput.removeAttribute("min");
  invGenInput.removeAttribute("max");
  ac_updateInvoiceGenDateMax();

  if (defaultCurrencyId) {
    currencySelect.value = defaultCurrencyId;
    ac_autoPopulateBankAccountByCurrency(defaultCurrencyId);
  } else {
    ac_lockBankAccountField();
  }

  if (monthlyValue) frequencySelect.value = monthlyValue;

  ac_autoPopulateRateRule();
  // Only pre-populate Due Date Rule when editing an existing charge, not on new
  if (_editingChargeIdx !== null && _editingChargeIdx !== undefined) {
    ac_autoPopulateDueDateRule();
  }

  openModal("modalAddCharge");

  setTimeout(() => {
    ac_setupInvoiceGenAutoCalculation();
    ac_clearDateValidations();
  }, 80);

  // Brand-new Add: copy the lease-wide common billing fields from an existing
  // charge on this lease (Frequency, Pre-Freq Offset, Proration, Due In Days,
  // Due Date Rule). Skipped when superseding or editing a staged charge, which
  // set their own values afterward. Invoice Generation Date is never copied.
  setTimeout(() => {
    if (_supersedeChargeId) return;
    if (_editingChargeIdx !== null && _editingChargeIdx !== undefined) return;
    const ref = amendExistingCharges[amendExistingCharges.length - 1];
    if (ref) ac_copyCommonFieldsFromCharge(ref);
  }, 200);

  openModal("modalAddCharge");
}

// ══════════════════════════════════════════════════════════════════════
// saveAddCharge()

//  Rule 1 — "All Units" scope:
//    A charge with no unit selected means it applies to ALL units on
//    the lease. If there is already an active charge (existing or newly
//    staged) of the same charge type with no unit selected, block it.
//    Additionally, warn (but still block) if there is already a charge
//    of the same type assigned to ANY specific unit, because the new
//    "all units" charge would create an implicit duplicate for that unit.
//
//  Rule 2 — Specific unit scope:
//    If a specific unit is selected, block if there is already an active
//    charge of the same charge type for that exact unit.
//    Also block if there is already an "all units" charge of the same
//    type (because that already covers this unit).
//
//  In EDIT mode the current row is excluded from the duplicate check
//  so that saving without changing charge type / unit does not self-block.
// ══════════════════════════════════════════════════════════════════════

async function saveAddCharge() {
  const name = document.getElementById("ac_name").value.trim();
  const chargeTypeId = document.getElementById("ac_chargeType").value;
  const amount = parseFloat(document.getElementById("ac_amount").value);
  const currencyId = document.getElementById("ac_currency").value;
  const freq = document.getElementById("ac_frequency").value;
  const startDate = document.getElementById("ac_startDate").value;
  const endDate = document.getElementById("ac_endDate").value;
  const invoiceGenDate = document.getElementById(
    "ac_invoiceGenerationDate",
  ).value;
  const dueInDaysRaw = document.getElementById("ac_dueInDays").value;
  const dueInDays = dueInDaysRaw !== "" ? parseInt(dueInDaysRaw) : null;
  const dueDateRule = document.getElementById("ac_dueDateRule").value;
  const prorationEnabled =
    document.getElementById("ac_prorationEnabled").value === "true";
  const preFrequencyOffset =
    document.getElementById("ac_preFrequencyOffset").value === "true";
  const billableArea =
    parseFloat(document.getElementById("ac_billableArea").value) || null;
  const frequencyStartDate =
    document.getElementById("ac_frequencyStartDate").value || "";
  const prorationEnabledLastCycle =
    document.getElementById("ac_prorationEnabledLastCycle").value === "true";
  const prorationEnabledFirstCycleRaw = document.getElementById(
    "ac_prorationEnabledFirstCycle",
  ).value;
  const prorationEnabledFirstCycle =
    prorationEnabledFirstCycleRaw === "true"
      ? true
      : prorationEnabledFirstCycleRaw === "false"
        ? false
        : null;
  const invoiceSeparately =
    document.getElementById("ac_invoiceSeparately").value === "true";
  const taxIncluded =
    document.getElementById("ac_taxIncluded").value === "true";
  const bankAccount = document.getElementById("ac_bankAccount").value || "";
  const bankAccountName =
    document.getElementById("ac_bankAccountDisplay").value || "";
  const rateRule = document.getElementById("ac_rateRule").value || "";
  const rateRuleName =
    document.getElementById("ac_rateRuleDisplay").value || "";
  const vatValue = document.getElementById("ac_vat").value || "";
  const invoiceType = document.getElementById("ac_invoiceType").value || "";
  const invoicePrefix = document.getElementById("ac_invoicePrefix").value || "";
  const invoicePrefixName =
    document.getElementById("ac_invoicePrefixDisplay").value || "";
  const exchangeRateDayRaw =
    document.getElementById("ac_exchangeRateDay")?.value;
  const exchangeRateDay =
    exchangeRateDayRaw && exchangeRateDayRaw !== ""
      ? parseInt(exchangeRateDayRaw)
      : null;
  const invCurrencyGroup = document.getElementById(
    "ac_useAsInvoiceCurrencyGroup",
  );
  const useAsInvoiceCurrency =
    invCurrencyGroup && invCurrencyGroup.style.display !== "none"
      ? document.getElementById("ac_useAsInvoiceCurrency").value === "true"
      : false;

  // ── Required-field validations ─────────────────────────────
  clearFieldErrors(document.getElementById("modalAddCharge"));
  if (!name) {
    showFieldError("ac_name", "Please enter a charge name.");
    return;
  }
  if (!chargeTypeId) {
    showFieldError("ac_chargeType", "Please select a charge type.");
    return;
  }
  if (isNaN(amount) || amount <= 0) {
    showFieldError("ac_amount", "Please enter a valid amount.");
    return;
  }
  if (!currencyId) {
    showFieldError("ac_currency", "Please select a currency.");
    return;
  }
  if (!startDate) {
    showFieldError("ac_startDate", "Please select a start date.");
    return;
  }
  if (!endDate) {
    showFieldError("ac_endDate", "Please select an end date.");
    return;
  }
  if (!freq) {
    showFieldError("ac_frequency", "Please select a frequency.");
    return;
  }
  if (!invoiceGenDate) {
    showFieldError(
      "ac_invoiceGenerationDate",
      "Please select an invoice generation date.",
    );
    return;
  }

  if (invoiceGenDate && startDate && freq) {
    const maxInvDate = ac_computeInvoiceGenMaxDate(startDate, freq);
    if (maxInvDate && invoiceGenDate > maxInvDate) {
      const freqObjV = amendFrequencies.find(
        (f) => String(f.Value) === String(freq),
      );
      const freqLabelV =
        freqObjV?.Label?.UserLocalizedLabel?.Label || "frequency";
      showFieldError(
        "ac_invoiceGenerationDate",
        `Must be within 2 ${freqLabelV} periods of the start date (max: ${maxInvDate}).`,
      );
      return;
    }
  }
  if (dueInDays === null || dueInDays === undefined) {
    showFieldError("ac_dueInDays", "Please enter due in days.");
    return;
  }
  if (!dueDateRule) {
    showFieldError("ac_dueDateRule", "Please select a due date rule.");
    return;
  }

  const erDayGroup = document.getElementById("ac_exchangeRateDayGroup");
  if (erDayGroup && erDayGroup.style.display !== "none") {
    if (
      exchangeRateDay === null ||
      isNaN(exchangeRateDay) ||
      !Number.isInteger(exchangeRateDay) ||
      exchangeRateDay < 1
    ) {
      showFieldError(
        "ac_exchangeRateDay",
        "Please enter a valid whole number.",
      );
      return;
    }
  }

  // ── FIX: VAT is now required ───────────────────────────────
  if (!vatValue) {
    showFieldError("ac_vat", "Please select a VAT rate.");
    return;
  }
  clearFieldError("ac_vat");

  // ── Duplicate charge-type validation ──────────────────────
  const normId = (v) =>
    (v || "").toString().toLowerCase().replace(/[{}]/g, "").trim();

  const unitIdOf = (charge) => {
    if (charge.array_Unit && charge.array_Unit.array_unitid)
      return normId(charge.array_Unit.array_unitid);
    return "";
  };

  const ctIdOf = (charge) =>
    normId(
      charge.array_ChargeType?.array_chargetypeid ||
        charge._array_chargetype_value ||
        "",
    );

  const FAR_FUTURE = "9999-12-31";

  const datesOverlap = (s1, e1, s2, e2) => {
    const start1 = s1 || "";
    const end1 = e1 && e1 !== "" ? e1 : FAR_FUTURE;
    const start2 = s2 || "";
    const end2 = e2 && e2 !== "" ? e2 : FAR_FUTURE;
    return !(end1 < start2 || end2 < start1);
  };

  const newCtId = normId(chargeTypeId);
  const unitId = document.getElementById("ac_unit").value || "";
  const newUnitId = normId(unitId);
  const newStart = startDate;
  const newEnd = endDate;

  const editingStableId =
    _editingChargeIdx !== null && _editingChargeIdx !== undefined
      ? normId(
          amendNewCharges[_editingChargeIdx]?.array_recurringchargeid || "",
        )
      : null;

  const supersedeStableId = _supersedeChargeId
    ? normId(_supersedeChargeId)
    : null;
  const allActiveCharges = [...amendExistingCharges, ...amendNewCharges].filter(
    (c) => {
      const id = normId(c.array_recurringchargeid);
      // Exclude the row being edited / the existing charge being superseded
      // so it does not conflict with its own replacement.
      return id !== editingStableId && id !== supersedeStableId;
    },
  );

  if (newUnitId === "") {
    const conflict = allActiveCharges.find((c) => {
      if (ctIdOf(c) !== newCtId) return false;
      const cStart = c.array_startdate
        ? c.array_startdate.substring(0, 10)
        : "";
      const cEnd = c.array_enddate ? c.array_enddate.substring(0, 10) : "";
      if (!datesOverlap(newStart, newEnd, cStart, cEnd)) return false;
      return true;
    });

    if (conflict) {
      const conflictUnit = unitIdOf(conflict);
      const conflictChargeTypeName =
        conflict.array_ChargeType?.array_name || chargeTypeId;
      const conflictName = conflict.array_chargename || "";
      const conflictStart = conflict.array_startdate
        ? conflict.array_startdate.substring(0, 10)
        : "";
      const conflictEnd = conflict.array_enddate
        ? conflict.array_enddate.substring(0, 10)
        : "";
      const dateRange =
        conflictStart || conflictEnd
          ? ` [${formatDateAmend(conflictStart) || "—"} → ${formatDateAmend(conflictEnd) || "open"}]`
          : "";

      if (conflictUnit === "") {
        showAmendNotification(
          `⚠️ A recurring charge with the same charge type already exists for the selected date range. ` +
            `Charge: "${conflictChargeTypeName}"${conflictName ? ` ("${conflictName}")` : ""} (All Units)${dateRange}. ` +
            `Please use non-overlapping dates or a different charge type.`,
          "warning",
        );
      } else {
        const conflictUnitName =
          conflict.array_Unit?.array_unitname || conflictUnit;
        showAmendNotification(
          `⚠️ A recurring charge with the same charge type already exists for the selected date range. ` +
            `Charge: "${conflictChargeTypeName}"${conflictName ? ` ("${conflictName}")` : ""} for unit "${conflictUnitName}"${dateRange}. ` +
            `An "All Units" charge of the same type would cover that unit. Please use non-overlapping dates or a different charge type.`,
          "warning",
        );
      }
      return;
    }
  } else {
    const conflict = allActiveCharges.find((c) => {
      if (ctIdOf(c) !== newCtId) return false;
      const existingUnit = unitIdOf(c);
      if (existingUnit !== "" && existingUnit !== newUnitId) return false;
      const cStart = c.array_startdate
        ? c.array_startdate.substring(0, 10)
        : "";
      const cEnd = c.array_enddate ? c.array_enddate.substring(0, 10) : "";
      if (!datesOverlap(newStart, newEnd, cStart, cEnd)) return false;
      return true;
    });

    if (conflict) {
      const conflictChargeTypeName =
        conflict.array_ChargeType?.array_name || chargeTypeId;
      const conflictName = conflict.array_chargename || "";
      const conflictStart = conflict.array_startdate
        ? conflict.array_startdate.substring(0, 10)
        : "";
      const conflictEnd = conflict.array_enddate
        ? conflict.array_enddate.substring(0, 10)
        : "";
      const dateRange =
        conflictStart || conflictEnd
          ? ` [${formatDateAmend(conflictStart) || "—"} → ${formatDateAmend(conflictEnd) || "open"}]`
          : "";

      if (unitIdOf(conflict) === "") {
        showAmendNotification(
          `⚠️ A recurring charge with the same charge type already exists for the selected date range. ` +
            `Charge: "${conflictChargeTypeName}"${conflictName ? ` ("${conflictName}")` : ""} (All Units)${dateRange}. ` +
            `This already covers the selected unit. Please use non-overlapping dates or a different charge type.`,
          "warning",
        );
      } else {
        const allAvailableUnits = [
          ...amendExistingUnits.map((a) => a.array_Unit).filter(Boolean),
          ...amendNewUnits.map((a) => a.array_Unit).filter(Boolean),
        ];
        const selectedUnitName =
          allAvailableUnits.find((u) => normId(u.array_unitid) === newUnitId)
            ?.array_unitname || unitId;
        showAmendNotification(
          `⚠️ A recurring charge with the same charge type already exists for the selected date range. ` +
            `Charge: "${conflictChargeTypeName}"${conflictName ? ` ("${conflictName}")` : ""} for unit "${selectedUnitName}"${dateRange}. ` +
            `Only one recurring charge of the same type is allowed per unit per period. Use non-overlapping dates or a different charge type.`,
          "warning",
        );
      }
      return;
    }
  }

  // ── Build payload ─────────────────────────────────────────
  const chargeTypeObj = amendChargeTypes.find(
    (ct) => ct.array_chargetypeid === chargeTypeId,
  );
  const currencyObj = amendCurrencies.find(
    (c) => c.transactioncurrencyid === currencyId,
  );
  const currencyName = currencyObj
    ? `${currencyObj.currencyname} (${currencyObj.isocurrencycode})`
    : "";
  const currencySymbol = currencyObj ? currencyObj.currencysymbol : "";
  const currencyCode = currencyObj ? currencyObj.isocurrencycode : "";

  const allAvailableUnits = [
    ...amendExistingUnits.map((a) => a.array_Unit).filter(Boolean),
    ...amendNewUnits.map((a) => a.array_Unit).filter(Boolean),
  ];
  const unitName = unitId
    ? allAvailableUnits.find((u) => u.array_unitid === unitId)
        ?.array_unitname || "Unknown"
    : "All Units";
  const freqObj = amendFrequencies.find(
    (f) => String(f.Value) === String(freq),
  );
  const frequencyLabel = freqObj?.Label?.UserLocalizedLabel?.Label || "";
  const vatObj = vatValue
    ? amendVATs.find((v) => v.array_vatid === vatValue)
    : null;
  const vatName = vatObj
    ? vatObj.array_name + (vatObj.array_vat ? ` (${vatObj.array_vat}%)` : "")
    : "";

  // Mirrors leasecreation.js:
  //   Frequency Start Date = charge Start Date (always)
  //   Frequency End Date   = First Cycle Frequency End Date when proration +
  //                          first-cycle proration are on, otherwise end of the
  //                          first full cycle counted from the Start Date.
  // NOTE: the "ac_frequencyStartDate" input is labelled "First Cycle Frequency
  // End Date" in the HTML — it is NOT the frequency start date.
  const _firstCycleEndDate = frequencyStartDate;
  const _freqStartDate = startDate || "";
  const _freqEndDate = ac_computeFrequencyEndDate(
    _freqStartDate,
    freq,
    prorationEnabled,
    prorationEnabledFirstCycle,
    _firstCycleEndDate,
  );
  const _freqStartDay = ac_extractDayFromDate(_freqStartDate);
  const _invGenDay = ac_extractDayFromDate(invoiceGenDate);
  const _propertyId =
    amendLeaseData?._array_property_value ||
    document.getElementById("propertyId")?.value ||
    "";
  const tenantId = getTenantId();

  const chargePayload = {
    name,
    chargeType: chargeTypeId,
    chargeTypeName: chargeTypeObj ? chargeTypeObj.array_name : "",
    amount,
    currency: currencyId,
    currencyName,
    currencySymbol,
    currencyCode,
    startDate,
    endDate,
    vat: vatValue,
    vatName,
    frequency: parseInt(freq),
    frequencyName: frequencyLabel,
    invoiceGenerationDate: invoiceGenDate,
    dueInDays,
    dueDateRule,
    prorationEnabled,
    preFrequencyOffset,
    billableArea: billableArea !== null ? billableArea : 0,
    frequencyStartDate: _freqStartDate,
    frequencyEndDate: _freqEndDate,
    firstCycleEndDate: _firstCycleEndDate,
    frequencyStartDay: _freqStartDay,
    invoiceGenerationDay: _invGenDay,
    propertyId: _propertyId,
    prorationEnabledLastCycle,
    prorationEnabledFirstCycle,
    invoiceSeparately,
    taxIncluded,
    bankAccount,
    bankAccountName,
    rateRule,
    rateRuleName,
    exchangeRateDay,
    invoiceType,
    invoicePrefix,
    invoicePrefixName,
    useAsInvoiceCurrency,
    unitId,
    unitName,
    tenantId: tenantId.id || "",
    tenantType: tenantId.type || "",
  };

  // ── EDIT MODE ─────────────────────────────────────────────
  if (_editingChargeIdx !== null && _editingChargeIdx !== undefined) {
    const existingRow = amendNewCharges[_editingChargeIdx];

    if (existingRow) {
      const stableId = existingRow.array_recurringchargeid;

      amendNewCharges[_editingChargeIdx] = {
        ...existingRow,
        array_chargename: name,
        array_amount: amount,
        array_startdate: startDate,
        array_enddate: endDate,
        array_frequency: parseInt(freq),
        array_dueindays: dueInDays,
        array_invoicegenerationdate: invoiceGenDate,
        array_prorationenabled: prorationEnabled,
        array_billablearea: billableArea !== null ? billableArea : 0,
        _transactioncurrencyid_value: currencyId,
        array_Unit: unitId
          ? { array_unitid: unitId, array_unitname: unitName }
          : null,
        array_ChargeType: chargeTypeId
          ? {
              array_chargetypeid: chargeTypeId,
              array_name: chargeTypeObj?.array_name || "—",
            }
          : null,
      };

      const pendingIdx = pendingNewCharges.findIndex((p) => p.id === stableId);
      if (pendingIdx !== -1) {
        pendingNewCharges[pendingIdx] = { ...chargePayload, id: stableId };
      } else {
        pendingNewCharges.push({ ...chargePayload, id: stableId });
      }

      amendCharges = [...amendExistingCharges, ...amendNewCharges];
      renderNewChargesTable();
      renderExistingChargesTable();
      updateBadge("charges", amendCharges.length);
      renderChargesTotals();

      _editingChargeIdx = null;
      showAmendNotification(`✅ Charge "${name}" updated.`, "success");
      closeModal("modalAddCharge");
      return;
    }

    _editingChargeIdx = null;
  }

  // ── ADD MODE (also handles SUPERSEDE create) ──────────────
  // If superseding an existing charge, deactivate the old record first (its
  // end date = the amendment effective date). The replacement charge is
  // created below from the edited form values; its start date is forced to
  // the amendment effective date at save time so it cannot drift regardless
  // of what the user typed in the modal.
  let effectiveStartDate = startDate;
  if (_supersedeChargeId) {
    const exIdx = amendExistingCharges.findIndex(
      (c) => c.array_recurringchargeid === _supersedeChargeId,
    );
    const effC = getAmendmentEffectiveDate();
    if (exIdx !== -1) {
      const oldCharge = amendExistingCharges[exIdx];
      amendDeactivatedCharges.push({
        ...oldCharge,
        _pendingDeactivate: true,
        _deactivateProration: false,
        _deactivateEndDate: effC || oldCharge.array_enddate,
        array_enddate: effC || oldCharge.array_enddate,
        _supersededBySave: true,
      });
      amendExistingCharges.splice(exIdx, 1);
    }
    // Carry the original charge id onto the new charge so saveAmendments can
    // set the array_AmendedFromCharge lookup back to the superseded record.
    chargePayload._amendedFromChargeId = _supersedeChargeId;
    // Force start date = amendment effective date on the superseding charge
    if (effC) {
      chargePayload.startDate = effC;
      effectiveStartDate = effC;
    }
    _supersedeChargeId = null;
  }

  const newId = "pending_" + Date.now();

  pendingNewCharges.push({ ...chargePayload, id: newId });

  const newChargeRow = {
    array_recurringchargeid: newId,
    array_chargename: name,
    array_amount: amount,
    array_startdate: effectiveStartDate,
    array_enddate: endDate,
    array_frequency: parseInt(freq),
    array_dueindays: dueInDays,
    array_invoicegenerationdate: invoiceGenDate,
    array_prorationenabled: prorationEnabled,
    array_billablearea: billableArea !== null ? billableArea : 0,
    _transactioncurrencyid_value: currencyId,
    array_Unit: unitId
      ? { array_unitid: unitId, array_unitname: unitName }
      : null,
    array_ChargeType: chargeTypeId
      ? {
          array_chargetypeid: chargeTypeId,
          array_name: chargeTypeObj?.array_name || "—",
        }
      : null,
    _isPending: true,
  };

  amendNewCharges.push(newChargeRow);
  amendCharges = [...amendExistingCharges, ...amendNewCharges];

  renderNewChargesTable();
  renderExistingChargesTable();
  updateBadge("charges", amendCharges.length);
  renderChargesTotals();

  showAmendNotification(
    `✅ Charge "${name}" staged. It will be saved when you click Save Amendments.`,
    "success",
  );
  closeModal("modalAddCharge");
}

// ══════════════════════════════════════════════════════════════
//  UNIFIED DEPOSIT MODAL — Add & Edit (ed_ prefix)
//  Add mode  : all fields editable
//  Edit mode (existing) : all fields locked except Due Date
//  Edit mode (new)      : all fields editable
// ══════════════════════════════════════════════════════════════

// Resolve "Deposit" option value dynamically from loaded collateral types
function getDepositTypeValue() {
  if (!amendCollateralTypes || !amendCollateralTypes.length) return 126330007;
  const match = amendCollateralTypes.find((o) => {
    const label = (
      o.Label?.UserLocalizedLabel?.Label ||
      o.Label?.LocalizedLabels?.[0]?.Label ||
      ""
    )
      .toLowerCase()
      .trim();
    return label === "deposit";
  });
  return match ? match.Value : 126330007;
}
const ED_DEPOSIT_TYPE_VALUE = 126330007; // kept for backward compat

// ── Show / hide deposit-only vs non-deposit fields ────────────
// ── Show/hide "approved-only" fields based on Collateral Approved ──
function ed_onCollateralApprovedChange(val) {
  const box = document.getElementById("ed_approvedFields");
  if (!box) return;
  box.style.display = String(val) === "true" ? "" : "none";
}

// ── Collateral types that do NOT require an amount ───────────
// Notary 777 p.4 KPC (return of premises) + p.5 KPC — no monetary value.
const COLLATERAL_TYPES_NO_AMOUNT = [126330002, 126330006];

// ── Bank Guarantee collateral type value ─────────────────────
const COLLATERAL_TYPE_BANK_GUARANTEE = 126330000;

function ed_typeRequiresAmount(typeVal) {
  if (typeVal === "" || typeVal == null) return true;
  return !COLLATERAL_TYPES_NO_AMOUNT.includes(parseInt(typeVal));
}

function ed_onDepositTypeChange(selectedValue) {
  const isDeposit = String(selectedValue) === String(getDepositTypeValue());
  const isBankGuarantee =
    String(selectedValue) === String(COLLATERAL_TYPE_BANK_GUARANTEE);
  const depositOnly = document.getElementById("ed_depositOnlyFields");
  const nonDeposit = document.getElementById("ed_nonDepositFields");
  if (depositOnly) depositOnly.style.display = isDeposit ? "" : "none";
  cl_updateDepositCollateralBanner();
  if (nonDeposit) nonDeposit.style.display = isDeposit ? "none" : "";

  // Bank Name visibility — Deposit OR Bank Guarantee only
  const bankGrp = document.getElementById("ed_bankNameGroup");
  if (bankGrp) {
    bankGrp.style.display = isDeposit || isBankGuarantee ? "" : "none";
  }

  // Toggle Required Amount / Currency asterisk based on type
  const amountRequired = ed_typeRequiresAmount(selectedValue);
  [
    "ed_amount",
    "ed_amountNonDeposit",
    "ed_currency",
    "ed_currencyNonDeposit",
  ].forEach((inputId) => {
    const input = document.getElementById(inputId);
    if (!input) return;
    const group = input.closest(".amend-form-group");
    if (!group) return;
    const lbl = group.querySelector("label");
    if (!lbl) return;
    lbl.classList.toggle("required", amountRequired);
  });
}

// ── Lock / unlock a single form element ──────────────────────
function ed_lockField(id) {
  const el = document.getElementById(id);
  if (!el) return;
  el.disabled = true;
  el.style.background = "#F1F2F4";
  el.style.color = "#5A6070";
  el.style.cursor = "not-allowed";
  el.style.pointerEvents = "none";
}

function ed_unlockField(id) {
  const el = document.getElementById(id);
  if (!el) return;
  el.disabled = false;
  el.style.background = "";
  el.style.color = "";
  el.style.cursor = "";
  el.style.pointerEvents = "";
}

// ── Populate both currency dropdowns ─────────────────────────
function ed_populateCurrencies(selectedId) {
  const effectiveId = selectedId || getDefaultCurrencyId();

  [
    "ed_currency",
    "ed_currencyNonDeposit",
    "ed_amountDeliveredCurrency",
  ].forEach((selId) => {
    const sel = document.getElementById(selId);
    if (!sel) return;
    sel.innerHTML = '<option value="">Select currency</option>';
    amendCurrencies.forEach((c) => {
      const opt = document.createElement("option");
      opt.value = c.transactioncurrencyid;
      opt.textContent = `${c.currencyname} (${c.isocurrencycode})`;
      sel.appendChild(opt);
    });
  });

  // Set values AFTER all options are in the DOM for all selects
  if (effectiveId) {
    [
      "ed_currency",
      "ed_currencyNonDeposit",
      "ed_amountDeliveredCurrency",
    ].forEach((selId) => {
      const sel = document.getElementById(selId);
      if (!sel) return;
      sel.value = effectiveId;
    });
  }
}

// ── Re-date active unit associations to a new lease expiry ────
// Updates each active array_leaseunitassociation on the lease whose end
// date is empty or equals the previous lease end date. Used by the
// same-day expiry-extension path so the Lease Terms UI promise is honored.
async function propagateExpiryToUnitAssociations(
  leaseId,
  newExpiry,
  oldLeaseEnd,
  statusFn,
) {
  if (!leaseId || !newExpiry) return;
  const clientUrl = XrmCtx.Utility.getGlobalContext().getClientUrl();
  const normLease = leaseId.replace(/[{}]/g, "").toLowerCase();
  const reqOpts = {
    headers: {
      "OData-MaxVersion": "4.0",
      "OData-Version": "4.0",
      Accept: "application/json",
      Prefer: 'odata.include-annotations="*"',
    },
    credentials: "same-origin",
  };

  const resp = await fetch(
    `${clientUrl}/api/data/v9.2/array_leaseunitassociations` +
      `?$select=array_leaseunitassociationid,array_enddate` +
      `&$filter=_array_leaseagreement_value eq ${normLease} and statecode eq 0`,
    reqOpts,
  );
  if (!resp.ok)
    throw new Error(`Unit association query failed: ${resp.status}`);
  const assocs = (await resp.json()).value || [];
  if (!assocs.length) return;

  const old10 = (oldLeaseEnd || "").substring(0, 10);
  const targets = assocs.filter((a) => {
    const end10 = a.array_enddate ? a.array_enddate.substring(0, 10) : "";
    return end10 === "" || (old10 && end10 === old10);
  });
  if (!targets.length) {
    console.log(
      "ℹ️ No unit associations needed re-dating (all have custom end dates).",
    );
    return;
  }

  let done = 0;
  for (const a of targets) {
    if (statusFn)
      statusFn(`Updating unit end dates… (${done + 1}/${targets.length})`);
    await XrmCtx.WebApi.updateRecord(
      "array_leaseunitassociation",
      a.array_leaseunitassociationid,
      { array_enddate: newExpiry },
    );
    done++;
  }
  console.log(`✅ Re-dated ${done} unit association(s) to ${newExpiry}`);
}

// ── Helper: get all active units across existing + new ────────
// Used by Stage 6 (deposits) and Stage 7 (clauses) unit dropdowns
function getAllLeaseUnits() {
  const units = [];

  // From existing DB units
  amendExistingUnits.forEach((assoc) => {
    if (assoc.array_Unit) {
      units.push({
        unitId: assoc.array_Unit.array_unitid,
        unitName: assoc.array_Unit.array_unitname || "—",
      });
    }
  });

  // From newly added units this session
  amendNewUnits.forEach((assoc) => {
    const unitId =
      assoc._unitId || (assoc.array_Unit && assoc.array_Unit.array_unitid);
    const unitName =
      (assoc.array_Unit && assoc.array_Unit.array_unitname) ||
      assoc._unitName ||
      "—";
    if (unitId) {
      units.push({ unitId, unitName });
    }
  });

  // Deduplicate by unitId
  const seen = new Set();
  return units.filter((u) => {
    if (seen.has(u.unitId)) return false;
    seen.add(u.unitId);
    return true;
  });
}

// ── Populate a unit <select> with all lease units ─────────────
// Pass the selectId and optionally the currently selected unitId
function populateUnitSelect(selectId, selectedUnitId) {
  const sel = document.getElementById(selectId);
  if (!sel) return;

  const units = getAllLeaseUnits();

  sel.innerHTML = '<option value="">All Units</option>';
  units.forEach((u) => {
    const opt = document.createElement("option");
    opt.value = u.unitId;
    opt.textContent = u.unitName;
    if (selectedUnitId && u.unitId === selectedUnitId) opt.selected = true;
    sel.appendChild(opt);
  });
}

// ── Open in ADD mode ──────────────────────────────────────────
function openAddDepositModal() {
  document.getElementById("ed_depositId").value = "";
  document.getElementById("ed_depositId").dataset.newIdx = "";
  document.getElementById("ed_isExisting").value = "false";
  document.getElementById("editDepositTitle").textContent =
    "Add Security / Insurance";
  document.getElementById("ed_saveBtnText").textContent = "Add Security";

  _ed_applyProfessionalModalStyling();

  // ── FIX: Populate Unit dropdown from getAllLeaseUnits() ───
  populateUnitSelect("ed_unit", "");

  populateCollateralTypeSelect("ed_type", "");
  populateDepositSubTypeSelect("ed_subType", "");

  [
    "ed_amount",
    "ed_amountNonDeposit",
    "ed_amountDelivered",
    "ed_payments",
  ].forEach((id) => {
    const el = document.getElementById(id);
    if (el) el.value = "";
  });

  const amendmentStart =
    document.getElementById("amend_startDate")?.value || "";
  const leaseStart = amendLeaseData.array_leasestartdate
    ? amendLeaseData.array_leasestartdate.substring(0, 10)
    : "";
  const resolvedStart = amendmentStart || leaseStart;

  const dueDateEl = document.getElementById("ed_dueDate");
  if (dueDateEl) {
    dueDateEl.value = resolvedStart || "";
    const maxDate = getMaxAllowedDate();
    if (maxDate) dueDateEl.max = maxDate;
    else dueDateEl.removeAttribute("max");
    dueDateEl.removeAttribute("min");
  }

  document.getElementById("ed_bankDisplay").value = "";
  document.getElementById("ed_bankId").value = "";
  document.getElementById("ed_issuerDisplay").value = "";
  document.getElementById("ed_issuerId").value = "";
  document.getElementById("ed_collateralApproved").value = "";

  // Reset approved-only fields and hide container
  ["ed_deliveryDate", "ed_expiryDate", "ed_guaranteeNo", "ed_comment"].forEach(
    (id) => {
      const el = document.getElementById(id);
      if (el) el.value = "";
    },
  );
  ed_onCollateralApprovedChange("");

  _ed_hideClearBtn("ed_clearBankBtn");
  _ed_hideClearBtn("ed_clearIssuerBtn");

  ed_setAllFieldsLocked(false);

  // Default Type to Deposit on open — matches CRM Quick Create behavior and
  // lets the collateral-requirement banner evaluate immediately instead of
  // staying hidden until the user picks a Type.
  const defaultTypeValue =
    typeof getDepositTypeValue === "function"
      ? getDepositTypeValue()
      : ED_DEPOSIT_TYPE_VALUE;
  const typeSelectEl = document.getElementById("ed_type");
  if (typeSelectEl && defaultTypeValue != null) {
    typeSelectEl.value = String(defaultTypeValue);
  }
  ed_onDepositTypeChange(
    defaultTypeValue != null ? String(defaultTypeValue) : "",
  );

  ed_populateCurrencies(getDefaultCurrencyId());

  cl_updateDepositCollateralBanner();
  openModal("modalEditDeposit");
}

// ── Apply recommended amount to the deposit form ─────────────
