// ── Delete a newly-added unit (local only, not yet saved) ──────
function confirmDeleteNewUnit(idx) {
  const u = amendNewUnits[idx];
  if (!u) return;
  document.getElementById("confirmDeleteMsg").textContent =
    "Remove this newly added unit from the list?";
  pendingDeleteCallback = () => {
    amendNewUnits.splice(idx, 1);
    renderNewUnitsTable();
    updateBadge("units", amendExistingUnits.length + amendNewUnits.length);
    showAmendNotification("✅ New unit removed.", "success");
  };
  document.getElementById("confirmDeleteOverlay").classList.add("active");
}

// ── openAddUnitModal ──────────────────────────────────────────
// Start Date defaults to the Effective Date from Step 2 (Terms).
// End Date defaults to the Expiry Date from Step 2 (Terms).
// Restores all fields that were locked in deactivate mode.
function openAddUnitModal() {
  if (optionRules.expansion) {
    const today = getTodayStr();
    const inRange = isDateInRange(
      today,
      optionRules.expansion.effectiveDate,
      optionRules.expansion.expiryDate,
    );
    if (!inRange) {
      const effFmt = formatDateAmend(optionRules.expansion.effectiveDate || "");
      const expFmt = formatDateAmend(optionRules.expansion.expiryDate || "");
      const rangeTxt =
        optionRules.expansion.effectiveDate && optionRules.expansion.expiryDate
          ? ` between ${effFmt} and ${expFmt}`
          : optionRules.expansion.effectiveDate
            ? ` on or after ${effFmt}`
            : optionRules.expansion.expiryDate
              ? ` on or before ${expFmt}`
              : "";
      showAmendNotification(
        `⚠️ New units can only be added during the Expansion option period${rangeTxt}.`,
        "warning",
      );
      return;
    }
  }

  const modalHeader = document.querySelector(
    "#modalAddUnit .amend-modal-header",
  );
  if (modalHeader) {
    modalHeader.style.background =
      "linear-gradient(135deg, #1C6BD4 0%, #0D4A9E 100%)";
  }

  _auSelectedUnit = null;
  _auAvailableUnits = [];
  _auAllUnitResults = [];

  // Clear any previous overlap notification
  const existingNotif = document.getElementById("au_overlapNotif");
  if (existingNotif) existingNotif.remove();

  document.getElementById("au_mode").value = "add";
  document.getElementById("au_assocId").value = "";
  document.getElementById("addUnitModalTitle").textContent =
    "Add Unit to Lease";

  const modalBody = document.querySelector("#modalAddUnit .amend-modal-body");

  const searchBox = document.getElementById("au_unitSearchBox");
  if (searchBox) {
    const sw = searchBox.closest("div[style]") || searchBox.parentElement;
    if (sw && sw !== modalBody) sw.style.display = "none";
    searchBox.style.display = "none";
    searchBox.value = "";
  }

  const resultsContainer = document.getElementById("au_unitResults");
  if (resultsContainer) resultsContainer.style.display = "";

  if (modalBody) {
    modalBody
      .querySelectorAll(":scope > svg")
      .forEach((s) => (s.style.display = ""));
    modalBody.querySelectorAll(":scope > div").forEach((div) => {
      if (
        div.children.length === 1 &&
        div.children[0].tagName.toLowerCase() === "svg"
      )
        div.style.display = "";
    });
  }

  const propDisplay = document.getElementById("au_propertyDisplay");
  const propGroup = propDisplay
    ? propDisplay.closest(".amend-form-group")
    : null;
  if (propGroup) propGroup.style.display = "";

  const propertyId = (
    (amendLeaseData.array_Property &&
      amendLeaseData.array_Property.array_propertyid) ||
    amendLeaseData["_array_property_value"] ||
    ""
  )
    .replace(/[{}]/g, "")
    .trim();

  const propertyName =
    (amendLeaseData.array_Property &&
      amendLeaseData.array_Property.array_propertyname) ||
    amendLeaseData[
      "_array_property_value@OData.Community.Display.V1.FormattedValue"
    ] ||
    "—";

  if (propDisplay) {
    propDisplay.value = propertyName;
    propDisplay.readOnly = true;
    propDisplay.style.cssText =
      "background:#F8F9FC;color:#374151;border:1.5px solid #EAECF0;" +
      "border-left:3px solid #2E7D32;padding-left:12px;cursor:default;";
  }
  const propIdInput = document.getElementById("au_propertyId");
  if (propIdInput) propIdInput.value = propertyId;

  // ── Date defaults ─────────────────────────────────────────
  const amendmentStart =
    document.getElementById("amend_startDate")?.value || "";
  const leaseStart = amendLeaseData.array_leasestartdate
    ? amendLeaseData.array_leasestartdate.substring(0, 10)
    : "";

  const resolvedStart = amendmentStart || leaseStart;

  // FIX: always use getMaxAllowedDate() as the global cap
  const maxDate = getMaxAllowedDate();

  // Use the authoritative "effective lease end" — amendment expiry if set, else lease end
  const resolvedEnd = getEffectiveLeaseEnd();

  const startInput = document.getElementById("au_startDate");
  const endInput = document.getElementById("au_endDate");
  const endDateLabel = document.getElementById("au_endDateLabel");

  startInput.value = resolvedStart;
  startInput.disabled = false;
  startInput.readOnly = false;
  startInput.style.cssText = "";
  if (maxDate) startInput.max = maxDate;
  else startInput.removeAttribute("max");

  const startGroup = startInput.closest(".amend-form-group");
  const startLabel = startGroup ? startGroup.querySelector("label") : null;
  if (startLabel) {
    startLabel.className = "required";
    startLabel.textContent = "Start Date";
  }

  endInput.disabled = false;
  endInput.readOnly = false;
  endInput.style.cssText = "";

  if (resolvedStart) {
    const minEnd = new Date(resolvedStart);
    minEnd.setDate(minEnd.getDate() + 1);
    endInput.min = minEnd.toISOString().substring(0, 10);
  } else {
    endInput.removeAttribute("min");
  }

  if (maxDate) endInput.max = maxDate;
  else endInput.removeAttribute("max");

  if (resolvedEnd && resolvedStart && resolvedEnd <= resolvedStart) {
    endInput.value = "";
    endInput.style.borderColor = "";
  } else {
    endInput.value = resolvedEnd || "";
    endInput.style.borderColor = "";
  }

  if (endDateLabel) {
    endDateLabel.textContent = "End Date";
    endDateLabel.className = "";
  }

  // ── Re-attach date listeners ──────────────────────────────
  const newStartInput = startInput.cloneNode(true);
  startInput.parentNode.replaceChild(newStartInput, startInput);
  const newEndInput = endInput.cloneNode(true);
  endInput.parentNode.replaceChild(newEndInput, endInput);

  document
    .getElementById("au_startDate")
    .addEventListener("change", function () {
      const endEl = document.getElementById("au_endDate");
      const startVal = this.value;
      if (startVal) {
        const minEnd = new Date(startVal);
        minEnd.setDate(minEnd.getDate() + 1);
        endEl.min = minEnd.toISOString().substring(0, 10);
        if (endEl.value && endEl.value <= startVal) {
          endEl.value = "";
          endEl.style.borderColor = "";
        } else {
          endEl.style.borderColor = "";
        }
      } else {
        endEl.min = "";
      }
    });

  document.getElementById("au_endDate").addEventListener("change", function () {
    const startEl = document.getElementById("au_startDate");
    const startVal = startEl.value;
    const endVal = this.value;
    if (startVal && endVal && endVal <= startVal) {
      showFieldError("au_endDate", "End Date must be after Start Date.");
      setTimeout(() => {
        this.value = "";
        clearFieldError("au_endDate");
      }, 1500);
      return;
    } else {
      this.style.borderColor = "";
    }
  });

  // ── Reset unit display ────────────────────────────────────
  const unitDisplay = document.getElementById("au_unitDisplay");
  const unitIdInput = document.getElementById("au_unitId");
  if (unitDisplay) {
    unitDisplay.value = "";
    unitDisplay.readOnly = true;
    unitDisplay.style.cssText =
      "background:#F8F9FC;border:1.5px solid #CBD5E1;cursor:pointer;";
  }
  if (unitIdInput) {
    unitIdInput.value = "";
    unitIdInput.dataset.buildingId = "";
    unitIdInput.dataset.buildingName = "";
  }

  const lookupBtn = document.getElementById("au_lookupBtn");
  if (lookupBtn) {
    lookupBtn.style.display = "";
    lookupBtn.disabled = false;
    lookupBtn.style.opacity = "";
    lookupBtn.style.cursor = "";
  }

  const btn = document.getElementById("au_saveBtn");
  if (btn) {
    btn.style.background = "";
    btn.innerHTML = `
      <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5">
        <line x1="12" y1="5" x2="12" y2="19"/>
        <line x1="5" y1="12" x2="19" y2="12"/>
      </svg> Add Unit`;
  }

  if (propertyId) {
    _au_loadUnitsForProperty(propertyId);
  } else {
    if (resultsContainer) {
      resultsContainer.innerHTML = `<div style="text-align:center;padding:24px;color:#B91C1C;font-size:13px;">
        No property linked to this lease. Cannot load units.
      </div>`;
    }
  }

  openModal("modalAddUnit");
}

// ── Load units for property with date-overlap filtering ───────
async function _au_loadUnitsForProperty(propertyId, searchTerm = "") {
  console.log(
    "🔍 _au_loadUnitsForProperty — propertyId:",
    propertyId,
    "| searchTerm:",
    searchTerm,
  );

  const container = document.getElementById("au_unitResults");
  if (!container) return;

  if (!propertyId) {
    container.innerHTML = `<div style="text-align:center;padding:24px;color:#B91C1C;font-size:13px;">
      No property ID found. Cannot load units.
    </div>`;
    return;
  }

  container.innerHTML = `<div style="text-align:center;padding:20px;color:#667eea;font-size:13px;">
    <div style="width:32px;height:32px;border:3px solid rgba(102,126,234,0.15);border-top:3px solid #667eea;border-radius:50%;animation:spin 0.7s linear infinite;margin:0 auto 10px;"></div>
    Loading available units...
  </div>`;

  const startDate = document.getElementById("au_startDate").value;
  const endDate = document.getElementById("au_endDate").value;

  // ── Build set of unit IDs already ACTIVE on this lease ───────────
  // Deactivated units are intentionally excluded from this set so they
  // can be re-added as a new association if needed.
  const alreadyUsedUnitIds = new Set();
  amendExistingUnits.forEach((a) => {
    if (a.array_Unit?.array_unitid)
      alreadyUsedUnitIds.add(a.array_Unit.array_unitid);
  });
  amendNewUnits.forEach((a) => {
    if (a._unitId) alreadyUsedUnitIds.add(a._unitId);
    if (a.array_Unit?.array_unitid)
      alreadyUsedUnitIds.add(a.array_Unit.array_unitid);
  });

  console.log("🚫 Units already on THIS lease (always excluded):", [
    ...alreadyUsedUnitIds,
  ]);

  try {
    let filter = `statecode eq 0 and array_Property/array_propertyid eq ${propertyId}`;
    if (searchTerm.trim()) {
      const escaped = searchTerm.trim().replace(/'/g, "''");
      filter += ` and (contains(array_unitname,'${escaped}') or contains(array_unitrecordid,'${escaped}'))`;
    }

    const allUnitsResp = await XrmCtx.WebApi.retrieveMultipleRecords(
      "array_unit",
      `?$select=array_unitid,array_unitname,array_unitrecordid,array_unitareasqm,array_marketrent,` +
        `_array_unittype_value,_array_building_value,_array_currentlease_value,_array_currenttenant_value` +
        `&$expand=array_Floor($select=array_floorname),array_Building($select=array_buildingname)` +
        `&$filter=${filter}&$orderby=array_unitname asc`,
    );

    let allUnits = allUnitsResp.entities || [];
    console.log(
      `✅ Dataverse returned ${allUnits.length} units for property ${propertyId}`,
    );

    // ── Step 1: Remove units already on THIS lease ────────────
    allUnits = allUnits.filter((u) => !alreadyUsedUnitIds.has(u.array_unitid));
    console.log(
      `✅ ${allUnits.length} units remain after removing units already on this lease`,
    );

    if (!allUnits.length) {
      container.innerHTML = `<div style="text-align:center;padding:32px;color:#718096;font-size:13px;">
        <svg width="40" height="40" viewBox="0 0 24 24" fill="none" stroke="#cbd5e0" stroke-width="1.5" style="display:block;margin:0 auto 12px;">
          <path d="M3 9l9-7 9 7v11a2 2 0 01-2 2H5a2 2 0 01-2-2z"/>
        </svg>
        <p style="margin:0;font-weight:600;">No available units found</p>
        <p style="margin:4px 0 0;font-size:11px;color:#a0aec0;">All units for this property are already on this lease.</p>
      </div>`;
      _auAvailableUnits = [];
      _auAllUnitResults = [];
      return;
    }

    // ── Check occupancy against active lease-unit associations ────
    // _array_currentlease_value / _array_currenttenant_value are
    // only set for active leases where start ≤ today.
    // For future leases the unit still appears vacant — so we query
    // array_leaseunitassociation directly for all returned unit IDs.
    const unitIds = allUnits.map((u) => u.array_unitid).filter(Boolean);

    if (unitIds.length > 0) {
      try {
        const clientUrl = XrmCtx.Utility.getGlobalContext().getClientUrl();
        const idFilter = unitIds
          .map((id) => `_array_unit_value eq ${id}`)
          .join(" or ");
        const assocResp = await fetch(
          `${clientUrl}/api/data/v9.2/array_leaseunitassociations` +
            `?$select=_array_unit_value,_array_leaseagreement_value,array_enddate` +
            `&$filter=statecode eq 0 and (${idFilter})`,
          {
            headers: {
              "OData-MaxVersion": "4.0",
              "OData-Version": "4.0",
              Accept: "application/json",
              Prefer: 'odata.include-annotations="*"',
            },
            credentials: "same-origin",
          },
        );
        if (assocResp.ok) {
          const assocData = await assocResp.json();
          const normalizedLeaseId = (amendLeaseId || "")
            .replace(/[{}]/g, "")
            .toLowerCase();

          // For each unit, track conflicting (OTHER-lease) occupancy:
          // the latest end date, and whether any conflict is open-ended (ongoing).
          const occMap = {}; // unitId -> { latestEnd: 'YYYY-MM-DD'|null, ongoing: bool }
          (assocData.value || []).forEach((assoc) => {
            const assocLeaseId = (assoc._array_leaseagreement_value || "")
              .replace(/[{}]/g, "")
              .toLowerCase();
            const assocUnitId = (assoc._array_unit_value || "")
              .replace(/[{}]/g, "")
              .toLowerCase();
            // Only consider conflicts on a DIFFERENT lease
            if (
              !assocUnitId ||
              !assocLeaseId ||
              assocLeaseId === normalizedLeaseId
            )
              return;

            const rec = occMap[assocUnitId] || {
              latestEnd: null,
              ongoing: false,
            };
            const end = assoc.array_enddate
              ? assoc.array_enddate.substring(0, 10)
              : null;
            if (!end) {
              rec.ongoing = true; // open-ended occupation
            } else if (!rec.latestEnd || end > rec.latestEnd) {
              rec.latestEnd = end; // keep the latest among multiples
            }
            occMap[assocUnitId] = rec;
          });

          // Effective lease end (accounts for any expiry extension in this amendment)
          const leaseEnd = (
            typeof getEffectiveLeaseEnd === "function"
              ? getEffectiveLeaseEnd() || ""
              : ""
          ).substring(0, 10);

          // Stamp occupancy + fit info on each unit.
          // Rule: a unit fits if vacant, or occupied but frees on/before lease end.
          // Occupied-with-no-end (ongoing) or occupied-beyond-lease-end → does not fit.
          allUnits = allUnits.map((u) => {
            const key = (u.array_unitid || "")
              .replace(/[{}]/g, "")
              .toLowerCase();
            const occ = occMap[key];
            const isOccupied = !!occ;
            let fitsLease = true;
            let unfitReason = "";
            const occEnd = occ ? occ.latestEnd : null;

            if (isOccupied) {
              if (occ.ongoing || !occ.latestEnd) {
                fitsLease = false;
                unfitReason = "Occupied with no end date";
              } else if (leaseEnd && occ.latestEnd > leaseEnd) {
                fitsLease = false;
                unfitReason =
                  "Occupied until " +
                  formatDateAmend(occ.latestEnd) +
                  " — beyond lease end";
              }
              // else: frees on/before lease end → fits (future-dated)
            }

            return {
              ...u,
              _isOccupied: isOccupied,
              _occEnd: occEnd,
              _fitsLease: fitsLease,
              _unfitReason: unfitReason,
            };
          });
        }
      } catch (e) {
        console.warn(
          "_au_loadUnitsForProperty: occupancy check failed (non-fatal):",
          e,
        );
      }
    }

    _auAvailableUnits = allUnits;
    _auAllUnitResults = allUnits;
    _au_renderUnitResults(allUnits, 0);
  } catch (err) {
    console.error("❌ Error in _au_loadUnitsForProperty:", err);
    container.innerHTML = `<div style="text-align:center;padding:24px;color:#B91C1C;font-size:13px;">
      Error loading units: ${esc(err.message || "Unknown error")}<br>
      <span style="font-size:11px;color:#718096;margin-top:4px;display:block;">Open browser console (F12) for details</span>
    </div>`;
  }
}

// ── Render unit result cards ──────────────────────────────────
function _au_renderUnitResults(units, filteredOutCount = 0) {
  const container = document.getElementById("au_unitResults");
  if (!container) return;

  if (!units.length) {
    const filteredMsg =
      filteredOutCount > 0
        ? `<p style="margin:4px 0 0;font-size:11px;color:#a0aec0;">${filteredOutCount} unit${filteredOutCount !== 1 ? "s are" : " is"} occupied by another lease during the selected period.</p>`
        : `<p style="margin:4px 0 0;font-size:11px;color:#a0aec0;">No units available for this property.</p>`;

    container.innerHTML = `<div style="text-align:center;padding:28px;color:#9CA3AF;font-size:13px;">
      <svg width="36" height="36" viewBox="0 0 24 24" fill="none" stroke="#CBD5E1" stroke-width="1.5" style="display:block;margin:0 auto 10px;">
        <path d="M3 9l9-7 9 7v11a2 2 0 01-2 2H5a2 2 0 01-2-2z"/>
        <polyline points="9 22 9 12 15 12 15 22"/>
      </svg>
      <p style="margin:0;font-weight:600;">No available units found</p>
      ${filteredMsg}
    </div>`;
    return;
  }

  // ── Info banner ───────────────────────────────────────────
  const startDate = document.getElementById("au_startDate").value;
  const endDate = document.getElementById("au_endDate").value;
  const _fitCount = units.filter((u) => u._fitsLease !== false).length;
  const _unfitCount = units.length - _fitCount;
  let bannerText = `${_fitCount} unit${_fitCount !== 1 ? "s" : ""} available`;
  if (startDate && endDate) {
    bannerText += ` for period ${formatDateAmend(startDate)} → ${formatDateAmend(endDate)}`;
  } else if (startDate) {
    bannerText += ` from ${formatDateAmend(startDate)}`;
  }
  if (filteredOutCount > 0) {
    bannerText += ` · ${filteredOutCount} occupied`;
  }
  if (_unfitCount > 0) {
    bannerText += ` · ${_unfitCount} can't fit this lease term`;
  }

  let html = `<div style="padding:7px 10px;background:#f0f9ff;border-left:3px solid #1C6BD4;border-radius:4px;margin-bottom:8px;font-size:11px;color:#0D4A9E;font-weight:700;">
    ${bannerText} — click a card to select
  </div>`;

  units.forEach((unit) => {
    const unitType =
      unit["_array_unittype_value@OData.Community.Display.V1.FormattedValue"] ||
      "";
    const building =
      unit.array_Building?.array_buildingname ||
      unit["_array_building_value@OData.Community.Display.V1.FormattedValue"] ||
      "";
    const floor = unit.array_Floor?.array_floorname || "";
    const area = unit.array_unitareasqm;
    const marketRent = unit.array_marketrent;
    const recordId = unit.array_unitrecordid || "";

    const isSelected =
      _auSelectedUnit && _auSelectedUnit.id === unit.array_unitid;
    const selectedStyle = isSelected
      ? "border:2px solid #2E7D32;background:#EDF7EE;"
      : "border:2px solid #EAECF0;background:#fff;";

    // Determine vacancy: vacant if no current lease or tenant is linked
    const currentLeaseId =
      unit._array_currentlease_value ||
      unit["_array_currentlease_value"] ||
      null;
    const currentTenantId =
      unit._array_currenttenant_value ||
      unit["_array_currenttenant_value"] ||
      null;
    // _isOccupied stamped by the association query in _au_loadUnitsForProperty
    const isVacant = !currentLeaseId && !currentTenantId && !unit._isOccupied;
    const vacancyBadge = isVacant
      ? `<span style="font-size:10px;background:#EDF7EE;color:#15803d;padding:2px 7px;border-radius:5px;font-weight:700;border:1px solid #A8D5AB;">Vacant</span>`
      : `<span style="font-size:10px;background:#FEF2F2;color:#B91C1C;padding:2px 7px;border-radius:5px;font-weight:700;border:1px solid #FCA5A5;">Occupied</span>`;

    const chips = [];
    chips.push(vacancyBadge);
    if (building)
      chips.push(
        `<span style="font-size:10px;background:#F1F2F4;color:#475569;padding:2px 7px;border-radius:5px;font-weight:600;">${esc(building)}</span>`,
      );
    if (floor)
      chips.push(
        `<span style="font-size:10px;background:#F1F2F4;color:#475569;padding:2px 7px;border-radius:5px;font-weight:600;">${esc(floor)}</span>`,
      );
    if (unitType)
      chips.push(
        `<span style="font-size:10px;background:#e0f2fe;color:#0369A1;padding:2px 7px;border-radius:5px;font-weight:600;">${esc(unitType)}</span>`,
      );
    if (area)
      chips.push(
        `<span style="font-size:10px;background:#EDF7EE;color:#15803d;padding:2px 7px;border-radius:5px;font-weight:600;">${area} sq m</span>`,
      );

    const _fits = unit._fitsLease !== false;
    if (unit._isOccupied && _fits && unit._occEnd) {
      chips.push(
        `<span style="font-size:10px;background:#FFF8EC;color:#7A4F0A;padding:2px 7px;border-radius:5px;font-weight:700;border:1px solid #FFCF7F;">Frees ${formatDateAmend(unit._occEnd)}</span>`,
      );
    }

    html += `
      <div ${_fits ? `onclick="_au_selectUnit('${unit.array_unitid}')"` : ""}
           id="au_card_${unit.array_unitid}"
           style="${_fits ? "cursor:pointer;" : "cursor:not-allowed;opacity:0.6;"}padding:12px 14px;border-radius:10px;margin-bottom:6px;${_fits ? selectedStyle : "border:2px solid #EAECF0;background:#F8F9FC;"}transition:all 0.15s;position:relative;"
           ${
             _fits
               ? `onmouseover="if(!this.classList.contains('au-selected')){this.style.borderColor='#667eea';this.style.background='#F5F3FF';}"
           onmouseout="if(!this.classList.contains('au-selected')){this.style.borderColor='#EAECF0';this.style.background='#fff';}"`
               : ""
           }>

        ${isSelected ? `<div style="position:absolute;top:8px;right:10px;background:#2E7D32;color:#fff;font-size:9px;font-weight:800;padding:2px 8px;border-radius:6px;letter-spacing:0.3px;">✓ SELECTED</div>` : ""}

        <div style="display:flex;align-items:flex-start;gap:10px;">
          <div style="width:36px;height:36px;border-radius:8px;background:${isSelected ? "#EDF7EE" : "#F1F2F4"};display:flex;align-items:center;justify-content:center;flex-shrink:0;">
            <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="${isSelected ? "#2E7D32" : "#5A6070"}" stroke-width="2">
              <path d="M3 9l9-7 9 7v11a2 2 0 01-2 2H5a2 2 0 01-2-2z"/>
              <polyline points="9 22 9 12 15 12 15 22"/>
            </svg>
          </div>
          <div style="flex:1;min-width:0;">
            <div style="display:flex;align-items:center;gap:7px;flex-wrap:wrap;margin-bottom:5px;">
              <strong style="font-size:14px;color:#0f172a;font-weight:700;">${esc(unit.array_unitname || "—")}</strong>
              ${recordId ? `<span style="font-size:10px;font-weight:700;color:#667eea;background:#EBF3FF;padding:2px 7px;border-radius:6px;letter-spacing:0.2px;">ID: ${esc(recordId)}</span>` : ""}
              ${marketRent ? `<span style="font-size:11px;font-weight:800;color:#2E7D32;margin-left:auto;">€${parseFloat(marketRent).toFixed(2)}</span>` : ""}
            </div>
            ${chips.length ? `<div style="display:flex;gap:5px;flex-wrap:wrap;">${chips.join("")}</div>` : ""}
            ${!_fits && unit._unfitReason ? `<div style="margin-top:6px;font-size:11px;color:#B91C1C;font-weight:600;">⚠ ${esc(unit._unfitReason)}</div>` : ""}
          </div>
          <div style="flex-shrink:0;align-self:center;">${_fits ? `<span style="color:#CBD5E1;font-size:18px;">›</span>` : `<span style="font-size:10px;font-weight:700;color:#9CA3AF;background:#F1F2F4;border:1px solid #EAECF0;padding:2px 7px;border-radius:5px;white-space:nowrap;">Unavailable</span>`}</div>
        </div>
      </div>`;
  });

  container.innerHTML = html;

  if (_auSelectedUnit) {
    const card = document.getElementById(`au_card_${_auSelectedUnit.id}`);
    if (card) card.classList.add("au-selected");
  }
}

// ── Select a unit from the list ───────────────────────────────
function _au_selectUnit(unitId) {
  const unit = _auAvailableUnits.find((u) => u.array_unitid === unitId);
  if (!unit) return;
  if (unit._fitsLease === false) return; // occupied beyond lease end / no end date — not selectable

  _auSelectedUnit = {
    id: unit.array_unitid,
    name: unit.array_unitname || "—",
    area: unit.array_unitareasqm || 0,
    type:
      unit["_array_unittype_value@OData.Community.Display.V1.FormattedValue"] ||
      "",
    building:
      unit.array_Building?.array_buildingname ||
      unit["_array_building_value@OData.Community.Display.V1.FormattedValue"] ||
      "",
    buildingId: unit._array_building_value || "",
    floor: unit.array_Floor?.array_floorname || "",
    recordId: unit.array_unitrecordid || "",
  };

  const unitDisplay = document.getElementById("au_unitDisplay");
  const unitIdInput = document.getElementById("au_unitId");
  if (unitDisplay) unitDisplay.value = unit.array_unitname || "—";
  if (unitIdInput) {
    unitIdInput.value = unit.array_unitid;
    unitIdInput.dataset.buildingId = _auSelectedUnit.buildingId;
    unitIdInput.dataset.buildingName = _auSelectedUnit.building;
  }

  _au_renderUnitResults(_auAvailableUnits);

  // ── Pre-populate dates based on selected unit ─────────────────
  // Start Date = unit's existing latest end date + 1 day
  // End Date   = amendment expiry date OR lease end date
  _au_prefillDatesFromUnit(unit.array_unitid);

  // ── Check if unit is active on another lease — show notification if so ──
  _au_checkUnitOverlapOnSelect(unit.array_unitid, unit.array_unitname || "—");
}

// ── Pre-fill Start/End dates from selected unit ──────────────────
async function _au_prefillDatesFromUnit(unitId) {
  if (!unitId) return;
  try {
    const clientUrl = XrmCtx.Utility.getGlobalContext().getClientUrl();
    const resp = await fetch(
      `${clientUrl}/api/data/v9.2/array_leaseunitassociations` +
        `?$select=array_enddate` +
        `&$filter=_array_unit_value eq ${unitId} and statecode eq 0 and array_enddate ne null` +
        `&$orderby=array_enddate desc&$top=1`,
      {
        headers: {
          "OData-MaxVersion": "4.0",
          "OData-Version": "4.0",
          Accept: "application/json",
        },
        credentials: "same-origin",
      },
    );

    const startInput = document.getElementById("au_startDate");
    const endInput = document.getElementById("au_endDate");

    // Start Date: unit's latest end date + 1 day
    let newStart = startInput?.value || "";
    if (resp.ok && startInput) {
      const data = await resp.json();
      const rec = data.value && data.value[0];
      if (rec && rec.array_enddate) {
        const d = new Date(rec.array_enddate.substring(0, 10));
        d.setDate(d.getDate() + 1);
        newStart = d.toISOString().substring(0, 10);
        startInput.value = newStart;
      }
    }

    // End Date: amendment expiry OR lease end date — only if > new start
    if (endInput) {
      // Update end input's min to new start + 1 so manual entry is constrained
      if (newStart) {
        const minEnd = new Date(newStart);
        minEnd.setDate(minEnd.getDate() + 1);
        endInput.min = minEnd.toISOString().substring(0, 10);
      }

      const resolvedEnd = getEffectiveLeaseEnd();
      if (resolvedEnd && (!newStart || resolvedEnd > newStart)) {
        endInput.value = resolvedEnd;
      } else {
        // Resolved end would be invalid → leave blank, user must enter manually
        endInput.value = "";
      }
    }
  } catch (e) {
    console.warn("_au_prefillDatesFromUnit: failed (non-fatal):", e);
  }
}

// ── Check if selected unit is on another lease — show notification only ──
async function _au_checkUnitOverlapOnSelect(unitId, unitName) {
  // Clear any previous notification
  const prev = document.getElementById("au_overlapNotif");
  if (prev) prev.remove();

  if (!unitId || !amendLeaseId) return;

  try {
    const clientUrl = XrmCtx.Utility.getGlobalContext().getClientUrl();
    const normalizedLeaseId = (amendLeaseId || "")
      .replace(/[{}]/g, "")
      .toLowerCase();

    const resp = await fetch(
      `${clientUrl}/api/data/v9.2/array_leaseunitassociations` +
        `?$select=array_leaseunitassociationid,array_startdate,array_enddate,_array_leaseagreement_value` +
        `&$expand=array_LeaseAgreement($select=array_leasename)` +
        `&$filter=_array_unit_value eq ${unitId} and statecode eq 0`,
      {
        headers: {
          "OData-MaxVersion": "4.0",
          "OData-Version": "4.0",
          Accept: "application/json",
          Prefer: 'odata.include-annotations="*"',
        },
        credentials: "same-origin",
      },
    );
    if (!resp.ok) return;

    const data = await resp.json();
    const otherAssocs = (data.value || []).filter((a) => {
      const aLeaseId = (a._array_leaseagreement_value || "")
        .replace(/[{}]/g, "")
        .toLowerCase();
      return aLeaseId !== normalizedLeaseId;
    });

    if (!otherAssocs.length) return;

    // Take the first conflicting association
    const assoc = otherAssocs[0];
    const otherEnd = assoc.array_enddate
      ? assoc.array_enddate.substring(0, 10)
      : "";
    const otherStart = assoc.array_startdate
      ? assoc.array_startdate.substring(0, 10)
      : "";
    const otherLeaseName =
      assoc.array_LeaseAgreement?.array_leasename || "another lease";

    _au_showOverlapNotification(
      unitName,
      otherLeaseName,
      otherStart,
      otherEnd,
      "",
    );
  } catch (e) {
    console.warn("_au_checkUnitOverlapOnSelect failed (non-fatal):", e);
  }
}

// ── Search units in modal ─────────────────────────────────────
function _au_searchUnits() {
  const searchTerm = document.getElementById("au_unitSearchBox")?.value || "";
  const propertyId = document.getElementById("au_propertyId")?.value || "";

  if (_auUnitSearchTimeout) clearTimeout(_auUnitSearchTimeout);
  _auUnitSearchTimeout = setTimeout(() => {
    if (propertyId) {
      _au_loadUnitsForProperty(propertyId, searchTerm);
    }
  }, 300);
}

// ── Reload units when dates change ────────────────────────────
function _au_onDateChange() {
  const propertyId = document.getElementById("au_propertyId")?.value || "";
  const searchTerm = document.getElementById("au_unitSearchBox")?.value || "";
  const startVal = document.getElementById("au_startDate").value;
  const endEl = document.getElementById("au_endDate");
  const endVal = endEl.value;

  // Update end date min constraint silently
  if (startVal) {
    const minEnd = new Date(startVal);
    minEnd.setDate(minEnd.getDate() + 1);
    endEl.min = minEnd.toISOString().substring(0, 10);

    if (endVal && endVal <= startVal) {
      // Clear silently — no error notification
      endEl.value = "";
      endEl.style.borderColor = "";
    } else {
      endEl.style.borderColor = "";
    }
  }

  if (propertyId) {
    _auSelectedUnit = null;
    const unitDisplay = document.getElementById("au_unitDisplay");
    const unitIdInput = document.getElementById("au_unitId");
    if (unitDisplay) unitDisplay.value = "";
    if (unitIdInput) {
      unitIdInput.value = "";
      unitIdInput.dataset.buildingId = "";
      unitIdInput.dataset.buildingName = "";
    }
    _au_loadUnitsForProperty(propertyId, searchTerm);
  }
}

// Dispatcher called by modal save button
function saveUnitModal() {
  const mode = document.getElementById("au_mode").value;
  if (mode === "deactivate") {
    executeDeactivateUnit();
  } else if (mode === "editExisting") {
    saveSupersedeUnit();
  } else {
    saveAddUnit();
  }
}

// Supersede an EXISTING unit association: deactivate the old association (end =
// amendment effective date) and create a new one (start = effective date) for
// the same unit, carrying the edited end date. Linked charges/deposits still
// reference the old association — the user is warned (no auto re-pointing).
function saveSupersedeUnit() {
  const assocId = document.getElementById("au_assocId").value;
  const startDate = document.getElementById("au_startDate").value;
  const endDate = document.getElementById("au_endDate").value;

  if (!assocId) return;

  if (!startDate) {
    showFieldError("au_startDate", "Association start date is required.");
    return;
  }
  if (endDate && startDate && endDate <= startDate) {
    showFieldError("au_endDate", "End Date must be after Start Date.");
    return;
  }
  clearFieldError("au_endDate");
  clearFieldError("au_startDate");

  const idx = amendExistingUnits.findIndex(
    (u) => u.array_leaseunitassociationid === assocId,
  );
  if (idx === -1) return;
  const assoc = amendExistingUnits[idx];
  const unit = assoc.array_Unit || {};
  const unitId = unit.array_unitid || null;
  const eff = getAmendmentEffectiveDate();

  // 1. Deactivate the old association (end = effective date, same day).
  const oldEnd = eff || endDate || assoc.array_enddate;
  amendDeactivatedUnits.push({
    ...assoc,
    _pendingDeactivate: true,
    _deactivateEndDate: oldEnd,
    array_enddate: oldEnd,
    _supersededBySave: true,
  });
  amendExistingUnits.splice(idx, 1);

  // 2. Create the replacement association (start = effective date by default).
  const newStart = startDate || eff;
  const newUnitEntry = {
    _isPending: true,
    _unitId: unitId,
    _startDate: newStart,
    _endDate: endDate || null,
    _buildingId: "",
    _buildingName: assoc._buildingName || "",
    _wasOccupied: false,
    _supersedesAssocId: assocId,
    array_startdate: newStart,
    array_enddate: endDate || null,
    array_Unit: unit,
  };
  newUnitEntry._assoc = {
    array_leaseunitassociationid: null,
    array_startdate: newStart,
    array_enddate: endDate || null,
    array_Unit: unit,
  };
  amendNewUnits.push(newUnitEntry);

  // 3. Warn about linked active charges/deposits that still reference the old
  //    association (they are NOT automatically re-pointed to the new one).
  let linkWarning = "";
  if (unitId) {
    const linkedCharges = (amendExistingCharges || []).filter(
      (c) => c.array_Unit && c.array_Unit.array_unitid === unitId,
    );
    const linkedDeposits = (amendDeposits || []).filter(
      (d) => d.array_Unit && d.array_Unit.array_unitid === unitId,
    );
    const n = linkedCharges.length + linkedDeposits.length;
    if (n) {
      linkWarning =
        ` Note: ${n} linked record${n !== 1 ? "s" : ""} (charges/deposits) on this unit still ` +
        `reference the previous association and are NOT automatically moved to the new one — ` +
        `review them on the Recurring Charges / Deposits steps.`;
    }
  }

  showAmendNotification(
    "Unit updated — the existing association will be deactivated and a new one created when you save." +
      linkWarning,
    linkWarning ? "warning" : "success",
  );
  closeModal("modalAddUnit");

  amendUnits = [
    ...amendExistingUnits,
    ...amendNewUnits.map((u) => u._assoc),
  ].filter(Boolean);
  renderExistingUnitsTable();
  renderNewUnitsTable();
  updateBadge("units", amendExistingUnits.length + amendNewUnits.length);
}

function saveEditExistingUnit() {
  const assocId = document.getElementById("au_assocId").value;
  const startDate = document.getElementById("au_startDate").value; // locked original
  const endDate = document.getElementById("au_endDate").value;

  if (!assocId) return;

  // Only validate end date (start is locked and unchanged)
  if (endDate && startDate && endDate <= startDate) {
    showFieldError("au_endDate", "End Date must be after Start Date.");
    return;
  }
  clearFieldError("au_endDate");

  // Stage the unit edit (cascade validation runs on Preview step)
  amendEditedUnits = amendEditedUnits.filter((e) => e.assocId !== assocId);
  amendEditedUnits.push({
    assocId,
    startDate,
    endDate: endDate || null,
  });
  // ── Notify about dependent recurring charges on THIS unit ────────
  // Notification ONLY — does not change or block anything. Flags charges
  // linked to this specific unit whose end date extends beyond the unit's
  // new end date (or that have no end date), so the user can review them.
  let chargeWarning = "";
  const newEnd = endDate || null;
  if (newEnd) {
    const assoc = (amendExistingUnits || []).find(
      (u) => u.array_leaseunitassociationid === assocId,
    );
    const unitId =
      assoc && assoc.array_Unit ? assoc.array_Unit.array_unitid : null;
    if (unitId) {
      const affected = (amendExistingCharges || []).filter((c) => {
        const cu = c.array_Unit ? c.array_Unit.array_unitid : null;
        if (!cu || cu !== unitId) return false; // only charges on THIS unit
        const ce = c.array_enddate ? c.array_enddate.substring(0, 10) : null;
        return !ce || ce > newEnd; // open-ended, or extends beyond new unit end
      });
      if (affected.length) {
        const names = affected
          .map((c) => c.array_chargename || "Unnamed charge")
          .slice(0, 3)
          .join(", ");
        const more = affected.length > 3 ? ` +${affected.length - 3} more` : "";
        chargeWarning =
          ` ⚠️ ${affected.length} recurring charge${affected.length !== 1 ? "s" : ""} on this unit ` +
          `(${names}${more}) may run beyond the new end date — review them on the Recurring Charges step.`;
      }
    }
  }

  showAmendNotification(
    "✅ Unit end date staged. Changes will be saved when you click Save Amendments." +
      chargeWarning,
    chargeWarning ? "warning" : "success",
  );
  closeModal("modalAddUnit");
  renderExistingUnitsTable();
}

function openUnitNativeLookup() {
  if (!window.parent || !window.parent.Xrm) {
    showAmendNotification("Xrm context not available for lookup.", "error");
    return;
  }
  window.parent.Xrm.Utility.lookupObjects({
    entityTypes: ["array_unit"],
    allowMultiSelect: false,
    defaultEntityType: "array_unit",
    title: "Select Unit",
  })
    .then(function (result) {
      if (!result || !result.length) return;
      const sel = result[0];
      const unitId = sel.id.replace(/[{}]/g, "");
      document.getElementById("au_unitDisplay").value = sel.name;
      document.getElementById("au_unitId").value = unitId;
      au_fetchUnitBuilding(unitId);
    })
    .catch(function (err) {
      console.error("Unit lookup error:", err);
    });
}

function au_fetchUnitBuilding(unitId) {
  const clientUrl = XrmCtx.Utility.getGlobalContext().getClientUrl();
  fetch(
    `${clientUrl}/api/data/v9.2/array_units(${unitId})?$select=_array_building_value`,
    {
      headers: {
        "OData-MaxVersion": "4.0",
        "OData-Version": "4.0",
        Accept: "application/json",
        Prefer: 'odata.include-annotations="*"',
      },
      credentials: "same-origin",
    },
  )
    .then((r) => r.json())
    .then((data) => {
      const buildingId = data["_array_building_value"] || "";
      const buildingName =
        data[
          "_array_building_value@OData.Community.Display.V1.FormattedValue"
        ] || "";
      const hiddenUnit = document.getElementById("au_unitId");
      hiddenUnit.dataset.buildingId = buildingId;
      hiddenUnit.dataset.buildingName = buildingName;
    })
    .catch(() => {
      const hiddenUnit = document.getElementById("au_unitId");
      hiddenUnit.dataset.buildingId = "";
      hiddenUnit.dataset.buildingName = "";
    });
}

function au_openLookupIfAllowed() {
  if (document.getElementById("au_mode").value === "deactivate") return;
  openUnitNativeLookup();
}

// ── Save Add Unit (updated to use _auSelectedUnit) ────────────
// ── Show inline overlap notification inside the Add Unit modal ───────────
function _au_showOverlapNotification(
  unitName,
  otherLeaseName,
  otherStart,
  otherEnd,
  enteredStart,
) {
  // Remove any existing notification
  const existing = document.getElementById("au_overlapNotif");
  if (existing) existing.remove();

  const earliestAllowed = otherEnd
    ? (function () {
        const d = new Date(otherEnd);
        d.setDate(d.getDate() + 1);
        return (
          d.getFullYear() +
          "-" +
          String(d.getMonth() + 1).padStart(2, "0") +
          "-" +
          String(d.getDate()).padStart(2, "0")
        );
      })()
    : "";

  // Auto-populate the start date field to earliest allowed
  if (earliestAllowed) {
    const startEl = document.getElementById("au_startDate");
    if (startEl) {
      startEl.value = earliestAllowed;
      startEl.min = earliestAllowed;
      startEl.style.borderColor = "#7A4F0A";
      startEl.style.boxShadow = "";
    }
    // Reconcile end date — if now ≤ start, clear it and update its min
    const endEl = document.getElementById("au_endDate");
    if (endEl) {
      const minEnd = new Date(earliestAllowed);
      minEnd.setDate(minEnd.getDate() + 1);
      const minEndStr = minEnd.toISOString().substring(0, 10);
      endEl.min = minEndStr;
      if (endEl.value && endEl.value <= earliestAllowed) {
        endEl.value = "";
        endEl.style.borderColor = "#7A4F0A";
      }
    }
  }

  const notif = document.createElement("div");
  notif.id = "au_overlapNotif";
  notif.style.cssText =
    "margin:12px 0 4px;border-radius:10px;overflow:hidden;" +
    "border:1.5px solid #7A4F0A;background:#FFF8EC;";

  notif.innerHTML = `
      <div style="background:linear-gradient(135deg,#7A4F0A,#7A4F0A);padding:10px 14px;
                  display:flex;align-items:center;gap:8px;">
        <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="#fff" stroke-width="2.5">
          <circle cx="12" cy="12" r="10"/>
          <line x1="12" y1="8" x2="12" y2="12"/>
          <line x1="12" y1="16" x2="12.01" y2="16"/>
        </svg>
        <span style="color:#fff;font-size:12px;font-weight:700;">Unit Currently Active on Another Lease</span>
      </div>
      <div style="padding:12px 14px;">
        <p style="font-size:13px;color:#7A4F0A;margin:0 0 10px;line-height:1.6;">
          <strong>${esc(unitName)}</strong> is currently linked to
          <strong>"${esc(otherLeaseName)}"</strong>
          until <strong>${otherEnd ? formatDateAmend(otherEnd) : "an ongoing date"}</strong>.
        </p>
        <div style="background:#fff;border:1px solid #FCA5A5;border-radius:8px;
                    padding:10px 12px;display:flex;gap:10px;align-items:flex-start;">
          <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="#B91C1C"
               stroke-width="2" style="flex-shrink:0;margin-top:1px;">
            <path d="M10.29 3.86L1.82 18a2 2 0 001.71 3h16.94a2 2 0 001.71-3L13.71 3.86a2 2 0 00-3.42 0z"/>
            <line x1="12" y1="9" x2="12" y2="13"/>
            <line x1="12" y1="17" x2="12.01" y2="17"/>
          </svg>
          <div style="font-size:12px;color:#7F1515;line-height:1.6;">
            <strong>Start Date must be on or after ${earliestAllowed ? formatDateAmend(earliestAllowed) : "the day after the other lease ends"}.</strong>
            <br>The Start Date has been updated automatically.
            Once the unit becomes available, it will be <strong>active on this lease</strong> and
            charges will be applied from that date onwards.
          </div>
        </div>
      </div>`;

  // Insert inside modal body before the unit results
  const modalBody = document.querySelector("#modalAddUnit .amend-modal-body");
  const resultsContainer = document.getElementById("au_unitResults");
  if (resultsContainer && modalBody) {
    modalBody.insertBefore(notif, resultsContainer);
    notif.scrollIntoView({ behavior: "smooth", block: "nearest" });
  } else if (modalBody) {
    modalBody.appendChild(notif);
  }
}

async function saveAddUnit() {
  const unitId = document.getElementById("au_unitId").value.trim();
  const unitName = document.getElementById("au_unitDisplay").value.trim();
  const startDate = document.getElementById("au_startDate").value;
  const endDate = document.getElementById("au_endDate").value; // may be blank — that's OK

  // ── Validate unit selected ──────────────────────────────────────────────────
  clearFieldErrors(document.getElementById("modalAddUnit"));
  if (!unitId) {
    showFieldError("au_unitDisplay", "Please select a unit from the list.");
    return;
  }

  // ── Validate start date ─────────────────────────────────────────────────────
  if (!startDate) {
    showFieldError("au_startDate", "Association start date is required.");
    return;
  }
  clearFieldError("au_startDate");

  // ── Validate end date (if provided) ────────────────────────────────────────
  if (endDate && endDate <= startDate) {
    showFieldError("au_endDate", "End Date must be after Start Date.");
    const endEl = document.getElementById("au_endDate");
    const minEnd = new Date(startDate);
    minEnd.setDate(minEnd.getDate() + 1);
    endEl.min = minEnd.toISOString().substring(0, 10);
    endEl.value = "";
    return;
  }
  clearFieldError("au_endDate");

  // ── Read building info from unit input dataset ──────────────────────────────
  const unitIdInput = document.getElementById("au_unitId");
  const buildingId = unitIdInput.dataset.buildingId || "";
  const buildingName = unitIdInput.dataset.buildingName || "";

  // ── Area from selected unit card ────────────────────────────────────────────
  const selectedArea = _auSelectedUnit ? _auSelectedUnit.area : null;

  // ── Stage the new unit entry (saved during final submit in STEP 4a) ─────────
  const _au_pickedUnit = (_auAvailableUnits || []).find(
    (u) => u.array_unitid === unitId,
  );
  const _wasOccupied = !!(_au_pickedUnit && _au_pickedUnit._isOccupied);

  const newUnitEntry = {
    _isPending: true,
    _unitId: unitId,
    _startDate: startDate,
    _endDate: endDate || null,
    _buildingId: buildingId,
    _buildingName: buildingName,
    _wasOccupied,
    array_startdate: startDate,
    array_enddate: endDate || null,
    array_Unit: {
      array_unitid: unitId,
      array_unitname: unitName,
      array_unitareasqm: selectedArea,
      "_array_building_value@OData.Community.Display.V1.FormattedValue":
        buildingName,
    },
  };

  // _assoc helper (used by validation engine + others)
  newUnitEntry._assoc = {
    array_leaseunitassociationid: null,
    array_startdate: startDate,
    array_enddate: endDate || null,
    array_Unit: newUnitEntry.array_Unit,
  };

  amendNewUnits.push(newUnitEntry);

  // ── Success notification ────────────────────────────────────────────────────
  showAmendNotification(
    `✅ Unit "${unitName}" staged. It will be saved when you click Save Amendments.`,
    "success",
  );

  closeModal("modalAddUnit");
  renderNewUnitsTable();
  renderUnitAreaSummary();
  updateBadge("units", amendExistingUnits.length + amendNewUnits.length);
}

// ── Helper: patch array_unit to set LeaseAgreement + Tenant ────────────────────
// Called only when startDate <= today (association covers current or past period).
//
// Fields written to array_unit:
//   array_LeaseAgreement@odata.bind   → current lease being amended
//   array_Tenant_account@odata.bind   → if lease tenant is an account
//   array_Tenant_contact@odata.bind   → if lease tenant is a contact
//
// Errors are non-fatal: logged and notified but do not block the unit staging.
async function _au_updateUnitLeaseAndTenant(unitId) {
  try {
    const payload = {};

    // ── Correct field name: array_CurrentLease ────────────────
    payload["array_CurrentLease@odata.bind"] =
      `/array_leaseagreements(${amendLeaseId})`;

    // ── Correct field name: array_CurrentTenant (polymorphic Customer lookup) ──
    const accountId =
      amendLeaseData["_array_tenant_account_value"] ||
      (amendLeaseData.array_Tenant_account &&
        amendLeaseData.array_Tenant_account.accountid) ||
      null;

    const contactId =
      amendLeaseData["_array_tenant_contact_value"] ||
      (amendLeaseData.array_Tenant_contact &&
        amendLeaseData.array_Tenant_contact.contactid) ||
      null;

    if (accountId) {
      const cleanId = accountId.replace(/[{}]/g, "").trim();
      payload["array_CurrentTenant_account@odata.bind"] =
        `/accounts(${cleanId})`;
    } else if (contactId) {
      const cleanId = contactId.replace(/[{}]/g, "").trim();
      payload["array_CurrentTenant_contact@odata.bind"] =
        `/contacts(${cleanId})`;
    }

    await XrmCtx.WebApi.updateRecord("array_unit", unitId, payload);

    console.log(
      `✅ Unit record ${unitId} updated — CurrentLease: ${amendLeaseId}` +
        (accountId
          ? ` | CurrentTenant (account): ${accountId}`
          : contactId
            ? ` | CurrentTenant (contact): ${contactId}`
            : " | No tenant found on lease"),
    );
  } catch (err) {
    console.error(
      `❌ Failed to update unit record (${unitId}) with CurrentLease/CurrentTenant:`,
      err,
    );
    // Non-fatal — association already saved, just warn
    showAmendNotification(
      `⚠️ Unit association saved, but could not update unit's Current Lease/Tenant: ${err.message || err}`,
      "warning",
    );
  }
}

// Legacy: keep openEditUnitModal as no-op
function openEditUnitModal(idx) {}

// ── Delete (confirm + execute) ────────────────────────────────
const ENTITY_MAP = {
  unit: "array_leaseunitassociation",
  charge: "array_recurringcharge",
  deposit: "array_deposit",
  clause: "array_leaseclause",
};
const DELETE_MSG = {
  unit: "Remove this unit association from the lease? The unit record itself will not be deleted.",
  charge: "Delete this recurring charge permanently?",
  deposit: "Delete this deposit/security record permanently?",
  clause: "Delete this financial clause permanently?",
};

function confirmDelete(type, recordId, idx) {
  document.getElementById("confirmDeleteMsg").textContent =
    DELETE_MSG[type] || "Delete this record?";
  pendingDeleteCallback = () => executeDelete(type, recordId, idx);
  document.getElementById("confirmDeleteOverlay").classList.add("active");
}
function closeConfirmDelete() {
  document.getElementById("confirmDeleteOverlay").classList.remove("active");
  pendingDeleteCallback = null;
}
function executeConfirmedDelete() {
  const cb = pendingDeleteCallback;
  closeConfirmDelete(); // this sets pendingDeleteCallback = null
  if (cb) cb(); // use the saved reference
}

async function executeDelete(type, recordId, idx) {
  const entity = ENTITY_MAP[type];
  if (!entity || !recordId) return;
  try {
    await XrmCtx.WebApi.deleteRecord(entity, recordId);
    showAmendNotification(`✅ Record deleted successfully.`, "success");
    if (type === "unit") await loadUnits();
    else if (type === "charge") await loadCharges();
    else if (type === "deposit") await loadDeposits();
    else if (type === "clause") await loadClauses();
  } catch (err) {
    showAmendNotification(
      `❌ Error deleting record: ` + (err.message || err),
      "error",
    );
  }
}

// ── Close UI ──────────────────────────────────────────────────
function closeAmendmentUI() {
  const confirmOverlay = document.createElement("div");
  confirmOverlay.id = "cancelConfirmOverlay";
  confirmOverlay.style.cssText = [
    "position:fixed",
    "inset:0",
    "background:rgba(0,0,0,0.55)",
    "z-index:999999",
    "display:flex",
    "align-items:center",
    "justify-content:center",
  ].join(";");

  const warningNote = isEditMode
    ? "Any unsaved changes will be discarded. The amendment will be restored to Pending status."
    : "Any unsaved changes will be lost.";

  confirmOverlay.innerHTML = `
    <div style="background:#fff;border-radius:14px;width:420px;overflow:hidden;
                box-shadow:0 20px 50px rgba(0,0,0,0.25);">
      <div style="background:linear-gradient(135deg,#B91C1C 0%,#B91C1C 100%);padding:16px 20px;">
        <h3 style="color:#fff;margin:0;font-size:15px;font-weight:700;
                   display:flex;align-items:center;gap:8px;">
          <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
            <path d="M10.29 3.86L1.82 18a2 2 0 001.71 3h16.94a2 2 0 001.71-3L13.71 3.86a2 2 0 00-3.42 0z"/>
            <line x1="12" y1="9" x2="12" y2="13"/>
            <line x1="12" y1="17" x2="12.01" y2="17"/>
          </svg>
          Confirm Close
        </h3>
      </div>
      <div style="padding:20px;font-size:14px;color:#374151;line-height:1.6;">
        Are you sure you want to close? ${warningNote}
      </div>
      <div style="padding:14px 20px;display:flex;justify-content:flex-end;gap:10px;
                  border-top:1px solid #EAECF0;">
        <button
          onclick="document.getElementById('cancelConfirmOverlay').remove()"
          style="background:#F1F2F4;color:#374151;border:1.5px solid #CBD5E1;
                 border-radius:8px;padding:10px 22px;font-size:14px;font-weight:600;
                 cursor:pointer;">
          No, Stay
        </button>
        <button
          onclick="document.getElementById('cancelConfirmOverlay').remove(); _closeAmendmentUIConfirmed();"
          style="background:linear-gradient(135deg,#B91C1C 0%,#B91C1C 100%);color:#fff;
                 border:none;border-radius:8px;padding:10px 22px;font-size:14px;font-weight:700;
                 cursor:pointer;">
          Yes, Close
        </button>
      </div>
    </div>`;

  document.body.appendChild(confirmOverlay);
}

async function _closeAmendmentUIConfirmed() {
  // In edit mode: flip amendment back to Pending before closing
  if (isEditMode && editingAmendmentId) {
    try {
      await XrmCtx.WebApi.updateRecord(
        "array_leaseamendments",
        editingAmendmentId,
        { statuscode: AMENDMENT_STATUS.PENDING },
      );
      console.log(
        `✅ Edit cancelled — amendment ${editingAmendmentId} restored to Pending.`,
      );
    } catch (e) {
      console.warn("Could not restore amendment to Pending on cancel:", e);
    }
    isEditMode = false;
    editingAmendmentId = null;
  }

  try {
    if (window.parent && window.parent.Xrm && window.parent.Xrm.Navigation) {
      try {
        const parentForm =
          window.parent.Xrm.Page?.data ||
          window.parent.Xrm.UI?.formContext?.data ||
          (window.parent.Xrm.getCurrentPage &&
            window.parent.Xrm.getCurrentPage()?.data);
        if (parentForm && typeof parentForm.refresh === "function") {
          parentForm.refresh(false);
        }
      } catch (refreshErr) {
        console.warn("Could not refresh parent form:", refreshErr);
      }
      window.parent.Xrm.Navigation.closeDialog();
    } else {
      window.close();
    }
  } catch (e) {
    window.close();
  }
}

// ── Modal helpers ─────────────────────────────────────────────
// Tracks the LIFO stack of open modals so Esc only dismisses the topmost.
const _amendModalStack = [];

function openModal(id) {
  const el = document.getElementById(id);
  if (!el) return;
  try {
    clearFieldErrors(el);
  } catch (_) {
    /* helper may not be loaded yet */
  }
  el.classList.add("active");
  el.setAttribute("role", "dialog");
  el.setAttribute("aria-modal", "true");
  // Auto-wire aria-labelledby to the modal's title element so screen readers
  // announce the modal name when it opens.
  if (!el.hasAttribute("aria-labelledby")) {
    const title = el.querySelector(".amend-modal-title, h1, h2, h3");
    if (title) {
      if (!title.id) title.id = id + "_title";
      el.setAttribute("aria-labelledby", title.id);
    }
  }
  // Push to stack (avoid dup if already there)
  const i = _amendModalStack.indexOf(id);
  if (i !== -1) _amendModalStack.splice(i, 1);
  _amendModalStack.push(id);
  // Focus first focusable control inside the modal for keyboard users
  setTimeout(() => {
    const focusable = el.querySelector(
      'input:not([disabled]):not([type="hidden"]), select:not([disabled]), textarea:not([disabled]), button:not([disabled]), [tabindex]:not([tabindex="-1"])',
    );
    if (focusable) {
      try {
        focusable.focus();
      } catch (_) {}
    }
  }, 50);
}

function closeModal(id) {
  const el = document.getElementById(id);
  if (!el) return;
  try {
    clearFieldErrors(el);
  } catch (_) {}
  el.classList.remove("active");
  const i = _amendModalStack.indexOf(id);
  if (i !== -1) _amendModalStack.splice(i, 1);
}

// Esc closes the topmost modal. Backdrop click is handled per-modal via existing HTML.
document.addEventListener("keydown", function (e) {
  if (e.key !== "Escape" && e.key !== "Esc") return;
  if (!_amendModalStack.length) return;
  // Don't intercept if an inner native dialog (e.g. <input> picker) is open — best effort
  const topId = _amendModalStack[_amendModalStack.length - 1];
  e.stopPropagation();
  closeModal(topId);
});

// ── Utility: populate <select> ────────────────────────────────
function populateSelect(
  selectId,
  items,
  valueKey,
  labelFn,
  selectedValue,
  addBlank = false,
) {
  const sel = document.getElementById(selectId);
  if (!sel) return;
  const blankOpt = sel.options[0] ? sel.options[0].textContent : "Select...";
  sel.innerHTML = `<option value="">${blankOpt}</option>`;
  if (addBlank) {
  }
  items.forEach((item) => {
    const opt = document.createElement("option");
    opt.value = item[valueKey] !== undefined ? item[valueKey] : item;
    opt.textContent = labelFn(item);
    if (String(opt.value) === String(selectedValue)) opt.selected = true;
    sel.appendChild(opt);
  });
}

function populateCollateralTypeSelect(selectId, selectedValue) {
  const sel = document.getElementById(selectId);
  if (!sel) return;
  if (!amendCollateralTypes.length) {
    console.warn(
      `populateCollateralTypeSelect('${selectId}'): amendCollateralTypes is empty — Type dropdown will show no options. Check GlobalOptionSet loading in loadAmendLookups().`,
    );
  }
  sel.innerHTML = `<option value="">Select type</option>`;
  amendCollateralTypes.forEach((t) => {
    const label =
      t.Label?.UserLocalizedLabel?.Label ||
      t.Label?.LocalizedLabels?.[0]?.Label ||
      String(t.Value);
    const opt = document.createElement("option");
    opt.value = t.Value;
    opt.textContent = label;
    if (String(t.Value) === String(selectedValue)) opt.selected = true;
    sel.appendChild(opt);
  });
}

function populateDepositSubTypeSelect(selectId, selectedValue) {
  const sel = document.getElementById(selectId);
  if (!sel) return;
  sel.innerHTML = `<option value="">Select sub type</option>`;
  amendDepositSubTypes.forEach((t) => {
    const label =
      t.Label?.UserLocalizedLabel?.Label ||
      t.Label?.LocalizedLabels?.[0]?.Label ||
      String(t.Value);
    const opt = document.createElement("option");
    opt.value = t.Value;
    opt.textContent = label;
    if (String(t.Value) === String(selectedValue)) opt.selected = true;
    sel.appendChild(opt);
  });
}

function getOptionLabel(options, value) {
  if (value === null || value === undefined) return null;
  const match = options.find((o) => String(o.Value) === String(value));
  if (!match) return null;
  return (
    match.Label?.UserLocalizedLabel?.Label ||
    match.Label?.LocalizedLabels?.[0]?.Label ||
    String(value)
  );
}

function getFreqLabel(value) {
  if (value === null || value === undefined) return "—";
  const match = amendFrequencies.find((f) => String(f.Value) === String(value));
  if (!match) return String(value);
  return match.Label?.UserLocalizedLabel?.Label || String(value);
}

function getDefaultCurrencyId() {
  // Primary: find PLN
  const pln = amendCurrencies.find(
    (c) => (c.isocurrencycode || "").toUpperCase() === "PLN",
  );
  if (pln) return pln.transactioncurrencyid;

  // Fallback: exchange rate = 1.0 (original behaviour)
  const base = amendCurrencies.find((c) => parseFloat(c.exchangerate) === 1.0);
  return base ? base.transactioncurrencyid : "";
}

function getTenantId() {
  // Tenant is a Customer lookup — IDs come from the expanded account/contact,
  // falling back to the raw _value columns.
  const accountId =
    amendLeaseData.array_Tenant_account?.accountid ||
    amendLeaseData["_array_tenant_account_value"] ||
    null;
  const contactId =
    amendLeaseData.array_Tenant_contact?.contactid ||
    amendLeaseData["_array_tenant_contact_value"] ||
    null;
  if (accountId) return { id: accountId.replace(/[{}]/g, ""), type: "account" };
  if (contactId) return { id: contactId.replace(/[{}]/g, ""), type: "contact" };
  return { id: null, type: null };
}

// ── Misc helpers ──────────────────────────────────────────────
function formatDateAmend(dateStr) {
  if (!dateStr) return "—";
  const d = new Date(dateStr);
  if (isNaN(d.getTime())) return dateStr;
  return `${String(d.getDate()).padStart(2, "0")}-${String(d.getMonth() + 1).padStart(2, "0")}-${d.getFullYear()}`;
}

function esc(str) {
  if (!str) return "";
  return String(str)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");
}

function updateBadge(tab, count) {
  const el = document.getElementById("badge-" + tab);
  if (el) el.textContent = count;
}

function setTableError(tbodyId, colspan, message) {
  const el = document.getElementById(tbodyId);
  if (el)
    el.innerHTML = `<tr><td colspan="${colspan}" style="text-align:center;padding:30px;color:#B91C1C;">${message}</td></tr>`;
}

function clearFormFields(ids) {
  ids.forEach((id) => {
    const el = document.getElementById(id);
    if (el) el.value = "";
  });
}

// ══════════════════════════════════════════════════════════════
//  DEFERRED WRITE — Pending amendment banner
//  If a Pending amendment exists, warn the user that new changes
//  will stack on top and may overlap with pending ones.
// ══════════════════════════════════════════════════════════════
async function checkPendingAmendmentBanner() {
  if (!amendLeaseId) return;
  try {
    const clientUrl = XrmCtx.Utility.getGlobalContext().getClientUrl();
    const url =
      `${clientUrl}/api/data/v9.2/array_leaseamendmentses` +
      `?$select=array_leaseamendmentsid,array_amendmentname,array_effectivedate,statuscode` +
      `&$filter=_array_leaseagreement_value eq ${amendLeaseId}` +
      ` and statuscode eq ${AMENDMENT_STATUS.PENDING}` +
      `&$orderby=array_effectivedate asc&$top=5`;
    const resp = await fetch(url, {
      headers: {
        "OData-MaxVersion": "4.0",
        "OData-Version": "4.0",
        Accept: "application/json",
        Prefer: 'odata.include-annotations="*"',
      },
      credentials: "same-origin",
    });
    if (!resp.ok) return;
    const data = await resp.json();
    const pending = data.value || [];
    if (!pending.length) return;

    const existing = document.getElementById("pendingAmendmentBanner");
    if (existing) existing.remove();

    const earliest = pending[0];
    const earliestDate = formatDateAmend(earliest.array_effectivedate);
    const countTxt =
      pending.length === 1
        ? `1 pending amendment`
        : `${pending.length} pending amendments`;

    const banner = document.createElement("div");
    banner.id = "pendingAmendmentBanner";
    banner.style.cssText = [
      "position:fixed",
      "top:0",
      "left:0",
      "right:0",
      "background:linear-gradient(135deg,#7A4F0A 0%,#7A4F0A 100%)",
      "color:#fff",
      "padding:9px 18px",
      "font-size:12px",
      "font-weight:600",
      "z-index:99998",
      "display:flex",
      "align-items:center",
      "gap:10px",
      "box-shadow:0 2px 8px rgba(0,0,0,0.15)",
    ].join(";");
    banner.innerHTML = `
      <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" style="flex-shrink:0">
        <path d="M10.29 3.86L1.82 18a2 2 0 001.71 3h16.94a2 2 0 001.71-3L13.71 3.86a2 2 0 00-3.42 0z"/>
        <line x1="12" y1="9" x2="12" y2="13"/>
        <line x1="12" y1="17" x2="12.01" y2="17"/>
      </svg>
      <span>This lease has ${countTxt} (earliest effective ${earliestDate}). Changes you save now will be added on top and may overlap with pending changes.</span>
    `;
    document.body.appendChild(banner);
  } catch (e) {
    console.warn("checkPendingAmendmentBanner: query failed", e);
  }
}

function showAmendNotification(message, type = "info") {
  const colors = {
    success: "#2E7D32",
    error: "#B91C1C",
    warning: "#7A4F0A",
    info: "#667eea",
  };

  // Remove any existing notification of same type to avoid stacking
  document.querySelectorAll(".amend-notif-toast").forEach((el) => el.remove());

  const n = document.createElement("div");
  n.className = "amend-notif-toast";
  n.setAttribute("role", type === "error" ? "alert" : "status");
  n.setAttribute("aria-live", type === "error" ? "assertive" : "polite");
  n.setAttribute("aria-atomic", "true");
  n.style.cssText = [
    "position:fixed",
    "top:20px",
    "right:24px",
    `background:${colors[type] || colors.info}`,
    "color:#fff",
    "padding:12px 20px",
    "border-radius:10px",
    "font-size:13px",
    "font-weight:600",
    "z-index:999999",
    "box-shadow:0 4px 16px rgba(0,0,0,0.25)",
    "max-width:380px",
    "display:flex",
    "align-items:center",
    "gap:10px",
    "opacity:1",
    "transition:opacity 0.3s",
    "pointer-events:none",
  ].join(";");

  // Icon per type
  const icons = {
    success: `<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" style="flex-shrink:0"><polyline points="20 6 9 17 4 12"/></svg>`,
    error: `<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" style="flex-shrink:0"><circle cx="12" cy="12" r="10"/><line x1="12" y1="8" x2="12" y2="12"/><line x1="12" y1="16" x2="12.01" y2="16"/></svg>`,
    warning: `<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" style="flex-shrink:0"><path d="M10.29 3.86L1.82 18a2 2 0 001.71 3h16.94a2 2 0 001.71-3L13.71 3.86a2 2 0 00-3.42 0z"/><line x1="12" y1="9" x2="12" y2="13"/><line x1="12" y1="17" x2="12.01" y2="17"/></svg>`,
    info: `<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" style="flex-shrink:0"><circle cx="12" cy="12" r="10"/><line x1="12" y1="8" x2="12" y2="12"/><line x1="12" y1="16" x2="12.01" y2="16"/></svg>`,
  };

  n.innerHTML = `${icons[type] || icons.info}<span>${message}</span>`;
  document.body.appendChild(n);

  setTimeout(() => {
    n.style.opacity = "0";
    setTimeout(() => n.remove(), 300);
  }, 3500);
}

function showAmendPopup(message, type = "info") {
  document.querySelectorAll(".amend-notif-popup").forEach((el) => el.remove());

  const bgColors = {
    success: "#1B5E20",
    error: "#7F1D1D",
    warning: "#78350F",
    info: "#1e3a5f",
  };
  const borderColors = {
    success: "#4CAF50",
    error: "#EF5350",
    warning: "#FFA726",
    info: "#667eea",
  };
  const bg = bgColors[type] || bgColors.info;
  const border = borderColors[type] || borderColors.info;

  const overlay = document.createElement("div");
  overlay.className = "amend-notif-popup";
  overlay.setAttribute("role", "dialog");
  overlay.setAttribute("aria-modal", "true");
  overlay.setAttribute("aria-live", type === "error" ? "assertive" : "polite");
  overlay.style.cssText =
    "position:fixed;inset:0;z-index:1000000;display:flex;align-items:flex-start;" +
    "justify-content:center;padding-top:72px;background:rgba(0,0,0,0.35);";

  const card = document.createElement("div");
  card.style.cssText =
    `background:${bg};color:#fff;border-radius:12px;padding:20px 24px 20px 20px;` +
    `max-width:580px;width:calc(100% - 48px);box-shadow:0 8px 32px rgba(0,0,0,0.4);` +
    `border-left:5px solid ${border};position:relative;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI','Segoe UI Variable',system-ui,Roboto,Helvetica,Arial,sans-serif;`;

  const closeBtn = document.createElement("button");
  closeBtn.innerHTML = "&#x2715;";
  closeBtn.style.cssText =
    "position:absolute;top:10px;right:12px;background:none;border:none;color:rgba(255,255,255,0.7);" +
    "font-size:18px;line-height:1;cursor:pointer;padding:2px 6px;border-radius:4px;";
  closeBtn.onmouseover = () => {
    closeBtn.style.color = "#fff";
    closeBtn.style.background = "rgba(255,255,255,0.15)";
  };
  closeBtn.onmouseout = () => {
    closeBtn.style.color = "rgba(255,255,255,0.7)";
    closeBtn.style.background = "none";
  };
  closeBtn.onclick = () => overlay.remove();

  const body = document.createElement("div");
  body.style.cssText =
    "font-size:13px;font-weight:500;line-height:1.6;padding-right:20px;";
  body.innerHTML = message;

  card.appendChild(closeBtn);
  card.appendChild(body);
  overlay.appendChild(card);

  overlay.addEventListener("click", (e) => {
    if (e.target === overlay) overlay.remove();
  });

  document.body.appendChild(overlay);
}

// ── Inline field-level validation errors ─────────────────────────
//   Highlights the field, shows a small error message directly below it,
//   focuses+scrolls the field into view. Cleared automatically when the
//   user edits the field.
function showFieldError(fieldId, message) {
  const el = document.getElementById(fieldId);
  if (!el) {
    showAmendNotification(message, "error");
    return;
  }
  el.style.borderColor = "#B91C1C";
  el.style.boxShadow = "0 0 0 2px rgba(185,28,28,0.15)";
  el.classList.add("amend-field-error-marked");
  el.setAttribute("aria-invalid", "true");
  el.setAttribute("aria-describedby", fieldId + "_err");

  let errEl = document.getElementById(fieldId + "_err");
  if (!errEl) {
    errEl = document.createElement("div");
    errEl.id = fieldId + "_err";
    errEl.className = "amend-field-error-msg";
    errEl.setAttribute("role", "alert");
    errEl.setAttribute("aria-live", "polite");
    errEl.style.cssText =
      "color:#B91C1C;font-size:12px;font-weight:500;margin-top:4px;" +
      "display:flex;align-items:center;gap:4px;line-height:1.3;";
    el.insertAdjacentElement("afterend", errEl);
  }
  errEl.innerHTML =
    '<svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" style="flex-shrink:0" aria-hidden="true"><circle cx="12" cy="12" r="10"/><line x1="12" y1="8" x2="12" y2="12"/><line x1="12" y1="16" x2="12.01" y2="16"/></svg>' +
    "<span>" +
    (message || "").replace(/^[❌⚠️✅ℹ️]+\s*/, "") +
    "</span>";

  try {
    el.focus({ preventScroll: false });
  } catch (_) {
    try {
      el.focus();
    } catch (_) {}
  }
  try {
    el.scrollIntoView({ behavior: "smooth", block: "center" });
  } catch (_) {}
}

function clearFieldError(fieldId) {
  const el = document.getElementById(fieldId);
  if (el) {
    el.style.borderColor = "";
    el.style.boxShadow = "";
    el.classList.remove("amend-field-error-marked");
    el.removeAttribute("aria-invalid");
    el.removeAttribute("aria-describedby");
  }
  const errEl = document.getElementById(fieldId + "_err");
  if (errEl) errEl.remove();
}

// Element-based variant — for fields without IDs (e.g. dynamic clause rows queried by class)
function showFieldErrorEl(el, message) {
  if (!el) {
    showAmendNotification(message, "error");
    return;
  }
  el.style.borderColor = "#B91C1C";
  el.style.boxShadow = "0 0 0 2px rgba(185,28,28,0.15)";
  el.classList.add("amend-field-error-marked");
  let errEl = el.nextElementSibling;
  if (!errEl || !errEl.classList.contains("amend-field-error-msg")) {
    errEl = document.createElement("div");
    errEl.className = "amend-field-error-msg";
    errEl.style.cssText =
      "color:#B91C1C;font-size:12px;font-weight:500;margin-top:4px;" +
      "display:flex;align-items:center;gap:4px;line-height:1.3;";
    el.insertAdjacentElement("afterend", errEl);
  }
  errEl.innerHTML =
    '<svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" style="flex-shrink:0"><circle cx="12" cy="12" r="10"/><line x1="12" y1="8" x2="12" y2="12"/><line x1="12" y1="16" x2="12.01" y2="16"/></svg>' +
    "<span>" +
    (message || "").replace(/^[❌⚠️✅ℹ️]+\s*/, "") +
    "</span>";
  try {
    el.focus();
  } catch (_) {}
  try {
    el.scrollIntoView({ behavior: "smooth", block: "center" });
  } catch (_) {}
}

function clearFieldErrors(scopeEl) {
  const root = scopeEl || document;
  root.querySelectorAll(".amend-field-error-marked").forEach((el) => {
    el.style.borderColor = "";
    el.style.boxShadow = "";
    el.classList.remove("amend-field-error-marked");
  });
  root.querySelectorAll(".amend-field-error-msg").forEach((el) => el.remove());
}

// Auto-clear errors as soon as the user starts editing the offending field
document.addEventListener(
  "input",
  function (e) {
    if (
      e.target &&
      e.target.classList &&
      e.target.classList.contains("amend-field-error-marked")
    ) {
      clearFieldError(e.target.id);
    }
  },
  true,
);
document.addEventListener(
  "change",
  function (e) {
    if (
      e.target &&
      e.target.classList &&
      e.target.classList.contains("amend-field-error-marked")
    ) {
      clearFieldError(e.target.id);
    }
  },
  true,
);

// ══════════════════════════════════════════════════════════════════════════════
//  AI-AUTOFILL BANNER (Lease Terms step)
//  Adds a slim "Drop a PDF to autofill" zone above the form fields. Two modes:
//    Mode A — files already staged in step 1: show "Use uploaded PDF" picker
//    Mode B — no files yet: drop zone; on drop, add to step-1 staging AND
//             trigger ai_offerPrefill (single drop does both jobs).
//  Hidden in edit mode (data is already loaded) and dismissable per session.
// ══════════════════════════════════════════════════════════════════════════════

var _aiBanner_dismissed = false;

function _aiBanner_isPdf(f) {
  return f && (f.type === "application/pdf" || /\.pdf$/i.test(f.name));
}

function _aiBanner_pdfsInStaging() {
  if (!Array.isArray(uploadedFiles)) return [];
  return uploadedFiles.filter(_aiBanner_isPdf);
}

function _aiBanner_updateMode() {
  var banner = document.getElementById("aiAutofillBanner");
  if (!banner) return;
  if (_aiBanner_dismissed) {
    banner.style.display = "none";
    return;
  }
  banner.style.display = "block";

  var pdfs = _aiBanner_pdfsInStaging();
  var modeA = banner.querySelector(".ai-banner-mode-a");
  var modeB = banner.querySelector(".ai-banner-mode-b");
  var picker = banner.querySelector("#aiBanner_pdfPicker");

  if (pdfs.length) {
    modeA.style.display = "flex";
    modeB.style.display = "none";
    // Refresh dropdown options
    picker.innerHTML = pdfs
      .map(function (f, i) {
        // Find true index in uploadedFiles for run-on-click
        var trueIdx = uploadedFiles.indexOf(f);
        return (
          '<option value="' +
          trueIdx +
          '">' +
          (f.name || "PDF " + (i + 1)) +
          "</option>"
        );
      })
      .join("");
  } else {
    modeA.style.display = "none";
    modeB.style.display = "flex";
  }
}

function _aiBanner_dismiss() {
  _aiBanner_dismissed = true;
  var banner = document.getElementById("aiAutofillBanner");
  if (banner) {
    banner.style.opacity = "0";
    banner.style.maxHeight = "0";
    banner.style.marginBottom = "0";
    banner.style.paddingTop = "0";
    banner.style.paddingBottom = "0";
    banner.style.overflow = "hidden";
    setTimeout(function () {
      banner.style.display = "none";
    }, 220);
  }
}

function _aiBanner_runOnSelected() {
  var picker = document.getElementById("aiBanner_pdfPicker");
  if (!picker) return;
  var idx = parseInt(picker.value, 10);
  if (isNaN(idx) || idx < 0 || idx >= uploadedFiles.length) return;
  var entry = uploadedFiles[idx];
  if (!entry) return;
  if (typeof ai_offerPrefill === "function") ai_offerPrefill(entry);
}

function _aiBanner_handleDroppedFiles(files) {
  if (!files || !files.length) return;
  // Restrict to a single PDF for this banner — the multi-file path is step 1.
  var pdf = Array.from(files).find(_aiBanner_isPdf);
  if (!pdf) {
    showAmendNotification(
      "⚠️ Please drop a PDF file. Other types belong in the Documents step.",
      "warning",
    );
    return;
  }
  // Size check (mirrors fu_handleFileSelect)
  var MAX = 20;
  if (pdf.size / (1024 * 1024) > MAX) {
    showAmendNotification(
      '❌ "' + pdf.name + '" exceeds the ' + MAX + "MB limit.",
      "error",
    );
    return;
  }
  // Skip duplicate against step-1 staging
  var dup = uploadedFiles.some(function (f) {
    return f.name === pdf.name && f.size === pdf.size;
  });
  if (dup) {
    showAmendNotification(
      'ℹ️ "' +
        pdf.name +
        '" is already in your uploads — running autofill on the existing copy.',
      "info",
    );
    var existing = uploadedFiles.find(function (f) {
      return f.name === pdf.name && f.size === pdf.size;
    });
    if (existing && typeof ai_offerPrefill === "function")
      ai_offerPrefill(existing);
    return;
  }
  // Add to step-1 staging so the PDF is also stored on save
  var entry = {
    file: pdf,
    name: pdf.name,
    size: pdf.size,
    type: pdf.type || "application/pdf",
    base64: null,
  };
  uploadedFiles.push(entry);
  try {
    if (typeof fu_renderFileList === "function") fu_renderFileList();
  } catch (_) {}
  _aiBanner_updateMode();
  showAmendNotification(
    '✅ "' + pdf.name + '" added to documents. Running autofill…',
    "success",
  );
  if (typeof ai_offerPrefill === "function") {
    setTimeout(function () {
      ai_offerPrefill(entry);
    }, 50);
  }
}

function _aiBanner_ensure() {
  var panel = document.getElementById("panel-terms");
  if (!panel) return;
  var existingBanner = document.getElementById("aiAutofillBanner");
  if (existingBanner) {
    // Banner already present in the HTML: attach its handlers once
    // (otherwise Run autofill / dismiss / browse / drop do nothing).
    if (!existingBanner.dataset.wired) {
      existingBanner.dataset.wired = "1";

      var dismissBtn = existingBanner.querySelector("#aiBanner_dismissBtn");
      var runBtn = existingBanner.querySelector("#aiBanner_runBtn");
      var fileInput = existingBanner.querySelector("#aiBanner_fileInput");

      if (dismissBtn) dismissBtn.onclick = _aiBanner_dismiss;
      if (runBtn) runBtn.onclick = _aiBanner_runOnSelected;

      if (fileInput) {
        fileInput.addEventListener("change", function () {
          _aiBanner_handleDroppedFiles(fileInput.files);
          fileInput.value = "";
        });
      }

      existingBanner.addEventListener("dragover", function (e) {
        e.preventDefault();
        e.stopPropagation();
        existingBanner.classList.add("is-dragover");
      });
      existingBanner.addEventListener("dragleave", function (e) {
        if (e.target === existingBanner)
          existingBanner.classList.remove("is-dragover");
      });
      existingBanner.addEventListener("drop", function (e) {
        e.preventDefault();
        e.stopPropagation();
        existingBanner.classList.remove("is-dragover");
        _aiBanner_handleDroppedFiles(e.dataTransfer && e.dataTransfer.files);
      });
    }
    _aiBanner_updateMode();
    return;
  }

  // Inject CSS once
  if (!document.getElementById("aiAutofillBannerCss_v1")) {
    var st = document.createElement("style");
    st.id = "aiAutofillBannerCss_v1";
    st.textContent =
      "#aiAutofillBanner{" +
      "background:linear-gradient(135deg,#EFF6FF 0%,#DBEAFE 100%);" +
      "border:1px dashed #93C5FD;border-radius:12px;" +
      "padding:14px 18px;margin-bottom:20px;" +
      "transition:opacity 220ms ease,max-height 220ms ease,margin 220ms ease,padding 220ms ease;" +
      "font-family:-apple-system,BlinkMacSystemFont,'Segoe UI','Segoe UI Variable',system-ui,Roboto,Helvetica,Arial,sans-serif;" +
      "position:relative;}" +
      "#aiAutofillBanner.is-dragover{" +
      "background:linear-gradient(135deg,#DBEAFE 0%,#BFDBFE 100%);" +
      "border-color:#1C6BD4;border-style:solid;" +
      "box-shadow:0 0 0 4px rgba(28,107,212,0.12);}" +
      ".ai-banner-row{" +
      "display:flex;align-items:center;gap:14px;flex-wrap:wrap;}" +
      ".ai-banner-icon{" +
      "width:38px;height:38px;border-radius:10px;flex-shrink:0;" +
      "background:#1C6BD4;color:#fff;" +
      "display:flex;align-items:center;justify-content:center;" +
      "box-shadow:0 4px 10px rgba(28,107,212,0.25);}" +
      ".ai-banner-text{flex:1 1 220px;min-width:0;}" +
      ".ai-banner-title{" +
      "font-size:13.5px;font-weight:600;color:#1E3A8A;margin:0;" +
      "display:flex;align-items:center;gap:6px;}" +
      ".ai-banner-sub{" +
      "font-size:12px;color:#1E40AF;margin-top:2px;opacity:0.85;}" +
      ".ai-banner-pill{" +
      "background:#1C6BD4;color:#fff;font-size:10px;font-weight:700;" +
      "padding:2px 7px;border-radius:999px;letter-spacing:0.3px;" +
      "text-transform:uppercase;}" +
      ".ai-banner-dismiss{" +
      "position:absolute;top:10px;right:12px;" +
      "background:transparent;border:none;cursor:pointer;" +
      "width:24px;height:24px;border-radius:6px;color:#6B7280;" +
      "display:flex;align-items:center;justify-content:center;" +
      "transition:background 140ms ease,color 140ms ease;}" +
      ".ai-banner-dismiss:hover{background:rgba(255,255,255,0.6);color:#1E40AF;}" +
      /* Mode A — staged PDF picker */
      ".ai-banner-mode-a{display:none;align-items:center;gap:8px;flex-wrap:wrap;" +
      "flex:1 1 260px;min-width:0;}" +
      "#aiBanner_pdfPicker{" +
      "flex:1 1 160px;min-width:0;max-width:100%;" +
      "height:34px;padding:0 10px;border-radius:8px;" +
      "border:1px solid #BFDBFE;background:#fff;color:#111827;" +
      "font-size:13px;cursor:pointer;outline:none;" +
      "text-overflow:ellipsis;overflow:hidden;white-space:nowrap;" +
      "transition:border-color 140ms ease,box-shadow 140ms ease;}" +
      "#aiBanner_pdfPicker:focus{border-color:#1C6BD4;box-shadow:0 0 0 3px rgba(28,107,212,0.16);}" +
      ".ai-banner-run-btn{" +
      "background:#1C6BD4;color:#fff;border:none;flex-shrink:0;" +
      "padding:8px 16px;border-radius:8px;font-size:13px;font-weight:600;" +
      "cursor:pointer;display:inline-flex;align-items:center;gap:6px;white-space:nowrap;" +
      "transition:background 140ms ease,box-shadow 140ms ease,transform 80ms ease;}" +
      ".ai-banner-run-btn:hover{background:#1E40AF;box-shadow:0 4px 10px rgba(28,107,212,0.30);}" +
      ".ai-banner-run-btn:active{transform:scale(0.97);}" +
      /* Mode B — drop zone */
      ".ai-banner-mode-b{display:flex;align-items:center;gap:14px;" +
      "flex:1 1 260px;min-width:0;}" +
      ".ai-banner-drop{" +
      "flex:1;cursor:pointer;font-size:12.5px;color:#1E40AF;" +
      "padding:6px 0;line-height:1.5;min-width:0;" +
      "overflow-wrap:break-word;word-break:normal;}" +
      ".ai-banner-drop u{text-decoration:underline;text-underline-offset:2px;}" +
      ".ai-banner-input{position:absolute;left:-9999px;opacity:0;width:0;height:0;}" +
      /* Narrow form pane — stack everything vertically + compact icon */
      "@media (max-width:520px),(max-width:520px){" +
      ".ai-banner-row{gap:10px;}" +
      ".ai-banner-text{flex-basis:100%;}" +
      ".ai-banner-mode-a,.ai-banner-mode-b{flex-basis:100%;}" +
      "#aiAutofillBanner{padding:12px 14px;}}" +
      /* Container-based fallback when form pane is narrow (~<420px).
               We can't rely on viewport media queries because the PDF pane
               eats half the width. Use a wrapping behaviour that stays
               readable at any width without per-pane container queries. */
      "#aiAutofillBanner{container-type:inline-size;}" +
      "@container (max-width:420px){" +
      ".ai-banner-text{flex-basis:100% !important;}" +
      ".ai-banner-mode-a,.ai-banner-mode-b{flex-basis:100% !important;}" +
      ".ai-banner-icon{width:32px;height:32px;}}";
    document.head.appendChild(st);
  }

  // Build the banner DOM
  var banner = document.createElement("div");
  banner.id = "aiAutofillBanner";
  banner.setAttribute("role", "region");
  banner.setAttribute("aria-label", "AI autofill from PDF");
  banner.innerHTML =
    '<button class="ai-banner-dismiss" id="aiBanner_dismissBtn" type="button" title="Dismiss" aria-label="Dismiss autofill banner">' +
    '<svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>' +
    "</button>" +
    '<div class="ai-banner-row">' +
    '<div class="ai-banner-icon">' +
    '<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">' +
    '<path d="M21 15v4a2 2 0 01-2 2H5a2 2 0 01-2-2v-4"/>' +
    '<polyline points="17 8 12 3 7 8"/>' +
    '<line x1="12" y1="3" x2="12" y2="15"/>' +
    "</svg>" +
    "</div>" +
    '<div class="ai-banner-text">' +
    '<div class="ai-banner-title">Autofill from PDF <span class="ai-banner-pill">AI</span></div>' +
    '<div class="ai-banner-sub">Save time — let AI extract amendment details from a signed document.</div>' +
    "</div>" +
    /* MODE A — staged PDF picker */
    '<div class="ai-banner-mode-a">' +
    '<select id="aiBanner_pdfPicker" aria-label="Choose an uploaded PDF"></select>' +
    '<button class="ai-banner-run-btn" id="aiBanner_runBtn" type="button">' +
    '<svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><polygon points="13 2 3 14 12 14 11 22 21 10 12 10 13 2"/></svg>' +
    "Run autofill" +
    "</button>" +
    "</div>" +
    /* MODE B — drop zone */
    '<div class="ai-banner-mode-b">' +
    '<label for="aiBanner_fileInput" class="ai-banner-drop">' +
    "Drop a PDF here or <u>click to browse</u>. The file will also be added to your Documents step." +
    "</label>" +
    '<input type="file" id="aiBanner_fileInput" class="ai-banner-input" accept="application/pdf,.pdf" aria-label="Upload PDF for autofill"/>' +
    "</div>" +
    "</div>";

  // Insert as the very first child of the Lease Terms panel
  panel.insertBefore(banner, panel.firstChild);
  banner.dataset.wired = "1";

  // Wire events
  banner.querySelector("#aiBanner_dismissBtn").onclick = _aiBanner_dismiss;
  banner.querySelector("#aiBanner_runBtn").onclick = _aiBanner_runOnSelected;
  var input = banner.querySelector("#aiBanner_fileInput");
  if (input) {
    input.addEventListener("change", function () {
      _aiBanner_handleDroppedFiles(input.files);
      input.value = "";
    });
  }

  // Drag-drop on the entire banner
  banner.addEventListener("dragover", function (e) {
    e.preventDefault();
    e.stopPropagation();
    banner.classList.add("is-dragover");
  });
  banner.addEventListener("dragleave", function (e) {
    if (e.target === banner) banner.classList.remove("is-dragover");
  });
  banner.addEventListener("drop", function (e) {
    e.preventDefault();
    e.stopPropagation();
    banner.classList.remove("is-dragover");
    _aiBanner_handleDroppedFiles(e.dataTransfer && e.dataTransfer.files);
  });

  _aiBanner_updateMode();
}

// Refresh banner mode when step 1's file list changes
(function () {
  if (typeof fu_renderFileList !== "function") return;
  var orig = fu_renderFileList;
  if (orig.__aiBannerWrapped) return;
  fu_renderFileList = function () {
    var r = orig.apply(this, arguments);
    try {
      _aiBanner_updateMode();
    } catch (_) {}
    return r;
  };
  fu_renderFileList.__aiBannerWrapped = true;
})();

// Ensure the banner exists once the wizard's Lease Terms panel is in the DOM
function _aiBanner_init() {
  if (document.getElementById("panel-terms")) {
    _aiBanner_ensure();
  } else {
    setTimeout(_aiBanner_init, 200);
  }
}
if (document.readyState === "loading") {
  document.addEventListener("DOMContentLoaded", function () {
    setTimeout(_aiBanner_init, 100);
  });
} else {
  setTimeout(_aiBanner_init, 100);
}

// ══════════════════════════════════════════════════════════════════════════════
//  UX ENHANCEMENTS — dirty-state, shortcuts panel, skeletons, empty states
//  All purely additive; do NOT touch business logic, save flow, or APIs.
// ══════════════════════════════════════════════════════════════════════════════

// ── 1. Dirty-state tracking + smart close confirm ──────────────────
var _amendDirty = false;
var _amendDirtyIgnored = false; // initial form population fires inputs we don't count

function _amendMarkDirty() {
  if (_amendDirtyIgnored) return;
  if (_amendDirty) return;
  _amendDirty = true;
  var badge = document.getElementById("amendDirtyBadge");
  if (badge) badge.style.display = "inline-flex";
}
function _amendMarkClean() {
  _amendDirty = false;
  var badge = document.getElementById("amendDirtyBadge");
  if (badge) badge.style.display = "none";
}
function _amendIsDirty() {
  return _amendDirty;
}

// Initial-load grace period — first 1.5s after bootstrap, inputs fire but
// they're being populated by loadLeaseDetails / edit-mode loaders, not the user.
(function () {
  _amendDirtyIgnored = true;
  setTimeout(function () {
    _amendDirtyIgnored = false;
  }, 1500);
})();

// Inject the "Unsaved changes" badge into the header on DOM ready
function _amendEnsureDirtyBadge() {
  if (document.getElementById("amendDirtyBadge")) return;
  var header = document.querySelector(".amend-header h1");
  if (!header) return;
  var badge = document.createElement("span");
  badge.id = "amendDirtyBadge";
  badge.setAttribute("role", "status");
  badge.setAttribute("aria-live", "polite");
  badge.style.cssText =
    "display:none;align-items:center;gap:6px;" +
    "margin-left:12px;padding:3px 10px;" +
    "background:#FEF3C7;color:#92400E;" +
    "border:1px solid #FDE68A;border-radius:999px;" +
    "font-size:11px;font-weight:600;letter-spacing:0.2px;";
  badge.innerHTML =
    '<span style="width:6px;height:6px;border-radius:50%;background:#F59E0B;' +
    'box-shadow:0 0 0 3px rgba(245,158,11,0.20);animation:amendPulseDot 1.4s ease-in-out infinite;"></span>' +
    "<span>Unsaved changes</span>";
  header.appendChild(badge);
}

// Listen globally for input/change events that indicate user edits
document.addEventListener(
  "input",
  function (e) {
    var t = e.target;
    if (!t) return;
    // Skip the find-in-PDF and document search inputs
    if (t.id === "pp_findInput" || t.id === "pp_search") return;
    // Only count real form fields
    if (!/^(INPUT|SELECT|TEXTAREA)$/.test(t.tagName)) return;
    _amendMarkDirty();
  },
  true,
);
document.addEventListener(
  "change",
  function (e) {
    var t = e.target;
    if (!t) return;
    if (t.id === "pp_findInput" || t.id === "pp_search") return;
    if (!/^(INPUT|SELECT|TEXTAREA)$/.test(t.tagName)) return;
    _amendMarkDirty();
  },
  true,
);

// Wrap closeAmendmentUI so the existing red confirm dialog only shows when
// there ARE unsaved changes. Clean exit = no confirm friction.
(function () {
  if (typeof closeAmendmentUI !== "function") return;
  var orig = closeAmendmentUI;
  window.closeAmendmentUI = function () {
    if (!_amendIsDirty()) {
      // Nothing to lose — close directly via the existing flow's exit path.
      // We still call orig so any cleanup it does runs; but mark the form
      // clean first so any beforeunload check passes.
      _amendDirtyIgnored = true;
      try {
        orig.apply(this, arguments);
      } finally {
        _amendDirtyIgnored = false;
      }
      return;
    }
    return orig.apply(this, arguments);
  };
})();

// Browser-tab close warning — only when dirty
window.addEventListener("beforeunload", function (e) {
  if (_amendIsDirty()) {
    e.preventDefault();
    e.returnValue = ""; // legacy support
    return "";
  }
});

// Clear dirty state when save completes successfully. We hook the wizard
// finish button — it triggers saveAmendments, which on success replaces the
// UI / closes the dialog. As a safety net, clear when the save loading
// overlay finishes too.
(function () {
  document.addEventListener(
    "click",
    function (e) {
      if (!e.target || !e.target.closest) return;
      var btn = e.target.closest("#btnWizardFinish");
      if (btn) {
        // Mark clean optimistically — if save fails, user will edit again
        // and dirty flag will re-arm naturally.
        setTimeout(_amendMarkClean, 1500);
      }
    },
    true,
  );
})();

// ── 2. Keyboard shortcuts help panel ─────────────────────────────────
function _amendShortcutsOpen() {
  if (document.getElementById("amendShortcutsOverlay")) return;
  var overlay = document.createElement("div");
  overlay.id = "amendShortcutsOverlay";
  overlay.setAttribute("role", "dialog");
  overlay.setAttribute("aria-modal", "true");
  overlay.setAttribute("aria-labelledby", "amendShortcutsTitle");
  overlay.style.cssText =
    "position:fixed;inset:0;z-index:1000001;display:flex;align-items:center;" +
    "justify-content:center;background:rgba(15,23,42,0.5);backdrop-filter:blur(3px);" +
    "font-family:-apple-system,BlinkMacSystemFont,'Segoe UI','Segoe UI Variable',system-ui,Roboto,Helvetica,Arial,sans-serif;";

  var rows = [
    ["?", "Open this shortcuts panel"],
    ["Esc", "Close modals, popups, or this panel"],
    ["Tab / Shift+Tab", "Navigate between fields"],
    ["Enter", "Confirm or activate focused button"],
    ["Ctrl + F", "Find in PDF (when preview is focused)"],
    ["Enter / Shift + Enter", "Next / previous PDF match"],
    ["Arrow ←/→ on resizer", "Adjust PDF pane width"],
    ["Shift + Arrow on resizer", "Adjust width in larger steps"],
    ["Double-click resizer", "Toggle PDF pane minimize"],
  ];

  var listHtml = rows
    .map(function (r) {
      return (
        '<div style="display:grid;grid-template-columns:200px 1fr;gap:14px;' +
        'padding:9px 0;border-bottom:1px solid #F3F4F6;align-items:center;">' +
        '<div style="display:flex;gap:6px;flex-wrap:wrap;">' +
        r[0]
          .split(/\s*[\+\/]\s*/)
          .map(function (k, i, arr) {
            var sep =
              i < arr.length - 1
                ? r[0].indexOf("/") > -1 && r[0].indexOf("+") === -1
                  ? " / "
                  : " + "
                : "";
            return (
              '<kbd style="background:#F3F4F6;border:1px solid #D1D5DB;border-bottom-width:2px;' +
              "border-radius:6px;padding:3px 8px;font-size:12px;font-family:inherit;" +
              'font-weight:600;color:#374151;min-width:24px;text-align:center;">' +
              k +
              "</kbd>" +
              (sep
                ? '<span style="color:#9CA3AF;align-self:center;">' +
                  sep +
                  "</span>"
                : "")
            );
          })
          .join("") +
        "</div>" +
        '<div style="font-size:13px;color:#374151;line-height:1.5;">' +
        r[1] +
        "</div>" +
        "</div>"
      );
    })
    .join("");

  overlay.innerHTML =
    '<div style="background:#fff;border-radius:14px;max-width:560px;width:calc(100% - 48px);' +
    "max-height:calc(100vh - 100px);box-shadow:0 24px 64px rgba(0,0,0,0.35);" +
    "border-top:5px solid #1C6BD4;overflow:hidden;display:flex;flex-direction:column;" +
    'animation:amendPopupRise 220ms cubic-bezier(0.16,1,0.3,1);">' +
    '<div style="display:flex;align-items:center;justify-content:space-between;' +
    'padding:16px 22px;border-bottom:1px solid #E5E7EB;background:#F9FAFB;">' +
    '<div style="display:flex;align-items:center;gap:10px;">' +
    '<div style="width:30px;height:30px;border-radius:50%;background:#DBEAFE;' +
    'display:flex;align-items:center;justify-content:center;">' +
    '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="#1C6BD4" stroke-width="2.5"><rect x="2" y="4" width="20" height="16" rx="2"/><path d="M6 8h.01M10 8h.01M14 8h.01M18 8h.01M8 12h.01M12 12h.01M16 12h.01M7 16h10"/></svg>' +
    "</div>" +
    "<div>" +
    '<div id="amendShortcutsTitle" style="font-size:15px;font-weight:700;color:#111827;">Keyboard Shortcuts</div>' +
    '<div style="font-size:12px;color:#6B7280;margin-top:1px;">Speed up your workflow</div>' +
    "</div>" +
    "</div>" +
    '<button id="amendShortcutsClose" aria-label="Close" style="background:none;border:none;color:#6B7280;' +
    'font-size:20px;line-height:1;cursor:pointer;padding:6px 10px;border-radius:6px;">&#x2715;</button>' +
    "</div>" +
    '<div style="padding:14px 22px;overflow-y:auto;">' +
    listHtml +
    "</div>" +
    '<div style="padding:12px 22px;background:#F9FAFB;border-top:1px solid #E5E7EB;' +
    'font-size:12px;color:#6B7280;text-align:center;">' +
    'Press <kbd style="background:#F3F4F6;border:1px solid #D1D5DB;border-radius:4px;padding:1px 6px;font-size:11px;">Esc</kbd> to close' +
    "</div>" +
    "</div>";

  document.body.appendChild(overlay);
  var cleanup = function () {
    overlay.remove();
  };
  overlay.addEventListener("click", function (e) {
    if (e.target === overlay) cleanup();
  });
  overlay.querySelector("#amendShortcutsClose").onclick = cleanup;
  document.addEventListener("keydown", function esc(e) {
    if (e.key === "Escape" || e.key === "Esc") {
      cleanup();
      document.removeEventListener("keydown", esc);
    }
  });
}

document.addEventListener("keydown", function (e) {
  // "?" key (Shift+/ on most keyboards) opens shortcuts panel
  // Skip if typing in any input/textarea/select or contenteditable
  if (e.key !== "?" && !(e.shiftKey && e.key === "/")) return;
  var t = e.target;
  if (t && (/^(INPUT|TEXTAREA|SELECT)$/.test(t.tagName) || t.isContentEditable))
    return;
  if (document.getElementById("amendShortcutsOverlay")) return;
  e.preventDefault();
  _amendShortcutsOpen();
});

