// Utility — render skeleton rows into a container. Callable by render
// functions during load, BUT only used opt-in (we don't auto-replace existing
// "loading" markup to avoid behavioral changes).
function amendRenderSkeletonRows(containerId, count) {
  var el =
    typeof containerId === "string"
      ? document.getElementById(containerId)
      : containerId;
  if (!el) return;
  var n = count || 3;
  var html = "";
  for (var i = 0; i < n; i++) {
    html +=
      '<div class="amend-skeleton-row">' +
      '<div class="amend-skeleton"></div>' +
      '<div class="amend-skeleton"></div>' +
      '<div class="amend-skeleton"></div>' +
      '<div class="amend-skeleton"></div>' +
      '<div class="amend-skeleton"></div>' +
      "</div>";
  }
  el.innerHTML = html;
}

