// ══════════════════════════════════════════════════════════════════════════════
//  ADD RECURRING CHARGE — HELPER FUNCTIONS (ac_ prefix)
// ══════════════════════════════════════════════════════════════════════════════

function ac_formatDate(date) {
  if (!date || isNaN(date.getTime())) return "";
  const y = date.getFullYear();
  const m = String(date.getMonth() + 1).padStart(2, "0");
  const d = String(date.getDate()).padStart(2, "0");
  return `${y}-${m}-${d}`;
}

function ac_extractDayFromDate(dateStr) {
  if (!dateStr || String(dateStr).trim() === "") return null;
  // Read the day straight from YYYY-MM-DD to avoid the UTC-midnight shift.
  const m = String(dateStr).match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (m) return parseInt(m[3], 10);
  const d = new Date(dateStr);
  if (isNaN(d.getTime())) return null;
  return d.getDate();
}

function ac_computeFrequencyEndDate(
  frequencyStartDate,
  frequencyValue,
  prorationEnabled,
  prorationEnabledFirstCycle,
  firstCycleEndDateFieldValue,
) {
  if (
    (prorationEnabled === true || prorationEnabled === "true") &&
    (prorationEnabledFirstCycle === true ||
      prorationEnabledFirstCycle === "true") &&
    firstCycleEndDateFieldValue &&
    firstCycleEndDateFieldValue.trim() !== ""
  ) {
    return firstCycleEndDateFieldValue;
  }
  if (!frequencyStartDate || String(frequencyStartDate).trim() === "")
    return null;
  // Parse YYYY-MM-DD as a local date (new Date("YYYY-MM-DD") is UTC midnight,
  // which lands on the previous day west of UTC). Mirrors leasecreation.js.
  const _parts = String(frequencyStartDate)
    .split("T")[0]
    .split("-")
    .map(Number);
  const start =
    _parts.length === 3
      ? new Date(_parts[0], _parts[1] - 1, _parts[2])
      : new Date(frequencyStartDate);
  if (isNaN(start.getTime())) return null;
  const freqInt = parseInt(frequencyValue);
  let end = new Date(start);
  // Start of the next cycle, n months on. 31 Jan + 1 month → 1 Mar, so the
  // cycle ends on the last day of Feb (not 2 Mar).
  const _addMonths = (d, n) => {
    const day = d.getDate();
    const r = new Date(d.getFullYear(), d.getMonth() + n, 1);
    const lastDay = new Date(r.getFullYear(), r.getMonth() + 1, 0).getDate();
    if (day > lastDay) r.setMonth(r.getMonth() + 1);
    else r.setDate(day);
    return r;
  };
  if (freqInt === 126330000) {
    end = _addMonths(start, 1);
    end.setDate(end.getDate() - 1);
  } else if (freqInt === 126330004) {
    end.setDate(end.getDate() + 6);
  } else if (freqInt === 126330001) {
    end.setDate(end.getDate() + 364);
  } else if (freqInt === 126330005) {
    end = _addMonths(start, 3);
    end.setDate(end.getDate() - 1);
  } else if (freqInt === 126330003) {
    /* same day */
  } else return null;
  return ac_formatDate(end);
}

function ac_escapeHtml(text) {
  if (!text) return "";
  return String(text)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#039;");
}

function ac_autoPopulateDueDateRule() {
  const select = document.getElementById("ac_dueDateRule");
  if (!select || !amendDueDateRules.length) return;
  const target = "as of the issue of the sales document";
  const match = amendDueDateRules.find(
    (r) =>
      (r.Label?.UserLocalizedLabel?.Label || "").toLowerCase().trim() ===
      target,
  );
  if (match) {
    select.value = match.Value;
  } else if (amendDueDateRules[0]) {
    select.value = amendDueDateRules[0].Value;
  }
  ac_handleDueDateRuleChange();
}

// Fetch and apply the exact Due Date Rule from an existing charge (the rule is
// not part of the loaded charge list, so it needs a lookup by id).
async function ac_applyDueDateRuleFromCharge(chargeId) {
  if (!chargeId || String(chargeId).startsWith("pending")) return;
  try {
    const rec = await XrmCtx.WebApi.retrieveRecord(
      "array_recurringcharge",
      chargeId,
      "?$select=array_duedaterule",
    );
    const ddrEl = document.getElementById("ac_dueDateRule");
    if (ddrEl && rec && rec.array_duedaterule != null) {
      ddrEl.value = String(rec.array_duedaterule);
      if (typeof ac_handleDueDateRuleChange === "function")
        ac_handleDueDateRuleChange();
    }
  } catch (e) {
    console.warn("Due date rule copy failed:", e);
  }
}

// Copy lease-wide common billing fields from an existing charge onto the open
// Add Charge form: Frequency, Pre-Frequency Offset, Proration Enabled, Due In
// Days (all already in memory) and the exact Due Date Rule (fetched). Does NOT
// touch Invoice Generation Date, amount, charge type, unit, or dates.
async function ac_copyCommonFieldsFromCharge(charge) {
  if (!charge) return;

  const freqEl = document.getElementById("ac_frequency");
  if (freqEl && charge.array_frequency != null) {
    freqEl.value = String(charge.array_frequency);
    if (typeof ac_handleFrequencyVisibility === "function")
      ac_handleFrequencyVisibility();
    if (typeof ac_updateInvoiceGenDateMax === "function")
      ac_updateInvoiceGenDateMax();
  }
  const pfEl = document.getElementById("ac_preFrequencyOffset");
  if (pfEl && charge.array_prefrequencyoffset != null)
    pfEl.value = charge.array_prefrequencyoffset ? "true" : "false";
  const proEl = document.getElementById("ac_prorationEnabled");
  if (proEl && charge.array_prorationenabled != null) {
    proEl.value = charge.array_prorationenabled ? "true" : "false";
    if (typeof ac_handleProrationChange === "function")
      ac_handleProrationChange();
  }
  const didEl = document.getElementById("ac_dueInDays");
  if (didEl && charge.array_dueindays != null)
    didEl.value = charge.array_dueindays;

  await ac_applyDueDateRuleFromCharge(charge.array_recurringchargeid);
}

function ac_autoPopulateRateRule() {
  if (!amendRateRules.length) return;
  const target = "of the date of issue";
  const match = amendRateRules.find(
    (r) => r.array_rulename && r.array_rulename.toLowerCase().trim() === target,
  );
  if (match) {
    document.getElementById("ac_rateRule").value =
      match.array_exchangerateselectionrulesid;
    document.getElementById("ac_rateRuleDisplay").value = match.array_rulename;
    const clearBtn = document.getElementById("ac_clearRateRuleBtn");
    if (clearBtn) clearBtn.style.display = "block";
  }
}

function ac_autoPopulateFrequencyStartDate() {
  const startDateField = document.getElementById("ac_startDate");
  const frequencyField = document.getElementById("ac_frequency");
  const fsdField = document.getElementById("ac_frequencyStartDate");
  const prorationEnabled =
    document.getElementById("ac_prorationEnabled").value === "true";
  if (!prorationEnabled || !startDateField.value || !frequencyField.value)
    return;
  const startDate = new Date(startDateField.value);
  const freqInt = parseInt(frequencyField.value);
  const FREQ_DAYS = {
    126330000: 30,
    126330001: 365,
    126330003: 1,
    126330004: 7,
    126330005: 90,
    126330002: 0,
  };
  const freqDays = FREQ_DAYS[freqInt];
  if (freqDays > 0) {
    const fsd = new Date(startDate);
    fsd.setDate(fsd.getDate() + freqDays - 1);
    fsdField.value = ac_formatDate(fsd);
    fsdField.setAttribute("min", ac_formatDate(startDate));
    const maxD = new Date(startDate);
    maxD.setDate(maxD.getDate() + freqDays - 1);
    fsdField.setAttribute("max", ac_formatDate(maxD));
  } else {
    fsdField.value = "";
    fsdField.removeAttribute("min");
    fsdField.removeAttribute("max");
  }
}

async function ac_autoPopulateBankAccountByCurrency(currencyId) {
  if (!currencyId) return;
  try {
    const results = await XrmCtx.WebApi.retrieveMultipleRecords(
      "array_bankaccount",
      `?$select=array_bankaccountid,array_bankaccountnumber,_array_bankaccountname_value&$filter=statecode eq 0 and _array_currency_value eq ${currencyId}&$orderby=createdon asc&$top=1`,
    );
    if (results.entities.length > 0) {
      const acct = results.entities[0];
      document.getElementById("ac_bankAccount").value =
        acct.array_bankaccountid;
      document.getElementById("ac_bankAccountDisplay").value =
        acct.array_bankaccountnumber || "Bank Account";
      const clearBtn = document.getElementById("ac_clearBankAccountBtn");
      if (clearBtn) clearBtn.style.display = "block";
    } else {
      ac_clearBankAccountField();
    }
  } catch (e) {
    console.error("Error auto-populating bank account:", e);
    ac_clearBankAccountField();
  }
}

function ac_handleProrationChange() {
  const prorationEnabled =
    document.getElementById("ac_prorationEnabled")?.value === "true";
  const conditionalFields = document.getElementById(
    "ac_prorationConditionalFields",
  );
  const lastCycleField = document.getElementById(
    "ac_prorationEnabledLastCycle",
  );
  const firstCycleField = document.getElementById(
    "ac_prorationEnabledFirstCycle",
  );
  const freqStartField = document.getElementById("ac_frequencyStartDate");
  const firstCycleEndGroup = document.getElementById(
    "ac_firstCycleFrequencyEndDateGroup",
  );

  if (prorationEnabled) {
    if (conditionalFields) conditionalFields.style.display = "block";

    // Default Last Cycle = false (only if not already user-set)
    if (lastCycleField && !lastCycleField.getAttribute("data-user-input")) {
      lastCycleField.value = "false";
    }
    // Default First Cycle = false (only if not already user-set)
    if (firstCycleField && !firstCycleField.getAttribute("data-user-input")) {
      firstCycleField.value = "false";
    }

    if (freqStartField) freqStartField.setAttribute("required", "required");

    // Auto-populate frequency start date
    ac_autoPopulateFrequencyStartDate();
  } else {
    if (conditionalFields) conditionalFields.style.display = "none";

    if (lastCycleField) {
      lastCycleField.value = "false";
      lastCycleField.removeAttribute("data-user-input");
    }
    if (firstCycleField) {
      firstCycleField.value = "";
      firstCycleField.removeAttribute("data-user-input");
    }
    if (freqStartField) {
      freqStartField.value = "";
      freqStartField.removeAttribute("required");
      freqStartField.removeAttribute("min");
      freqStartField.removeAttribute("max");
      freqStartField.removeAttribute("data-user-input");
    }
    if (firstCycleEndGroup) firstCycleEndGroup.style.display = "none";
  }

  ac_updateInvoiceGenDateMax();
  ac_validateAllDates();
}

// ── Set up all date-related event listeners for the charge modal ──────────────
function ac_setupInvoiceGenAutoCalculation() {
  const fields = {
    startDate: document.getElementById("ac_startDate"),
    endDate: document.getElementById("ac_endDate"),
    frequency: document.getElementById("ac_frequency"),
    invGenDate: document.getElementById("ac_invoiceGenerationDate"),
    preFreqOffset: document.getElementById("ac_preFrequencyOffset"),
    prorationEn: document.getElementById("ac_prorationEnabled"),
    freqStartDate: document.getElementById("ac_frequencyStartDate"),
    firstCycle: document.getElementById("ac_prorationEnabledFirstCycle"),
  };

  Object.entries(fields).forEach(([key, el]) => {
    if (!el) return;
    const clone = el.cloneNode(true);
    el.parentNode.replaceChild(clone, el);
    fields[key] = clone;
  });

  if (fields.startDate) {
    fields.startDate.addEventListener("change", function () {
      this.setAttribute("data-user-modified", "true");
      if (fields.prorationEn && fields.prorationEn.value === "true") {
        ac_autoPopulateFrequencyStartDate();
      }
      ac_updateInvoiceGenDateMax();
      ac_validateAllDates();
    });
  }

  if (fields.endDate) {
    fields.endDate.addEventListener("input", function () {
      this.setAttribute("data-user-modified", "true");
    });
    fields.endDate.addEventListener("change", function () {
      this.setAttribute("data-user-modified", "true");
      ac_validateAllDates();
    });
  }

  if (fields.frequency) {
    fields.frequency.addEventListener("change", function () {
      if (fields.prorationEn && fields.prorationEn.value === "true") {
        ac_autoPopulateFrequencyStartDate();
      }
      ac_handleFrequencyVisibility();
      ac_updateInvoiceGenDateMax();
      ac_validateAllDates();
    });
  }

  if (fields.invGenDate) {
    fields.invGenDate.addEventListener("change", function () {
      this.setAttribute("data-user-modified", "true");
      ac_validateAllDates();
    });
    fields.invGenDate.addEventListener("input", function () {
      this.setAttribute("data-user-modified", "true");
    });
  }

  if (fields.preFreqOffset) {
    fields.preFreqOffset.addEventListener("change", function () {
      ac_handlePreFrequencyOffsetChange();
      ac_updateInvoiceGenDateMax();
      ac_validateAllDates();
    });
  }

  if (fields.prorationEn) {
    fields.prorationEn.addEventListener("change", function () {
      ac_handleProrationChange();
    });
  }

  if (fields.freqStartDate) {
    fields.freqStartDate.addEventListener("change", function () {
      this.setAttribute("data-user-modified", "true");
      ac_validateAllDates();
    });
  }

  if (fields.firstCycle) {
    fields.firstCycle.addEventListener("change", function () {
      this.setAttribute("data-user-input", "true");
      ac_handleFirstCycleProrationChange();
    });
  }
}

function ac_validateAllDates() {
  validateAllDates();
}

function ac_handleFirstCycleProrationChange() {
  const firstCycleEnabled =
    document.getElementById("ac_prorationEnabledFirstCycle").value === "true";
  const endDateGroup = document.getElementById(
    "ac_firstCycleFrequencyEndDateGroup",
  );
  const fsdField = document.getElementById("ac_frequencyStartDate");
  if (firstCycleEnabled) {
    endDateGroup.style.display = "block";
    ac_autoPopulateFrequencyStartDate();
  } else {
    endDateGroup.style.display = "none";
    fsdField.value = "";
    fsdField.removeAttribute("data-user-input");
    fsdField.removeAttribute("min");
    fsdField.removeAttribute("max");
  }
}

function ac_handlePreFrequencyOffsetChange() {
  // (keep any existing body here, then add:)
  ac_updateInvoiceGenDateMax();
  ac_validateAllDates();
}

function ac_handleFrequencyVisibility() {
  const frequencySelect = document.getElementById("ac_frequency");
  const selectedOption = frequencySelect.options[frequencySelect.selectedIndex];
  const freqText = selectedOption
    ? selectedOption.textContent.toLowerCase()
    : "";
  const freqVal = selectedOption ? parseInt(selectedOption.value) : null;

  const prorationGroup = document
    .getElementById("ac_prorationEnabled")
    ?.closest(".amend-form-group");
  const preFreqOffsetGroup = document
    .getElementById("ac_preFrequencyOffset")
    ?.closest(".amend-form-group");

  const isDaily = freqVal === 126330003 || freqText.includes("daily");
  const isOneTime = freqVal === 126330002 || freqText.includes("one time");

  if (isDaily) {
    if (prorationGroup) {
      prorationGroup.style.display = "none";
      document.getElementById("ac_prorationEnabled").value = "false";
    }
    const cf = document.getElementById("ac_prorationConditionalFields");
    if (cf) cf.style.display = "none";
  } else if (isOneTime) {
    if (prorationGroup) {
      prorationGroup.style.display = "none";
      document.getElementById("ac_prorationEnabled").value = "false";
    }
    if (preFreqOffsetGroup) {
      preFreqOffsetGroup.style.display = "none";
      document.getElementById("ac_preFrequencyOffset").value = "false";
    }
    const cf = document.getElementById("ac_prorationConditionalFields");
    if (cf) cf.style.display = "none";
  } else {
    if (prorationGroup) prorationGroup.style.display = "";
    if (preFreqOffsetGroup) preFreqOffsetGroup.style.display = "";
  }

  if (document.getElementById("ac_prorationEnabled")?.value === "true") {
    ac_autoPopulateFrequencyStartDate();
  }

  ac_updateInvoiceGenDateMax();
  ac_validateAllDates(); //  validate after visibility change
}

// ── Auto-populate Invoice Type from property+chargeType config ──
function ac_autoPopulateInvoiceType() {
  const chargeTypeId = document.getElementById("ac_chargeType").value;
  const unitId = document.getElementById("ac_unit").value;
  const invTypeSelect = document.getElementById("ac_invoiceType");
  const prefixDisplay = document.getElementById("ac_invoicePrefixDisplay");
  const prefixHidden = document.getElementById("ac_invoicePrefix");

  // Derive the property from the selected unit (via amendExistingUnits / amendNewUnits),
  // or fall back to the property on the lease itself.
  let propertyId = null;
  if (unitId) {
    const allAssocs = [...(amendExistingUnits || []), ...(amendNewUnits || [])];
    const assoc = allAssocs.find(
      (a) => a.array_Unit && a.array_Unit.array_unitid === unitId,
    );
    if (assoc) {
      propertyId =
        assoc._array_property_value ||
        assoc["_array_property_value"] ||
        (assoc.array_Unit &&
          (assoc.array_Unit._array_property_value ||
            assoc.array_Unit["_array_building_value"])) ||
        null;
    }
  }
  // Always fall back to the lease-level property if no unit-level property found
  if (!propertyId) {
    propertyId = amendLeaseData._array_property_value || null;
  }

  if (!chargeTypeId) {
    // Reset invoice type + prefix when charge type is cleared
    invTypeSelect.value = "";
    invTypeSelect.disabled = true;
    invTypeSelect.style.background = "#F1F2F4";
    invTypeSelect.style.cursor = "not-allowed";
    invTypeSelect.style.opacity = "0.6";
    prefixDisplay.value = "";
    prefixHidden.value = "";
    return;
  }

  if (
    !amendPropertyInvoiceTypeConfigs ||
    !amendPropertyInvoiceTypeConfigs.length
  ) {
    console.warn(
      "ac_autoPopulateInvoiceType: no property invoice type configs loaded",
    );
    return;
  }

  // Match by property + charge type
  let match = null;
  if (propertyId) {
    match = amendPropertyInvoiceTypeConfigs.find(
      (cfg) =>
        cfg._array_property_value === propertyId &&
        cfg._array_chargetype_value === chargeTypeId,
    );
  }
  // If no property-specific match, try charge type only (no property filter)
  if (!match) {
    match = amendPropertyInvoiceTypeConfigs.find(
      (cfg) => cfg._array_chargetype_value === chargeTypeId,
    );
  }

  if (!match || !match._array_invoicetype_value) {
    // No config found — unlock but leave empty so user can pick manually
    invTypeSelect.value = "";
    invTypeSelect.disabled = false;
    invTypeSelect.style.background = "";
    invTypeSelect.style.cursor = "";
    invTypeSelect.style.opacity = "1";
    prefixDisplay.value = "";
    prefixHidden.value = "";
    return;
  }

  const invoiceTypeId = match._array_invoicetype_value;

  // Set the invoice type dropdown value and unlock it (read-only auto-fill style)
  invTypeSelect.value = invoiceTypeId;
  invTypeSelect.disabled = false;
  invTypeSelect.style.background = "#EDF7EE"; // subtle green tint = auto-filled
  invTypeSelect.style.cursor = "";
  invTypeSelect.style.opacity = "1";

  // Now derive the invoice prefix from amendInvoiceTypes
  const invoiceTypeRec = amendInvoiceTypes.find(
    (t) => t.array_invoicetypeid === invoiceTypeId,
  );
  if (invoiceTypeRec && invoiceTypeRec._array_invoiceprefix_value) {
    prefixHidden.value = invoiceTypeRec._array_invoiceprefix_value;
    prefixDisplay.value =
      invoiceTypeRec[
        "_array_invoiceprefix_value@OData.Community.Display.V1.FormattedValue"
      ] ||
      invoiceTypeRec._array_invoiceprefix_value ||
      "Invoice Prefix";
  } else {
    prefixDisplay.value = "";
    prefixHidden.value = "";
  }
}

function ac_handleInvoiceTypeChange() {
  const sel = document.getElementById("ac_invoiceType");
  const prefixDisplay = document.getElementById("ac_invoicePrefixDisplay");
  const prefixHidden = document.getElementById("ac_invoicePrefix");
  const selectedId = sel.value;

  // Remove auto-fill tint when user manually changes
  sel.style.background = "";

  if (!selectedId || !amendInvoiceTypes) {
    prefixDisplay.value = "";
    prefixHidden.value = "";
    return;
  }
  const selectedType = amendInvoiceTypes.find(
    (t) => t.array_invoicetypeid === selectedId,
  );
  if (selectedType && selectedType._array_invoiceprefix_value) {
    prefixHidden.value = selectedType._array_invoiceprefix_value;
    prefixDisplay.value =
      selectedType[
        "_array_invoiceprefix_value@OData.Community.Display.V1.FormattedValue"
      ] || "Invoice Prefix";
  } else {
    prefixDisplay.value = "";
    prefixHidden.value = "";
  }
}

async function ac_handleCurrencyChange() {
  const currencyId = document.getElementById("ac_currency").value;
  const invCurrGroup = document.getElementById("ac_useAsInvoiceCurrencyGroup");
  const invCurrSel = document.getElementById("ac_useAsInvoiceCurrency");
  if (!currencyId) {
    ac_lockBankAccountField();
    ac_clearBankAccountField();
    if (invCurrGroup) {
      invCurrGroup.style.display = "none";
      if (invCurrSel) invCurrSel.value = "false";
    }
    return;
  }
  const currObj = amendCurrencies.find(
    (c) => c.transactioncurrencyid === currencyId,
  );
  const isPLN =
    currObj && (currObj.isocurrencycode || "").toUpperCase() === "PLN";
  if (invCurrGroup) {
    invCurrGroup.style.display = isPLN ? "none" : "";
    if (isPLN && invCurrSel) invCurrSel.value = "false";
  }
  ac_unlockBankAccountField();
  await ac_autoPopulateBankAccountByCurrency(currencyId);
}

function ac_handleDueDateRuleChange() {
  const select = document.getElementById("ac_dueDateRule");
  if (!select) return;
  const dueInDaysInput = document.getElementById("ac_dueInDays");
  if (dueInDaysInput && select) {
    const label = dueInDaysInput
      .closest(".amend-form-group")
      ?.querySelector("label");
    if (label) {
      const selectedText = (
        select.options[select.selectedIndex]?.text || ""
      ).toLowerCase();
      label.textContent = selectedText.includes(
        "on a specific day of the month",
      )
        ? "Specific Day"
        : "Due In (Days)";
    }
  }
}

function ac_lockBankAccountField() {
  const f = document.getElementById("ac_bankAccountDisplay");
  if (f) {
    f.disabled = true;
    f.style.cursor = "not-allowed";
    f.style.opacity = "0.6";
    f.style.backgroundColor = "#F1F2F4";
    f.placeholder = "Select currency first";
  }
}

function ac_unlockBankAccountField() {
  const f = document.getElementById("ac_bankAccountDisplay");
  if (f) {
    f.disabled = false;
    f.style.cursor = "pointer";
    f.style.opacity = "1";
    f.style.backgroundColor = "";
    f.style.pointerEvents = "auto";
    f.placeholder = "Search bank account...";
  }
}

function ac_clearBankAccountField() {
  document.getElementById("ac_bankAccount").value = "";
  document.getElementById("ac_bankAccountDisplay").value = "";
  const clearBtn = document.getElementById("ac_clearBankAccountBtn");
  if (clearBtn) clearBtn.style.display = "none";
}

function ac_openBankAccountLookup() {
  const currencyId = document.getElementById("ac_currency").value;
  if (!currencyId) {
    showFieldError("ac_currency", "Please select a currency first.");
    return;
  }
  const modal = document.getElementById("ac_bankAccountLookupModal");
  modal.classList.add("active");
  document.body.style.overflow = "hidden";
  const searchBox = document.getElementById("ac_bankAccountSearchBox");
  searchBox.value = "";
  const currentValue = document.getElementById("ac_bankAccount").value;
  const deselectBtn = document.getElementById("ac_btnDeselectBankAccount");
  if (deselectBtn)
    deselectBtn.style.display = currentValue ? "inline-flex" : "none";
  setTimeout(() => searchBox.focus(), 100);
  ac_loadBankAccountsByCurrency(currencyId);
}

function ac_searchBankAccounts() {
  const searchTerm = document.getElementById("ac_bankAccountSearchBox").value;
  const currencyId = document.getElementById("ac_currency").value;
  if (!currencyId) {
    closeModal("ac_bankAccountLookupModal");
    showFieldError("ac_currency", "Please select a currency first.");
    return;
  }
  ac_loadBankAccountsByCurrency(currencyId, searchTerm);
}

function ac_loadBankAccountsByCurrency(currencyId, searchTerm = "") {
  const container = document.getElementById("ac_bankAccountSearchResults");
  container.innerHTML = `<div style="text-align:center;padding:20px;color:#667eea;">Loading bank accounts...</div>`;
  let filter = `statecode eq 0 and _array_currency_value eq ${currencyId}`;
  if (searchTerm.trim())
    filter += ` and contains(array_bankaccountnumber,'${searchTerm.trim().replace(/'/g, "''")}')`;
  XrmCtx.WebApi.retrieveMultipleRecords(
    "array_bankaccount",
    `?$select=array_bankaccountid,array_bankaccountnumber,_array_bankaccountname_value&$filter=${filter}&$top=50&$orderby=array_bankaccountnumber asc`,
  ).then(
    function (results) {
      if (!results.entities.length) {
        container.innerHTML = `<div style="text-align:center;padding:40px;color:#718096;">No bank accounts found for this currency.</div>`;
        return;
      }
      let html = `<div style="padding:12px 16px;background:#f0f9ff;border-left:4px solid #1C6BD4;margin-bottom:16px;border-radius:6px;"><p style="font-size:13px;color:#0D4A9E;margin:0;font-weight:600;">🏦 ${results.entities.length} account${results.entities.length !== 1 ? "s" : ""} found</p></div><div>`;
      results.entities.forEach((acct, i) => {
        const num = ac_escapeHtml(acct.array_bankaccountnumber || "N/A");
        const bank =
          acct[
            "_array_bankaccountname_value@OData.Community.Display.V1.FormattedValue"
          ] || "Unknown Bank";
        html += `<div onclick="ac_selectBankAccount('${acct.array_bankaccountid}','${num.replace(/'/g, "\\'")}')" style="cursor:pointer;padding:16px;margin-bottom:8px;border-radius:8px;border-left:3px solid transparent;background:${i % 2 === 0 ? "#F8F9FC" : "white"};" onmouseover="this.style.background='#f0f9ff';this.style.borderLeftColor='#1C6BD4';" onmouseout="this.style.background='${i % 2 === 0 ? "#F8F9FC" : "white"}';this.style.borderLeftColor='transparent';">
                <div style="font-weight:700;color:#0f172a;">${num}</div>
                <div style="font-size:13px;color:#5A6070;">${ac_escapeHtml(bank)}</div>
            </div>`;
      });
      html += "</div>";
      container.innerHTML = html;
    },
    function (err) {
      container.innerHTML = `<div style="text-align:center;padding:40px;color:#B91C1C;">Error loading bank accounts: ${ac_escapeHtml(err.message || "")}</div>`;
    },
  );
}

function ac_selectBankAccount(id, accountNumber) {
  document.getElementById("ac_bankAccount").value = id;
  document.getElementById("ac_bankAccountDisplay").value = accountNumber;
  const clearBtn = document.getElementById("ac_clearBankAccountBtn");
  if (clearBtn) clearBtn.style.display = "block";
  closeModal("ac_bankAccountLookupModal");
  showAmendNotification("✅ Bank account selected.", "success");
}

function ac_deselectBankAccount() {
  ac_clearBankAccountField();
  closeModal("ac_bankAccountLookupModal");
}

function ac_clearRateRuleField() {
  document.getElementById("ac_rateRule").value = "";
  document.getElementById("ac_rateRuleDisplay").value = "";
  const clearBtn = document.getElementById("ac_clearRateRuleBtn");
  if (clearBtn) clearBtn.style.display = "none";
  ac_toggleExchangeRateDayField("");
}

function ac_openRateRuleLookup() {
  const modal = document.getElementById("ac_rateRuleLookupModal");
  modal.classList.add("active");
  document.body.style.overflow = "hidden";
  const searchBox = document.getElementById("ac_rateRuleSearchBox");
  searchBox.value = "";
  const currentValue = document.getElementById("ac_rateRule").value;
  const deselectBtn = document.getElementById("ac_btnDeselectRateRule");
  if (deselectBtn)
    deselectBtn.style.display = currentValue ? "inline-flex" : "none";
  setTimeout(() => searchBox.focus(), 100);
  ac_loadRateRules();
}

function ac_searchRateRules() {
  ac_loadRateRules(document.getElementById("ac_rateRuleSearchBox").value);
}

function ac_loadRateRules(searchTerm = "") {
  const container = document.getElementById("ac_rateRuleSearchResults");
  if (!container) return;
  container.innerHTML = `<div style="text-align:center;padding:20px;color:#667eea;">Loading rate rules...</div>`;
  let rules = amendRateRules;
  if (searchTerm.trim()) {
    const s = searchTerm.trim().toLowerCase();
    rules = rules.filter((r) =>
      (r.array_rulename || "").toLowerCase().includes(s),
    );
  }
  if (!rules.length) {
    container.innerHTML = `<div style="text-align:center;padding:40px;color:#718096;">No rate rules found.</div>`;
    return;
  }
  let html = `<div style="padding:12px 16px;background:#f0f9ff;border-left:4px solid #1C6BD4;margin-bottom:16px;border-radius:6px;"><p style="font-size:13px;color:#0D4A9E;margin:0;font-weight:600;">📋 ${rules.length} rule${rules.length !== 1 ? "s" : ""} found</p></div><div>`;
  rules.forEach((rule, i) => {
    const name = ac_escapeHtml(rule.array_rulename || "Unnamed Rule");
    const desc = ac_escapeHtml(rule.array_ruledescription || "");
    html += `<div onclick="ac_selectRateRule('${rule.array_exchangerateselectionrulesid}','${name.replace(/'/g, "\\'")}')" style="cursor:pointer;padding:16px;margin-bottom:8px;border-radius:8px;border-left:3px solid transparent;background:${i % 2 === 0 ? "#F8F9FC" : "white"};" onmouseover="this.style.background='#f0f9ff';this.style.borderLeftColor='#1C6BD4';" onmouseout="this.style.background='${i % 2 === 0 ? "#F8F9FC" : "white"}';this.style.borderLeftColor='transparent';">
            <div style="font-weight:700;color:#0f172a;">${name}</div>
            ${desc ? `<div style="font-size:13px;color:#5A6070;">${desc}</div>` : ""}
        </div>`;
  });
  html += "</div>";
  container.innerHTML = html;
}

function ac_selectRateRule(id, name) {
  document.getElementById("ac_rateRule").value = id;
  document.getElementById("ac_rateRuleDisplay").value = name;
  const clearBtn = document.getElementById("ac_clearRateRuleBtn");
  if (clearBtn) clearBtn.style.display = "block";
  ac_toggleExchangeRateDayField(name);
  closeModal("ac_rateRuleLookupModal");
  showAmendNotification("✅ Rate rule selected.", "success");
}

function ac_deselectRateRule() {
  ac_clearRateRuleField();
  closeModal("ac_rateRuleLookupModal");
}

function ac_toggleExchangeRateDayField(ruleName) {
  const group = document.getElementById("ac_exchangeRateDayGroup");
  const input = document.getElementById("ac_exchangeRateDay");
  if (!group || !input) return;
  const lower = (ruleName || "").toLowerCase();
  const show =
    lower.includes("on a specific day of the month (or earlier)") ||
    lower.includes("on a specific day of the month (or later)");
  group.style.display = show ? "" : "none";
  if (show) input.setAttribute("required", "required");
  else {
    input.removeAttribute("required");
    input.value = "";
  }
}

function ac_computeInvoiceGenMaxDate(startDateVal, freqVal) {
  if (!startDateVal || !freqVal) return null;
  const startDate = new Date(startDateVal);
  if (isNaN(startDate.getTime())) return null;

  const freqOpt = amendFrequencies.find(
    (f) => String(f.Value) === String(freqVal),
  );
  const freqLabel = freqOpt
    ? (
        freqOpt.Label?.UserLocalizedLabel?.Label ||
        freqOpt.Label?.LocalizedLabels?.[0]?.Label ||
        ""
      ).toLowerCase()
    : "";

  const maxDate = new Date(startDate);

  if (freqLabel.includes("daily")) maxDate.setDate(maxDate.getDate() + 2);
  else if (freqLabel.includes("weekly"))
    maxDate.setDate(maxDate.getDate() + 14);
  else if (freqLabel.includes("monthly"))
    maxDate.setMonth(maxDate.getMonth() + 2);
  else if (freqLabel.includes("quarterly"))
    maxDate.setMonth(maxDate.getMonth() + 6);
  else if (freqLabel.includes("annual") || freqLabel.includes("yearly"))
    maxDate.setFullYear(maxDate.getFullYear() + 2);
  else maxDate.setMonth(maxDate.getMonth() + 2);

  return (
    maxDate.getFullYear() +
    "-" +
    String(maxDate.getMonth() + 1).padStart(2, "0") +
    "-" +
    String(maxDate.getDate()).padStart(2, "0")
  );
}

function ac_updateInvoiceGenDateMax() {
  const startDateVal = document.getElementById("ac_startDate")?.value;
  const freqVal = document.getElementById("ac_frequency")?.value;
  const invGenInput = document.getElementById("ac_invoiceGenerationDate");
  if (!invGenInput) return;

  const maxStr = ac_computeInvoiceGenMaxDate(startDateVal, freqVal);

  if (!maxStr) {
    invGenInput.removeAttribute("max");
    invGenInput.style.borderColor = "";
    return;
  }

  invGenInput.setAttribute("max", maxStr);

  // If current value exceeds new max, clear it and notify
  if (invGenInput.value && invGenInput.value > maxStr) {
    invGenInput.value = "";
    invGenInput.style.borderColor = "#B91C1C";
    const freqLabel = ac_getFrequencyLabel(freqVal);
    showAmendNotification(
      `⚠️ Invoice Generation Date reset — must be within 2 ${freqLabel} periods of the Start Date (max: ${formatDateAmend(maxStr)}).`,
      "warning",
    );
  } else {
    invGenInput.style.borderColor = "";
  }
}

function ac_updateInvoiceDatePreview() {
  const startDate = document.getElementById("ac_startDate").value;
  const endDate = document.getElementById("ac_endDate").value;
  if (startDate && endDate) {
    if (new Date(endDate) <= new Date(startDate)) {
      document.getElementById("ac_endDate").style.borderColor = "#B91C1C";
    } else {
      document.getElementById("ac_endDate").style.borderColor = "";
    }
  }
  ac_updateInvoiceGenDateMax();
}

// ============================================================
//  LEASE AMENDMENT — UNIFIED CLAUSE MODAL
//  Supports: Step Rent Indexation | Value Protection (CPI) | Turnover Rent
//  One modal, clause-type selector drives field section visibility.
//  All show/hide logic, validation & save logic ported from Lease Draft.
// ============================================================

// ── Clause state ──────────────────────────────────────────────
let amendClauseChoiceMappings = {};
let amendCpiTypesLookup = {};
let amendClauseChargeTypes = { stepIncrease: {}, cpi: {} };
let amendNewClauses = [];
let amendDeactivatedClauses = [];
let cl_editingIdx = null;
let cl_clauseLookupsReady = false;
let pendingDeactivateClauseId = null;

// CPI Rent Frequency / CPI Reference Month option values (same as Lease Creation)
const CL_CPI_FREQ = {
  MONTHLY: 126330000,
  QUARTERLY: 126330001,
  HALF_YEARLY: 126330002,
  YEARLY: 126330003,
};
const CL_CPI_REF = { START: 1, LAST: 2, CUSTOM: 3, LATEST: 4 };

// ── Bootstrap: load clause lookups once ───────────────────────
async function cl_loadClauseLookups() {
  if (cl_clauseLookupsReady) return;
  const clientUrl = XrmCtx.Utility.getGlobalContext().getClientUrl();
  const headers = {
    "OData-MaxVersion": "4.0",
    "OData-Version": "4.0",
    Accept: "application/json",
    "Content-Type": "application/json; charset=utf-8",
  };

  const fieldsToLoad = [
    "array_increasetype",
    "array_steprentfrequency",
    "array_settlementcycle",
    "array_reportingcycle",
    "array_cpirentfrequency",
    "array_turnoverrentbasis",
    "array_turnoverrentcalculationtype",
    "array_increasetypeturnoverrent",
    // CPI reference-month fields (global choices)
    "array_cpireferencemonth",
    "array_cpicustommonth",
  ];
  for (const field of fieldsToLoad) {
    try {
      const url = `${clientUrl}/api/data/v9.2/EntityDefinitions(LogicalName='array_leaseclause')/Attributes(LogicalName='${field}')/Microsoft.Dynamics.CRM.PicklistAttributeMetadata?$select=LogicalName&$expand=OptionSet($select=Options)`;
      const resp = await fetch(url, { headers, credentials: "same-origin" });
      if (!resp.ok) continue;
      const data = await resp.json();
      if (data?.OptionSet?.Options) {
        const map = {};
        data.OptionSet.Options.forEach((o) => {
          const label =
            o.Label?.UserLocalizedLabel?.Label ||
            o.Label?.LocalizedLabels?.[0]?.Label;
          if (label && o.Value !== null) map[label] = o.Value;
        });
        amendClauseChoiceMappings[field] = map;
      }
    } catch (e) {
      console.warn(`cl_loadClauseLookups: failed ${field}`, e);
    }
  }
  if (amendClauseChoiceMappings["array_increasetype"])
    amendClauseChoiceMappings["array_increasetypecpirentprocess"] =
      amendClauseChoiceMappings["array_increasetype"];

  // Fall back to the known global-choice values if metadata could not be read,
  // so the CPI Reference Month / Custom Month dropdowns stay usable.
  if (!amendClauseChoiceMappings["array_cpireferencemonth"]) {
    amendClauseChoiceMappings["array_cpireferencemonth"] = {
      "Start Month": 1,
      "Last Month": 2,
      "Custom Month": 3,
      "Latest Published Index Value": 4,
    };
  }
  if (!amendClauseChoiceMappings["array_cpicustommonth"]) {
    amendClauseChoiceMappings["array_cpicustommonth"] = {
      January: 1,
      February: 2,
      March: 3,
      April: 4,
      May: 5,
      June: 6,
      July: 7,
      August: 8,
      September: 9,
      October: 10,
      November: 11,
      December: 12,
    };
  }

  try {
    const res = await XrmCtx.WebApi.retrieveMultipleRecords(
      "array_cpitype",
      "?$select=array_cpitypeid,array_name&$filter=statecode eq 0&$orderby=array_name asc",
    );
    amendCpiTypesLookup = {};
    (res.entities || []).forEach((e) => {
      amendCpiTypesLookup[e.array_name] = e.array_cpitypeid;
    });
  } catch (e) {
    console.warn("cl_loadClauseLookups: CPI types failed", e);
  }

  amendClauseChargeTypes = { stepIncrease: {}, cpi: {} };
  amendChargeTypes.forEach((ct) => {
    amendClauseChargeTypes.stepIncrease[ct.array_name] = ct.array_chargetypeid;
    amendClauseChargeTypes.cpi[ct.array_name] = ct.array_chargetypeid;
  });
  if (!Object.keys(amendClauseChargeTypes.stepIncrease).length) {
    try {
      const res = await XrmCtx.WebApi.retrieveMultipleRecords(
        "array_chargetype",
        "?$select=array_chargetypeid,array_name&$filter=statecode eq 0&$orderby=array_name asc",
      );
      (res.entities || []).forEach((e) => {
        amendClauseChargeTypes.stepIncrease[e.array_name] =
          e.array_chargetypeid;
        amendClauseChargeTypes.cpi[e.array_name] = e.array_chargetypeid;
      });
    } catch (e) {
      console.warn("cl_loadClauseLookups: charge types fallback failed", e);
    }
  }

  cl_clauseLookupsReady = true;
}

// ── Option generators (mirrors Lease Draft helpers) ───────────
function cl_choiceOptions(fieldName, emptyLabel = "Select...") {
  const choices = amendClauseChoiceMappings[fieldName];
  if (!choices) return `<option value="">⚠ Options not loaded</option>`;
  return (
    `<option value="">${emptyLabel}</option>` +
    Object.entries(choices)
      .map(
        ([label, value]) => `<option value="${value}">${esc(label)}</option>`,
      )
      .join("")
  );
}

function cl_chargeTypeOptions(type = "stepIncrease") {
  const ct = amendClauseChargeTypes[type] || {};
  if (!Object.keys(ct).length)
    return `<option value="">No charge types available</option>`;
  return (
    `<option value="">Select charge type</option>` +
    Object.entries(ct)
      .map(([name, id]) => `<option value="${id}">${esc(name)}</option>`)
      .join("")
  );
}
function cl_cpiTypeOptions() {
  if (!Object.keys(amendCpiTypesLookup).length)
    return `<option value="">⚠ CPI Types not loaded</option>`;
  return (
    `<option value="">Select type</option>` +
    Object.entries(amendCpiTypesLookup)
      .map(([name, id]) => `<option value="${id}">${esc(name)}</option>`)
      .join("")
  );
}
function cl_vatOptions() {
  if (!amendVATs.length) return `<option value="">No VAT records</option>`;
  return (
    `<option value="">Select VAT</option>` +
    amendVATs
      .map(
        (v) => `<option value="${v.array_vatid}">${esc(v.array_name)}</option>`,
      )
      .join("")
  );
}
function cl_currencyOptions() {
  if (!amendCurrencies.length) return `<option value="">No currencies</option>`;
  return (
    `<option value="">Select currency</option>` +
    amendCurrencies
      .map(
        (c) =>
          `<option value="${c.transactioncurrencyid}">${esc(c.isocurrencycode)} — ${esc(c.currencyname)}</option>`,
      )
      .join("")
  );
}

// ── Unit options helper (for instance dropdowns) ──────────────
function cl_unitOptions() {
  let opts = `<option value="">All Units</option>`;
  amendUnits.forEach((a) => {
    if (a.array_Unit) {
      opts += `<option value="${esc(a.array_Unit.array_unitid)}">${esc(a.array_Unit.array_unitname)}</option>`;
    }
  });
  return opts;
}

// ── Open modal in ADD mode ────────────────────────────────────
async function openAddClauseModal() {
  cl_editingIdx = null;
  document.getElementById("clauseModalTitle").textContent =
    "Add Financial Clause";
  document.getElementById("cl_saveBtnText").textContent = "Add Clause";

  document.getElementById("cl_clauseType").value = "";
  cl_showTypeSection("");

  _cl_applyModalStyling();

  if (!cl_clauseLookupsReady) {
    showAmendNotification("Loading clause configuration...", "info");
    await cl_loadClauseLookups();
  }
  openModal("modalAddClause");
}

// ── Apply professional modal styling (matching Add Charge / Add Deposit) ──
function _cl_applyModalStyling() {
  const modal = document.getElementById("modalAddClause");
  if (!modal) return;

  const modalBody = modal.querySelector(".amend-modal-body");
  if (!modalBody) return;

  modalBody.style.cssText =
    "flex:1;overflow-y:auto;min-height:0;padding:24px 28px;";

  modal.querySelectorAll(".amend-form-group label").forEach((lbl) => {
    lbl.style.fontSize = "12px";
    lbl.style.fontWeight = "600";
    lbl.style.color = "#374151";
    lbl.style.marginBottom = "5px";
  });

  modal
    .querySelectorAll(
      ".amend-form-group input:not([type=hidden])," +
        ".amend-form-group select," +
        ".amend-form-group textarea",
    )
    .forEach((el) => {
      el.style.borderRadius = "8px";
      el.style.border = "1.5px solid #CBD5E1";
      el.style.padding = "9px 12px";
      el.style.fontSize = "13px";
      el.style.boxSizing = "border-box";
      el.style.transition = "border-color 0.15s";
    });
}

