// Keep this as no-op since cl_buildBalanceSection now handles it inline
function cl_populateUnitSelect() {
  // Unit selects are now built dynamically in cl_buildBalanceSection
  // using getAllLeaseUnits() — nothing to do here.
}

// ── Clause type change: show/hide sections ────────────────────
function cl_onClauseTypeChange(type) {
  cl_showTypeSection(type);
}

function cl_showTypeSection(type) {
  document.getElementById("cl_typePlaceholder").style.display = type
    ? "none"
    : "block";
  document.getElementById("cl_stepRentSection").style.display =
    type === "Step Rent Indexation" ? "block" : "none";
  document.getElementById("cl_cpiSection").style.display =
    type === "Value Protection (CPI)" ? "block" : "none";
  document.getElementById("cl_turnoverSection").style.display =
    type === "Turnover Rent" ? "block" : "none";

  if (
    type === "Step Rent Indexation" &&
    !document.getElementById("cl_stepRentInstances").children.length
  )
    cl_addInstance("stepRent");
  if (
    type === "Value Protection (CPI)" &&
    !document.getElementById("cl_cpiInstances").children.length
  )
    cl_addInstance("cpi");
  if (
    type === "Turnover Rent" &&
    !document.getElementById("cl_turnoverInstances").children.length
  )
    cl_addInstance("turnover");
}

