function cl_srCalcEndDate(block) {
  const tog = block.querySelector(".cl-sr-customToggle");
  if (!tog?.checked) return;
  const start = block.querySelector(".cl-sr-cycleStart")?.value;
  const freq = block.querySelector(".cl-sr-frequency");
  const end = block.querySelector(".cl-sr-cycleEnd");
  if (!start || !freq || !end) return;
  const txt = freq.options[freq.selectedIndex]?.text.toLowerCase() || "";
  const add = txt.includes("month")
    ? 1
    : txt.includes("quarter")
      ? 3
      : txt.includes("half")
        ? 6
        : txt.includes("year")
          ? 12
          : 0;
  if (!add) return;
  const d = new Date(start);
  d.setMonth(d.getMonth() + add);
  d.setDate(d.getDate() - 1);
  end.value = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;
}

