// Validate + compute the CPI 2nd Schedule End Date, then refresh the cycles card
function cl_cpiCalcEndDate(block) {
  _cl_cpiCalcEndDateCore(block);
  cl_cpiUpdateCyclesCard(block);
}

function _cl_cpiCalcEndDateCore(block) {
  const tog = block.querySelector(".cl-cpi-customToggle");
  if (!tog?.checked) return;

  const cycleStart = block.querySelector(".cl-cpi-cycleStart")?.value;
  const freqSel = block.querySelector(".cl-cpi-frequency");
  const endInput = block.querySelector(".cl-cpi-cycleEnd");
  const expInput = block.querySelector(".cl-inst-expiryDate");

  // Always validate first — this shows/clears the error message
  const isValid = cl_validateCpiCycleStartDate(block);
  if (!isValid || !cycleStart) {
    if (endInput) endInput.value = "";
    return;
  }

  // Need a frequency to calculate the end date
  const freqVal = parseInt(freqSel?.value || "");
  if (!freqSel?.value || isNaN(freqVal)) {
    if (endInput) endInput.value = "";
    return;
  }

  // CRM: autopopulateCpiScheduleEndDateByFrequency
  // endDate = cycleStart + frequency − 1 day, capped at expiryDate
  const d = new Date(cycleStart);
  switch (freqVal) {
    case 126330000:
      d.setMonth(d.getMonth() + 1);
      break; // Monthly
    case 126330001:
      d.setMonth(d.getMonth() + 3);
      break; // Quarterly
    case 126330002:
      d.setMonth(d.getMonth() + 6);
      break; // Half-Year
    case 126330003:
      d.setFullYear(d.getFullYear() + 1);
      break; // Annual
    default:
      if (endInput) endInput.value = "";
      return;
  }
  d.setDate(d.getDate() - 1);

  // Cap at expiry date — CRM: getValidatedEndDate
  const expDate = expInput?.value || "";
  if (expDate) {
    const expD = new Date(expDate);
    expD.setHours(0, 0, 0, 0);
    if (d > expD) d.setTime(expD.getTime());
  }

  if (endInput) {
    endInput.value = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;
  }
}

function cl_onCpiFrequencyChange(block) {
  const cycleEndInput = block.querySelector(".cl-cpi-cycleEnd");
  const cycleStartInput = block.querySelector(".cl-cpi-cycleStart");
  const tog = block.querySelector(".cl-cpi-customToggle");

  // CRM onCpiRentFrequencyChange: clear both fields on frequency change
  if (cycleEndInput) cycleEndInput.value = "";
  if (cycleStartInput) cycleStartInput.value = "";

  // Clear any existing validation error
  if (cycleStartInput) cycleStartInput.style.borderColor = "";
  const fg = cycleStartInput?.closest(".amend-form-group");
  if (fg) {
    const err = fg.querySelector(".cl-cpi-start-err");
    if (err) err.remove();
  }

  // Reference Month options / Custom Month visibility depend on the frequency
  cl_cpiApplyReferenceMonthRules(block);
  cl_cpiUpdateCyclesCard(block);

  if (!tog?.checked) return;

  // If cycle start still has a value after clear, recalculate
  if (cycleStartInput?.value) {
    cl_cpiCalcEndDate(block);
  }
}

// Clear an inline field error added by showFieldErrorEl()
function _cl_clearElError(el) {
  if (!el) return;
  el.style.borderColor = "";
  el.style.boxShadow = "";
  el.classList.remove("amend-field-error-marked");
  const next = el.nextElementSibling;
  if (next && next.classList.contains("amend-field-error-msg")) next.remove();
}

// ── CPI Reference Month + CPI Custom Month rules ──────────────
// Mirrors the Lease Creation CPI form / Lease Clause form. By CPI Rent Frequency:
//   no frequency           -> Reference Month hidden
//   Monthly                -> Start / Last / Latest Published (defaults to Start Month)
//   Quarterly, Half-Yearly -> Start / Last / Latest Published
//   Yearly                 -> all options; "Custom Month" reveals CPI Custom Month
function cl_cpiApplyReferenceMonthRules(block) {
  if (!block) return;
  const fs = block.querySelector(".cl-cpi-frequency");
  const refWrap = block.querySelector(".cl-cpi-refMonthWrapper");
  const refSel = block.querySelector(".cl-cpi-refMonth");
  const custWrap = block.querySelector(".cl-cpi-customMonthWrapper");
  const custSel = block.querySelector(".cl-cpi-customMonth");
  if (!fs || !refWrap || !refSel) return;

  const hideCustomMonth = () => {
    if (custWrap) custWrap.style.display = "none";
    if (custSel) {
      custSel.value = "";
      _cl_clearElError(custSel);
    }
  };

  // No frequency selected -> hide both fields
  const freq = fs.value === "" ? NaN : parseInt(fs.value, 10);
  if (isNaN(freq)) {
    refWrap.style.display = "none";
    refSel.value = "";
    _cl_clearElError(refSel);
    hideCustomMonth();
    return;
  }

  // Option value first; label as a fallback in case values differ per environment
  const freqLabel = (fs.options[fs.selectedIndex]?.text || "")
    .trim()
    .toLowerCase();
  const isYearly =
    freq === CL_CPI_FREQ.YEARLY ||
    (/year|annual/.test(freqLabel) && !/half/.test(freqLabel));
  const isMonthly = freq === CL_CPI_FREQ.MONTHLY || freqLabel === "monthly";

  const allowed = isYearly
    ? [CL_CPI_REF.START, CL_CPI_REF.LAST, CL_CPI_REF.CUSTOM, CL_CPI_REF.LATEST]
    : [CL_CPI_REF.START, CL_CPI_REF.LAST, CL_CPI_REF.LATEST];

  // Rebuild the options only when the allowed set changes
  const current = refSel.value === "" ? NaN : parseInt(refSel.value, 10);
  const allowedKey = allowed.join(",");
  if (refSel.dataset.allowed !== allowedKey) {
    const map = amendClauseChoiceMappings["array_cpireferencemonth"] || {};
    refSel.innerHTML =
      '<option value="">Select reference month</option>' +
      Object.entries(map)
        .filter(([, v]) => allowed.includes(Number(v)))
        .sort((a, b) => Number(a[1]) - Number(b[1]))
        .map(([label, v]) => `<option value="${v}">${esc(label)}</option>`)
        .join("");
    refSel.dataset.allowed = allowedKey;
  }

  // Keep a still-allowed selection; Monthly defaults to Start Month;
  // otherwise clear a value that is no longer offered (e.g. Custom Month)
  if (!isNaN(current) && allowed.includes(current)) {
    refSel.value = String(current);
  } else if (isMonthly) {
    refSel.value = String(CL_CPI_REF.START);
  } else {
    refSel.value = "";
  }
  refWrap.style.display = "block";
  if (refSel.value) _cl_clearElError(refSel);

  // Custom Month only for Yearly + Reference Month = Custom Month
  if (isYearly && refSel.value === String(CL_CPI_REF.CUSTOM)) {
    if (custWrap) custWrap.style.display = "block";
  } else {
    hideCustomMonth();
  }
}

