// ── Open modal in EDIT mode ───────────────────────────────────
async function ao_openEditOptionModal(idx) {
  const opt = amendNewOptions[idx];
  if (!opt) return;

  _aoSupersedeOptionId = null;
  document.getElementById("addOptionModalTitle").textContent =
    "Edit Lease Option";
  document.getElementById("ao_saveBtnText").textContent = "Save Changes";

  // Apply sectioned layout first (rebuilds the body HTML)
  _ao_applyModalStyling();

  // Wait a tick for DOM to settle after innerHTML rebuild
  await new Promise((r) => setTimeout(r, 0));

  // Re-populate dropdowns with current data
  await ao_populateModalDropdowns();

  // Now set values
  document.getElementById("ao_editIdx").value = idx;
  document.getElementById("ao_optionType").value =
    opt.array_optiontype != null ? opt.array_optiontype : "";
  document.getElementById("ao_optionHolder").value =
    opt.array_optionholder != null ? opt.array_optionholder : "";
  document.getElementById("ao_executionDate").value =
    opt.array_optionavailablefrom
      ? opt.array_optionavailablefrom.substring(0, 10)
      : "";
  document.getElementById("ao_expiryDate").value = opt.array_optionexpirydate
    ? opt.array_optionexpirydate.substring(0, 10)
    : "";
  document.getElementById("ao_noticePeriod").value =
    opt.array_noticeperiod != null ? opt.array_noticeperiod : "";
  document.getElementById("ao_noticeDeadline").value =
    opt.array_noticesubmissiondeadline
      ? opt.array_noticesubmissiondeadline.substring(0, 10)
      : "";
  document.getElementById("ao_penaltyAmount").value =
    opt.array_penaltyamount != null ? opt.array_penaltyamount : "";
  document.getElementById("ao_currency").value = opt._currencyId || "";
  document.getElementById("ao_description").value = opt.array_description || "";

  openModal("modalAddOption");
}

// ── Open modal to SUPERSEDE an existing (saved) option ────────
// Opens the full Add Option modal pre-filled from the existing record, with
// Option Available From defaulted to the amendment effective date (editable).
// On save the old option is deactivated and a new one created.
async function ao_openSupersedeOptionModal(optionId) {
  const opt = amendExistingOptions.find((o) => o.array_optionid === optionId);
  if (!opt) return;

  _aoSupersedeOptionId = optionId;

  document.getElementById("addOptionModalTitle").textContent =
    "Edit Lease Option";
  document.getElementById("ao_saveBtnText").textContent = "Save Changes";

  _ao_applyModalStyling();
  await new Promise((r) => setTimeout(r, 0));
  await ao_populateModalDropdowns();

  const eff = getAmendmentEffectiveDate();

  document.getElementById("ao_editIdx").value = "-1";
  document.getElementById("ao_optionType").value =
    opt.array_optiontype != null ? opt.array_optiontype : "";
  document.getElementById("ao_optionHolder").value =
    opt.array_optionholder != null ? opt.array_optionholder : "";
  // Option Available From defaults to the amendment effective date (editable).
  document.getElementById("ao_executionDate").value =
    eff ||
    (opt.array_optionavailablefrom
      ? opt.array_optionavailablefrom.substring(0, 10)
      : "");
  document.getElementById("ao_expiryDate").value = opt.array_optionexpirydate
    ? opt.array_optionexpirydate.substring(0, 10)
    : "";
  document.getElementById("ao_noticePeriod").value =
    opt.array_noticeperiod != null ? opt.array_noticeperiod : "";
  document.getElementById("ao_noticeDeadline").value =
    opt.array_noticesubmissiondeadline
      ? opt.array_noticesubmissiondeadline.substring(0, 10)
      : "";
  document.getElementById("ao_penaltyAmount").value =
    opt.array_penaltyamount != null ? opt.array_penaltyamount : "";
  document.getElementById("ao_currency").value =
    opt._currencyId || opt._transactioncurrencyid_value || "";
  document.getElementById("ao_description").value = opt.array_description || "";

  openModal("modalAddOption");
}

// ── Save (add or update) ──────────────────────────────────────
function ao_saveOption() {
  const editIdx = parseInt(document.getElementById("ao_editIdx").value);
  const isEdit = editIdx >= 0 && editIdx < amendNewOptions.length;
  const isSupersede = !!_aoSupersedeOptionId;

  const typeVal = document.getElementById("ao_optionType").value;
  const holderVal = document.getElementById("ao_optionHolder").value;
  const executionDate = document.getElementById("ao_executionDate").value;
  const expiryDate = document.getElementById("ao_expiryDate").value;
  const noticeDeadline = document.getElementById("ao_noticeDeadline").value;
  const noticePeriodRaw = document.getElementById("ao_noticePeriod").value;
  const noticePeriod =
    noticePeriodRaw !== "" ? parseInt(noticePeriodRaw) : null;
  const penaltyRaw = document.getElementById("ao_penaltyAmount").value;
  const penalty = penaltyRaw !== "" ? parseFloat(penaltyRaw) : null;
  const currencyId = document.getElementById("ao_currency").value;
  const description = document.getElementById("ao_description").value;

  // ── Validation: required fields ───────────────────────────
  clearFieldErrors(document.getElementById("modalAddOption"));
  if (!typeVal) {
    showFieldError("ao_optionType", "Option Type is required.");
    return;
  }
  if (!holderVal) {
    showFieldError("ao_optionHolder", "Option Holder is required.");
    return;
  }
  if (!executionDate) {
    showFieldError(
      "ao_executionDate",
      "Option Available From date is required.",
    );
    return;
  }
  if (!expiryDate) {
    showFieldError("ao_expiryDate", "Option Expiry Date is required.");
    return;
  }
  if (!noticeDeadline) {
    showFieldError(
      "ao_noticeDeadline",
      "Notice Submission Deadline is required.",
    );
    return;
  }
  if (expiryDate && executionDate && expiryDate <= executionDate) {
    showFieldError(
      "ao_expiryDate",
      "Option Expiry Date must be after Option Available From date.",
    );
    return;
  }

  // ── NEW: Duplicate option type check ─────────────────────
  // An option of the same type can only exist once unless the
  // existing one is deactivated. Check existing DB options,
  // newly-added pending options (excluding the row being edited),
  // and deactivated-this-session options separately.

  const newTypeInt = parseInt(typeVal);

  // Check active existing (DB) options for same type (exclude the record
  // being superseded — it is about to be deactivated).
  const conflictExisting = amendExistingOptions.find(
    (o) =>
      o.array_optiontype === newTypeInt &&
      o.array_optionid !== _aoSupersedeOptionId,
  );

  // Check newly-staged pending options for same type (exclude self when editing)
  const conflictNew = amendNewOptions.find((o, idx) => {
    if (isEdit && idx === editIdx) return false; // skip self in edit mode
    return o.array_optiontype === newTypeInt;
  });

  // OTH - Other is a catch-all type: several can coexist on one lease.
  const isOtherType = /^OTH\b/i.test(
    ao_choiceLabel(ao_optionTypeChoices, newTypeInt) || "",
  );
  if (!isOtherType && (conflictExisting || conflictNew)) {
    const conflictSource = conflictExisting ? "an active" : "a newly added";
    const typeLblForError = ao_choiceLabel(ao_optionTypeChoices, newTypeInt);
    showAmendNotification(
      `⚠️ ${conflictSource} "${typeLblForError}" option already exists on this lease. ` +
        `Only one active option of the same type is allowed at a time. ` +
        `Please deactivate the existing option before adding a new one.`,
      "warning",
    );
    return;
  }

  // Reset border colours after passing validation
  [
    "ao_optionType",
    "ao_optionHolder",
    "ao_executionDate",
    "ao_expiryDate",
    "ao_noticeDeadline",
  ].forEach((id) => {
    const el = document.getElementById(id);
    if (el) el.style.borderColor = "";
  });

  const typeLbl = ao_choiceLabel(ao_optionTypeChoices, typeVal);
  const holderLbl = ao_choiceLabel(ao_optionHolderChoices, holderVal);
  const ccyObj = amendCurrencies.find(
    (c) => c.transactioncurrencyid === currencyId,
  );

  const record = {
    array_optiontype: typeVal !== "" ? parseInt(typeVal) : null,
    array_optionholder: holderVal !== "" ? parseInt(holderVal) : null,
    array_optionavailablefrom: executionDate || null,
    array_optionexpirydate: expiryDate || null,
    array_noticeperiod: noticePeriod,
    array_noticesubmissiondeadline: noticeDeadline || null,
    array_penaltyamount: penalty,
    array_description: description,
    _currencyId: currencyId || null,
    _currencyCode: ccyObj ? ccyObj.isocurrencycode : "",
    _currencySymbol: ccyObj ? ccyObj.currencysymbol : "",
    _optionTypeName: typeLbl,
    _optionHolderName: holderLbl,
    _pending: true,
  };

  // ── SUPERSEDE an existing option ──────────────────────────
  //   Deactivate the old option (expiry = amendment effective date, same day)
  //   and create a new one from the edited values. Both are written by
  //   ao_saveAllPendingOptions during saveAmendments.
  if (isSupersede) {
    const sIdx = amendExistingOptions.findIndex(
      (o) => o.array_optionid === _aoSupersedeOptionId,
    );
    if (sIdx !== -1) {
      const eff = getAmendmentEffectiveDate();
      const deactivated = { ...amendExistingOptions[sIdx] };
      deactivated._pendingDeactivate = true;
      deactivated._newExpiryDate = eff || deactivated.array_optionexpirydate;
      deactivated.array_optionexpirydate = deactivated._newExpiryDate;
      amendDeactivatedOptions.push(deactivated);
      amendExistingOptions.splice(sIdx, 1);
    }
    amendNewOptions.push(record);
    _aoSupersedeOptionId = null;
    showAmendNotification(
      "✅ Option updated — the existing option will be deactivated and a new one created when you save.",
      "success",
    );
    closeModal("modalAddOption");
    ao_renderExistingOptionsTable();
    ao_renderNewOptionsTable();
    updateBadge(
      "options",
      amendExistingOptions.length + amendNewOptions.length,
    );
    return;
  }

  if (isEdit) {
    amendNewOptions[editIdx] = record;
    showAmendNotification("✅ Option updated.", "success");
  } else {
    amendNewOptions.push(record);
    showAmendNotification(
      "✅ Option staged. It will be saved when you click Save Amendments.",
      "success",
    );
  }

  closeModal("modalAddOption");
  ao_renderNewOptionsTable();
  updateBadge("options", amendExistingOptions.length + amendNewOptions.length);
}

// ── Remove a newly-added option (local only) ──────────────────
function ao_removeNewOption(idx) {
  const opt = amendNewOptions[idx];
  if (!opt) return;
  document.getElementById("confirmDeleteMsg").textContent =
    `Remove this newly added "${opt._optionTypeName || "lease option"}"? It has not yet been saved to the database.`;
  pendingDeleteCallback = () => {
    amendNewOptions.splice(idx, 1);
    ao_renderNewOptionsTable();
    updateBadge(
      "options",
      amendExistingOptions.length + amendNewOptions.length,
    );
    showAmendNotification("Option removed.", "info");
  };
  document.getElementById("confirmDeleteOverlay").classList.add("active");
}

// ── Save all pending new options to Dataverse ─────────────────
// Called inside saveAmendments() alongside other pending saves.
async function ao_saveAllPendingOptions(newAmendmentId, isSameDay = false) {
  // ── 1. Apply option deactivations ────────────────────────────
  // Same-day: deactivate immediately. Future: Pending Deactivation.
  for (const opt of amendDeactivatedOptions.filter(
    (o) => o._pendingDeactivate,
  )) {
    try {
      const optDeactPayload = isSameDay
        ? {
            statecode: 1,
            statuscode: 2,
            array_optionexpirydate: opt._newExpiryDate,
            "array_LeaseAmendment@odata.bind": `/array_leaseamendmentses(${newAmendmentId})`,
          }
        : {
            // DEFERRED: mark action on the existing active record.
            array_amendmentactions: 126330001,
            array_amendmentexpirydate: opt._newExpiryDate,
            "array_LeaseAmendment@odata.bind": `/array_leaseamendmentses(${newAmendmentId})`,
          };
      await XrmCtx.WebApi.updateRecord(
        "array_option",
        opt.array_optionid,
        optDeactPayload,
      );
      opt._pendingDeactivate = false;
      console.log(
        isSameDay
          ? `✅ Option deactivated live: ${opt.array_optionid}`
          : `✅ Option marked Pending Deactivation: ${opt.array_optionid}`,
      );
    } catch (err) {
      console.error(`❌ Failed to deactivate option:`, err);
      showAmendNotification(
        `❌ Failed to deactivate option: ${err.message || err}`,
        "error",
      );
    }
  }

  // ── 1b. Apply AI-routed edits to EXISTING active options ──────
  // Renewal/Break terms from the amendment PDF that matched an existing
  // option. Same-day: write changes live. Future-dated: write changes AND
  // mark array_amendmentactions = Edit so the downstream amendment apply
  // treats it as a deferred edit. Never touches statecode/statuscode here.
  for (const edit of Array.isArray(amendOptionEdits) ? amendOptionEdits : []) {
    try {
      const editPayload = {
        ...edit.changes,
        "array_LeaseAmendment@odata.bind": `/array_leaseamendmentses(${newAmendmentId})`,
      };
      if (!isSameDay) {
        editPayload.array_amendmentactions = STATUS.option.ACTION;
        if (edit._newExpiryDate)
          editPayload.array_amendmentexpirydate = edit._newExpiryDate;
      }
      await XrmCtx.WebApi.updateRecord(
        "array_option",
        edit.array_optionid,
        editPayload,
      );
      console.log(
        isSameDay
          ? `✅ Option edited live: ${edit._optionTypeName} (${edit.array_optionid})`
          : `✅ Option edit staged as Pending Action: ${edit._optionTypeName} (${edit.array_optionid})`,
      );
    } catch (err) {
      console.error(`❌ Failed to edit option "${edit._optionTypeName}":`, err);
      showAmendNotification(
        `❌ Failed to edit option "${edit._optionTypeName}": ${err.message || err}`,
        "error",
      );
    }
  }
  amendOptionEdits = [];

  if (!amendNewOptions.length) return;

  const isValidGuid = (id) =>
    typeof id === "string" &&
    /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(
      id.trim(),
    );

  // ── 2. Save pending new options ───────────────────────────────
  // Same-day: create active. Future: create then flip to Pending Action.
  for (const opt of amendNewOptions) {
    try {
      const payload = {
        "array_LeaseAgreement@odata.bind": `/array_leaseagreements(${amendLeaseId})`,
        "array_LeaseAmendment@odata.bind": `/array_leaseamendmentses(${newAmendmentId})`,
      };

      if (opt.array_optiontype != null)
        payload.array_optiontype = opt.array_optiontype;
      if (opt.array_optionholder != null)
        payload.array_optionholder = opt.array_optionholder;
      if (opt.array_noticeperiod != null)
        payload.array_noticeperiod = opt.array_noticeperiod;
      if (opt.array_penaltyamount != null)
        payload.array_penaltyamount = opt.array_penaltyamount;
      if (opt.array_description)
        payload.array_description = opt.array_description;
      if (opt.array_optionavailablefrom)
        payload.array_optionavailablefrom = opt.array_optionavailablefrom;
      if (opt.array_optionexpirydate)
        payload.array_optionexpirydate = opt.array_optionexpirydate;
      if (opt.array_noticesubmissiondeadline)
        payload.array_noticesubmissiondeadline =
          opt.array_noticesubmissiondeadline;
      if (isValidGuid(opt._currencyId))
        payload["transactioncurrencyid@odata.bind"] =
          `/transactioncurrencies(${opt._currencyId})`;

      const created = await XrmCtx.WebApi.createRecord("array_option", payload);
      if (!isSameDay) {
        const createdId = created.id.replace(/[{}]/g, "");
        await XrmCtx.WebApi.updateRecord("array_option", createdId, {
          statecode: 1,
          statuscode: STATUS.option.ACTION,
        });
        console.log(
          `✅ Option staged as Pending Action: ${opt._optionTypeName || opt.array_optiontype}`,
        );
      } else {
        console.log(
          `✅ Option saved live: ${opt._optionTypeName || opt.array_optiontype}`,
        );
      }
    } catch (err) {
      console.error(`❌ Failed to save option "${opt._optionTypeName}":`, err);
      showAmendNotification(
        `❌ Failed to save option "${opt._optionTypeName}": ${err.message || err}`,
        "error",
      );
    }
  }
  amendNewOptions = [];
}

// ── Open deactivate option modal ──────────────────────────────
async function dao_openDeactivateOptionModal(optionId) {
  pendingDeactivateOptionId = optionId;

  await ao_loadChoices();

  const option =
    amendExistingOptions.find((o) => o.array_optionid === optionId) || {};

  const typeLbl =
    option["array_optiontype@OData.Community.Display.V1.FormattedValue"] ||
    ao_choiceLabel(ao_optionTypeChoices, option.array_optiontype) ||
    "—";
  const holderLbl =
    option["array_optionholder@OData.Community.Display.V1.FormattedValue"] ||
    ao_choiceLabel(ao_optionHolderChoices, option.array_optionholder) ||
    "—";

  const originalExpiry = option.array_optionexpirydate
    ? option.array_optionexpirydate.substring(0, 10)
    : "";

  const maxDate = getMaxAllowedDate(); // ← lease end OR amendment expiry, whichever is greater

  document.getElementById("dao_optionType").textContent = typeLbl;
  document.getElementById("dao_optionHolder").textContent = holderLbl;
  document.getElementById("dao_currentExpiry").textContent =
    formatDateAmend(originalExpiry);

  const expiryInput = document.getElementById("dao_newExpiryDate");
  expiryInput.value = originalExpiry;

  // Cap at global max (greater of lease end / amendment expiry), but never
  // allow the user to set a date beyond the original expiry either.
  let effectiveMax = "";
  if (maxDate && originalExpiry) {
    effectiveMax = maxDate > originalExpiry ? maxDate : originalExpiry;
  } else if (maxDate) {
    effectiveMax = maxDate;
  } else if (originalExpiry) {
    effectiveMax = originalExpiry;
  }

  if (effectiveMax) expiryInput.max = effectiveMax;
  else expiryInput.removeAttribute("max");

  // Allow past dates for retroactive deactivation
  expiryInput.removeAttribute("min");
  expiryInput.style.borderColor = "#FFCF7F";
  expiryInput.dataset.originalExpiry = originalExpiry;

  // Update hint text
  const formGroup = expiryInput.closest(".amend-form-group");
  if (formGroup) {
    let hint = formGroup.querySelector("p");
    if (hint) {
      hint.textContent = effectiveMax
        ? `The option will be deactivated with this new expiry date on final save (max: ${formatDateAmend(effectiveMax)}).`
        : "The option will be deactivated with this new expiry date on final save.";
    }
  }

  const modalTitle = document.querySelector(
    "#modalDeactivateOption .amend-modal-title",
  );
  if (modalTitle) modalTitle.textContent = "Deactivate Lease Option";

  _dao_applyModalBodyStyling();
  openModal("modalDeactivateOption");
}

// ── Apply professional body padding/spacing to deactivate option modal ──
function _dao_applyModalBodyStyling() {
  const modalBody = document.querySelector(
    "#modalDeactivateOption .amend-modal-body",
  );
  if (!modalBody) return;

  modalBody.style.cssText =
    "flex:1;overflow-y:auto;min-height:0;padding:24px 28px;";

  modalBody.querySelectorAll(".amend-form-group").forEach((fg) => {
    fg.style.marginBottom = "16px";
    fg.style.display = "flex";
    fg.style.flexDirection = "column";
    fg.style.gap = "6px";
  });

  modalBody.querySelectorAll(".amend-form-group label").forEach((lbl) => {
    lbl.style.fontSize = "12px";
    lbl.style.fontWeight = "600";
    lbl.style.color = "#374151";
  });

  modalBody
    .querySelectorAll(
      ".amend-form-group input:not([type=hidden])," +
        ".amend-form-group select",
    )
    .forEach((el) => {
      el.style.borderRadius = "8px";
      el.style.padding = "9px 12px";
      el.style.fontSize = "13px";
      el.style.boxSizing = "border-box";
    });

  const infoBox = modalBody.querySelector("div[style*='f8fafc']");
  if (infoBox) {
    infoBox.style.borderRadius = "10px";
    infoBox.style.padding = "14px 16px";
    infoBox.style.marginBottom = "18px";
  }
}

// ── Execute deactivation (local only — saved on final submit) ─
function dao_executeDeactivateOption() {
  const expiryInput = document.getElementById("dao_newExpiryDate");
  const newExpiry = expiryInput.value;
  const originalExpiry = expiryInput.dataset.originalExpiry || "";

  if (!newExpiry) {
    showFieldError("dao_newExpiryDate", "Please enter a new expiry date.");
    return;
  }
  if (originalExpiry && newExpiry > originalExpiry) {
    showAmendNotification(
      "⚠️ New expiry date cannot be later than the original expiry date.",
      "warning",
    );
    expiryInput.style.borderColor = "#B91C1C";
    return;
  }
  expiryInput.style.borderColor = "";

  const idx = amendExistingOptions.findIndex(
    (o) => o.array_optionid === pendingDeactivateOptionId,
  );
  if (idx !== -1) {
    const deactivated = { ...amendExistingOptions[idx] };
    deactivated._pendingDeactivate = true;
    deactivated._newExpiryDate = newExpiry;
    deactivated.array_optionexpirydate = newExpiry;
    amendDeactivatedOptions.push(deactivated);
    amendExistingOptions.splice(idx, 1);
  }

  showAmendNotification(
    "⚠️ Option marked for deactivation. Changes will apply when you save.",
    "warning",
  );
  closeModal("modalDeactivateOption");

  ao_renderExistingOptionsTable();
  ao_renderNewOptionsTable();
  updateBadge("options", amendExistingOptions.length + amendNewOptions.length);
  pendingDeactivateOptionId = null;
}

// ── Re-activate an option deactivated this session ────────────
function dao_activateOption(optionId) {
  const idx = amendDeactivatedOptions.findIndex(
    (o) => o.array_optionid === optionId,
  );

  if (idx === -1) {
    showAmendNotification(
      "ℹ️ This option was already inactive in the system. Refresh to reload.",
      "info",
    );
    ao_renderExistingOptionsTable();
    ao_renderNewOptionsTable();
    updateBadge(
      "options",
      amendExistingOptions.length + amendNewOptions.length,
    );
    return;
  }

  if (!amendDeactivatedOptions[idx]._pendingDeactivate) {
    showAmendNotification(
      "ℹ️ This option was already inactive in the system. Refresh to reload.",
      "info",
    );
    ao_renderExistingOptionsTable();
    ao_renderNewOptionsTable();
    updateBadge(
      "options",
      amendExistingOptions.length + amendNewOptions.length,
    );
    return;
  }

  // ── NEW: Block re-activation if same option type is already active ────────
  // Check if there is already an active (non-deactivated) option of the
  // same type in either the existing DB options or newly-staged options.
  const typeToReactivate = amendDeactivatedOptions[idx].array_optiontype;

  const conflictExisting = amendExistingOptions.find(
    (o) => o.array_optiontype === typeToReactivate,
  );

  const conflictNew = amendNewOptions.find(
    (o) => o.array_optiontype === typeToReactivate,
  );

  if (conflictExisting || conflictNew) {
    const typeLbl = ao_choiceLabel(ao_optionTypeChoices, typeToReactivate);
    const conflictSource = conflictExisting
      ? "an active existing"
      : "a newly added";
    showAmendNotification(
      `⚠️ Cannot re-activate this "${typeLbl}" option because ${conflictSource} option of the same type is already active. ` +
        `Only one active option of the same type is allowed at a time. ` +
        `Please deactivate the other option first before re-activating this one.`,
      "warning",
    );
    return;
  }

  // Safe to re-activate — no conflict
  const reactivated = { ...amendDeactivatedOptions[idx] };
  delete reactivated._pendingDeactivate;
  delete reactivated._newExpiryDate;
  amendDeactivatedOptions.splice(idx, 1);
  amendExistingOptions.push(reactivated);
  showAmendNotification("✅ Option deactivation cancelled.", "success");

  ao_renderExistingOptionsTable();
  ao_renderNewOptionsTable();
  updateBadge("options", amendExistingOptions.length + amendNewOptions.length);
}

// ── Compute option rules from loaded option arrays ────────────
function computeOptionRules() {
  optionRules = {
    hasOptions: false,
    expansion: null,
    contraction: null,
    renewal: null,
  };

  const allOptions = [...amendExistingOptions, ...amendNewOptions];
  if (!allOptions.length) return;

  optionRules.hasOptions = true;

  allOptions.forEach((opt) => {
    const type = opt.array_optiontype;
    const from = opt.array_optionavailablefrom
      ? opt.array_optionavailablefrom.substring(0, 10)
      : null;
    const expiry = opt.array_optionexpirydate
      ? opt.array_optionexpirydate.substring(0, 10)
      : null;

    if (type === OPTION_TYPE_EXPANSION && !optionRules.expansion)
      optionRules.expansion = { effectiveDate: from, expiryDate: expiry };
    if (type === OPTION_TYPE_CONTRACTION && !optionRules.contraction)
      optionRules.contraction = { effectiveDate: from, expiryDate: expiry };
    if (type === OPTION_TYPE_RENEWAL && !optionRules.renewal)
      optionRules.renewal = { effectiveDate: from, expiryDate: expiry };
  });

  console.log("✅ Option rules computed:", JSON.stringify(optionRules));
}

// ── Date helpers ──────────────────────────────────────────────
function getTodayStr() {
  const d = new Date();
  return (
    d.getFullYear() +
    "-" +
    String(d.getMonth() + 1).padStart(2, "0") +
    "-" +
    String(d.getDate()).padStart(2, "0")
  );
}

function isDateInRange(dateStr, fromStr, toStr) {
  if (!dateStr) return false;
  const d = dateStr.substring(0, 10);
  if (fromStr && d < fromStr) return false;
  if (toStr && d > toStr) return false;
  return true;
}

// ── Apply renewal constraint to the expiry date input (Stage 2) ──
// Call this after options load and whenever the terms panel is shown.
function applyRenewalDateConstraint() {
  // Expiry date restrictions removed by request — user may pick any date,
  // including dates beyond the lease agreement end and future dates.
  const endInput = document.getElementById("amend_endDate");
  if (!endInput) return;

  endInput.min = "";
  endInput.max = "";
  endInput.dataset.optionMinDate = "";
  endInput.dataset.optionMaxDate = "";
  endInput.dataset.optionMaxLabel = "";
}

function openEditEndDateChargeModal(chargeId, idx) {
  pendingDeactivateChargeId = chargeId;
  pendingDeactivateChargeIdx = idx;

  const today = new Date();
  const todayStr =
    today.getFullYear() +
    "-" +
    String(today.getMonth() + 1).padStart(2, "0") +
    "-" +
    String(today.getDate()).padStart(2, "0");

  const cbProration = document.getElementById("dc_lastCycleProration");
  const endDateInput = document.getElementById("dc_endDate");
  const endDateGroup = document.getElementById("dc_endDateGroup");

  const charge =
    amendExistingCharges.find((c) => c.array_recurringchargeid === chargeId) ||
    amendExistingCharges[idx] ||
    {};

  const chargeEndDate =
    charge && charge.array_enddate
      ? charge.array_enddate.substring(0, 10)
      : todayStr;

  // ── Read proration value: check dedicated last-cycle field first,
  //    then fall back to general proration field,
  //    then check pending session value.
  //    Priority: _pendingLastCycleProration (session) > array_prorationenabledforlastcycle > array_prorationenabled
  let chargeProrationEnabled = false;
  if (charge._pendingLastCycleProration !== undefined) {
    // A previous edit this session already set this
    chargeProrationEnabled = charge._pendingLastCycleProration === true;
  } else if (
    charge.array_prorationenabledforlastcycle !== undefined &&
    charge.array_prorationenabledforlastcycle !== null
  ) {
    // Dedicated last-cycle proration field on the charge record
    chargeProrationEnabled =
      charge.array_prorationenabledforlastcycle === true ||
      charge.array_prorationenabledforlastcycle === "true";
  } else if (
    charge.array_prorationenabled !== undefined &&
    charge.array_prorationenabled !== null
  ) {
    // Fall back to general proration enabled field
    chargeProrationEnabled =
      charge.array_prorationenabled === true ||
      charge.array_prorationenabled === "true";
  }
  cbProration.checked = chargeProrationEnabled;

  // ── ALWAYS show end date group regardless of checkbox state ──────────────
  endDateInput.value = chargeEndDate;
  endDateInput.min = todayStr;
  endDateInput.dataset.today = todayStr;
  endDateInput.dataset.chargeEndDate = chargeEndDate;
  endDateInput.dataset.mode = "edit";
  endDateInput.style.cssText =
    "border:1.5px solid #BBDBFF;border-radius:8px;padding:9px 12px;" +
    "font-size:13px;width:100%;box-sizing:border-box;";
  endDateGroup.style.display = "block";

  // ── ALWAYS show proration row ─────────────────────────────────────────────
  const prorationGroup = cbProration.closest(".amend-form-group");
  if (prorationGroup) {
    prorationGroup.style.cssText =
      "display:flex;flex-direction:column;gap:8px;padding:0;margin-bottom:16px;";
  }

  // ── Modal body: set padding + hide amber warning banner ───────────────────
  const modalBody = document.querySelector(
    "#modalDeactivateCharge .amend-modal-body",
  );
  if (modalBody) {
    modalBody.style.padding = "24px 28px";

    // Hide amber warning banner (belongs to deactivate mode only)
    Array.from(modalBody.querySelectorAll(":scope > div")).forEach((div) => {
      const hasFde = div.innerHTML && div.innerHTML.includes("fffbeb");
      const bg = div.style.background || div.style.backgroundColor || "";
      if (bg.includes("fffbeb") || bg.includes("fef3c7") || hasFde) {
        div.style.display = "none";
        div.dataset.hiddenByEdit = "true";
      }
    });

    // Remove any stale charge info panel from a previous open
    const existingPanel = document.getElementById("dc_chargeInfoPanel");
    if (existingPanel) existingPanel.remove();
  }

  // ── Style the end date form group ─────────────────────────────────────────
  const endDateFormGroup = endDateInput.closest(".amend-form-group");
  if (endDateFormGroup) {
    endDateFormGroup.style.cssText =
      "display:flex;flex-direction:column;gap:6px;padding:0;margin-bottom:0;";
    const endLbl = endDateFormGroup.querySelector("label");
    if (endLbl) {
      endLbl.innerHTML = `Last Date of Recurring Charge (End Date)
        <span style="color:#B91C1C;margin-left:2px;">*</span>`;
      endLbl.className = "";
      endLbl.style.cssText = "font-size:12px;font-weight:600;color:#374151;";
    }
    const endHint = endDateFormGroup.querySelector("p");
    if (endHint) {
      endHint.textContent =
        "Auto-populated with the charge's current end date. You may update it.";
      endHint.style.cssText =
        "font-size:11px;color:#5A6070;margin:4px 0 0;line-height:1.5;";
    }
  }

  // ── Header → BLUE ─────────────────────────────────────────────────────────
  const modalHeader = document.querySelector(
    "#modalDeactivateCharge .amend-modal-header",
  );
  if (modalHeader) {
    modalHeader.style.background =
      "linear-gradient(135deg, #1C6BD4 0%, #0D4A9E 100%)";
  }

  // ── Title ─────────────────────────────────────────────────────────────────
  const modalTitle = document.querySelector(
    "#modalDeactivateCharge .amend-modal-title",
  );
  if (modalTitle) {
    modalTitle.innerHTML = `
      <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor"
           stroke-width="2" style="margin-right:6px;flex-shrink:0;">
        <path d="M11 4H4a2 2 0 00-2 2v14a2 2 0 002 2h14a2 2 0 002-2v-7"/>
        <path d="M18.5 2.5a2.121 2.121 0 013 3L12 15l-4 1 1-4 9.5-9.5z"/>
      </svg>
      Edit Recurring Charge`;
  }

  // ── Save button → BLUE ────────────────────────────────────────────────────
  const saveBtn = document.querySelector(
    "#modalDeactivateCharge .amend-modal-footer .btn-amend-save",
  );
  if (saveBtn) {
    saveBtn.style.cssText =
      "background:linear-gradient(135deg,#1C6BD4 0%,#0D4A9E 100%);color:#fff;" +
      "border:none;border-radius:8px;padding:10px 22px;font-size:14px;font-weight:700;" +
      "cursor:pointer;display:inline-flex;align-items:center;gap:8px;";
    saveBtn.innerHTML = `
      <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
        <path d="M19 21H5a2 2 0 01-2-2V5a2 2 0 012-2h11l5 5v11a2 2 0 01-2 2z"/>
        <polyline points="17 21 17 13 7 13 7 21"/>
        <polyline points="7 3 7 8 15 8"/>
      </svg>
      Save Changes`;
    saveBtn.setAttribute("onclick", "executeDeactivateCharge()");
  }

  openModal("modalDeactivateCharge");
}

