// ── Load existing SharePoint documents for the amendment (edit mode only) ──
async function fu_loadExistingSharePointFiles(amendmentId) {
  // Resolve the display containers. They normally live in the HTML web resource,
  // but if they are absent we inject them (JS-only) so this never silently no-ops.
  let section = document.getElementById("sp_existingDocsSection");
  let list = document.getElementById("sp_existingDocsList");

  if (!section || !list) {
    const panel = document.getElementById("panel-fileupload");
    if (!panel) return; // upload panel not in DOM yet

    section = document.createElement("div");
    section.id = "sp_existingDocsSection";
    section.style.cssText =
      "margin-bottom:16px;display:none;border:1px solid #EAECF0;" +
      "border-radius:10px;padding:12px 14px;background:#fbfcfe;";
    section.innerHTML =
      `<div style="display:flex;align-items:center;gap:7px;margin-bottom:8px;">` +
      `<span style="font-size:12px;font-weight:600;color:#1C6BD4;">Previously uploaded documents</span>` +
      `<span style="font-size:11px;color:#9CA3AF;font-weight:400;">· saved to SharePoint, read-only</span>` +
      `</div><div id="sp_existingDocsList"></div>`;
    panel.insertBefore(section, panel.firstChild);
    list = section.querySelector("#sp_existingDocsList");
  }

  if (!amendmentId) return;

  section.style.display = "block";
  list.innerHTML = `<p style="font-size:13px;color:#9CA3AF;text-align:center;padding:14px 0;margin:0;">Loading documents…</p>`;

  const emptyMsg = (txt) => {
    list.innerHTML = `<p style="font-size:13px;color:#9CA3AF;text-align:center;padding:20px 0;margin:0;">${txt}</p>`;
  };

  try {
    const clientUrl = XrmCtx.Utility.getGlobalContext().getClientUrl();
    const apiBase = `${clientUrl}/api/data/v9.2`;
    const reqOpts = {
      headers: {
        "OData-MaxVersion": "4.0",
        "OData-Version": "4.0",
        Accept: "application/json",
        Prefer: 'odata.include-annotations="*"',
      },
      credentials: "same-origin",
    };

    // ── Step 1: SharePoint document location linked to THIS amendment record.
    //    NOTE: filter by _regardingobjectid_value (the OOB regarding lookup).
    //    The navigation-property path filter does not resolve for this entity.
    const locResp = await fetch(
      `${apiBase}/sharepointdocumentlocations` +
        `?$select=sharepointdocumentlocationid,relativeurl,_parentsiteorlocation_value` +
        `&$filter=_regardingobjectid_value eq ${amendmentId}`,
      reqOpts,
    );
    if (!locResp.ok)
      throw new Error(`Location query failed: ${locResp.status}`);

    const leaf = ((await locResp.json()).value || [])[0];
    if (!leaf || !leaf.relativeurl) {
      emptyMsg("No documents found in SharePoint for this amendment.");
      return;
    }

    // ── Step 2: walk up the parent chain to build the full folder path and
    //    resolve the site's absolute URL. (The sharepointdocument virtual
    //    entity cannot be listed via Web API in this org — S2S not enabled —
    //    so we link out to the folder instead of listing files inline.)
    const segments = [leaf.relativeurl];
    let parentId = leaf._parentsiteorlocation_value;
    let parentType =
      leaf[
        "_parentsiteorlocation_value@Microsoft.Dynamics.CRM.lookuplogicalname"
      ];
    let siteAbsoluteUrl = "";
    let guard = 0;

    while (parentId && guard++ < 10) {
      if (parentType === "sharepointsite") {
        const siteResp = await fetch(
          `${apiBase}/sharepointsites(${parentId})?$select=absoluteurl`,
          reqOpts,
        );
        if (siteResp.ok)
          siteAbsoluteUrl = (await siteResp.json()).absoluteurl || "";
        break;
      }
      // parent is another document location
      const pResp = await fetch(
        `${apiBase}/sharepointdocumentlocations(${parentId})` +
          `?$select=relativeurl,absoluteurl,_parentsiteorlocation_value`,
        reqOpts,
      );
      if (!pResp.ok) break;
      const p = await pResp.json();
      if (p.absoluteurl) {
        siteAbsoluteUrl = p.absoluteurl;
        break;
      } // carries full URL up to this folder
      if (p.relativeurl) segments.unshift(p.relativeurl);
      parentId = p._parentsiteorlocation_value;
      parentType =
        p[
          "_parentsiteorlocation_value@Microsoft.Dynamics.CRM.lookuplogicalname"
        ];
    }

    // Fallback: org has a single active SharePoint site.
    if (!siteAbsoluteUrl) {
      const sResp = await fetch(
        `${apiBase}/sharepointsites?$select=absoluteurl&$filter=statecode eq 0&$top=1`,
        reqOpts,
      );
      if (sResp.ok)
        siteAbsoluteUrl =
          (((await sResp.json()).value || [])[0] || {}).absoluteurl || "";
    }

    if (!siteAbsoluteUrl) {
      emptyMsg(
        "Documents are stored in SharePoint, but the site URL could not be resolved.",
      );
      return;
    }

    const folderUrl = encodeURI(
      [siteAbsoluteUrl.replace(/\/+$/, ""), ...segments].join("/"),
    );

    // ── Step 3: render the "open folder" action as one large clickable card ──
    list.innerHTML = `
            <a href="${folderUrl}" target="_blank" rel="noopener noreferrer"
               style="display:flex;align-items:center;gap:14px;padding:18px 20px;
                      background:#eef2ff;border:1.5px solid #c7d2fe;border-radius:12px;
                      text-decoration:none;cursor:pointer;transition:background .15s,border-color .15s,box-shadow .15s;"
               onmouseover="this.style.background='#EBF3FF';this.style.borderColor='#4f46e5';this.style.boxShadow='0 2px 8px rgba(79,70,229,0.15)';"
               onmouseout="this.style.background='#eef2ff';this.style.borderColor='#c7d2fe';this.style.boxShadow='none';">
                <div style="width:46px;height:46px;border-radius:10px;background:#4f46e5;
                            display:flex;align-items:center;justify-content:center;flex-shrink:0;">
                    <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="#ffffff" stroke-width="1.9">
                        <path d="M22 19a2 2 0 01-2 2H4a2 2 0 01-2-2V5a2 2 0 012-2h5l2 3h9a2 2 0 012 2z"></path>
                    </svg>
                </div>
                <div style="flex:1;min-width:0;">
                    <div style="font-size:16px;font-weight:700;color:#1C6BD4;line-height:1.3;">
                        Previously uploaded documents
                    </div>
                    <div style="font-size:13px;color:#4f46e5;font-weight:600;margin-top:3px;">
                        View documents in SharePoint &rarr;
                    </div>
                    <div style="font-size:11px;color:#9CA3AF;margin-top:2px;">
                        Saved to SharePoint, read-only · opens in a new tab
                    </div>
                </div>
                <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="#5A6070" stroke-width="1.9" style="flex-shrink:0;">
                    <path d="M18 13v6a2 2 0 01-2 2H5a2 2 0 01-2-2V8a2 2 0 012-2h6"></path>
                    <polyline points="15 3 21 3 21 9"></polyline>
                    <line x1="10" y1="14" x2="21" y2="3"></line>
                </svg>
            </a>`;
  } catch (e) {
    console.warn("fu_loadExistingSharePointFiles: failed (non-fatal):", e);
    emptyMsg("Could not load existing documents.");
  }
}

// ── Handle file input change ──────────────────────────────────
function fu_handleFileSelect(input) {
  const files = Array.from(input.files || []);
  if (!files.length) return;

  const MAX_SIZE_MB = 20;
  const ALLOWED_TYPES = [
    "application/pdf",
    "application/msword",
    "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
    "application/vnd.ms-excel",
    "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
    "image/jpeg",
    "image/png",
    "image/gif",
    "image/bmp",
    "image/tiff",
    "text/plain",
  ];

  let addedCount = 0;
  let skippedCount = 0;
  let lastAddedPdf = null; // most recent PDF added this call — offered for AI prefill

  files.forEach((file) => {
    // Duplicate check (by name + size)
    const isDuplicate = uploadedFiles.some(
      (f) => f.name === file.name && f.size === file.size,
    );
    if (isDuplicate) {
      skippedCount++;
      return;
    }

    // Size check
    const sizeMB = file.size / (1024 * 1024);
    if (sizeMB > MAX_SIZE_MB) {
      showAmendNotification(
        `❌ "${file.name}" exceeds the ${MAX_SIZE_MB}MB limit and was not added.`,
        "error",
      );
      skippedCount++;
      return;
    }

    // Type check
    if (!ALLOWED_TYPES.includes(file.type)) {
      showAmendNotification(
        `❌ "${file.name}" is not a supported file type.`,
        "error",
      );
      skippedCount++;
      return;
    }

    const entry = {
      file,
      name: file.name,
      size: file.size,
      type: file.type,
      base64: null, // populated lazily on save
    };
    uploadedFiles.push(entry);
    const isPdf = file.type === "application/pdf" || /\.pdf$/i.test(file.name);
    if (isPdf) lastAddedPdf = entry;
    addedCount++;
  });

  // Reset input so same file can be re-added after removal
  input.value = "";

  if (addedCount > 0) {
    showAmendNotification(
      `✅ ${addedCount} file${addedCount !== 1 ? "s" : ""} added.`,
      "success",
    );
  }
  if (skippedCount > 0 && addedCount === 0) {
    showAmendNotification(
      `⚠️ ${skippedCount} file${skippedCount !== 1 ? "s were" : " was"} skipped (duplicate, too large, or unsupported type).`,
      "warning",
    );
  }

  fu_renderFileList();

  // ── AI prefill offer (legacy) ────────────────────────────────
  // Disabled: the AI-autofill entry point now lives on Step 2 (Lease Terms)
  // via the dedicated banner. Auto-popping a confirm modal on file upload
  // here would conflict with the banner flow and surprise the user.
  // The banner picks up files staged here via the dropdown.
  // (Reference kept for traceability.) lastAddedPdf is intentionally unused.
}

// ── Remove a file from the staged list ───────────────────────
function fu_removeFile(idx) {
  if (idx < 0 || idx >= uploadedFiles.length) return;
  const removed = uploadedFiles.splice(idx, 1);
  showAmendNotification(`"${removed[0]?.name}" removed.`, "info");
  fu_renderFileList();
}

// ── Format bytes to human-readable ───────────────────────────
function fu_formatSize(bytes) {
  if (bytes < 1024) return bytes + " B";
  if (bytes < 1024 * 1024) return (bytes / 1024).toFixed(1) + " KB";
  return (bytes / (1024 * 1024)).toFixed(2) + " MB";
}

// ── Get icon SVG based on MIME type ──────────────────────────
function fu_getFileIcon(mimeType) {
  if (mimeType === "application/pdf") {
    return `<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="#B91C1C" stroke-width="1.8">
      <path d="M14 2H6a2 2 0 00-2 2v16a2 2 0 002 2h12a2 2 0 002-2V8z"/>
      <polyline points="14 2 14 8 20 8"/>
      <line x1="9" y1="13" x2="15" y2="13"/>
      <line x1="9" y1="17" x2="12" y2="17"/>
    </svg>`;
  }
  if (mimeType.startsWith("image/")) {
    return `<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="#1C6BD4" stroke-width="1.8">
      <rect x="3" y="3" width="18" height="18" rx="2"/>
      <circle cx="8.5" cy="8.5" r="1.5"/>
      <polyline points="21 15 16 10 5 21"/>
    </svg>`;
  }
  if (mimeType.includes("word") || mimeType.includes("document")) {
    return `<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="#1C6BD4" stroke-width="1.8">
      <path d="M14 2H6a2 2 0 00-2 2v16a2 2 0 002 2h12a2 2 0 002-2V8z"/>
      <polyline points="14 2 14 8 20 8"/>
      <line x1="8" y1="13" x2="16" y2="13"/>
      <line x1="8" y1="17" x2="16" y2="17"/>
    </svg>`;
  }
  if (mimeType.includes("excel") || mimeType.includes("spreadsheet")) {
    return `<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="#2E7D32" stroke-width="1.8">
      <path d="M14 2H6a2 2 0 00-2 2v16a2 2 0 002 2h12a2 2 0 002-2V8z"/>
      <polyline points="14 2 14 8 20 8"/>
      <line x1="8" y1="13" x2="16" y2="13"/>
      <line x1="8" y1="17" x2="16" y2="17"/>
    </svg>`;
  }
  // Default / text
  return `<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="#5A6070" stroke-width="1.8">
    <path d="M14 2H6a2 2 0 00-2 2v16a2 2 0 002 2h12a2 2 0 002-2V8z"/>
    <polyline points="14 2 14 8 20 8"/>
  </svg>`;
}

// ── Render the file list ──────────────────────────────────────
function fu_renderFileList() {
  const container = document.getElementById("fu_fileList");
  const countEl = document.getElementById("fu_fileCount");
  if (!container) return;

  if (countEl) {
    countEl.textContent =
      uploadedFiles.length > 0
        ? `${uploadedFiles.length} file${uploadedFiles.length !== 1 ? "s" : ""} staged`
        : "No files selected";
  }

  if (!uploadedFiles.length) {
    container.innerHTML = `
      <div style="text-align:center;padding:32px 16px;color:#9CA3AF;">
        <svg width="40" height="40" viewBox="0 0 24 24" fill="none" stroke="#CBD5E1" stroke-width="1.5"
             style="display:block;margin:0 auto 12px;">
          <path d="M21 15v4a2 2 0 01-2 2H5a2 2 0 01-2-2v-4"/>
          <polyline points="17 8 12 3 7 8"/>
          <line x1="12" y1="3" x2="12" y2="15"/>
        </svg>
        <p style="font-size:13px;font-weight:600;margin:0 0 4px;">No files uploaded yet</p>
        <p style="font-size:12px;margin:0;">Use the upload area above to add files</p>
      </div>`;
    return;
  }

  container.innerHTML = uploadedFiles
    .map(
      (f, i) => `
      <div style="display:flex;align-items:center;gap:12px;padding:10px 14px;border-radius:8px;
                  background:${i % 2 === 0 ? "#F8F9FC" : "#fff"};
                  border:1px solid #EAECF0;margin-bottom:6px;transition:background 0.15s;">
        <div style="flex-shrink:0;width:36px;height:36px;border-radius:8px;background:#F1F2F4;
                    display:flex;align-items:center;justify-content:center;">
          ${fu_getFileIcon(f.type)}
        </div>
        <div style="flex:1;min-width:0;">
          <div style="font-size:13px;font-weight:600;color:#111827;
                      overflow:hidden;text-overflow:ellipsis;white-space:nowrap;"
               title="${esc(f.name)}">${esc(f.name)}</div>
          <div style="font-size:11px;color:#9CA3AF;margin-top:2px;">${fu_formatSize(f.size)}</div>
        </div>
        <button
          onclick="fu_removeFile(${i})"
          title="Remove file"
          style="flex-shrink:0;display:inline-flex;align-items:center;justify-content:center;
                 width:28px;height:28px;border-radius:6px;border:1px solid #FCA5A5;
                 background:#FEF2F2;color:#B91C1C;cursor:pointer;transition:all 0.15s;"
          onmouseover="this.style.background='#FEF2F2';this.style.borderColor='#B91C1C';"
          onmouseout="this.style.background='#FEF2F2';this.style.borderColor='#FCA5A5';">
          <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5">
            <polyline points="3 6 5 6 21 6"/>
            <path d="M19 6l-1 14H6L5 6"/>
            <path d="M10 11v6M14 11v6"/>
            <path d="M9 6V4h6v2"/>
          </svg>
        </button>
      </div>`,
    )
    .join("");
}

// ── Drag-and-drop handlers ────────────────────────────────────
function fu_onDragOver(e) {
  e.preventDefault();
  e.stopPropagation();
  const zone = document.getElementById("fu_dropZone");
  if (zone) zone.style.borderColor = "#1C6BD4";
}

function fu_onDragLeave(e) {
  e.preventDefault();
  e.stopPropagation();
  const zone = document.getElementById("fu_dropZone");
  if (zone) zone.style.borderColor = "#c7d2fe";
}

function fu_onDrop(e) {
  e.preventDefault();
  e.stopPropagation();
  const zone = document.getElementById("fu_dropZone");
  if (zone) zone.style.borderColor = "#c7d2fe";

  const dt = e.dataTransfer;
  if (!dt || !dt.files.length) return;

  // Simulate file input change
  const fakeInput = { files: dt.files };
  fu_handleFileSelect(fakeInput);
}

// ── Convert all staged files to base64 (called on save) ──────
async function fu_encodeAllFiles() {
  const promises = uploadedFiles.map((f) => {
    if (f.base64) return Promise.resolve(); // already encoded
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.onload = () => {
        // Strip the "data:...;base64," prefix
        f.base64 = reader.result.split(",")[1] || "";
        resolve();
      };
      reader.onerror = () => reject(new Error(`Failed to read ${f.name}`));
      reader.readAsDataURL(f.file);
    });
  });
  await Promise.all(promises);
}

// ── Trigger the Power Automate flow with the amendment ID and files ──
async function fu_triggerFlow(amendmentId) {
  // Lazy-load the flow URL from the 'array_UploadPdf' environment variable.
  if (!AMENDMENT_FLOW_URL) {
    AMENDMENT_FLOW_URL = await getEnvVarText("array_UploadPdf");
  }
  if (!AMENDMENT_FLOW_URL) {
    console.warn(
      "⚠️ 'array_UploadPdf' environment variable is not set. Skipping flow trigger.",
    );
    return;
  }

  if (!uploadedFiles.length) {
    console.log("ℹ️ No files to send to flow.");
    return;
  }

  // Encode all files to base64
  await fu_encodeAllFiles();

  // Get amendment name for the payload
  const amendmentName = amendLeaseData.array_leasename
    ? `${amendLeaseData.array_leasename} - Amendment`
    : `Amendment ${amendmentId}`;

  // Send one request per file (schema requires single file per call)
  for (const f of uploadedFiles) {
    const payload = {
      recordId: amendLeaseId,
      fileName: f.name,
      fileContent: f.base64,
      fileType: f.type,
      leaseName: amendLeaseData.array_leasename || "",
      documentType: "Amendment Document",
      amendmentId: amendmentId,
      amendmentname: amendmentName,
    };

    const resp = await fetch(AMENDMENT_FLOW_URL, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(payload),
    });

    if (!resp.ok) {
      throw new Error(
        `Flow trigger failed for "${f.name}": HTTP ${resp.status} ${resp.statusText}`,
      );
    }

    console.log(`✅ Flow triggered for file: ${f.name}`);
  }
}

// ══════════════════════════════════════════════════════════════
//  AI EXTRACTION — prefill amendment fields from an uploaded PDF
//  Separate from fu_triggerFlow (SharePoint upload). This calls the
//  AI-extraction flow and returns the parsed JSON for prefill.
// ══════════════════════════════════════════════════════════════
// Loaded lazily from Dynamics environment variable 'array_AiExtract'.
// Change the value per environment via the solution's environment variable.
let AI_EXTRACT_FLOW_URL = null;

// Encode a single staged file to base64 (reuses lazy cache on the entry)
function ai_encodeOne(entry) {
  if (entry.base64) return Promise.resolve(entry.base64);
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => {
      entry.base64 = reader.result.split(",")[1] || "";
      resolve(entry.base64);
    };
    reader.onerror = () => reject(new Error(`Failed to read ${entry.name}`));
    reader.readAsDataURL(entry.file);
  });
}

// Minimal full-screen loader (no external deps)
function ai_showLoader(msg) {
  let el = document.getElementById("ai_extractLoader");
  if (!el) {
    el = document.createElement("div");
    el.id = "ai_extractLoader";
    el.style.cssText =
      "position:fixed;inset:0;z-index:99999;display:flex;flex-direction:column;" +
      "align-items:center;justify-content:center;background:rgba(15,23,42,0.55);" +
      "backdrop-filter:blur(2px);font-family:-apple-system,BlinkMacSystemFont,'Segoe UI','Segoe UI Variable',system-ui,Roboto,Helvetica,Arial,sans-serif;";
    el.innerHTML =
      '<div style="width:46px;height:46px;border:4px solid #c7d2fe;border-top-color:#1C6BD4;' +
      'border-radius:50%;animation:ai_spin 0.8s linear infinite;"></div>' +
      '<div id="ai_extractLoaderMsg" style="margin-top:16px;color:#fff;font-size:14px;font-weight:600;"></div>' +
      "<style>@keyframes ai_spin{to{transform:rotate(360deg)}}</style>";
    document.body.appendChild(el);
  }
  const m = document.getElementById("ai_extractLoaderMsg");
  if (m) m.textContent = msg || "Extracting…";
  el.style.display = "flex";
}

function ai_hideLoader() {
  const el = document.getElementById("ai_extractLoader");
  if (el) el.style.display = "none";
}

// Fire the extraction flow for one file entry; return parsed JSON
async function ai_extractFromFile(entry) {
  // Lazy-load the extraction URL from the 'array_AiExtract' environment variable.
  if (!AI_EXTRACT_FLOW_URL) {
    AI_EXTRACT_FLOW_URL = await getEnvVarText("array_AiExtract");
  }
  if (!AI_EXTRACT_FLOW_URL) {
    throw new Error(
      "'array_AiExtract' environment variable is not set. Please configure it in the solution.",
    );
  }
  const base64 = await ai_encodeOne(entry);
  const payload = {
    recordId: amendLeaseId,
    fileName: entry.name,
    fileContent: base64,
    fileType: entry.type,
    leaseName: (amendLeaseData && amendLeaseData.array_leasename) || "",
  };

  // 90s timeout — Power Automate flows can take 30-60s legitimately,
  // but anything beyond 90s indicates the flow is stuck.
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), 90000);
  let resp;
  try {
    resp = await fetch(AI_EXTRACT_FLOW_URL, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(payload),
      signal: controller.signal,
    });
  } catch (e) {
    clearTimeout(timer);
    if (e.name === "AbortError") {
      throw new Error(
        "Extraction flow timed out after 90 seconds. Please try again or contact support if the issue persists.",
      );
    }
    throw e;
  }
  clearTimeout(timer);

  if (!resp.ok) {
    throw new Error(
      `Extraction flow failed: HTTP ${resp.status} ${resp.statusText}`,
    );
  }

  // Tolerant parse: response may be JSON, or text containing JSON,
  // or a wrapper with a stringified body.
  const raw = await resp.text();
  let data = raw;
  try {
    data = JSON.parse(raw);
  } catch (e) {
    /* leave as text */
  }
  if (data && typeof data.body === "string") {
    try {
      data = JSON.parse(data.body);
    } catch (e) {
      /* keep */
    }
  }
  // Flow returns a single-element array — unwrap to the object.
  if (Array.isArray(data)) data = data[0] || {};

  // Detect Power Automate tracking/throttle envelope, e.g.
  // {"acc":0,"rej":1,"efi":{"EventLevelThrottling":[0]}} — this is NOT
  // the extraction result. The flow accepted nothing / rejected the run.
  if (
    data &&
    typeof data === "object" &&
    ("acc" in data || "rej" in data) &&
    !("amendmentDate" in data)
  ) {
    const rej = data.rej != null ? data.rej : "?";
    throw new Error(
      `Flow did not return extraction data (rejected: ${rej}). ` +
        `The flow appears to be throttling or running asynchronously — ` +
        `it must return the extraction JSON in the HTTP response. ` +
        `Raw: ${raw.slice(0, 200)}`,
    );
  }

  // Sanity: a real extraction has at least one known field.
  const looksLikeExtraction =
    data &&
    typeof data === "object" &&
    ("amendmentDate" in data ||
      "amendmentTypes" in data ||
      "discounts" in data ||
      "charges" in data ||
      "format_detected" in data);
  if (!looksLikeExtraction) {
    throw new Error(
      `Unexpected flow response (no extraction fields found). ` +
        `Raw: ${raw.slice(0, 200)}`,
    );
  }

  return data;
}

// ── Map extracted JSON → header inputs (this pass: header only) ──
function ai_applyPrefill(data) {
  if (!data || typeof data !== "object") return 0;
  const val = (f) =>
    data[f] && data[f].value != null ? String(data[f].value) : "";

  // Amendment Date: use extracted value, else default to today (YYYY-MM-DD).
  let amendmentDate = val("amendmentDate");
  if (!amendmentDate) {
    const t = new Date();
    amendmentDate =
      t.getFullYear() +
      "-" +
      String(t.getMonth() + 1).padStart(2, "0") +
      "-" +
      String(t.getDate()).padStart(2, "0");
  }

  const map = [
    ["amend_startDate", val("effectiveDate")],
    ["amend_endDate", val("newLeaseExpiryDate")],
    ["amend_description", val("description")],
  ];

  let filled = 0;
  map.forEach(([id, value]) => {
    if (!value) return;
    const el = document.getElementById(id);
    if (!el) return;
    el.value = el.type === "date" ? value.substring(0, 10) : value;
    el.dispatchEvent(new Event("input", { bubbles: true }));
    el.dispatchEvent(new Event("change", { bubbles: true }));
    filled++;
  });

  // Amendment Date LAST — the effective-date "change" listener sets a max on
  // amend_moveInDate and clears any date after the effective date. We set it
  // after that listener has run and lift the max so a valid extracted date
  // (which may legitimately differ from the effective date) is not wiped.
  if (amendmentDate) {
    const adEl = document.getElementById("amend_moveInDate");
    if (adEl) {
      adEl.removeAttribute("max");
      adEl.value = amendmentDate.substring(0, 10);
      adEl.dispatchEvent(new Event("input", { bubbles: true }));
      adEl.dispatchEvent(new Event("change", { bubbles: true }));
      filled++;
    }
  }
  return filled;
}

// ══════════════════════════════════════════════════════════════
//  AI ARRAY PREFILL — write discounts / charges / (typed) clauses
//  Option A: resolve what we can by label, blank + flag the rest.
//  Rows flagged with _aiIncomplete must be opened & completed by
//  the user before final submit.
// ══════════════════════════════════════════════════════════════

// Pull a {value} leaf or a raw scalar.
function ai_leaf(x) {
  if (x == null) return "";
  if (typeof x === "object" && "value" in x)
    return x.value == null ? "" : x.value;
  return x;
}

// Resolve a recurring-charge GUID by fuzzy label match against loaded charges.
function ai_resolveChargeGuid(label) {
  if (!label) return null;
  const norm = String(label).toLowerCase();
  const pool = Array.isArray(amendCharges) ? amendCharges : [];
  const hit = pool.find((c) => {
    const n = (c.array_chargename || "").toLowerCase();
    return (
      n && (n === norm || n.indexOf(norm) !== -1 || norm.indexOf(n) !== -1)
    );
  });
  return hit ? hit.array_recurringchargeid || null : null;
}

// Resolve a currency GUID by ISO code (e.g. "PLN") against loaded currencies.
function ai_resolveCurrencyGuid(code) {
  if (!code) return null;
  const norm = String(code).toUpperCase();
  const pool = Array.isArray(amendCurrencies) ? amendCurrencies : [];
  const hit = pool.find(
    (c) =>
      (c.isocurrencycode || c.currencyname || "")
        .toUpperCase()
        .indexOf(norm) !== -1,
  );
  return hit ? hit.transactioncurrencyid || null : null;
}

// Amendment effective date — fallback end-date when the AI record doesn't carry one.
function ai_amendmentEffectiveDate() {
  const el = document.getElementById("amend_startDate");
  return (el && el.value ? el.value : "").substring(0, 10);
}

// Honor "explicitDelete: true" by end-dating the matching existing record on the
// amendment effective date (or the record's own start/effective date if present).
// Mirrors the user-initiated deactivation flow: pushes to amendDeactivated* and
// removes from amendExisting*. Returns true if the record was handled (caller
// must NOT also create a new record), false otherwise.
function ai_applyExplicitDelete(table, F, recordEffectiveDate, report) {
  const endDate = (
    recordEffectiveDate ||
    ai_amendmentEffectiveDate() ||
    ""
  ).substring(0, 10);
  if (!report._deleted)
    report._deleted = { charges: 0, clauses: 0, discounts: 0, deposits: 0 };
  if (!Array.isArray(report.skippedDeletes)) report.skippedDeletes = [];

  if (table === "charges") {
    const extName = F("chargeName") || F("chargeType") || F("name") || "";
    const match = ai_matchExistingCharge(extName, F("chargeType"));
    if (!match) {
      report.skippedDeletes.push(`charge: ${extName || "(unnamed)"}`);
      return true;
    }
    const idx = amendExistingCharges.findIndex(
      (c) => c.array_recurringchargeid === match.array_recurringchargeid,
    );
    if (idx === -1) {
      report.skippedDeletes.push(`charge: ${extName}`);
      return true;
    }
    const deact = {
      ...amendExistingCharges[idx],
      _pendingDeactivate: true,
      _deactivateProration: false,
      _deactivateEndDate: endDate,
      array_enddate: endDate,
    };
    amendDeactivatedCharges.push(deact);
    amendExistingCharges.splice(idx, 1);
    amendCharges = [...amendExistingCharges, ...amendNewCharges];
    report._deleted.charges++;
    return true;
  }

  if (table === "clauses") {
    const clauseTypeLabel = String(F("clauseType") || "").toLowerCase();
    const idx = amendClauses.findIndex((c) => {
      const t = String(
        c.array_clausetype_label || c._clauseTypeLabel || c.clauseType || "",
      ).toLowerCase();
      return (
        t &&
        clauseTypeLabel &&
        (t === clauseTypeLabel ||
          t.indexOf(clauseTypeLabel) !== -1 ||
          clauseTypeLabel.indexOf(t) !== -1)
      );
    });
    if (idx === -1) {
      report.skippedDeletes.push(`clause: ${clauseTypeLabel || "(untyped)"}`);
      return true;
    }
    const deact = {
      ...amendClauses[idx],
      _pendingDeactivate: true,
      _newExpiryDate: endDate,
      array_expirydate: endDate,
    };
    amendDeactivatedClauses.push(deact);
    amendClauses.splice(idx, 1);
    report._deleted.clauses++;
    return true;
  }

  if (table === "discounts") {
    const startDate = (F("periodStart") || F("startDate") || "")
      .toString()
      .substring(0, 10);
    const idx = amendExistingDiscounts.findIndex((d) => {
      const sd = (d.array_startdate || "").substring(0, 10);
      return startDate && sd === startDate;
    });
    if (idx === -1) {
      report.skippedDeletes.push(`discount @ ${startDate || "(no date)"}`);
      return true;
    }
    const deact = {
      ...amendExistingDiscounts[idx],
      _pendingDeactivate: true,
      _deactivateEndDate: endDate,
      array_enddate: endDate,
    };
    amendDeactivatedDiscounts.push(deact);
    amendExistingDiscounts.splice(idx, 1);
    report._deleted.discounts++;
    return true;
  }

  if (table === "deposits") {
    // Deposits have no deactivation flow in this UI — record but skip.
    report.skippedDeletes.push(
      `deposit (deposits do not support delete in this form)`,
    );
    return true;
  }
  return false;
}

function ai_writeDiscounts(arr, report) {
  if (!Array.isArray(arr) || !arr.length) return;
  arr.forEach((d) => {
    const v = d.value || d;
    // Read a field from new shape (fields.* / matchKey.*) or old flat shape.
    const F = (name) => {
      if (v[name] !== undefined) return ai_leaf(v[name]);
      if (v.fields && v.fields[name] !== undefined)
        return ai_leaf(v.fields[name]);
      if (v.matchKey && v.matchKey[name] !== undefined)
        return ai_leaf(v.matchKey[name]);
      return "";
    };

    if (d.explicitDelete === true || v.explicitDelete === true) {
      if (
        ai_applyExplicitDelete(
          "discounts",
          F,
          F("periodStart") || F("startDate"),
          report,
        )
      ) {
        if (typeof disc_renderDiscountsTable === "function")
          disc_renderDiscountsTable();
        return;
      }
    }

    const chargeLabel =
      F("affectedCharge") || F("chargeType") || F("discountName") || "";

    // Explicit type if provided ("Percentage"/"Flat"); else infer from "%".
    const typeRaw = String(F("discountType") || "").toLowerCase();
    const valueRaw = String(
      F("discountValue") ||
        F("discountPercentage") ||
        F("amount") ||
        F("discountName") ||
        "",
    );
    const numMatch = valueRaw.match(/(\d+(?:\.\d+)?)/);
    const pct = numMatch ? parseFloat(numMatch[1]) : 0; // numeric, never null

    let discountType;
    if (typeRaw.indexOf("percent") !== -1) discountType = 126330001;
    else if (typeRaw === "flat" || typeRaw.indexOf("fixed") !== -1)
      discountType = 126330000;
    else discountType = /%|percent/i.test(valueRaw) ? 126330001 : 126330000;

    // Default charge type: Specific Charge if the AI-extracted charge label
    // resolves to a known recurring charge; otherwise All Charges. Prevents
    // the discount from staging with a null charge type (which the modal
    // then forced the user to pick manually).
    const resolvedChargeGuid = ai_resolveChargeGuid(chargeLabel);
    const record = {
      array_chargetype: resolvedChargeGuid
        ? DISC_CHARGE_SPECIFIC_CHARGE
        : DISC_CHARGE_ALL,
      array_discounttype: discountType, // integer, matches DISC_TYPE_*
      array_discountpercentage: pct, // numeric
      array_discountamount: discountType === 126330001 ? null : pct,
      array_startdate:
        F("periodStart") || F("startDate") || ai_leaf(d.effectiveDate) || "",
      array_enddate: F("periodEnd") || F("endDate") || "",
      _chargeTypeCategoryId: null,
      _recurringChargeId: resolvedChargeGuid,
      _aiIncomplete: true,
      _aiNote: F("description") || F("clauseSummary") || "",
    };
    amendNewDiscounts.push(record);
    report.discounts++;
  });
  if (typeof disc_renderDiscountsTable === "function")
    disc_renderDiscountsTable();
}

// ── AI value → Dataverse lookups (exact matches only; else null = user picks) ──
// Charge type: "RHAN - Rent - retail space" → code "RHAN" → array_chargetype by array_name.
function ai_resolveChargeType(label) {
  const raw = String(label || "").trim();
  if (!raw) return null;
  const code = raw.split(" - ")[0].trim().toLowerCase();
  const list = Array.isArray(amendChargeTypes) ? amendChargeTypes : [];
  const hit =
    list.find(
      (ct) =>
        String(ct.array_name || "")
          .trim()
          .toLowerCase() === code,
    ) ||
    list.find(
      (ct) =>
        String(ct.array_name || "")
          .trim()
          .toLowerCase() === raw.toLowerCase(),
    );
  return hit ? { id: hit.array_chargetypeid, name: hit.array_name } : null;
}
// Frequency: "Monthly" → option value by exact label.
function ai_resolveFrequency(label) {
  const raw = String(label || "")
    .trim()
    .toLowerCase();
  if (!raw) return null;
  const opts = Array.isArray(amendFrequencies) ? amendFrequencies : [];
  const lbl = (o) =>
    String(
      o.Label?.UserLocalizedLabel?.Label ||
        o.Label?.LocalizedLabels?.[0]?.Label ||
        "",
    ).trim();
  const hit = opts.find((o) => lbl(o).toLowerCase() === raw);
  return hit ? { value: parseInt(hit.Value, 10), name: lbl(hit) } : null;
}
// VAT: 23 → the single active VAT record with array_vat = 23 (ambiguous → null).
function ai_resolveVat(pct) {
  const n = parseFloat(pct);
  if (isNaN(n)) return null;
  const hits = (Array.isArray(amendVATs) ? amendVATs : []).filter(
    (v) => parseFloat(v.array_vat) === n,
  );
  if (hits.length !== 1) return null;
  const v = hits[0];
  return {
    id: v.array_vatid,
    name: v.array_name + (v.array_vat != null ? ` (${v.array_vat}%)` : ""),
  };
}
// Total area (m²) of the lease's active units — same basis as Smart Suggestions.
function ai_leaseUnitArea() {
  return (Array.isArray(amendExistingUnits) ? amendExistingUnits : []).reduce(
    (sum, u) => sum + (parseFloat(u.array_Unit?.array_unitareasqm) || 0),
    0,
  );
}
// Option holder: "Landlord" / "Tenant" / "Mutual" → option value by exact label.
function ai_resolveOptionHolder(label) {
  const raw = String(label || "")
    .trim()
    .toLowerCase();
  if (!raw) return null;
  const opts = Array.isArray(ao_optionHolderChoices)
    ? ao_optionHolderChoices
    : [];
  const lbl = (o) =>
    String(
      o.Label?.UserLocalizedLabel?.Label ||
        o.Label?.LocalizedLabels?.[0]?.Label ||
        "",
    ).trim();
  const hit = opts.find((o) => lbl(o).toLowerCase() === raw);
  return hit ? { value: parseInt(hit.Value, 10), name: lbl(hit) } : null;
}

function ai_writeCharges(arr, report) {
  if (!Array.isArray(arr) || !arr.length) return;

  // Proposed supersessions/edits awaiting user confirmation (filled here,
  // committed by ai_confirmSupersessions()).
  if (!Array.isArray(window._aiProposedChargeActions))
    window._aiProposedChargeActions = [];

  arr.forEach((c) => {
    const v = c.value || c;
    const F = (name) => {
      if (v[name] !== undefined) return ai_leaf(v[name]);
      if (v.fields && v.fields[name] !== undefined)
        return ai_leaf(v.fields[name]);
      if (v.matchKey && v.matchKey[name] !== undefined)
        return ai_leaf(v.matchKey[name]);
      return "";
    };

    if (c.explicitDelete === true || v.explicitDelete === true) {
      if (ai_applyExplicitDelete("charges", F, F("startDate"), report)) {
        if (typeof renderExistingChargesTable === "function")
          renderExistingChargesTable();
        if (typeof renderNewChargesTable === "function")
          renderNewChargesTable();
        if (typeof renderChargesTotals === "function") renderChargesTotals();
        if (typeof updateBadge === "function")
          updateBadge("charges", amendCharges.length);
        return;
      }
    }

    const extName =
      F("chargeName") || F("chargeType") || F("name") || "AI Charge";
    let extAmount = parseFloat(F("amount"));
    const extStart = (F("startDate") || ai_leaf(c.effectiveDate) || "")
      .toString()
      .substring(0, 10);
    const extEnd = (F("endDate") || "").toString().substring(0, 10);
    const extCurrGuid = ai_resolveCurrencyGuid(F("currency"));
    const freqRaw = String(F("frequency") || "").toLowerCase();
    const extDue = parseInt(F("dueInDays"), 10);
    const extCt = ai_resolveChargeType(F("chargeType"));
    const extFreq = ai_resolveFrequency(F("frequency"));
    const extVat = ai_resolveVat(F("vatPercent"));
    // Amount = rate per m² × area when the document gives only a rate.
    // Area: billableArea from the document, else the lease's unit area.
    const extRate = parseFloat(F("ratePerSqM"));
    let extArea = parseFloat(F("billableArea"));
    let extAmountNote = "";
    if (isNaN(extAmount) && !isNaN(extRate) && extRate > 0) {
      if (isNaN(extArea) || extArea <= 0) extArea = ai_leaseUnitArea();
      if (extArea > 0) {
        extAmount = Math.round(extRate * extArea * 100) / 100;
        extAmountNote = `Amount = ${extRate} × ${extArea} m² (unit area)`;
      }
    }
    if (isNaN(extArea) || extArea <= 0) extArea = null;

    // ── Try to match an existing active charge ────────────────────────
    const match = ai_matchExistingCharge(extName, F("chargeType"));

    if (match) {
      // Decide: end-date-only change → in-place edit; else → supersede.
      const onlyEndDateChanged = ai_isEndDateOnlyChange(match, {
        amount: extAmount,
        currencyGuid: extCurrGuid,
        dueInDays: extDue,
        endDate: extEnd,
      });

      window._aiProposedChargeActions.push({
        kind: onlyEndDateChanged ? "edit" : "supersede",
        existingId: match.array_recurringchargeid,
        existingName: match.array_chargename,
        effectiveDate: extStart || "", // new charge start / old charge cutoff basis
        ext: {
          name: extName,
          amount: isNaN(extAmount) ? null : extAmount,
          startDate: extStart,
          endDate: extEnd,
          currencyGuid: extCurrGuid,
          dueInDays: isNaN(extDue) ? null : extDue,
          freqNote: freqRaw,
          note: [F("description") || "", extAmountNote]
            .filter(Boolean)
            .join(" | "),
          chargeType: extCt,
          frequency: extFreq,
          vat: extVat,
          billableArea: extArea,
        },
      });
      report.proposedCharges = (report.proposedCharges || 0) + 1;
      return; // do NOT create a plain new charge for a matched item
    }

    // Dedup: skip if amendNewCharges already has this charge (same name + startDate).
    // Critical for edit-mode re-runs where prior-session AI rows live in amendNewCharges,
    // not amendExistingCharges, so ai_matchExistingCharge can't find them.
    const dupNewCharge = (
      Array.isArray(amendNewCharges) ? amendNewCharges : []
    ).find(function (r) {
      return (
        r &&
        String(r.array_chargename || "")
          .toLowerCase()
          .trim() ===
          String(extName || "")
            .toLowerCase()
            .trim() &&
        String(r.array_startdate || "").substring(0, 10) ===
          String(extStart || "").substring(0, 10)
      );
    });
    if (dupNewCharge) {
      report.skippedDuplicates = (report.skippedDuplicates || 0) + 1;
      return;
    }

    // ── No match → create a fresh new charge (original behaviour) ─────
    const id = "pending_ai_" + Date.now() + "_" + report.charges;
    const row = {
      array_recurringchargeid: id,
      array_chargename: extName,
      array_amount: isNaN(extAmount) ? 0 : extAmount,
      array_startdate: extStart,
      array_enddate: extEnd,
      array_frequency: extFreq ? extFreq.value : null,
      array_dueindays: isNaN(extDue) ? null : extDue,
      array_invoicegenerationdate: "",
      array_prorationenabled: false,
      array_billablearea: extArea || 0,
      _transactioncurrencyid_value: extCurrGuid,
      array_Unit: null,
      array_ChargeType: extCt
        ? { array_chargetypeid: extCt.id, array_name: extCt.name }
        : null,
      _isPending: true,
      _aiIncomplete: true,
      _aiNote: [
        F("description"),
        extAmountNote,
        freqRaw ? "Frequency: " + freqRaw : "",
      ]
        .filter(Boolean)
        .join(" | "),
    };
    const payload = {
      id,
      array_chargename: extName,
      array_amount: isNaN(extAmount) ? 0 : extAmount,
      array_startdate: extStart,
      array_enddate: extEnd,
      // saveAmendments reads charge.currency when building the @odata.bind.
      // Manually-created charges set it in saveAddCharge. AI-created ones
      // were only setting _transactioncurrencyid_value, leaving currency
      // undefined → "/transactioncurrencies(undefined)" 400 at save time.
      currency: extCurrGuid || null,
      _transactioncurrencyid_value: extCurrGuid,
      // Same keys the Add/Edit Charge modal reads and writes, so the modal
      // opens prefilled. Row stays _aiIncomplete until the user saves it.
      name: extName,
      amount: isNaN(extAmount) ? 0 : extAmount,
      startDate: extStart,
      endDate: extEnd,
      chargeType: extCt ? extCt.id : "",
      chargeTypeName: extCt ? extCt.name : "",
      frequency: extFreq ? extFreq.value : null,
      frequencyName: extFreq ? extFreq.name : "",
      vat: extVat ? extVat.id : "",
      vatName: extVat ? extVat.name : "",
      billableArea: extArea || 0,
      dueInDays: isNaN(extDue) ? null : extDue,
      _aiIncomplete: true,
    };
    amendNewCharges.push(row);
    pendingNewCharges.push(payload);
    report.charges++;
  });

  amendCharges = [...amendExistingCharges, ...amendNewCharges];
  if (typeof renderNewChargesTable === "function") renderNewChargesTable();
  if (typeof renderChargesTotals === "function") renderChargesTotals();
  if (typeof updateBadge === "function")
    updateBadge("charges", amendCharges.length);
}

// Match an extracted charge to an existing active charge.
// Rule (per spec): ChargeType GUID match OR array_chargename contains the text.
function ai_matchExistingCharge(extName, extTypeLabel) {
  const pool = Array.isArray(amendExistingCharges) ? amendExistingCharges : [];
  if (!pool.length) return null;
  const needle = String(extTypeLabel || extName || "")
    .toLowerCase()
    .trim();
  if (!needle) return null;

  // Token set from the extracted label for contains-matching (handles the
  // bilingual "Minimum Guaranteed Rent (Czynsz Minimalny Gwarantowany)" form).
  const tokens = needle
    .replace(/[()]/g, " ")
    .split(/\s+/)
    .filter((t) => t.length > 3);

  return (
    pool.find((c) => {
      const cname = (c.array_chargename || "").toLowerCase();
      const ctype = (
        (c.array_ChargeType && c.array_ChargeType.array_name) ||
        ""
      ).toLowerCase();
      if (!cname && !ctype) return false;
      // direct contains either way
      if (
        cname &&
        (cname.indexOf(needle) !== -1 || needle.indexOf(cname) !== -1)
      )
        return true;
      if (
        ctype &&
        (ctype.indexOf(needle) !== -1 || needle.indexOf(ctype) !== -1)
      )
        return true;
      // token overlap (any distinctive token present in name or type)
      return tokens.some(
        (t) => cname.indexOf(t) !== -1 || ctype.indexOf(t) !== -1,
      );
    }) || null
  );
}

// True only when the ONLY difference vs the existing charge is the end date.
// Any change to amount, currency, or due-in-days → not end-date-only → supersede.
function ai_isEndDateOnlyChange(existing, ext) {
  const sameAmount =
    ext.amount == null || Number(ext.amount) === Number(existing.array_amount);
  const sameCurrency =
    !ext.currencyGuid ||
    ext.currencyGuid === existing._transactioncurrencyid_value;
  const sameDue =
    ext.dueInDays == null ||
    Number(ext.dueInDays) === Number(existing.array_dueindays);
  return sameAmount && sameCurrency && sameDue;
}

// ─────────────────────────────────────────────────────────────
//  SHARED SUPERSEDE HELPERS  (edit-existing = deactivate old + create new)
//  When a user edits an existing SAVED related record (charge, discount,
//  unit, deposit, clause, option), the widget supersedes it: the old record
//  is DEACTIVATED with its end/expiry/due date set to the amendment EFFECTIVE
//  DATE (same day — NOT effective date minus 1), and a NEW record is created
//  starting on the effective date carrying every unchanged value forward.
// ─────────────────────────────────────────────────────────────

// Read the amendment effective date (YYYY-MM-DD) from the widget, or "".
function getAmendmentEffectiveDate() {
  return document.getElementById("amend_startDate")?.value || "";
}

// Build a deactivation clone of an existing record for the supersede flow.
// `endField` is the entity's end/expiry/due date field (e.g. "array_enddate",
// "array_expirydate"); set to the effective date so the old record ends the
// same day the new record begins.
function buildSupersedeDeactivation(existing, endField, eff) {
  const deactivated = { ...existing, _pendingDeactivate: true };
  if (endField) deactivated[endField] = eff;
  return deactivated;
}

// Auto-supersede any existing active CPI/Step Rent clause on the same lease
// with the same charge type — mirrors the CRM form's checkExistingCPIClauseOnSave
// and checkExistingStepRentClauseOnSave guards. Turnover Rent is intentionally
// excluded (multiple concurrent turnover clauses per lease are allowed).
// Called from the new-clause create loop before createRecord.
async function cl_autoSupersedeDuplicateActiveClause(inst) {
  const cfg =
    inst.stepRentEnabled && inst.chargeTypeStepIncrease
      ? {
          chargeField: "_array_chargetypestepincrease_value",
          chargeId: inst.chargeTypeStepIncrease,
          label: "Step Rent",
        }
      : inst.indexationEnabled && inst.chargeTypeCPI
        ? {
            chargeField: "_array_chargetypecpi_value",
            chargeId: inst.chargeTypeCPI,
            label: "CPI",
          }
        : null;
  if (!cfg) return;
  const eff = getAmendmentEffectiveDate();
  if (!eff) return;
  try {
    const clientUrl = XrmCtx.Utility.getGlobalContext().getClientUrl();
    const filter = `_array_leaseagreement_value eq ${amendLeaseId} and ${cfg.chargeField} eq ${cfg.chargeId} and statecode eq 0`;
    const resp = await fetch(
      `${clientUrl}/api/data/v9.2/array_leaseclauses?$select=array_leaseclauseid,array_leaseclausename&$filter=${encodeURIComponent(filter)}`,
      {
        headers: {
          "OData-MaxVersion": "4.0",
          "OData-Version": "4.0",
          Accept: "application/json",
          Prefer: 'odata.include-annotations="*"',
        },
        credentials: "same-origin",
      },
    );
    if (!resp.ok) return;
    const data = await resp.json();
    for (const dup of data.value || []) {
      // Skip clauses the user has already explicitly deactivated in this session
      if (
        amendDeactivatedClauses.some(
          (c) => c.array_leaseclauseid === dup.array_leaseclauseid,
        )
      )
        continue;
      await XrmCtx.WebApi.updateRecord(
        "array_leaseclause",
        dup.array_leaseclauseid,
        {
          array_amendmentactions: 126330001,
          array_amendmentexpirydate: eff,
          "array_LeaseAmendment@odata.bind": `/array_leaseamendmentses(${newAmendmentId})`,
        },
      );
      // Deactivate associated CPI/Step adjustment schedules
      const schedEntities = [
        {
          entitySet: "array_cpiadjustmentschedules",
          entityLogicalName: "array_cpiadjustmentschedule",
          filter: `_array_leaseclause_value eq ${dup.array_leaseclauseid}`,
        },
        {
          entitySet: "array_stepadjustmentschedules",
          entityLogicalName: "array_stepadjustmentschedule",
          filter: `_array_leaseclause_value eq ${dup.array_leaseclauseid}`,
        },
      ];
      for (const {
        entitySet,
        entityLogicalName,
        filter: schedFilter,
      } of schedEntities) {
        try {
          const schedResp = await fetch(
            `${clientUrl}/api/data/v9.2/${entitySet}?$select=${entityLogicalName}id&$filter=${schedFilter} and statecode eq 0`,
            {
              headers: {
                "OData-MaxVersion": "4.0",
                "OData-Version": "4.0",
                Accept: "application/json",
                Prefer: 'odata.include-annotations="*"',
              },
              credentials: "same-origin",
            },
          );
          if (!schedResp.ok) continue;
          const schedData = await schedResp.json();
          for (const sched of schedData.value || []) {
            const pkField = Object.keys(sched).find(
              (k) =>
                k.endsWith("id") &&
                !k.startsWith("_") &&
                k !== "array_leaseagreementid",
            );
            if (!pkField) continue;
            const schedId = sched[pkField].replace(/[{}]/g, "");
            await XrmCtx.WebApi.updateRecord(entityLogicalName, schedId, {
              statecode: 1,
              statuscode: 2,
            });
          }
        } catch (schedErr) {
          console.warn(
            `⚠️ Could not deactivate schedules for ${entitySet}:`,
            schedErr,
          );
        }
      }
      console.log(
        `✅ Auto-superseded duplicate ${cfg.label} clause: ${dup.array_leaseclausename || dup.array_leaseclauseid}`,
      );
    }
  } catch (dupErr) {
    console.warn(`⚠️ Duplicate ${cfg.label} clause check failed:`, dupErr);
  }
}

// Commit confirmed proposals into the existing save arrays.
// edit      → in-place end-date edit on amendExistingCharges (_pendingEndDateEdit)
// supersede → old charge to amendDeactivatedCharges + new charge to
//             amendNewCharges/pendingNewCharges, carrying old data forward.
function ai_commitChargeActions(actions) {
  if (!Array.isArray(actions) || !actions.length) return;

  actions.forEach((a) => {
    const exIdx = amendExistingCharges.findIndex(
      (c) => c.array_recurringchargeid === a.existingId,
    );
    if (exIdx === -1) return;
    const existing = amendExistingCharges[exIdx];

    if (a.kind === "edit") {
      const newEnd = a.ext.endDate || a.effectiveDate || existing.array_enddate;
      amendExistingCharges[exIdx] = {
        ...existing,
        array_enddate: newEnd,
        _pendingEndDateEdit: true,
        _pendingEndDate: newEnd,
        _pendingLastCycleProration: false,
        _pendingProrationEnabled: existing.array_prorationenabled || false,
      };
      return;
    }

    // ── supersede ────────────────────────────────────────────────
    // Old charge end date = day before the amendment effective date.
    const eff = a.effectiveDate || a.ext.startDate || "";
    let oldEnd = eff;
    if (eff) {
      const d = new Date(eff + "T00:00:00");
      d.setDate(d.getDate() - 1);
      oldEnd = d.toISOString().substring(0, 10);
    }
    const deactivated = {
      ...existing,
      _pendingDeactivate: true,
      _deactivateProration: false,
      _deactivateEndDate: oldEnd || existing.array_enddate,
      array_enddate: oldEnd || existing.array_enddate,
      _supersededByAI: true,
    };
    amendDeactivatedCharges.push(deactivated);
    amendExistingCharges.splice(exIdx, 1);

    // New charge = old data + overlaid changes; end date carried forward
    // from the old charge's ORIGINAL end date (spec answer 3).
    const id =
      "pending_ai_sup_" + Date.now() + "_" + Math.floor(Math.random() * 1000);
    const newAmount =
      a.ext.amount != null ? a.ext.amount : existing.array_amount;
    const newCurr = a.ext.currencyGuid || existing._transactioncurrencyid_value;
    const newDue =
      a.ext.dueInDays != null ? a.ext.dueInDays : existing.array_dueindays;
    const newStart = eff || existing.array_startdate;
    const carriedEnd = existing.array_enddate || ""; // original end forward

    const row = {
      array_recurringchargeid: id,
      array_chargename: existing.array_chargename,
      array_amount: newAmount,
      array_startdate: newStart,
      array_enddate: carriedEnd,
      array_frequency: a.ext.frequency
        ? a.ext.frequency.value
        : existing.array_frequency != null
          ? existing.array_frequency
          : null,
      array_dueindays: newDue,
      array_invoicegenerationdate: "",
      array_prorationenabled: existing.array_prorationenabled || false,
      array_billablearea: existing.array_billablearea || 0,
      _transactioncurrencyid_value: newCurr,
      array_Unit: existing.array_Unit || null,
      array_ChargeType: existing.array_ChargeType || null,
      _isPending: true,
      _supersedesId: a.existingId,
      _aiIncomplete: true,
      _aiNote: [
        a.ext.note,
        a.ext.freqNote ? "Frequency: " + a.ext.freqNote : "",
        "Supersedes " + (existing.array_chargename || "existing charge"),
      ]
        .filter(Boolean)
        .join(" | "),
    };
    const payload = {
      id,
      array_chargename: existing.array_chargename,
      array_amount: newAmount,
      array_startdate: newStart,
      array_enddate: carriedEnd,
      // currency: name used by saveAmendments; mirror _transactioncurrencyid_value
      currency: newCurr || null,
      _transactioncurrencyid_value: newCurr,
      array_dueindays: newDue,
      _supersedesId: a.existingId,
      // Modal keys (prefill): new values from the document, else the old charge's.
      name: existing.array_chargename,
      amount: newAmount,
      startDate: newStart,
      endDate: carriedEnd,
      chargeType:
        (a.ext.chargeType && a.ext.chargeType.id) ||
        existing.array_ChargeType?.array_chargetypeid ||
        existing._array_chargetype_value ||
        "",
      chargeTypeName:
        (a.ext.chargeType && a.ext.chargeType.name) ||
        existing.array_ChargeType?.array_name ||
        "",
      frequency: a.ext.frequency
        ? a.ext.frequency.value
        : existing.array_frequency != null
          ? existing.array_frequency
          : null,
      frequencyName: a.ext.frequency ? a.ext.frequency.name : "",
      vat: a.ext.vat ? a.ext.vat.id : "",
      vatName: a.ext.vat ? a.ext.vat.name : "",
      billableArea: a.ext.billableArea || existing.array_billablearea || 0,
      dueInDays: newDue,
      _aiIncomplete: true,
    };
    amendNewCharges.push(row);
    pendingNewCharges.push(payload);
  });

  amendCharges = [...amendExistingCharges, ...amendNewCharges];
  if (typeof renderExistingChargesTable === "function")
    renderExistingChargesTable();
  if (typeof renderNewChargesTable === "function") renderNewChargesTable();
  if (typeof renderChargesTotals === "function") renderChargesTotals();
  if (typeof updateBadge === "function")
    updateBadge("charges", amendCharges.length);
}

// Confirmation modal listing proposed supersessions/edits. Resolves after the
// user confirms (commits) or skips (discards). Mirrors ai_confirmModal styling.
function ai_writeDeposits(arr, report) {
  if (!Array.isArray(arr) || !arr.length) return;
  if (typeof amendNewDeposits === "undefined") {
    console.warn("ai_writeDeposits: amendNewDeposits missing");
    return;
  }
  if (!Array.isArray(window._aiPendingDepositDisamb))
    window._aiPendingDepositDisamb = [];

  arr.forEach((d) => {
    const v = d.value || d;
    const F = (name) => {
      if (v[name] !== undefined) return ai_leaf(v[name]);
      if (v.fields && v.fields[name] !== undefined)
        return ai_leaf(v.fields[name]);
      if (v.matchKey && v.matchKey[name] !== undefined)
        return ai_leaf(v.matchKey[name]);
      return "";
    };

    if (d.explicitDelete === true || v.explicitDelete === true) {
      if (ai_applyExplicitDelete("deposits", F, null, report)) return;
    }

    const amount = parseFloat(F("amount")) || 0;
    const months = parseInt(F("monthsCovered"), 10);
    const cur = ai_depositCurrency(F("currency")); // {guid, code, symbol}
    const rawType = String(F("depositType") || "").toLowerCase();
    const note = F("description") || "";

    // Map document term -> {type, subType} option values. null = needs user.
    const m = ai_mapDepositType(rawType);

    // Dedup: skip if amendNewDeposits already has matching deposit.
    const dupNewDep = (
      Array.isArray(amendNewDeposits) ? amendNewDeposits : []
    ).find(function (r) {
      return (
        r &&
        r.array_type === m.type &&
        r.array_deposittype === m.subType &&
        Number(r.array_requiredamount) === Number(amount) &&
        (r._currencyId || null) === (cur.guid || null)
      );
    });
    if (dupNewDep) {
      report.skippedDuplicates = (report.skippedDuplicates || 0) + 1;
      return;
    }

    const base = {
      array_type: m.type,
      // Sub Type removed entirely — always null
      array_deposittype: null,
      array_requiredamount: amount,
      array_numberofpayments: isNaN(months) ? null : months,
      array_duedate: /^\d{4}-\d{2}-\d{2}/.test(String(F("dueDate") || ""))
        ? String(F("dueDate")).substring(0, 10)
        : null,
      // _currencyId is the property the save flow (saveAmendments) reads
      // when building array_RequiredAmountCurrency@odata.bind. Manually-
      // created deposits set this in saveDepositEdit; AI-extracted ones
      // were previously omitting it, producing "/transactioncurrencies(undefined)"
      // and a 0x80060888 query-syntax error at save time.
      _currencyId: cur.guid || null,
      _RequiredAmountCurrency_value: cur.guid,
      _transactioncurrencyid_value: cur.guid,
      // display fields the NEW deposits table reads:
      _typeLabel: m.typeLabel || "—",
      _subTypeLabel: "—",
      _currencyCode: cur.code || "—",
      _currencySymbol: cur.symbol || "",
      _unitName: "All Units",
      _isPending: true,
      _aiIncomplete: m.ambiguous || !cur.guid,
      _aiNote: note,
    };

    if (m.ambiguous) {
      // Defer: collect for the disambiguation modal. Push the record now so
      // it's visible (with — for type), resolve on confirm.
      base._aiNeedsType = true;
      const idx = amendNewDeposits.push(base) - 1;
      window._aiPendingDepositDisamb.push({
        depIndex: idx,
        label: rawType || "guarantee",
        amount,
        currencyCode: cur.code,
      });
    } else {
      amendNewDeposits.push(base);
    }
    report.deposits = (report.deposits || 0) + 1;
  });

  if (typeof renderDepositsTable === "function") renderDepositsTable();
  if (typeof renderDepositsTotals === "function") renderDepositsTotals();
  if (typeof updateBadge === "function")
    updateBadge(
      "deposits",
      (amendDeposits.length || 0) + amendNewDeposits.length,
    );
}

// Resolve currency for deposits. Only EURO and PLN exist in this environment.
function ai_depositCurrency(raw) {
  const s = String(raw || "").toUpperCase();
  let code = "";
  if (
    s.indexOf("PLN") !== -1 ||
    s.indexOf("ZŁOTY") !== -1 ||
    s.indexOf("ZLOTY") !== -1
  )
    code = "PLN";
  else if (s.indexOf("EUR") !== -1) code = "EUR"; // matches EUR and EURO
  const pool = Array.isArray(amendCurrencies) ? amendCurrencies : [];
  const hit = pool.find(
    (c) => (c.isocurrencycode || "").toUpperCase() === code,
  );
  return {
    guid: hit ? hit.transactioncurrencyid || null : null,
    code: code || "",
    symbol: hit
      ? hit.currencysymbol || ""
      : code === "EUR"
        ? "€"
        : code === "PLN"
          ? "zł"
          : "",
  };
}

// Map a document deposit/collateral term to option-set values.
// Returns {type, subType, typeLabel, subTypeLabel, ambiguous}.
// Collateral Types: BankGuarantee 126330000, LiabInsurance 126330001,
//   Notary777p4 126330002, PropertyInsurance 126330004, CorporateGuarantee 126330005,
//   Notary777p5 126330006, Deposit 126330007.
// Sub Types: Cash 126330000, BankGuarantee 126330001, LetterOfCredit 126330002,
//   SavingsBook 126330003, IndividualAccount 126330004, Pledge 126330005, ParentGuarantee 126330006.
function ai_mapDepositType(raw) {
  const s = String(raw || "").toLowerCase();
  const R = (type, subType, typeLabel, subTypeLabel, ambiguous) => ({
    type,
    subType,
    typeLabel,
    subTypeLabel,
    ambiguous: !!ambiguous,
  });

  // Notarial deed (art. 777 KPC): "Notary deed 777 p. 4 KPC" / "... p. 5 KPC"
  if (s.indexOf("notar") !== -1 || s.indexOf("777") !== -1) {
    if (/(p\.?|pkt\.?|point)\s*5\b/.test(s))
      return R(126330006, null, "Notary deed 777 p. 5 KPC", "—", false);
    if (/(p\.?|pkt\.?|point)\s*4\b/.test(s))
      return R(126330002, null, "Notary deed 777 p. 4 KPC", "—", false);
    return R(null, null, "—", "—", true);
  }

  // Cash deposit (Kaucja)
  if (
    s.indexOf("kaucj") !== -1 ||
    s.indexOf("cash") !== -1 ||
    s.indexOf("deposit") !== -1
  )
    return R(126330007, 126330000, "Deposit", "Cash", false);

  // Letter of credit
  if (s.indexOf("akredyt") !== -1 || s.indexOf("letter of credit") !== -1)
    return R(126330000, 126330002, "Bank Guarantee", "Letter of Credit", false);

  // Qualified guarantees
  const isGuarantee =
    s.indexOf("gwarancj") !== -1 || s.indexOf("guarantee") !== -1;
  if (isGuarantee) {
    if (s.indexOf("bankow") !== -1 || s.indexOf("bank") !== -1)
      return R(126330000, 126330001, "Bank Guarantee", "Bank Guarantee", false);
    if (
      s.indexOf("korporac") !== -1 ||
      s.indexOf("corporate") !== -1 ||
      s.indexOf("parent") !== -1
    )
      return R(
        126330005,
        126330006,
        "Corporate Guarantee",
        "Parent Guarantee",
        false,
      );
    // Unqualified guarantee -> ambiguous, ask user
    return R(null, null, "—", "—", true);
  }

  // Insurance
  if (s.indexOf("property") !== -1 || s.indexOf("nieruchom") !== -1)
    return R(126330004, null, "Property insurance", "—", false);
  if (s.indexOf("liab") !== -1 || s.indexOf("odpowiedzial") !== -1)
    return R(126330001, null, "Liab. Insurance", "—", false);

  // Unknown -> ambiguous (user decides)
  return R(null, null, "—", "—", true);
}

// Disambiguation modal: shown only when >=1 deposit is ambiguous (e.g. unqualified
// "Gwarancja"). Presents a Type dropdown per ambiguous deposit; Sub Type derived.
function ai_confirmDeposits() {
  return new Promise((resolve) => {
    const list = Array.isArray(window._aiPendingDepositDisamb)
      ? window._aiPendingDepositDisamb
      : [];
    if (!list.length) {
      resolve(0);
      return;
    }

    const rows = list
      .map((it, i) => {
        return (
          '<tr style="border-top:1px solid #eee;">' +
          '<td style="padding:8px 10px;font-size:12.5px;color:#111827;">' +
          pp_esc(it.label) +
          (it.amount
            ? " &middot; " +
              parseFloat(it.amount).toFixed(2) +
              " " +
              pp_esc(it.currencyCode || "")
            : "") +
          "</td>" +
          '<td style="padding:8px 10px;">' +
          '<select id="ai_depType_' +
          i +
          '" style="width:100%;padding:7px 8px;border:1px solid #CBD5E1;border-radius:7px;font-size:12.5px;">' +
          '<option value="bank">Bank Guarantee</option>' +
          '<option value="corporate">Corporate Guarantee</option>' +
          "</select>" +
          "</td>" +
          "</tr>"
        );
      })
      .join("");

    const overlay = document.createElement("div");
    overlay.id = "ai_depositModal";
    overlay.style.cssText =
      "position:fixed;inset:0;z-index:99998;display:flex;align-items:center;" +
      "justify-content:center;background:rgba(15,23,42,0.5);backdrop-filter:blur(2px);font-family:-apple-system,BlinkMacSystemFont,'Segoe UI','Segoe UI Variable',system-ui,Roboto,Helvetica,Arial,sans-serif;";
    overlay.innerHTML =
      '<div style="background:#fff;border-radius:14px;max-width:560px;width:92%;box-shadow:0 20px 50px rgba(0,0,0,0.3);overflow:hidden;">' +
      '<div style="padding:22px 24px 0;">' +
      '<h3 style="margin:0 0 6px;font-size:16px;font-weight:700;color:#111827;">Confirm guarantee type</h3>' +
      '<p style="margin:0 0 12px;font-size:13px;color:#4B5563;line-height:1.5;">' +
      "The document does not specify the guarantee type. Please choose so the collateral record is set correctly.</p>" +
      '<table style="width:100%;border-collapse:collapse;border:1px solid #eee;border-radius:8px;overflow:hidden;">' +
      '<thead><tr style="background:#f8fafc;">' +
      '<th style="text-align:left;padding:8px 10px;font-size:11px;color:#6b7280;text-transform:uppercase;">Deposit</th>' +
      '<th style="text-align:left;padding:8px 10px;font-size:11px;color:#6b7280;text-transform:uppercase;">Type</th>' +
      "</tr></thead><tbody>" +
      rows +
      "</tbody></table>" +
      "</div>" +
      '<div style="display:flex;gap:10px;justify-content:flex-end;padding:18px 24px 22px;">' +
      '<button id="ai_depConfirm" style="padding:9px 18px;border-radius:8px;border:none;background:#1C6BD4;color:#fff;font-size:13px;font-weight:600;cursor:pointer;">Confirm</button>' +
      "</div>" +
      "</div>";
    document.body.appendChild(overlay);

    const cleanup = (n) => {
      overlay.remove();
      window._aiPendingDepositDisamb = [];
      resolve(n);
    };
    overlay.querySelector("#ai_depConfirm").onclick = () => {
      list.forEach((it, i) => {
        const sel = document.getElementById("ai_depType_" + i);
        const choice = sel ? sel.value : "bank";
        const rec = amendNewDeposits[it.depIndex];
        if (!rec) return;
        if (choice === "corporate") {
          rec.array_type = 126330005;
          rec.array_deposittype = 126330006;
          rec._typeLabel = "Corporate Guarantee";
          rec._subTypeLabel = "Parent Guarantee";
        } else {
          rec.array_type = 126330000;
          rec.array_deposittype = 126330001;
          rec._typeLabel = "Bank Guarantee";
          rec._subTypeLabel = "Bank Guarantee";
        }
        rec._aiIncomplete = false;
        rec._aiNeedsType = false;
      });
      if (typeof renderDepositsTable === "function") renderDepositsTable();
      cleanup(list.length);
    };
  });
}

function ai_confirmSupersessions() {
  return new Promise((resolve) => {
    const actions = Array.isArray(window._aiProposedChargeActions)
      ? window._aiProposedChargeActions
      : [];
    if (!actions.length) {
      resolve(0);
      return;
    }

    const rows = actions
      .map((a) => {
        const kindLabel =
          a.kind === "edit"
            ? '<span style="color:#92400e;font-weight:700;">End date only</span>'
            : '<span style="color:#9d174d;font-weight:700;">Supersede</span>';
        const detail =
          a.kind === "edit"
            ? "New end date: " + (a.ext.endDate || a.effectiveDate || "—")
            : "Deactivate old, create new from " + (a.effectiveDate || "—");
        return (
          '<tr style="border-top:1px solid #eee;">' +
          '<td style="padding:8px 10px;font-size:12.5px;color:#111827;">' +
          pp_esc(a.existingName || "(charge)") +
          "</td>" +
          '<td style="padding:8px 10px;font-size:12.5px;">' +
          kindLabel +
          "</td>" +
          '<td style="padding:8px 10px;font-size:11.5px;color:#4B5563;">' +
          pp_esc(detail) +
          "</td>" +
          "</tr>"
        );
      })
      .join("");

    const overlay = document.createElement("div");
    overlay.id = "ai_supersedeModal";
    overlay.style.cssText =
      "position:fixed;inset:0;z-index:99998;display:flex;align-items:center;" +
      "justify-content:center;background:rgba(15,23,42,0.5);backdrop-filter:blur(2px);" +
      "font-family:-apple-system,BlinkMacSystemFont,'Segoe UI','Segoe UI Variable',system-ui,Roboto,Helvetica,Arial,sans-serif;";
    overlay.innerHTML =
      '<div style="background:#fff;border-radius:14px;max-width:600px;width:92%;' +
      'box-shadow:0 20px 50px rgba(0,0,0,0.3);overflow:hidden;">' +
      '<div style="padding:22px 24px 0;">' +
      '<h3 style="margin:0 0 6px;font-size:16px;font-weight:700;color:#111827;">' +
      "Existing charges affected by this amendment</h3>" +
      '<p style="margin:0 0 12px;font-size:13px;color:#4B5563;line-height:1.5;">' +
      "The document changes charges that already exist on this lease. " +
      "Confirm to apply. <strong>Supersede</strong> deactivates the old charge and " +
      "creates a new one carrying the existing data forward with the changes.</p>" +
      '<table style="width:100%;border-collapse:collapse;border:1px solid #eee;border-radius:8px;overflow:hidden;">' +
      '<thead><tr style="background:#f8fafc;">' +
      '<th style="text-align:left;padding:8px 10px;font-size:11px;color:#6b7280;text-transform:uppercase;">Charge</th>' +
      '<th style="text-align:left;padding:8px 10px;font-size:11px;color:#6b7280;text-transform:uppercase;">Action</th>' +
      '<th style="text-align:left;padding:8px 10px;font-size:11px;color:#6b7280;text-transform:uppercase;">Detail</th>' +
      "</tr></thead><tbody>" +
      rows +
      "</tbody></table>" +
      "</div>" +
      '<div style="display:flex;gap:10px;justify-content:flex-end;padding:18px 24px 22px;">' +
      '<button id="ai_supSkip" style="padding:9px 16px;border-radius:8px;border:1px solid #CBD5E1;' +
      'background:#fff;color:#374151;font-size:13px;font-weight:600;cursor:pointer;">Skip</button>' +
      '<button id="ai_supConfirm" style="padding:9px 18px;border-radius:8px;border:none;' +
      'background:#1C6BD4;color:#fff;font-size:13px;font-weight:600;cursor:pointer;">Confirm changes</button>' +
      "</div>" +
      "</div>";
    document.body.appendChild(overlay);

    const cleanup = (committed) => {
      overlay.remove();
      window._aiProposedChargeActions = [];
      resolve(committed);
    };
    overlay.querySelector("#ai_supConfirm").onclick = () => {
      ai_commitChargeActions(actions);
      cleanup(actions.length);
    };
    overlay.querySelector("#ai_supSkip").onclick = () => cleanup(0);
    overlay.onclick = (e) => {
      if (e.target === overlay) cleanup(0);
    };
  });
}

// ══════════════════════════════════════════════════════════════
//  AI → Lease Option routing
//  Renewal / Break (= termination) terms extracted from the
//  amendment PDF are LEASE OPTIONS, not clauses. They must reach
//  array_option in Dataverse:
//    • match an existing active option of the same type → stage EDIT
//    • no match → stage CREATE (amendNewOptions)
//  Only ONE active option per type is allowed (matches ao_saveOption
//  rule), so the type alone is the match key.
// ══════════════════════════════════════════════════════════════

// Resolve an option-type label to its array_optiontype integer.
// Renewal uses the known constant; Break/termination resolves to the "Break"
// option. In real annexes these terms appear as "Contract Cancellation",
// "right to terminate", "rozwiązać", "wypowiedzenie" — not the literal word
// "break" — so detection is deliberately broad. Returns { value, label } or
// null if the type can't be resolved (caller reports it rather than guessing).
function ai_resolveOptionType(rawLabel) {
  const norm = String(rawLabel || "")
    .toLowerCase()
    .trim();
  if (!norm) return null;

  const isRenewal =
    /renew|renewal|ren\b|ryy|r55|odnowien|przedłuż|przedluz/.test(norm);
  // Break covers: break, termination, (contract) cancellation, and the
  // Polish equivalents used in these leases. Also the source client codes
  // CLA / CTE / CLT (Contract cancellation — Landlord / Tenant).
  const isBreak =
    /break|terminat|cancellation|cancel|rozwiąz|rozwiaz|wypowiedz|\bcla\b|\bcte\b|\bclt\b/.test(
      norm,
    );

  const choices = Array.isArray(ao_optionTypeChoices)
    ? ao_optionTypeChoices
    : [];
  const optLabel = (o) =>
    (
      o.Label?.UserLocalizedLabel?.Label ||
      o.Label?.LocalizedLabels?.[0]?.Label ||
      String(o.Value)
    )
      .toLowerCase()
      .trim();

  // Renewal: prefer the known constant, but confirm it exists in metadata.
  if (isRenewal) {
    const hit =
      choices.find((o) => parseInt(o.Value, 10) === OPTION_TYPE_RENEWAL) ||
      choices.find((o) => optLabel(o).indexOf("renew") !== -1);
    if (hit) return { value: parseInt(hit.Value, 10), label: optLabel(hit) };
    // Constant is defined even if metadata didn't load — fall back to it.
    return { value: OPTION_TYPE_RENEWAL, label: "Renewal" };
  }

  // Break / termination: resolve to the "Break" choice by label.
  if (isBreak) {
    const hit =
      choices.find((o) => optLabel(o) === "break") ||
      choices.find((o) => optLabel(o).indexOf("break") !== -1) ||
      choices.find((o) => optLabel(o).indexOf("terminat") !== -1);
    if (hit) return { value: parseInt(hit.Value, 10), label: optLabel(hit) };
    return null; // can't resolve safely — caller reports as skipped
  }

  // Any other option label: try a direct fuzzy match.
  const hit = choices.find((o) => {
    const l = optLabel(o);
    return l === norm || l.indexOf(norm) !== -1 || norm.indexOf(l) !== -1;
  });
  return hit ? { value: parseInt(hit.Value, 10), label: optLabel(hit) } : null;
}

// Is this clause/option record a renewal or break/termination item?
// The TYPE LABEL is the primary signal and uses the broad vocabulary these
// terms appear under (incl. Polish + source codes CLA/CTE/CLT). The summary
// is only a weak fallback matched against STRONG, unambiguous option phrases —
// this prevents misrouting rent-calculation/reduction clauses (RCE/RRC/NTR)
// whose body text merely mentions "terminate" in passing.
function ai_isOptionLike(typeLabel, summary) {
  const label = String(typeLabel || "").toLowerCase();
  const labelRe =
    /renew|renewal|odnowien|przedłuż|przedluz|break|terminat|cancellation|cancel|rozwiąz|rozwiaz|wypowiedz|\bcla\b|\bcte\b|\bclt\b/;
  if (labelRe.test(label)) return true;

  // Strong summary phrases only — explicit option HEADERS, not stray mentions.
  // Deliberately excludes generic body phrases like "right to terminate",
  // which appear inside rent-calculation/reduction clause bodies (RCE/RRC).
  const sum = String(summary || "").toLowerCase();
  const strongRe =
    /right of contract cancellation|contract cancellation|prawo (?:do )?wypowiedzenia umowy|prawo (?:do )?rozwiązania umowy|right of renewal|renewal option|option to renew|break option|prawo do odnowienia/;
  return strongRe.test(sum);
}

// Is this clause record actually a DEPOSIT / collateral term? Deposits have a
// dedicated handler (ai_writeDeposits → amendNewDeposits) and wizard step, so
// they must never fall through to Additional Clauses. The TYPE LABEL is the
// primary signal; the summary is a weak fallback matched only against strong
// collateral phrases, to avoid catching rent clauses that merely reference a
// deposit in passing.
function ai_isDepositLike(typeLabel, summary) {
  const label = String(typeLabel || "").toLowerCase();
  // kaucj/gwarancj/akredyt = PL deposit/guarantee/letter-of-credit;
  // nieruchom/odpowiedzial = PL property/liability insurance.
  const labelRe =
    /deposit|kaucj|guarantee|gwarancj|collateral|letter of credit|akredyt|security (?:deposit|amount)|insurance|nieruchom|odpowiedzial/;
  if (labelRe.test(label)) return true;

  const sum = String(summary || "").toLowerCase();
  const strongRe =
    /security deposit|cash deposit|bank guarantee|corporate guarantee|parent guarantee|letter of credit|kaucj|gwarancj bankow|gwarancj korporac/;
  return strongRe.test(sum);
}

// Route ONE extracted option-like record into the option staging arrays.
// `F` is the field accessor (new {fields}/{matchKey} or flat shape).
// Returns true if handled (caller must not also dump to Additional Clauses).
function ai_routeOption(F, report) {
  if (!report.optionsCreated) report.optionsCreated = 0;
  if (!report.optionsEdited) report.optionsEdited = 0;
  if (!Array.isArray(report.skippedOptions)) report.skippedOptions = [];

  const rawType =
    F("optionType") || F("clauseType") || F("type") || F("name") || "";
  let resolved = ai_resolveOptionType(rawType);
  if (!resolved) {
    // The item may have qualified via its description (strong option phrase)
    // rather than its type field. Retry resolution against the summary text
    // so e.g. "Landlord Right of Contract Cancellation" maps to Break.
    const summaryText =
      F("description") || F("clauseSummary") || F("originalText") || "";
    resolved = ai_resolveOptionType(summaryText);
  }
  if (!resolved) {
    report.skippedOptions.push(String(rawType || "(untyped option)"));
    return false; // unresolved — let caller fall through to Additional Clauses
  }

  const typeInt = resolved.value;
  const typeLbl =
    resolved.label || ao_choiceLabel(ao_optionTypeChoices, typeInt);
  // OTH - Other is a catch-all type: several can coexist on one lease.
  const isOther = /^OTH\b/i.test(typeLbl || "");

  // Amendable fields from the extraction.
  const availFrom = (
    F("availableFrom") ||
    F("optionAvailableFrom") ||
    F("effectiveDate") ||
    ""
  )
    .toString()
    .substring(0, 10);
  const expiry = (
    F("expiryDate") ||
    F("optionExpiryDate") ||
    F("endDate") ||
    ""
  )
    .toString()
    .substring(0, 10);
  const noticeDeadline = (
    F("noticeSubmissionDeadline") ||
    F("noticeDeadline") ||
    ""
  )
    .toString()
    .substring(0, 10);
  const npRaw = F("noticePeriod") || F("noticePeriodDays") || "";
  const noticePeriod =
    String(npRaw).trim() !== "" && !isNaN(parseInt(npRaw, 10))
      ? parseInt(npRaw, 10)
      : null;
  const penRaw = F("penaltyAmount") || F("penalty") || "";
  const penalty =
    String(penRaw).trim() !== "" && !isNaN(parseFloat(penRaw))
      ? parseFloat(penRaw)
      : null;
  const holderRaw = F("optionHolder") || F("holder") || "";
  const description =
    F("description") || F("clauseSummary") || F("originalText") || "";
  const currencyGuid = ai_resolveCurrencyGuid(F("currency"));

  // ── Match an existing ACTIVE option by type (one-per-type rule) ──
  const existing = isOther
    ? null
    : (
        Array.isArray(amendExistingOptions) ? amendExistingOptions : []
      ).find((o) => parseInt(o.array_optiontype, 10) === typeInt);

  if (existing) {
    // Stage an EDIT of the existing DB record (deferred amendment Edit).
    // Skip if this option is already staged for deactivation this session.
    const alreadyDeact = (amendDeactivatedOptions || []).some(
      (o) =>
        o.array_optionid === existing.array_optionid && o._pendingDeactivate,
    );
    if (alreadyDeact) {
      report.skippedOptions.push(
        `${typeLbl} (already staged for deactivation)`,
      );
      return true;
    }
    // Dedup: collapse repeat extractions of the same existing option.
    const dupIdx = amendOptionEdits.findIndex(
      (e) => e.array_optionid === existing.array_optionid,
    );

    // Build a changes payload of only the fields the PDF actually provided.
    const changes = {};
    if (availFrom) changes.array_optionavailablefrom = availFrom;
    if (expiry) changes.array_optionexpirydate = expiry;
    if (noticeDeadline) changes.array_noticesubmissiondeadline = noticeDeadline;
    if (noticePeriod != null) changes.array_noticeperiod = noticePeriod;
    if (penalty != null) changes.array_penaltyamount = penalty;
    if (description) changes.array_description = description;

    if (Object.keys(changes).length === 0) {
      report.skippedOptions.push(`${typeLbl} (no changed fields)`);
      return true;
    }

    const editEntry = {
      array_optionid: existing.array_optionid,
      _optionTypeName: typeLbl,
      _newExpiryDate: expiry || existing.array_optionexpirydate || "",
      changes,
    };
    if (dupIdx >= 0) amendOptionEdits[dupIdx] = editEntry;
    else amendOptionEdits.push(editEntry);
    report.optionsEdited++;
  } else {
    // No existing option of this type → stage a CREATE.
    // Dedup against options already staged new this session.
    const dupNew = (amendNewOptions || []).some(
      (o) =>
        parseInt(o.array_optiontype, 10) === typeInt &&
        (!isOther || (o.array_optionexpirydate || "") === (expiry || "")),
    );
    if (dupNew) {
      report.skippedOptions.push(`${typeLbl} (already staged)`);
      return true;
    }
    const ccyObj = (amendCurrencies || []).find(
      (c) => c.transactioncurrencyid === currencyGuid,
    );
    const holder = ai_resolveOptionHolder(holderRaw); // exact label, else user picks
    // No deadline and no notice period stated -> the expiry date is the
    // last day to exercise the right, so use it as the deadline.
    const effDeadline = noticeDeadline || (noticePeriod == null ? expiry : "");
    amendNewOptions.push({
      array_optiontype: typeInt,
      array_optionholder: holder ? holder.value : null,
      array_optionavailablefrom: availFrom || null,
      array_optionexpirydate: expiry || null,
      array_noticeperiod: noticePeriod,
      array_noticesubmissiondeadline: effDeadline || null,
      array_penaltyamount: penalty,
      array_description: description,
      _currencyId: currencyGuid || null,
      _currencyCode: ccyObj ? ccyObj.isocurrencycode : "",
      _currencySymbol: ccyObj ? ccyObj.currencysymbol : "",
      _optionTypeName: typeLbl,
      _optionHolderName: holder ? holder.name : "",
      _pending: true,
      // Missing holder and/or required dates → surfaced in the options
      // tab so the user completes before final submit (same convention
      // as AI-created charges/clauses).
      _aiIncomplete: !availFrom || !expiry || !effDeadline || !holder,
      _aiNote: description || "",
    });
    report.optionsCreated++;
  }
  return true;
}

// Entry point for a dedicated data.options array (if the flow sends one).
async function ai_writeOptions(arr, report) {
  if (!Array.isArray(arr) || !arr.length) return;
  // Option-type resolution needs the GlobalOptionSet metadata, which is
  // otherwise loaded lazily on first options-tab visit. Ensure it's present.
  try {
    if (typeof ao_loadChoices === "function") await ao_loadChoices();
  } catch (e) {
    console.warn("ao_loadChoices (ai_writeOptions):", e);
  }

  arr.forEach((o) => {
    const v = o.value || o;
    const F = (name) => {
      if (v[name] !== undefined) return ai_leaf(v[name]);
      if (v.fields && v.fields[name] !== undefined)
        return ai_leaf(v.fields[name]);
      if (v.matchKey && v.matchKey[name] !== undefined)
        return ai_leaf(v.matchKey[name]);
      return "";
    };
    // explicitDelete on an option → stage the existing one for deactivation.
    if (o.explicitDelete === true || v.explicitDelete === true) {
      const resolved = ai_resolveOptionType(
        F("optionType") || F("clauseType") || F("type"),
      );
      if (resolved) {
        const ex = (amendExistingOptions || []).find(
          (x) => parseInt(x.array_optiontype, 10) === resolved.value,
        );
        if (ex) {
          const idx = amendExistingOptions.findIndex(
            (x) => x.array_optionid === ex.array_optionid,
          );
          const endDate = (
            F("expiryDate") ||
            ai_amendmentEffectiveDate() ||
            ""
          ).substring(0, 10);
          amendDeactivatedOptions.push({
            ...ex,
            _pendingDeactivate: true,
            _newExpiryDate: endDate,
          });
          if (idx >= 0) amendExistingOptions.splice(idx, 1);
          if (!report.skippedOptions) report.skippedOptions = [];
          return;
        }
      }
    }
    ai_routeOption(F, report);
  });

  if (typeof ao_renderNewOptionsTable === "function")
    ao_renderNewOptionsTable();
  if (typeof ao_renderExistingOptionsTable === "function")
    ao_renderExistingOptionsTable();
  if (typeof updateBadge === "function")
    updateBadge(
      "options",
      amendExistingOptions.length + amendNewOptions.length,
    );
}

function ai_writeClauses(arr, report) {
  if (!Array.isArray(arr) || !arr.length) return;
  // Only these 3 clause types exist in array_clausetype (required lookup).
  // Anything else is reported as skipped — never created (would be un-saveable).
  const TYPED = {
    "step rent indexation": "Step Rent Indexation",
    "value protection (cpi)": "Value Protection (CPI)",
    "turnover rent": "Turnover Rent",
  };
  arr.forEach((cl) => {
    const v = cl.value || cl;
    const F = (name) => {
      if (v[name] !== undefined) return ai_leaf(v[name]);
      if (v.fields && v.fields[name] !== undefined)
        return ai_leaf(v.fields[name]);
      if (v.matchKey && v.matchKey[name] !== undefined)
        return ai_leaf(v.matchKey[name]);
      return "";
    };
    const clauseTypeLabel = String(F("clauseType") || "").trim();
    const summary =
      F("description") || F("clauseSummary") || F("originalText") || "";
    const effDate = (F("effectiveDate") || ai_leaf(cl.effectiveDate) || "")
      .toString()
      .substring(0, 10);
    const expDate = (F("endDate") || F("expiryDate") || "")
      .toString()
      .substring(0, 10);

    if (cl.explicitDelete === true || v.explicitDelete === true) {
      if (ai_applyExplicitDelete("clauses", F, effDate, report)) {
        if (typeof cl_renderClausesTable === "function")
          cl_renderClausesTable();
        if (typeof cl_updateClauseCounters === "function")
          cl_updateClauseCounters();
        return;
      }
    }
    const hay = (clauseTypeLabel + " " + summary).toLowerCase();
    const typeKey = Object.keys(TYPED).find((k) => hay.indexOf(k) !== -1);

    if (!typeKey) {
      // ── Renewal / Break (termination) are LEASE OPTIONS, not clauses ──
      // Reroute them to array_option staging so they persist to Dataverse,
      // instead of dead-ending in the (non-persisted) Additional Clauses bin.
      if (ai_isOptionLike(clauseTypeLabel, summary)) {
        if (ai_routeOption(F, report)) {
          if (typeof ao_renderNewOptionsTable === "function")
            ao_renderNewOptionsTable();
          if (typeof ao_renderExistingOptionsTable === "function")
            ao_renderExistingOptionsTable();
          if (typeof updateBadge === "function")
            updateBadge(
              "options",
              amendExistingOptions.length + amendNewOptions.length,
            );
          return;
        }
        // ai_routeOption returned false (type unresolved) → fall through
        // to Additional Clauses so the term is at least visible.
      }
      // ── Deposit / collateral term mislabeled as a clause ──────────────
      // Deposits have their own handler + wizard step and must never land
      // in Additional Clauses. Reroute into the deposit pipeline.
      if (ai_isDepositLike(clauseTypeLabel, summary)) {
        // Reshape into the deposit JSON shape ai_writeDeposits expects.
        const depType = (function () {
          const t = String(clauseTypeLabel || "").toLowerCase();
          // If the type label itself isn't a deposit word, fall back to
          // scanning the summary so ai_mapDepositType can classify it.
          const re =
            /deposit|kaucj|guarantee|gwarancj|collateral|letter of credit|akredyt|insurance|nieruchom|odpowiedzial/;
          return re.test(t)
            ? clauseTypeLabel
            : summary || clauseTypeLabel || "";
        })();
        const depRecord = {
          fields: {
            depositType: depType,
            amount: F("amount") || F("requiredAmount") || "",
            currency: F("currency") || "",
            monthsCovered: F("monthsCovered") || F("numberOfPayments") || "",
            description: summary || "",
          },
        };
        try {
          ai_writeDeposits([depRecord], report);
          return;
        } catch (e) {
          console.warn("deposit reroute from clause failed:", e);
          // fall through to Additional Clauses if rerouting errored
        }
      }
      // Not one of the 3 supported financial-clause types.
      // Route to the "Additional Clauses" step for UI display (storage TBD).
      // Still reported in skippedClauses so the banner reminds the user this
      // record won't be persisted on save yet.
      const flat = {
        clauseType: clauseTypeLabel || "Unnamed clause",
        effectiveDate: effDate || null,
        expiryDate: expDate || null,
        description: summary || null,
      };
      // Preserve any other AI-returned fields (e.g. noticePeriod, abatementDays).
      if (v.fields && typeof v.fields === "object") {
        Object.keys(v.fields).forEach((k) => {
          if (flat[k] === undefined) flat[k] = ai_leaf(v.fields[k]);
        });
      }
      if (cl.sourceText || v.sourceText)
        flat.sourceText = cl.sourceText || v.sourceText;
      if (!Array.isArray(amendAdditionalClauses)) amendAdditionalClauses = [];
      amendAdditionalClauses.push(flat);
      if (typeof renderAdditionalClauses === "function")
        renderAdditionalClauses();
      report.skippedClauses.push(clauseTypeLabel || "Unnamed clause");
      return;
    }

    const clauseType = TYPED[typeKey];

    // Dedup: skip if amendNewClauses already has same type + effectiveDate.
    const dupNewClause = (
      Array.isArray(amendNewClauses) ? amendNewClauses : []
    ).find(function (r) {
      return (
        r &&
        r.clauseType === clauseType &&
        String(r.effectiveDate || "").substring(0, 10) ===
          String(effDate || "").substring(0, 10)
      );
    });
    if (dupNewClause) {
      report.skippedDuplicates = (report.skippedDuplicates || 0) + 1;
      return;
    }

    const instTypeKey =
      clauseType === "Step Rent Indexation"
        ? "stepRentInstances"
        : clauseType === "Value Protection (CPI)"
          ? "cpiInstances"
          : "turnoverInstances";
    const inst = {
      effectiveDate: effDate,
      expiryDate: expDate,
      description: summary,
      clauseSummary: summary,
      unitId: "",
      unitName: "All Units",
    };
    amendNewClauses.push({
      _pending: true,
      clauseType,
      effectiveDate: effDate,
      expiryDate: expDate,
      description: summary,
      clauseSummary: summary,
      unitId: "",
      unitName: "All Units",
      [instTypeKey]: [inst],
      _aiIncomplete: true,
      _aiNote: summary,
    });
    report.clauses++;
  });
  if (typeof cl_renderClausesTable === "function") cl_renderClausesTable();
  if (typeof cl_updateClauseCounters === "function") cl_updateClauseCounters();
}

// Map JSON amendmentTypes labels → selectedAmendmentTypes integer values
// by matching against the loaded option-set metadata. Returns counts.
function ai_applyAmendmentTypes(data) {
  const result = { matched: 0, unmatched: [] };
  const node = data && data.amendmentTypes;
  if (!node) return result;
  let labels = node.value != null ? node.value : node;
  if (!Array.isArray(labels)) labels = [labels];
  labels = labels.map((l) => String(ai_leaf(l) || "").trim()).filter(Boolean);
  if (!labels.length) return result;

  if (
    typeof amendmentTypeOptions === "undefined" ||
    !amendmentTypeOptions.length
  ) {
    // Options not loaded yet — can't resolve.
    result.unmatched = labels;
    return result;
  }

  const optLabel = (opt) =>
    (
      opt.Label?.UserLocalizedLabel?.Label ||
      opt.Label?.LocalizedLabels?.[0]?.Label ||
      String(opt.Value)
    )
      .toLowerCase()
      .trim();

  labels.forEach((lbl) => {
    const norm = lbl.toLowerCase();
    // 1) exact, 2) contains either way, 3) word-token overlap
    let hit = amendmentTypeOptions.find((opt) => optLabel(opt) === norm);
    if (!hit) {
      hit = amendmentTypeOptions.find((opt) => {
        const o = optLabel(opt);
        return o.indexOf(norm) !== -1 || norm.indexOf(o) !== -1;
      });
    }
    if (!hit) {
      const tokens = norm.split(/\s+/).filter(Boolean);
      hit = amendmentTypeOptions.find((opt) => {
        const o = optLabel(opt);
        return tokens.some((t) => t.length > 3 && o.indexOf(t) !== -1);
      });
    }
    if (hit) {
      if (
        typeof selectedAmendmentTypes !== "undefined" &&
        !selectedAmendmentTypes.includes(hit.Value)
      ) {
        selectedAmendmentTypes.push(hit.Value);
        result.matched++;
      }
    } else {
      result.unmatched.push(lbl);
    }
  });

  // Diagnostics — inspect in console if some types don't map.
  console.log("🧠 amendmentTypes — JSON labels:", labels);
  console.log(
    "🧠 amendmentTypes — CRM options:",
    amendmentTypeOptions.map((o) => optLabel(o)),
  );
  console.log(
    "🧠 amendmentTypes — selected values:",
    selectedAmendmentTypes,
    "unmatched:",
    result.unmatched,
  );

  if (typeof renderAmendmentTypeDropdown === "function")
    renderAmendmentTypeDropdown();
  if (typeof renderAmendmentTypeChips === "function")
    renderAmendmentTypeChips();
  return result;
}

// Dispatcher — walks whatever arrays the JSON contains.
async function ai_applyArrays(data) {
  const report = {
    discounts: 0,
    charges: 0,
    clauses: 0,
    deposits: 0,
    proposedCharges: 0,
    skippedClauses: [],
    optionsCreated: 0,
    optionsEdited: 0,
    skippedOptions: [],
  };
  // Reset Additional Clauses store before re-applying — avoids stale rows
  // from a previous PDF when the user re-extracts.
  amendAdditionalClauses = [];
  // Reset AI-staged option edits too (re-extraction should not stack edits).
  amendOptionEdits = [];
  // Ensure option-type metadata is loaded BEFORE any routing runs. Both the
  // dedicated options path AND the clause-borne renewal/break reroute depend
  // on ao_optionTypeChoices to resolve types (e.g. "Break"). This is normally
  // loaded lazily on first options-tab visit, which may not have happened yet.
  try {
    if (typeof ao_loadChoices === "function") await ao_loadChoices();
  } catch (e) {
    console.warn("ao_loadChoices (ai_applyArrays):", e);
  }
  try {
    ai_writeDiscounts(data.discounts, report);
  } catch (e) {
    console.warn("discounts:", e);
  }
  try {
    ai_writeCharges(data.charges, report);
  } catch (e) {
    console.warn("charges:", e);
  }
  // Options before clauses: a dedicated data.options array wins; clause-borne
  // renewal/break items are rerouted inside ai_writeClauses as a fallback.
  try {
    await ai_writeOptions(data.options, report);
  } catch (e) {
    console.warn("options:", e);
  }
  try {
    ai_writeClauses(data.clauses, report);
  } catch (e) {
    console.warn("clauses:", e);
  }
  try {
    ai_writeDeposits(data.deposits, report);
  } catch (e) {
    console.warn("deposits:", e);
  }
  if (typeof renderAdditionalClauses === "function") renderAdditionalClauses();
  return report;
}

